    {"id": 0x0044, "text": "\x13\x16\x08Vous obtenez une \x05\x42Potion \x01Verte\x05\x40!\x09 Assignez-la à \x05\x46§\x05\x40, \x05\x46¦\x05\x40 \x01ou \x05\x46¨\x05\x40 dans l'\x05\x46Inventaire\x05\x40.\x04\x13\x16Buvez-la avec \x05\x46¡\x05\x40 pour \x01restaurer votre magie. Cette \x01potion remplit l'une de vos \x01bouteilles.\x02", "box_type": 2},
