    {"id": 0x0047, "text": "\x13\x19\x08Vous obtenez un \x05\x41Poisson\x05\x40!\x09\x01Utilisez-le avec \x05\x46¡\x05\x40 au bon \x01endroit pour qu'il se passe \x01quelque chose.\x04\x13\x19Assignez-le en appuyant sur \x01\x05\x46§\x05\x40, \x05\x46¦\x05\x40 ou \x05\x46¨\x05\x40 dans l'Inventaire\x01et utilisez ce \x05\x46¡ \x05\x40pour vous en\x01servir.\x02", "box_type": 2},
