    {"id": 0x00D7, "text": "\x1ABienvenue \x0F!\x01Je suis la divine Fée de la Force!\x04\x1AJe vais t'enseigner une nouvelle\x01\x05\x42technique d'attaque\x05\x40.\x04\x1AQu'il en soit ainsi!\x02", "box_type": 0},
    {"id": 0x00D8, "text": "\x1ABienvenue \x0F!\x01Je suis la divine Fée de la \x01Sagesse!\x04\x1AJe vais accroître ta \x05\x42puissance\x05\x40 \x01\x05\x42magique\x05\x40.\x04\x1AQu'il en soit ainsi!\x02", "box_type": 0},
    {"id": 0x00D9, "text": "\x1ABienvenue \x0F!\x01Je suis la divine Fée du Courage!\x04\x1AJe vais renforcer ton \x05\x44endurance\x05\x40.\x04\x1AQu'il en soit ainsi!\x02", "box_type": 0},
