    {"id": 0x00DD, "text": "\x08\x1AVous maîtrisez la technique\x01secrète de l'\x05\x41Attaque Cyclone\x05\x40!\x09\x04\x1AChargez votre épée avec \x05\x42 \x05\x40 puis\x01relâcher \x05\x42 \x05\x40 pour créer une vague\x01tourbillonnante d'énergie!\x04\x1APour créer un cyclone d'énergie\x01sans charger votre épée, faites un\x01tour complet avec\x05\x44 ª \x05\x40puis appuyez\x01sur \x05\x42 \x05\x40!\x02", "box_type": 2},
