    {"id": 0x00E6, "text": "\x1A\x08Vous obtenez \x05\x46plusieurs flèches\x05\x40!\x09\x02", "box_type": 2},
    {"id": 0x00E7, "text": "\x1AMais prends garde: en concentrant\x01ton attaque, le \x05\x42niveau de magie\x01\x05\x40diminuera!\x04\x1AHé, mon garçon! Tu es un \x01messager de la Famille Royale, \x01n'est-ce pas?\x04\x1ASi tu retournes au château,\x01va rendre visite à l'une de mes\x01amies vivant dans le coin.\x04\x1AElle se fera une joie de te\x01donner un petit quelque chose!\x02", "box_type": 0},
    {"id": 0x00E8, "text": "\x1AVotre puissance magique a\x01augmenté! Vous disposerez à \x01présent d'une puissance magique\x01\x05\x41deux fois plus importante\x05\x40!\x02", "box_type": 0},
    {"id": 0x00E9, "text": "\x1ATes blessures seront désormais\x01réduites de \x05\x41moitié\x05\x40.\x02", "box_type": 0},
    {"id": 0x00EA, "text": "\x1ABienvenue \x0F!\x01Je suis la Divine Fée des \x01enchantements!\x04\x1AJe t'offre un \x05\x41sortilège\x05\x40.\x01Utilise-le avec soin.\x02", "box_type": 0},
    {"id": 0x00EB, "text": "\x08Désolé, ce masque n'est pas \x01disponible pour l'instant.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00EC, "text": "\x1ALe \x05\x41Feu de Din\x05\x40 consumera tes \x01ennemis et certains obstacles!\x02", "box_type": 0},
    {"id": 0x00ED, "text": "\x1ASouviens-toi, le \x05\x42Vent de Farore \x05\x40ne\x01fonctionne que dans les donjons\x01possédant une carte.\x02", "box_type": 0},
    {"id": 0x00EE, "text": "\x1AL'\x05\x43Amour de Nayru\x05\x44 \x05\x40ne fonctionne \x01que pendant un court instant, \x01alors prends-en soin!\x02", "box_type": 0},
    {"id": 0x00EF, "text": "Si les batailles un jour t'épuisent,\x01j'apaiserai tes blessures!\x02", "box_type": 0},
    {"id": 0x00F0, "text": "\x08Vous obtenez un \x05\x41Rubis rouge\x05\x40!\x01Vous gagnez \x05\x41vingt Rubis\x05\x40!\x09\x02", "box_type": 2},
    {"id": 0x00F1, "text": "\x08Vous obtenez un \x05\x45Rubis pourpre\x05\x40!\x01Vous gagnez \x05\x45cinquante Rubis\x05\x40!\x09\x02", "box_type": 2},
    {"id": 0x00F2, "text": "\x08Vous obtenez un \x05\x46énorme Rubis\x05\x40!\x01Cette pierre vous rapporte\x01\x05\x46deux cents Rubis\x05\x40!\x09\x02", "box_type": 2},
    {"id": 0x00F3, "text": "\x13\x77\x08Vous obtenez une\x05\x41 Clé\x05\x40!\x09\x01Utilisez cette clé pour accéder\x01à la salle suivante. Ouvrez un \x01coffre et... Surprise!\x02", "box_type": 2},
    {"id": 0x00F4, "text": "\x06\x4D\x05\x44Perdu!\x05\x40\x04\x08Vous ne trouvez qu'\x05\x42un Rubis\x05\x40.\x01Dommage.\x09\x02", "box_type": 2},
    {"id": 0x00F5, "text": "\x06\x4D\x05\x44Perdu!\x05\x40\x04\x08Vous trouvez \x05\x43cinq Rubis\x05\x40.\x01C'est peu.\x09\x02", "box_type": 2},
    {"id": 0x00F6, "text": "\x06\x4D\x05\x44Perdu!\x05\x40\x04\x08Vous trouvez \x05\x41vingt Rubis\x05\x40.\x01Votre dernier choix fut une\x01erreur... C'est frustrant, hein?\x09\x02", "box_type": 2},
    {"id": 0x00F7, "text": "\x06\x4D\x05\x41Gagné!\x05\x40\x04\x08Vous trouvez \x05\x46cinquante Rubis\x05\x40.\x01Vous êtes troooop chanceux!\x09\x02", "box_type": 2},
    {"id": 0x00F8, "text": "00f8\x02", "box_type": 0},
    {"id": 0x00F9, "text": "\x13\x1E\x08Vous enfermez une\x05\x41 Ame \x05\x40dans \x01une bouteille!\x09 Allez vite la \x01vendre au \x05\x41Marchand d'Ames\x05\x40!\x02", "box_type": 2},
    {"id": 0x00FA, "text": "\x06\x49\x05\x41GAGNE\x05\x40!\x04\x13\x73\x08Vous obtenez un \x05\x41Quart de\x01coeur\x05\x40!\x09 Trouvez quatre \x01fragments pour créer un \x01nouveau coeur de vie!\x02", "box_type": 2},
    {"id": 0x00FB, "text": "\x06\x4B\x05\x41GAGNE\x05\x40!\x04\x13\x73\x08Vous obtenez un \x05\x41Quart de\x01coeur\x05\x40!\x09 Vous disposez de deux\x01fragments. Encore deux et\x01vous gagnerez plus d'énergie!\x02", "box_type": 2},
    {"id": 0x00FC, "text": "\x06\x4B\x05\x41GAGNE\x05\x40!\x04\x13\x73\x08Vous obtenez un \x05\x41Quart de\x01coeur\x05\x40!\x09 Vous disposez de trois\x01fragments! Plus qu'un et votre\x01énergie sera plus importante!\x02", "box_type": 2},
    {"id": 0x00FD, "text": "\x06\x4B\x05\x41GAGNE\x05\x40!\x04\x13\x73\x08Vous obtenez un \x05\x41Quart de\x01coeur\x05\x40!\x09 Un nouveau coeur\x01d'énergie est créé!\x02", "box_type": 2},
    {"id": 0x00FE, "text": "Cherche-les bien à l'extérieur mais\x01également dans tous les donjons.\x04Bien entendu, rien ne t'oblige à\x01nous aider, tu sais...\x07\x00\x27\x02", "box_type": 0},
    {"id": 0x0100, "text": "\x05\x44C'est quoi, ça?\x05\x40\x02", "box_type": 0},
    {"id": 0x0101, "text": "\x1A\x05\x44Hé! Regarde, \x0F!\x01Tu peux voir à travers cette\x01\x05\x40toile d'araignée \x05\x44en utilisant \x05\x46¥\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0102, "text": "\x1A\x05\x44Regarde ce mur! Les racines qui\x01le recouvrent le rendent praticable.\x01Tu dois pouvoir l'escalader,\x01\x0F!\x05\x40\x02", "box_type": 0},
    {"id": 0x0103, "text": "\x1A\x05\x44Place-toi devant une \x05\x40porte \x05\x44et\x01ouvre-la avec \x05\x43\x05\x44.\x05\x40\x04\x1A\x05\x44Observe bien l'\x05\x43icône d'action\x05\x44.\x01C'est l'\x05\x43icône bleue\x05\x44 située en haut\x01de l'écran!\x05\x40\x02", "box_type": 0},
    {"id": 0x0104, "text": "\x1A\x05\x44Là! Il y a quelque chose qui pend!\x01On dirait une vieille \x05\x40échelle\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0105, "text": "\x1A\x05\x44Dis donc...\x01Ce symbole n'apparaît-il pas\x01sur la \x05\x40Porte du Temps\x05\x44?\x05\x40\x02", "box_type": 0},
    {"id": 0x0106, "text": "\x1A\x05\x44Cette torche semble être éteinte\x01depuis peu...\x05\x40\x02", "box_type": 0},
    {"id": 0x0107, "text": "\x1A\x05\x44A partir d'ici nous allons emprunter\x01d'étroits passages! Si tu procèdes\x01prudemment, tu surprendras certai-\x01nement quelques monstres.\x04\x05\x40\x1A\x05\x44Utilise la \x05\x40Visée ¤ \x05\x44pour toujours\x01regarder dans la bonne direction.\x01Axe-toi pour voir le fond d'un \x01couloir avant de bifurquer.\x04\x05\x40\x1A\x05\x44Une fois bien placé, maintiens \x05\x40¤\x01\x05\x44pour faire un \x05\x40pas de côté\x05\x44.\x01Ainsi tu ne seras jamais pris dans\x01une embuscade.\x05\x40\x02", "box_type": 0},
    {"id": 0x0108, "text": "\x1A\x05\x44Approche-toi de ce \x05\x40bloc de pierre\x05\x44\x01et saisis-le avec \x05\x43\x05\x44. En maintenant\x01\x05\x43\x05\x44, tu peux le pousser ou le tirer.\x04\x05\x40\x1A\x05\x44Tu peux grimper sur un \x05\x40bloc de\x01pierre \x05\x44en maintenant \x05\x40ª \x05\x44vers le \x01\x05\x40bloc\x05\x44 et en appuyant sur \x05\x43\x05\x44.\x04\x05\x40\x1A\x05\x44Observe bien l'\x05\x43icône d'action\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0109, "text": "0109\x02", "box_type": 0},
    {"id": 0x010A, "text": "010a\x02", "box_type": 0},
    {"id": 0x010B, "text": "010b\x02", "box_type": 0},
    {"id": 0x010C, "text": "\x1A\x05\x44Une fois dans l'eau, tu pourras\x01plonger en maintenant\x05\x43 \x05\x44!\x01Je parie que tu y trouveras \x01quelque chose!\x05\x40\x02", "box_type": 0},
    {"id": 0x010D, "text": "010d\x02", "box_type": 0},
    {"id": 0x010E, "text": "010e\x02", "box_type": 0},
    {"id": 0x010F, "text": "010f\x02", "box_type": 0},
    {"id": 0x0110, "text": "0110\x02", "box_type": 0},
    {"id": 0x0111, "text": "0111\x02", "box_type": 0},
    {"id": 0x0112, "text": "0112\x02", "box_type": 0},
    {"id": 0x0113, "text": "0113\x02", "box_type": 0},
    {"id": 0x0114, "text": "\x1A\x05\x44Woah! Mate-moi tous ces \x01\x05\x40Choux-Péteurs\x05\x44!\x05\x40\x04\x1A\x05\x44Crois-tu pouvoir tous les faire\x01exploser en même temps?\x05\x40\x02", "box_type": 0},
    {"id": 0x0115, "text": "\x1A\x05\x44Prends garde aux nombreux\x01\x05\x40puits de lave\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0116, "text": "\x1A\x05\x44Une fois enfoncé, cet interrupteur\x01fait monter cette \x05\x40plate-forme \x01\x05\x44jusqu'au deuxième étage!\x05\x40\x02", "box_type": 0},
    {"id": 0x0117, "text": "0117\x02", "box_type": 0},
    {"id": 0x0118, "text": "0118\x02", "box_type": 0},
    {"id": 0x0119, "text": "\x1A\x05\x44On ne sait jamais ce qu'il y a au\x01détour de ces étroits couloirs....\x04\x05\x40\x1A\x05\x44Utilise la \x05\x40Visée ¤ \x05\x44pour bien axer\x01ton angle de vue. Pratique, non?\x05\x40\x02", "box_type": 0},
    {"id": 0x011A, "text": "011a\x02", "box_type": 0},
    {"id": 0x011B, "text": "011b\x02", "box_type": 0},
    {"id": 0x011C, "text": "011c\x02", "box_type": 0},
    {"id": 0x011D, "text": "011d\x02", "box_type": 0},
    {"id": 0x011E, "text": "011e\x02", "box_type": 0},
    {"id": 0x011F, "text": "\x1A\x05\x44Dis donc, \x0F...\x01On peut savoir ce que tu mates?\x05\x40\x02", "box_type": 0},
    {"id": 0x0120, "text": "0120\x02", "box_type": 0},
    {"id": 0x0121, "text": "0121\x02", "box_type": 0},
    {"id": 0x0122, "text": "0122\x02", "box_type": 0},
    {"id": 0x0123, "text": "0123\x02", "box_type": 0},
    {"id": 0x0124, "text": "\x1A\x05\x44Le Mal se lit sur le visage de \x01cette statue...\x01J'ai un peu la trouille!\x05\x40\x02", "box_type": 0},
    {"id": 0x0125, "text": "0125\x02", "box_type": 0},
    {"id": 0x0126, "text": "\x1A\x05\x44J'entends les esprits murmurer \x01dans cette pièce:\x04\x05\x40\x1A\"Cherche l'oeil de vérité...\"\x02", "box_type": 0},
    {"id": 0x0127, "text": "0127\x02", "box_type": 0},
    {"id": 0x0128, "text": "\x1A\x05\x44J'entends les esprits murmurer \x01dans cette pièce:\x05\x40\x04\x1A\"Le héros aux \x05\x41pieds ailés \x05\x40se \x01laissera porter par le vent.\x01Puisse-t-il être guidé sur la voie\x01secrète.\"\x02", "box_type": 0},
    {"id": 0x0129, "text": "\x1A\x05\x44Ce mur...Il me parle...\x01\x05\x40\"Danger au-dessus...\"\x02", "box_type": 0},
    {"id": 0x012A, "text": "\x1A\x05\x44Ce mur...Il me parle...\x01\x05\x40\"Danger en dessous...\"\x02", "box_type": 0},
    {"id": 0x012B, "text": "\x1A\x05\x44L'eau qui coule de cette statue\x01inonde le sol.\x05\x40\x02", "box_type": 0},
    {"id": 0x012C, "text": "012c\x02", "box_type": 0},
    {"id": 0x012D, "text": "012d\x02", "box_type": 0},
    {"id": 0x012E, "text": "012e\x02", "box_type": 0},
    {"id": 0x012F, "text": "\x1A\x05\x44Prends garde, \x0F!\x01Cette chose\x05\x42 verte et gluante\x05\x44 est\x01électrifiée!\x05\x40\x02", "box_type": 0},
    {"id": 0x0130, "text": "0130\x02", "box_type": 0},
    {"id": 0x0131, "text": "\x1A\x05\x44Prends garde, \x0F!\x01Cette chose \x05\x41rouge et visqueuse \x01\x05\x44est électrifiée!\x05\x40\x02", "box_type": 0},
    {"id": 0x0132, "text": "\x1A\x05\x44Prends garde, \x0F!\x01Cette chose \x05\x43bleue et visqueuse\x01\x05\x44est électrifiée!\x05\x40\x02", "box_type": 0},
    {"id": 0x0133, "text": "\x1A\x05\x44Cet \x05\x40interrupteur\x05\x44...\x01Ta carrure de poids plume ne sera\x01pas suffisante pour l'activer, \x01\x0F...\x05\x40\x02", "box_type": 0},
    {"id": 0x0134, "text": "0134\x02", "box_type": 0},
    {"id": 0x0135, "text": "0135\x02", "box_type": 0},
    {"id": 0x0136, "text": "0136\x02", "box_type": 0},
    {"id": 0x0137, "text": "\x1A\x05\x44Depuis que tu as tranché le \x01\x05\x41tentacule rouge\x05\x44, la chose \x05\x41rouge et \x01visqueuse \x05\x44n'est plus là! Cela\x01fonctionnera-t-il avec les autres?\x05\x40\x02", "box_type": 0},
    {"id": 0x0138, "text": "0138\x02", "box_type": 0},
    {"id": 0x0139, "text": "\x1A\x05\x44Il y a un interrupteur\x01derrière ce mur!\x05\x40\x02", "box_type": 0},
    {"id": 0x013A, "text": "\x1A\x05\x44Il y a quelque chose sur cette\x01plate-forme, là-haut!\x05\x40\x02", "box_type": 0},
    {"id": 0x013B, "text": "013b\x02", "box_type": 0},
    {"id": 0x013C, "text": "013c\x02", "box_type": 0},
    {"id": 0x013D, "text": "\x1A\x06\x2B\x05\x44Qu... Comm... Hein?\x04\x05\x40\x1A\x05\x44Regarde cette flopée de \x05\x40drapeaux\x05\x44!\x01Sauras-tu distinguer les vrais des\x01faux?\x05\x40\x02", "box_type": 0},
    {"id": 0x013E, "text": "013e\x02", "box_type": 0},
    {"id": 0x013F, "text": "013f\x02", "box_type": 0},
    {"id": 0x0140, "text": "\x05\x44Le très vénérable \x05\x40Arbre Mojo\x01\x05\x44veut te parler! Suis-moi vite!\x05\x40\x02", "box_type": 0},
    {"id": 0x0141, "text": "\x05\x44Courage! \x01Entrons dans l'Arbre Mojo!\x05\x40\x02", "box_type": 0},
    {"id": 0x0142, "text": "\x05\x44Le très vénérable Arbre Mojo \x01nous a demandé de rendre visite à \x01la Princesse du \x05\x40Château d'Hyrule\x05\x44....\x01On devrait y aller, non?\x05\x40\x02", "box_type": 0},
    {"id": 0x0143, "text": "\x05\x44La fille du Ranch nous a demandé\x01de retrouver son \x05\x40père\x05\x44... \x01Sais-tu où il se trouve?\x05\x40\x02", "box_type": 0},
    {"id": 0x0144, "text": "\x05\x44Je me demande où la \x05\x40Princesse \x05\x44se\x01cache dans cet immense château.\x05\x40\x02", "box_type": 0},
    {"id": 0x0145, "text": "\x05\x44Que dirait \x05\x40Saria\x05\x41 \x05\x44en apprenant que\x01nous devons sauver Hyrule?\x05\x40\x02", "box_type": 0},
    {"id": 0x0146, "text": "Impa \x05\x44nous a dit que la Pierre \x01Ancestrale du Feu est dissimulée\x01dans le \x05\x40Mont du Péril\x05\x44.\x05\x40\x02", "box_type": 0},
    {"id": 0x0147, "text": "\x05\x44Entrons dans la Caverne Dodongo \x01en utilisant un \x05\x40Chou-Péteur\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0148, "text": "\x05\x44Darunia affirme qu'une \x05\x40fée \x05\x44vit au\x01sommet du Mont du Péril.\x05\x40\x02", "box_type": 0},
    {"id": 0x0149, "text": "\x05\x44Je me demande si \x05\x40Saria \x05\x44sait\x01quelque chose sur l'autre Pierre\x01Ancestrale...\x05\x40\x02", "box_type": 0},
    {"id": 0x014A, "text": "\x05\x44La \x05\x40Princesse Ruto \x05\x44est sans doute\x01dans le ventre de Jabu-Jabu...\x05\x40\x02", "box_type": 0},
    {"id": 0x014B, "text": "\x05\x44Tu as trouvé les trois Pierres\x01Ancestrales! Retournons au \x01\x05\x40Château d'Hyrule\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x014C, "text": "\x05\x44N'était-ce pas Impa et Zelda sur \x01le cheval blanc? Je crois qu'elles \x01ont jeté quelque chose dans les \x01\x05\x40douves\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x014D, "text": "\x05\x44Et si nous allions faire un tour\x01dans le \x05\x40Temple du Temps\x05\x44?\x05\x40\x02", "box_type": 0},
    {"id": 0x014E, "text": "\x05\x44Devrions-nous croire ce que Sheik\x01raconte et aller au \x05\x40Village\x01Cocorico\x05\x44?\x05\x40\x02", "box_type": 0},
    {"id": 0x014F, "text": "014f\x02", "box_type": 0},
    {"id": 0x0150, "text": "\x05\x44Je me demande ce qu'il se passe\x01dans la forêt en ce moment... \x01Et que devient \x05\x40Saria\x05\x44?\x05\x40\x02", "box_type": 0},
    {"id": 0x0151, "text": "\x05\x44Ce nuage au sommet du \x01\x05\x40Mont du Péril \x05\x44ne m'inspire pas\x01confiance...\x05\x40\x02", "box_type": 0},
    {"id": 0x0152, "text": "\x05\x44Un étrange souffle glacé nous \x01vient du \x05\x40Fleuve Zora\x05\x44...\x05\x40\x02", "box_type": 0},
    {"id": 0x0153, "text": "\x05\x44Tes \x05\x40Bottes de plomb \x05\x44ont l'air de \x01peser une tonne! En les portant, \x01tu pourras sûrement marcher \x05\x40au \x01fond d'un lac\x05\x44.\x05\x40\x02", "box_type": 0},
    {"id": 0x0154, "text": "\x05\x44Quelqu'un peut-il nous renseigner\x01sur les autres \x05\x40Sages\x05\x44?\x05\x40\x02", "box_type": 0},
    {"id": 0x0155, "text": "\x05\x44Ce monstre! Il est sorti du \x05\x40puits\x01du village\x05\x44! Allons l'examiner!\x05\x40\x02", "box_type": 0},
    {"id": 0x0156, "text": "\x05\x44Je me demande bien qui a pu\x01construire le \x05\x40Temple de l'Esprit\x05\x44...\x01Et pourquoi?\x05\x40\x02", "box_type": 0},
    {"id": 0x0157, "text": "\x05\x44N'as-tu jamais joué le \x05\x45Nocturne\x01de l'Ombre\x05\x44 que Sheik t'a enseigné?\x05\x40\x02", "box_type": 0},
    {"id": 0x0158, "text": "\x05\x44Le \x05\x40désert\x05\x44... C'est là que Ganondorf\x01a vu le jour. Je suis sûre que \x01nous y trouverons quelque chose...\x05\x40\x02", "box_type": 0},
    {"id": 0x0159, "text": "0159\x02", "box_type": 0},
    {"id": 0x015A, "text": "\x05\x44Enfile tes \x05\x40Gantelets d'argent \x05\x44et \x01tente de bouger quelque chose de\x01très lourd!\x05\x40\x02", "box_type": 0},
    {"id": 0x015B, "text": "\x05\x44Celui qui nous attend au Temple \x01du Temps...ne serait-ce pas...\x05\x40\x02", "box_type": 0},
    {"id": 0x015C, "text": "\x05\x44Allons vite dans le Château\x05\x40 \x05\x44libérer\x01la Princesse Zelda des griffes de\x01l'ignoble Ganondorf!\x05\x40\x02", "box_type": 0},
    {"id": 0x015D, "text": "015D\x02", "box_type": 0},
    {"id": 0x015E, "text": "015E\x02", "box_type": 0},
    {"id": 0x015F, "text": "\x05\x44\x0F...\x01Continue ta quête!\x05\x40\x02", "box_type": 0},
    {"id": 0x0160, "text": "Pourquoi utilises-tu ton ocarina?\x01Je ne suis qu'à deux pas!\x0B\x02", "box_type": 2},
    {"id": 0x0161, "text": "La forêt est reliée à bien des \x01lieux! Si tu entends ma chanson, \x01l'une des entrées n'est pas loin!\x0B\x02", "box_type": 2},
    {"id": 0x0162, "text": "Je suis si contente d'apprendre \x01que Darunia aime ma chanson!\x04Je suis d'autant plus ravie que \x01cela t'a aidé dans ta quête!\x0B\x02", "box_type": 2},
    {"id": 0x0163, "text": "Cherches-tu les \x05\x43Pierres \x01Ancestrales\x05\x40? Il doit te manquer \x01celle de l'\x05\x43eau\x05\x40, n'est-ce pas?\x04Le très vénérable Arbre Mojo m'a\x01dit un jour que le \x05\x43Roi Zora\x05\x40,\x05\x43 \x01souverain du Domaine Zora\x05\x40, garde\x01cette pierre...\x0B\x02", "box_type": 2},
    {"id": 0x0164, "text": "Cherches-tu les \x05\x41Pierres \x01Ancestrales\x05\x40?\x05\x41 \x05\x40Il doit te manquer \x01celle du \x05\x41feu\x05\x40, n'est-ce pas?\x04Le très vénérable Arbre Mojo m'a\x01dit un jour que \x05\x41Darunia le Goron \x01\x05\x40garde cette pierre...\x0B\x02", "box_type": 2},
    {"id": 0x0165, "text": "\x0F...\x01J'ai une étrange intuition...\x01Je suis terrifiée...\x04Le Château...\x01Il se passe quelque chose au \x01Château!\x0B\x02", "box_type": 2},
    {"id": 0x0166, "text": "Tiens... Ton ocarina sonne\x01différemment... \x01T'es-tu beaucoup entraîné, \x01\x0F?\x0B\x02", "box_type": 2},
    {"id": 0x0167, "text": "Cherches-tu un temple?\x01Un bien étrange oiseau m'a dit un \x01jour...\x04\"\x05\x44L'oeil qui voit dans les ténèbres\x01s'ouvrira dans la tempête.\x05\x40\"\x01Ca te dit quelque chose?\x0B\x02", "box_type": 2},
    {"id": 0x0168, "text": "Où es-tu, \x0F?\x01Cherches-tu un temple?\x01Un bien étrange oiseau m'a dit un \x01jour...\x04\"\x05\x44Va jusqu'à la Déesse du Désert,\x01un ocarina dans la main.\x05\x40\"\x01Ca te dit quelque chose?\x0B\x02", "box_type": 2},
    {"id": 0x0169, "text": "As-tu déjà trouvé tous les\x01temples?\x0B\x02", "box_type": 2},
    {"id": 0x016A, "text": "Incroyable! Tu es en vie!\x01J'étais sûre que tu donnerais signe\x01de vie!\x04Je suis dans le \x05\x42Temple de la Forêt\x05\x40!\x01Les esprits des bois ont appellé \x01au secours et je m'y suis rendue...\x04Mais de terribles monstres \x01pervertissent cet endroit...\x01A l'aide, \x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016B, "text": "\x0F...\x01Je n'ai jamais voulu devenir le\x01\x05\x42Sage de la Forêt\x05\x40...\x04Mais j'trouve ça pas mal,\x01finalement.\x04Ainsi je peux t'aider à sauver\x01Hyrule, \x0F!\x01J'en suis très heureuse!\x0B\x02", "box_type": 2},
    {"id": 0x016C, "text": "Si les six \x05\x41Sages\x05\x40 s'allient, nous \x01pourrons emprisonner Ganondorf,  \x01le seigneur du Malin, dans le\x01Saint Royaume.\x04Mais pour sceller parfaitement\x01cette prison, il nous faudra l'aide\x01du \x05\x41Septième Sage\x05\x40.\x04C'est certainement quelqu'un que\x01tu as déjà rencontré,\x01\x0F...\x04Dès maintenant, parcours passé et\x01futur pour éveiller les derniers\x01Sages!\x04Tu es sur le bon chemin,\x01\x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016D, "text": "Nous, les Six Sages, te confions\x01nos pouvoirs!\x04La fragile destinée d'Hyrule repose\x01sur ton noble courage!\x0B\x02", "box_type": 2},
    {"id": 0x016E, "text": "016e\x02", "box_type": 0},
    {"id": 0x016F, "text": "016f\x02", "box_type": 0},
    {"id": 0x0180, "text": "\x1A\x05\x44J'entends une voix...\x05\x40\x04\x1A\x05\x44Elle me dit:\x01\x01\x05\x40\x06\x0D\"Amasse cinq Rubis d'argent...\"\x02", "box_type": 0},
    {"id": 0x0181, "text": "\x1A\x05\x44Ce mur... Il me parle!\x05\x40\x04\x1A\x05\x44Il dit:\x01\x05\x40\x01\x06\x0ASi tu veux un aller simple pour\x01\x06\x15l'enfer, approche pour voir!\x02", "box_type": 0},
    {"id": 0x0182, "text": "0182\x02", "box_type": 0},
    {"id": 0x0183, "text": "\x1A\x05\x44Ce \x05\x40bâteau \x05\x44m'a l'air vieux... \x01Es-tu certain qu'il ne va pas \x01sombrer?\x05\x40\x02", "box_type": 0},
    {"id": 0x0184, "text": "\x1A\x05\x44Il y a une \x05\x40porte \x05\x44de ce côté...  \x01Sais-tu comment traverser?\x05\x40\x02", "box_type": 0},
    {"id": 0x0185, "text": "0185\x02", "box_type": 0},
    {"id": 0x0186, "text": "\x1A\x05\x44Cette \x05\x40glace rouge\x05\x44...\x01Bizarre, non?\x05\x40\x02", "box_type": 0},
    {"id": 0x0187, "text": "0187\x02", "box_type": 0},
    {"id": 0x0188, "text": "0188\x02", "box_type": 0},
    {"id": 0x0189, "text": "\x1A\x05\x44Cette \x05\x40flamme bleue\x05\x44... Elle n'a pas\x01l'air naturel. Elle doit sûrement \x01servir à quelque chose...\x05\x40\x02", "box_type": 0},
    {"id": 0x018A, "text": "018a\x02", "box_type": 0},
    {"id": 0x018B, "text": "018b\x02", "box_type": 0},
    {"id": 0x018C, "text": "\x1A\x05\x44Le \x05\x40feu de ces torches \x05\x44s'est éteint.\x01Comme si les spectres l'avaient \x01consumé!\x05\x40\x02", "box_type": 0},
    {"id": 0x018D, "text": "\x1A\x05\x44Regarde, \x0F! \x01Une \x05\x40torche \x05\x44s'est allumée quand\x01tu as vaincu un spectre!\x05\x40\x02", "box_type": 0},
    {"id": 0x018E, "text": "018e\x02", "box_type": 0},
    {"id": 0x018F, "text": "\x1A\x05\x44Regarde!\x01Il y a des \x05\x40flèches \x05\x44peintes sur le \x01sol!\x05\x40\x02", "box_type": 0},
    {"id": 0x0190, "text": "\x1A\x05\x44Ce \x05\x40couloir \x05\x44est tordu!\x05\x40\x02", "box_type": 0},
    {"id": 0x0191, "text": "\x1A\x05\x44Prends garde à l'\x05\x40ombre des \x01monstres \x05\x44qui apparaissent au\x01plafond.\x05\x40\x02", "box_type": 0},
    {"id": 0x0192, "text": "\x1A\x05\x44Il y a un \x05\x40coffre\x05\x44 ici.\x05\x40\x02", "box_type": 0},
    {"id": 0x0193, "text": "0193\x02", "box_type": 0},
    {"id": 0x0194, "text": "\x1A\x05\x44Cette \x05\x40torche\x05\x44 est identique à celle\x01de l'entrée du temple!\x05\x40\x02", "box_type": 0},
    {"id": 0x0195, "text": "\x1A\x05\x44Si cette \x05\x40torche\x05\x44 est allumée...\x01Cela veut dire que...\x05\x40\x02", "box_type": 0},
    {"id": 0x0196, "text": "0196\x02", "box_type": 0},
    {"id": 0x0197, "text": "\x1A\x05\x44Cet \x05\x40interrupteur \x05\x44est pris dans la \x01glace!\x05\x40\x02", "box_type": 0},
    {"id": 0x0198, "text": "\x1A\x05\x44\x0F, attention!\x01Le plafond nous tombe dessus!\x05\x40\x02", "box_type": 0},
    {"id": 0x0199, "text": "0199\x02", "box_type": 0},
    {"id": 0x019A, "text": "019a\x02", "box_type": 0},
    {"id": 0x019B, "text": "019b\x02", "box_type": 0},
    {"id": 0x019C, "text": "019c\x02", "box_type": 0},
    {"id": 0x019D, "text": "019d\x02", "box_type": 0},
    {"id": 0x019E, "text": "019e\x02", "box_type": 0},
    {"id": 0x019F, "text": "019f\x02", "box_type": 0},
    {"id": 0x01A0, "text": "01a0\x02", "box_type": 0},
    {"id": 0x01A1, "text": "01a1\x02", "box_type": 0},
    {"id": 0x01A2, "text": "01a2\x02", "box_type": 0},
    {"id": 0x01A3, "text": "\x1A\x05\x44\x0F, \x01j'entends \x05\x40des Gorons \x05\x44juste en bas.\x05\x40\x02", "box_type": 0},
    {"id": 0x01A4, "text": "01a4\x02", "box_type": 0},
    {"id": 0x01A5, "text": "\x1A\x05\x44D'ici on peut voir ce qu'il se passe\x01en bas... N'était-ce pas la salle où\x01\x05\x40Darunia \x05\x44est apparu?\x05\x40\x02", "box_type": 0},
    {"id": 0x01A6, "text": "01a6\x02", "box_type": 0},
    {"id": 0x01A7, "text": "\x1A\x05\x44Cette \x05\x40statue\x05\x44... Ne l'aurions-nous\x01pas croisée autre part?\x05\x40\x02", "box_type": 0},
    {"id": 0x01A8, "text": "01a8\x02", "box_type": 0},
    {"id": 0x01A9, "text": "\x1A\x05\x44Cet \x05\x40interrupteur \x05\x44m'a l'air rouillé.\x05\x40\x02", "box_type": 0},
    {"id": 0x01AA, "text": "01aa\x02", "box_type": 0},
    {"id": 0x01AB, "text": "\x1A\x05\x44\x0F! Prends garde!\x01Ne te fais pas engloutir par le\x01tourbillon!\x05\x40\x02", "box_type": 0},
    {"id": 0x01AC, "text": "01ac\x02", "box_type": 0},
    {"id": 0x01AD, "text": "01ad\x02", "box_type": 0},
    {"id": 0x01AE, "text": "01ae\x02", "box_type": 0},
    {"id": 0x01AF, "text": "01af\x02", "box_type": 0},
    {"id": 0x01B0, "text": "01b0\x02", "box_type": 0},
    {"id": 0x01B1, "text": "01B1\x02", "box_type": 0},
    {"id": 0x0200, "text": "\x06\x0EBonjour! Je suis une porte \x01\x06\x46qui parle!\x02", "box_type": 0},
    {"id": 0x0201, "text": "\x06\x19\x05\x44Etrange... Cette porte ne \x01\x05\x40\x06\x41\x05\x44s'ouvre pas\x05\x40\x02", "box_type": 0},
    {"id": 0x0202, "text": "\x06\x19\x05\x44De lourdes \x05\x40barres d'acier \x01\x06\x0C\x05\x44verrouillent cette porte. Tu ne\x01\x05\x40\x06\x16\x05\x44peux l'ouvrir de tes mains!\x05\x40\x02", "box_type": 0},
    {"id": 0x0203, "text": "\x05\x44Tu as besoin d'une \x05\x40Clé\x05\x44 pour ouvrir\x01\x05\x40\x06\x0B\x05\x44cette porte. Elle est fortement\x01\x05\x40\x06\x43\x05\x44verrouillée.\x05\x40\x02", "box_type": 0},
    {"id": 0x0204, "text": "\x06\x0A\x05\x44Tu as besoin d'une \x05\x40Clé spéciale\x01\x06\x1E\x05\x44pour ouvrir cette porte.\x05\x40\x02", "box_type": 0},
    {"id": 0x0205, "text": "\x08Silence!\x09\x04Il n'est que \x1F!\x01Moi, \x05\x41Igor \x05\x40le fossoyeur, \x01j'suis au pieu!\x04Dégage et va jouer avec les \x01spectres du jour!\x02", "box_type": 2},
    {"id": 0x0206, "text": "Il est \x1F.\x01L'\x05\x41Excursion du fossoyeur\x05\x40 est finie!\x04Moi, \x05\x41Igor\x05\x40, j'suis au pieu!\x04Dégage et va jouer avec les \x01spectres!\x02", "box_type": 2},
    {"id": 0x0207, "text": "\x08\x05\x44Foire aux Masques\x01\x05\x40Veuillez lire cette affiche avant \x01de faire appel à nos services.\x09\x04\x08\x05\x41Fonctionnement de la Foire\x01\x05\x40Ici les masques ne sont pas à \x01vendre mais sont \x05\x41confiés\x05\x40 à un \x01coursier gratuitement.\x09\x04\x08Vous vendez le masque emprunté\x01à votre convenance.\x09\x04\x08Vous apportez l'\x05\x41argent\x05\x40 et l'on vous\x01confiera un nouveau masque.\x09\x04\x08Vous pouvez emprunter un masque \x01déjà vendu sans pouvoir le vendre \x01de nouveau.\x09\x04\x08Pourquoi ne pas essayer?\x01\x06\x34--Le propriétaire\x09\x02", "box_type": 2},
    {"id": 0x0208, "text": "Temple de l'Ombre...\x01Ici sommeillent les légendes\x01sanglantes d'Hyrule, faites de haine\x01et de cupidité...\x0B\x02", "box_type": 2},
    {"id": 0x0209, "text": "Reposent au fond des ténèbres \x01pièges vicieux, trappes sournoises,\x01et l'ombre qui masque le chemin...\x0B\x02", "box_type": 2},
    {"id": 0x020A, "text": "Seul le gardien de l'\x05\x41oeil de vérité \x01\x05\x40pourra scruter le tréfonds obscur.\x0B\x02", "box_type": 2},
    {"id": 0x020B, "text": "\x05\x44Une étrange substance nous bloque\x01l'entrée. Tu dois résoudre l'\x05\x40énigme\x05\x44 \x01de cette pièce pour passer.\x05\x40\x02", "box_type": 0},
    {"id": 0x020C, "text": "\x08Crâne géant de Dodongo...\x01Quand il voit rouge, un nouveau\x01chemin se découvre.\x09\x02", "box_type": 2},
    {"id": 0x020D, "text": "\x06\x2A\x05\x44Chasse aux trésors\x01\x05\x40\x06\x21Fermée pour le moment\x01\x06\x2AOuverture: ce soir!\x02", "box_type": 2},
    {"id": 0x020E, "text": "\x06\x41\x05\x44Apothicaire\x01\x05\x40\x06\x28Fermé jusqu'au matin\x02", "box_type": 2},
    {"id": 0x020F, "text": "\x06\x3C\x05\x44Jeu d'adresse\x01\x05\x40\x06\x1BOuvert seulement le jour\x02", "box_type": 2},
    {"id": 0x0210, "text": "\x06\x2D\x05\x44Foire aux Masques\x01\x05\x40\x06\x37Nous recrutons\x01\x06\x1ESe renseigner la journée\x02", "box_type": 2},
    {"id": 0x0211, "text": "\x06\x51\x05\x44Bazar\x01\x05\x40\x06\x1BOuvert seulement le jour\x02", "box_type": 2},
    {"id": 0x0212, "text": "Apporte-moi la lumière!\x02", "box_type": 2},
    {"id": 0x0213, "text": "\x08Seul un \x05\x41regard juste \x05\x40discernera\x01le guide fantomatique jusqu'au\x01Temple de l'Esprit.\x09\x02", "box_type": 2},
    {"id": 0x0214, "text": "\x08Toi qui désires ouvrir le sentier\x01enfoui au fond du lac, entonne le\x01\x05\x41Chant de la Famille Royale\x05\x40.\x09\x02", "box_type": 2},
    {"id": 0x0215, "text": "\x08Toi qui désires ouvrir la porte\x01des hauteurs célestes, entonne le\x01\x05\x41Chant de la Famille Royale\x05\x40.\x09\x02", "box_type": 2},
    {"id": 0x0216, "text": "Qui a la \x05\x41petite clé\x05\x40 passera.\x01Qui ne l'a pas, s'en va!\x02", "box_type": 2},
    {"id": 0x0217, "text": "Si tu veux Nous demander \x01audience, fais-le de la plate-forme.\x0B\x02", "box_type": 0},
    {"id": 0x0218, "text": "\x1A\x12\x68\x6D\x08Salut, \x0F!\x09\x01Regarde par là!\x04Regarde-moi avec \x05\x44¤\x05\x40, et parle-moi\x01avec \x05\x43\x05\x40.\x02", "box_type": 0},
    {"id": 0x0219, "text": "Au quatrième top; il sera:\x01\x05\x41\x1F\x05\x40.\x02", "box_type": 0},
    {"id": 0x021A, "text": "Inonde de lumière les morts.\x02", "box_type": 2},
    {"id": 0x021B, "text": "Celui qui viole la Tombe Royale\x01réveillera les \x05\x41bêtes de l'ombre\x05\x40.\x02", "box_type": 2},
    {"id": 0x021C, "text": "Hé, toi! P'tit gars!\x01Regarde par là! Dans la cellule!\x0B\x02", "box_type": 0},
    {"id": 0x021D, "text": "Mon gamin n'est pas là pour\x01l'instant...\x01Je crois qu'il traîne du côté du\x01cimetière...\x02", "box_type": 0},
    {"id": 0x021E, "text": "Mon gamin dort pour le moment.\x01Reviens demain matin pour jouer\x01avec lui!\x02", "box_type": 0},
    {"id": 0x021F, "text": "\x08Quand les premières lueurs de \x01l'aube se reflèteront sur le lac, \x01décoche vers l'astre du matin.\x09\x02", "box_type": 2},
    {"id": 0x0220, "text": "\x08Pour t'aventurer dans le futur,\x01rapporte le \x05\x43pouvoir de l'argent \x05\x40du \x01passé.\x09\x02", "box_type": 2},
    {"id": 0x0221, "text": "\x08Pour errer dans le passé, présente\x01ici un coeur pur d'enfant.\x09\x02", "box_type": 2},
    {"id": 0x0222, "text": "\x08Cette porte est en réparation.\x09\x02", "box_type": 2},
    {"id": 0x0223, "text": "\x08Quelque chose devait être fixé \x01sur ce socle...\x09\x02", "box_type": 2},
    {"id": 0x0224, "text": "\x08\x06\x21Pointe mon bec vers le\x01\x06\x34\x05\x41crâne de vérité\x05\x40.\x09\x04\x08\x06\x14Une erreur te plongera dans\x01\x06\x25les abîmes infernales.\x09\x0B\x02", "box_type": 2},
    {"id": 0x0225, "text": "\x05\x44Ce n'est pas la bonne \x05\x40clé\x05\x44...\x01Cette porte ne s'ouvre pas!\x05\x40\x02", "box_type": 0},
    {"id": 0x0226, "text": "\x08\x06\x42\x05\x44Apothicaire\x01\x05\x40\x06\x50Fermé\x09\x04\x08\x06\x1BJe suis partie faire des \x01\x06\x3Cexpériences...\x01\x06\x2CRevenez plus tard!\x01\x06\x4B--Granny\x09\x02", "box_type": 2},
    {"id": 0x0227, "text": "\x08Qui va là? Quel sale môme!\x01Essayer de passer par derrière!\x09\x04\x14\x02Vilain petit...\x14\x00\x01Je m'en vais te raconter une \x01petite histoire!\x04Le chef des ouvriers a un fils...\x01Il passe ses nuits assis sous \x01l'arbre...\x04Ne va pas dire au chef que je \x01t'en ai parlé!\x02", "box_type": 0},
    {"id": 0x0228, "text": "\x05\x44Regarde ça!\x05\x40\x02", "box_type": 0},
    {"id": 0x0229, "text": "Malon est au lit!\x01Je vais me coucher, moi aussi.\x01Reviens demain lorsqu'il fera jour!\x02", "box_type": 0},
    {"id": 0x022A, "text": "\x08\x05\x41Records de \x0F!\x01\x05\x40Araignées écrabouillées: \x19\x01Plus gros poisson: \x1E\x02 livres\x09\x04\x08Marathon: \x1E\x04\x01Course à cheval: \x1E\x03\x01Archerie montée: \x1E\x00 points\x09\x02", "box_type": 2},
    {"id": 0x022B, "text": "\x08\x06\x0FLe blason de la Famille Royale\x01\x06\x24d'Hyrule est gravé ici.\x09\x02", "box_type": 2},
    {"id": 0x022C, "text": "\x08\x06\x32Paix à leur âme\x01\x06\x0CIci reposent éternellement les \x01\x06\x09fidèles serviteurs de la Famille \x01\x06\x36Royale d'Hyrule.\x09\x04\x08\x06\x09Les Sheikahs, protecteurs de la\x01\x06\x0AFamille Royale et fondateurs de\x01\x06\x07Cocorico, veillent sur le sommeil\x01\x06\x32éternel des âmes.\x09\x02", "box_type": 2},
    {"id": 0x022D, "text": "\x08\x06\x28\x05\x43Cascade Insomniaque\x01\x05\x40\x06\x02Le flux de cette cascade obéit au\x01\x06\x05Roi d'Hyrule. Lorsque le Roi dort,\x01\x06\x28la cascade se meure.\x09\x02", "box_type": 2},
    {"id": 0x022E, "text": "Des crapauds vous toisent depuis\x01le fond des eaux...\x02", "box_type": 2},
    {"id": 0x022F, "text": "Vous foulez du pied un tapis \x01d'apparat...\x01C'est tout doux entre les orteils!\x02", "box_type": 2},
    {"id": 0x0230, "text": "Passe maître des \x05\x41épreuves \x01\x05\x40suivantes et notre trésor secret \x01récompensera ta valeur!\x02", "box_type": 2},
    {"id": 0x0231, "text": "Ouvre la voie jusqu'au trésor\x01secret en méritant les \x05\x41clés \x01\x05\x40dissimulées dans chaque salle!\x02", "box_type": 2},
    {"id": 0x0232, "text": "Ecrase tes ennemis en un \x01\x05\x41temps record\x05\x40!\x02", "box_type": 2},
    {"id": 0x0233, "text": "Amasse les \x05\x41gemmes sous-marines\x05\x40!\x02", "box_type": 2},
    {"id": 0x0234, "text": "Traverse les flots en feu!\x02", "box_type": 2},
    {"id": 0x0235, "text": "Révèle le secret de cette pièce!\x02", "box_type": 2},
    {"id": 0x0236, "text": "Aveugle \x05\x41cette statue\x05\x40!\x02", "box_type": 2},
    {"id": 0x0237, "text": "Celui aux \x05\x41doigts d'argent \x05\x40pourra\x01déplacer un bloc de géant!\x02", "box_type": 2},
    {"id": 0x0238, "text": "Sans les bons objets, \x01la compréhension sera obscurcie \x01par d'innombrables mystères.\x02", "box_type": 2},
    {"id": 0x0239, "text": "Amasse les \x05\x41joyaux de platine\x05\x40 et \x01évite pièges et dangers!\x02", "box_type": 2},
    {"id": 0x023A, "text": "\x08\x06\x51\x05\x44Etang\x05\x40\x01\x06\x03Les poissons mordent aujourd'hui!\x09\x02", "box_type": 1},
    {"id": 0x023B, "text": "\x06\x4E\x05\x44....???\x05\x40\x02", "box_type": 0},
