    {"id": 0x030D, "text": "\x08\x06\x05L'oeil de la vérité, enfoui sous le\x01\x06\x14Village Cocorico, procurera \x01\x06\x1Bl'alliance des ombres à son\x01\x06\x46détenteur.\x09\x02", "box_type": 1},
    {"id": 0x030E, "text": "\x08\x06\x3C\x05\x43Domaine Zora\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x030F, "text": "\x08\x06\x3C\x05\x43Fontaine Zora\x01\x05\x40\x06\x12Ne pas déranger le Seigneur\x01\x06\x3CJabu-Jabu! \x01\x06\x25--Zora le XVIème, Roi\x09\x02", "box_type": 1},
    {"id": 0x0310, "text": "\x08\x06\x0F\x05\x45Aire d'Entraînement Sylvestre\x05\x41\x01\x05\x40\x06\x0FPrière de ne pas trancher les\x01\x06\x0Fpancartes comme un barbare...\x09\x02", "box_type": 1},
    {"id": 0x0311, "text": "\x08\x06\x12A ceux assez fous pour se \x01\x06\x1Erisquer dans le désert: \x01\x06\x25Passez donc me voir!\x09\x04\x08\x06\x2E\x05\x46Marchand de Tapis\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x0312, "text": "\x08\x06\x3CDroit devant:\x01\x06\x1ALa \x05\x42Clairière du Vénérable\x01\x05\x40\x06\x41\x05\x42Arbre Mojo\x05\x40\x09\x02", "box_type": 1},
