    {"id": 0x0318, "text": "\x08\x06\x2D\x05\x43Laboratoire du Lac\x01\x05\x40\x06\x14Nous tentons de percer les\x01\x06\x24secrets du Lac Hylia!\x01\x06\x34--Le Scientifique\x09\x02", "box_type": 1},
    {"id": 0x0319, "text": "\x08\x06\x3C\x05\x46Vallée Gerudo\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x031A, "text": "\x08\x06\x33\x05\x46Archerie Montée\x05\x40\x01\x06\x0CBienvenue aux habiles archers!\x01\x06\x15Record actuel: \x05\x41\x1E\x00\x05\x40 Points\x09\x02", "box_type": 1},
    {"id": 0x031B, "text": "\x08\x06\x33\x05\x46Gymnase Gerudo\x01\x05\x40\x06\x0DSeuls les membres actifs sont\x01\x06\x46autorisés!\x09\x02", "box_type": 1},
    {"id": 0x031C, "text": "\x08\x06\x3C\x05\x46Désert Hanté\x05\x40\x01\x06\x07Poursuis un mirage et les sables\x01\x06\x07t'engloutiront. Seul un chemin te\x01\x06\x32mènera au salut!\x09\x02", "box_type": 1},
