    {"id": 0x0321, "text": "\x08\x06\x03Longez la falaise pour accéder au\x01\x05\x41Village Goron\x05\x40, demeure des Gorons.\x09\x02", "box_type": 1},
    {"id": 0x0322, "text": "\x08\x06\x23Merveille de la nature:\x01\x06\x37Le \x05\x41Chou-Péteur\x05\x40\x01\x06\x16Danger! Ne pas déraciner!\x09\x02", "box_type": 1},
    {"id": 0x0323, "text": "\x08\x06\x34\x05\x41Sommet du Péril\x01\x05\x40\x06\x2FEntrée du cratère\x01\x06\x04Attention aux vagues de chaleur!\x09\x02", "box_type": 1},
    {"id": 0x0324, "text": "\x08\x06\x12\x05\x43Salle d'Audience du Roi Zora\x01\x05\x40\x06\x0APour entendre les proclamations\x01\x06\x19royales, tenez-vous sur la\x01\x06\x25plate-forme et parlez.\x09\x02", "box_type": 1},
    {"id": 0x0325, "text": "\x08\x06\x11Arrête ma course folle et je\x01t'offrirai (peut-être) quelque chose.\x01\x06\x34-- \x05\x41Le Goron Fou\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x0326, "text": "\x08\x06\x12Un oeil de vérité révèlera le\x01\x06\x06bouclier de pierre, seule défense\x01\x06\x1Ccontre la nuée de lames.\x09\x02", "box_type": 1},
    {"id": 0x0327, "text": "\x08\x06\x03Seuls ceux au \x05\x41pied léger \x05\x40pourront\x01\x06\x0Ftraverser la vallée des morts.\x09\x02", "box_type": 1},
    {"id": 0x0328, "text": "\x08Le plus rapide de mes adversaires\x01a fait:\x01\x05\x44\x1E\x06\x05\x40\x01--Igor le fossoyeur\x09\x02", "box_type": 1},
    {"id": 0x0329, "text": "\x08\x05\x44Jeu d'adresse  \x0120 Rubis la partie\x01\x05\x4110 cibles\x05\x40, \x05\x4115 coups\x05\x40, facile!\x09\x04\x0810 cibles touchées -- Premier Prix\x018 cibles ou plus -- Partie gratuite\x01Moins de 8 cibles -- T'es nul\x09\x04\x08\x05\x44Règles du Jeu d'adresse\x01\x05\x40Ne pas tirer sur le patron.\x01Ne pas jeter de bombes.\x01Ne JAMAIS tirer sur le patron.\x09\x02", "box_type": 1},
    {"id": 0x032A, "text": "\x08\x06\x2A\x05\x44Chasse aux trésors\x05\x40\x01\x06\x08T'auras du pot si t'es chanceux.\x09\x02", "box_type": 1},
    {"id": 0x032B, "text": "\x08\x06\x34\x05\x44Jeu du plongeon\x01\x05\x40\x06\x05Aurez-vous le courage de plonger\x01\x06\x23du haut de la falaise?\x09\x02", "box_type": 1},
    {"id": 0x032C, "text": "032c\x02", "box_type": 1},
    {"id": 0x032D, "text": "\x08\x06\x1F\x05\x41Sommet de la Montagne\x05\x40\x01\x06\x46Danger!!!\x09\x02", "box_type": 1},
    {"id": 0x032E, "text": "\x08\x06\x2A\x05\x44Foire aux Masques!\x05\x40\x01\x06\x0CNous recherchons un coursier!\x09\x02", "box_type": 1},
    {"id": 0x032F, "text": "\x08\x06\x33\x05\x44Bowling Teigneux\x05\x40\x01\x06\x08Testez les dernières nouveautés\x01\x06\x1Een matière d'explosions!\x09\x02", "box_type": 1},
    {"id": 0x0330, "text": "\x08\x06\x51\x05\x44Bazar\x05\x40\x01\x06\x20Ici l'on trouve de tout!\x09\x02", "box_type": 1},
    {"id": 0x0331, "text": "\x08\x06\x42\x05\x44Apothicaire\x01\x05\x40\x06\x0APotions, bandages et onguents!\x09\x02", "box_type": 1},
    {"id": 0x0332, "text": "\x08\x06\x37\x05\x41Boutique Goron\x01\x05\x40\x06\x23Matériel de montagne!\x09\x02", "box_type": 1},
    {"id": 0x0333, "text": "\x08\x06\x36\x05\x43Boutique Zora\x05\x40\x01\x06\x1ELes produits de la mer!\x09\x02", "box_type": 1},
    {"id": 0x0334, "text": "\x08\x06\x1E\x05\x44Excursion du Fossoyeur!\x01\x05\x40\x06\x10De 18h à 21h (heure d'Hyrule)\x01\x06\x2D--Igor le fossoyeur\x09\x02", "box_type": 1},
    {"id": 0x0335, "text": "\x08\x06\x1EExcursion du Fossoyeur!\x01\x06\x0AL'attraction est \x05\x41annulée\x05\x40 jusqu'à\x01\x06\x3Cnouvel ordre...\x01\x06\x20Recherchons fossoyeur.\x09\x02", "box_type": 1},
    {"id": 0x0336, "text": "\x08\x05\x45Attaque en Fente!\x01\x05\x40Pour faire une fente avec votre \x01lame, maintenez \x05\x44¤ \x05\x40et\x05\x44 ª \x05\x40vers\x01votre cible puis appuyez sur \x05\x42 \x05\x40.\x09\x02", "box_type": 1},
    {"id": 0x0337, "text": "\x08\x06\x39\x05\x45Passage étroit\x01\x05\x40Faufilez-vous dans ce trou!\x09\x04\x08Placez-vous devant le trou et \x01maintenez \x05\x44ª \x05\x40vers celui-ci. \x01Lorsque l'\x05\x43icône d'action \x05\x40indique\x01\"Entrer\", appuyez sur \x05\x43\x05\x40.\x09\x04\x08Observez bien ce qu'affiche\x01\x05\x43l'icône d'action\x05\x40!\x09\x02", "box_type": 1},
    {"id": 0x0338, "text": "\x08\x05\x45Coupez l'herbe avec votre épée!\x01\x05\x40Attaquez avec \x05\x42 \x05\x40 pour trancher\x01horizontalement. Maintenez \x05\x44¤\x05\x40 \x01pour trancher verticalement.\x09\x02", "box_type": 1},
    {"id": 0x0339, "text": "\x08\x06\x33\x05\x44Château d'Hyrule\x05\x40\x01\x06\x38\x05\x46Ranch Lon Lon\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x033A, "text": "\x08\x06\x0AVous êtes ici: \x05\x44Château d'Hyrule\x05\x40\x01\x06\x19Tout droit: \x05\x46Ranch Lon Lon\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x033B, "text": "\x08\x06\x43Tout droit:\x01\x06\x13\x05\x43Salle d'audience du Roi Zora\x01\x05\x40\x06\x11Appliquez-vous au protocole!\x09\x02", "box_type": 1},
    {"id": 0x033C, "text": "\x08\x06\x23Cabane du Grand \x05\x41Mido\x05\x40\x01\x06\x32Chef des Kokiris\x09\x02", "box_type": 1},
    {"id": 0x033D, "text": "\x08\x06\x0ACabane des Frères Je-Sais-Tout\x09\x02", "box_type": 1},
    {"id": 0x033E, "text": "\x08\x06\x28Cabane des Jumelles\x09\x02", "box_type": 1},
    {"id": 0x033F, "text": "\x08\x06\x33Cabane de \x05\x41Saria\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x0340, "text": "\x08\x05\x45Axer l'angle de vue avec ¤ \x01\x05\x40Appuyez sur \x05\x44¤ \x05\x40pour axer votre \x01angle de vue vers l'avant.\x09\x04\x08Restez immobile puis changez de\x01direction ou \x05\x44maintenez ¤ \x05\x40pendant\x01un court instant.\x09\x04\x08Cette technique permet de vous\x01orienter toujours dans la bonne\x01direction. Pratique, non?\x09\x04\x08En \x05\x44maintenant ¤\x05\x40, vous pouvez \x01vous déplacez \x05\x41latéralement\x05\x40 en \x01faisant face toujours au même \x01point.\x09\x04\x08\x05\x41Les pas de côté\x05\x40 sont très \x01importants dans les couloirs d'un\x01donjon ou pendant un combat.\x01Entraînez-vous dès maintenant!\x09\x02", "box_type": 1},
    {"id": 0x0341, "text": "\x08\x05\x41Sauter sur les pierres\x01\x05\x40Marchez vers le bord d'une plate-\x01forme pour sauter automatiquement.\x09\x04\x08Sautez sur toutes les pierres et\x01vous passerez une bonne journée!\x01\x06\x32(proverbe Kokiri)\x09\x02", "box_type": 1},
    {"id": 0x0342, "text": "\x08\x06\x23\x05\x41Interdiction de plonger\x01\x05\x40\x06\x32(L'eau ça mouille)\x09\x02", "box_type": 1},
    {"id": 0x0343, "text": "\x08\x05\x45Visée\x01\x05\x40Si vous apercevez une icône \x05\x42©\x05\x40 \x01au-dessus d'un élément, vous \x01pouvez cibler celui-ci avec \x05\x44¤\x05\x40.\x09\x04\x08En d'autres termes, en appuyant \x01sur \x05\x44¤\x05\x40 lorsque vous voyez \x05\x42©\x05\x46 \x05\x40au-\x01dessus d'un objet, vous pouvez \x01vous axer vers celui-ci. Cool, non?\x09\x04\x08En appuyant de nouveau sur \x05\x44¤\x05\x40, \x01la cible \x05\x41disparaîtra\x05\x40 ou se fixera\x01sur un nouvel élément possédant \x01une icône \x05\x42©\x05\x40.\x09\x04\x08Lors d'un combat vous opposant à \x01de nombreux ennemis, appuyez sur\x01\x05\x44¤ \x05\x40et \x05\x44ª\x05\x40 vers l'arrière pour\x01faire disparaître la cible.\x09\x04\x08Ciblez les \x05\x41pierres\x05\x40 à côté de cette\x01pancarte pour vous entraîner!\x09\x02", "box_type": 1},
    {"id": 0x0344, "text": "\x08\x06\x30\x05\x42Théâtre Sylvestre\x05\x40\x09\x04\x08Venez nous montrer vos grimaces!\x01\x06\x0DDe fabuleux prix à remporter!\x09\x02", "box_type": 1},
    {"id": 0x0345, "text": "\x08\x06\x1FVenez voir les fabuleux\x01\x06\x2D\x05\x41Frères Je-Sais-Tout\x01\x05\x40\x06\x0FEt vos questions ne resteront\x01\x06\x29plus sans réponse!!\x09\x02", "box_type": 1},
    {"id": 0x0400, "text": "Ceci est une \x05\x41Pierre à Potins\x05\x40!\x02", "box_type": 2},
    {"id": 0x0401, "text": "On raconte que d'appuyer sur \x05\x42 \x01\x05\x40vous fait nager plus vite.\x02", "box_type": 2},
    {"id": 0x0402, "text": "On raconte qu'il y a un passage \x01secret près de l'arbre au\x01Nord-Est de la Plaine d'Hyrule.\x02", "box_type": 2},
    {"id": 0x0403, "text": "On raconte qu'il y a un passage\x01secret sur la route menant au Lac \x01Hylia.\x02", "box_type": 2},
    {"id": 0x0404, "text": "On raconte que l'épée de Biggoron\x01est indestructible.\x02", "box_type": 2},
    {"id": 0x0405, "text": "On raconte que Medigoron pue des\x01pieds.\x02", "box_type": 2},
    {"id": 0x0406, "text": "On raconte que Malon est la\x01première à avoir inscrit un record\x01à la course d'obstacle du Ranch\x01Lon Lon.\x02", "box_type": 2},
    {"id": 0x0407, "text": "On raconte que Malon du Ranch\x01Lon Lon rêve toutes les nuits \x01qu'un prince charmant la demande\x01en mariage.\x02", "box_type": 2},
    {"id": 0x0408, "text": "On dit que Ruto, la capricieuse\x01princesse Zora, est amoureuse\x01d'un garçon...\x02", "box_type": 2},
    {"id": 0x0409, "text": "On dit que choisir la visée \x01\"maintenue\" au début du jeu \x01est super cool!\x02", "box_type": 2},
    {"id": 0x040A, "text": "On raconte qu'il y a un passage\x01secret non loin d'un arbre sur la\x01route de Cocorico.\x02", "box_type": 2},
    {"id": 0x040B, "text": "On raconte que, contrairement aux\x01apparences, la Princesse Zelda du\x01Château d'Hyrule est un vrai\x01garçon manqué!\x02", "box_type": 2},
    {"id": 0x040C, "text": "On raconte que la nourrice de la\x01Princesse Zelda est une Sheikah, \x01une race souvent considérée comme\x01éteinte.\x02", "box_type": 2},
    {"id": 0x040D, "text": "On dit qu'un drôle de type\x01s'amuse à cavaler autour de la\x01Plaine d'Hyrule.\x02", "box_type": 2},
    {"id": 0x040E, "text": "On dit qu'il est interdit d'utiliser\x01des lunettes pendant la chasse\x01aux trésors..\x02", "box_type": 2},
    {"id": 0x040F, "text": "On dit que cogner sur les poules,\x01c'est rigolo et ça défoule!\x02", "box_type": 2},
    {"id": 0x0410, "text": "On raconte que les Gerudos \x01viennent souvent chercher des \x01petits amis au Château d'Hyrule.\x02", "box_type": 2},
    {"id": 0x0411, "text": "On dit que Zelda est le plus beau\x01jeu du monde... Ben, j'crois bien\x01qu'c'est vrai!\x02", "box_type": 2},
    {"id": 0x0412, "text": "On dit que tenir un bâton Mojo\x01près d'un papillon fait \x01apparaître quelque chose.\x02", "box_type": 2},
    {"id": 0x0413, "text": "On dit qu'un donjon une fois\x01terminé peut faire apparaître\x01de nouveaux monstres.\x02", "box_type": 2},
    {"id": 0x0414, "text": "On dit que les Gerudos vénèrent\x01Ganondorf comme un dieu.\x02", "box_type": 2},
    {"id": 0x0415, "text": "On dit qu'il y a un passage secret \x01près de l'entrée de la Vallée \x01Gerudo.\x02", "box_type": 2},
    {"id": 0x0416, "text": "On dit que la chouette du nom de\x01Kaepora Gaebora est la réincarna-\x01tion d'un ancien Sage.\x02", "box_type": 2},
    {"id": 0x0417, "text": "On dit que le traducteur de Zelda\x01est super beau et méga cool!\x02", "box_type": 2},
    {"id": 0x0418, "text": "On dit que le destrier de\x01Ganondorf est un étalon dressé \x01par les Gerudos.\x02", "box_type": 2},
    {"id": 0x0419, "text": "On dit que Ganondorf veut non\x01seulement dominer les Gerudos \x01mais aussi Hyrule!\x02", "box_type": 2},
    {"id": 0x041A, "text": "On dit que le Gymnase Gerudo est\x01super balèze...\x01Et que le trésor secret n'est pas \x01aussi cool qu'on le pense!\x02", "box_type": 2},
    {"id": 0x041B, "text": "On dit qu'il y a un interrupteur\x01à activer avec l'Attaque Cyclone.\x02", "box_type": 2},
    {"id": 0x041C, "text": "On dit qu'il y a en tout\x01100 Skulltulas d'or à trouver.\x02", "box_type": 2},
    {"id": 0x041D, "text": "On dit qu'un Hylien se transforme\x01en monstre s'il s'égare dans les\x01Bois Perdus!\x02", "box_type": 2},
    {"id": 0x041E, "text": "On dit que les insectes adorent\x01se cacher dans les trous du sol\x01d'Hyrule.\x02", "box_type": 2},
    {"id": 0x041F, "text": "On dit que manger des cafards,\x01c'est dégueulasse.\x02", "box_type": 2},
    {"id": 0x0420, "text": "On dit qu'un Kokiri a quitté la \x01forêt et a survécu!\x02", "box_type": 2},
    {"id": 0x0421, "text": "0421\x02", "box_type": 0},
    {"id": 0x0600, "text": "\x08\x05\x41C'est quoi ce truc?\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0601, "text": "\x08Gohma\x01\x05\x44Ce monstre ronge les entrailles de\x01l'Arbre Mojo! Vise son \x05\x40oeil\x05\x44 lorsque\x01celui-ci est rouge!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0602, "text": "\x08Oeuf Gohma\x01\x05\x44Si cet oeuf éclot, une Larve\x01Gohma apparaîtra.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0603, "text": "\x08Larve Gohma\x01\x05\x44Prends garde à ses sauts!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0604, "text": "\x08Skulltula\x01\x05\x44Son \x05\x40ventre\x05\x44 est son point faible!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0605, "text": "\x08Grosse Skulltula\x01\x05\x44Son \x05\x40ventre\x05\x44 est son point faible!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0606, "text": "\x08Tailpasaran\x01\x05\x44Sa \x05\x40queue \x05\x44est son point faible!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0607, "text": "\x08Mojo Baba\x01\x05\x44Frappe-la après son attaque et \x01elle se dressera. Tranche-la vite \x01pour obtenir un \x05\x40Bâton Mojo\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0608, "text": "\x08Grosse Mojo Baba\x01\x05\x44Frappe-la après son attaque et \x01elle se dressera. Tranche-la vite \x01pour obtenir un \x05\x40Bâton Mojo\x05\x44!\x09\x02", "box_type": 2},
    {"id": 0x0609, "text": "\x08Mojo Baba\x01\x05\x44Son seul contact te fera souffrir!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060A, "text": "\x08Peste Mojo\x01\x05\x44Approche-t'en et il se cachera \x01dans l'herbe. Fais rebondir ses\x01projectiles!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060B, "text": "060b\x02", "box_type": 2},
    {"id": 0x060C, "text": "\x08King Dodongo\x01\x05\x44Cet énorme Dodongo avalerait \x01n'importe quoi! Donne-lui une bonne\x01secousse et frappe avec ton \x05\x40épée\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060D, "text": "\x08Dodongo\x01\x05\x44Prends garde à son souffle!\x01Utilise bien la \x05\x40Visée ¤\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060E, "text": "\x08Dodongo Junior\x01\x05\x44Prends garde à ses sauts!\x01Il explosera une fois vaincu!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060F, "text": "\x08Lizalfos \x01\x05\x44Utilise souvent ton bouclier et \x01la \x05\x40Visée ¤\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0610, "text": "\x08Dinolfos \x01\x05\x44Utilise souvent ton bouclier et \x01la \x05\x40Visée ¤\x05\x44!\x09\x02", "box_type": 2},
    {"id": 0x0611, "text": "\x08Saigneur ardent\x01\x05\x44Détruis-le rapidement ou ses \x01flammes feront brûler ton \x01\x05\x40Bouclier Mojo\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0612, "text": "\x08Saigneur\x01\x05\x44Utilise la \x05\x40Visée ¤ \x05\x44pour toujours\x01garder un oeil sur lui.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0613, "text": "\x08Armos\x01\x05\x44Immobilise-le pour ensuite le\x01détruire!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0614, "text": "\x08Barinade\x01\x05\x44De dangereuses méduses lui \x01tournent autour. Vise la partie\x01protégée de son corps!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0615, "text": "\x08Tentacule Parasite?\x01\x05\x44La partie mince semble être son\x01point faible... Tu as besoin d'une\x01arme spéciale pour le couper!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0616, "text": "\x08Bulld'O\x01\x05\x44Ta lame la fera rebondir!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0617, "text": "\x08Biri\x01\x05\x44Touche-la et tu recevras une\x01décharge électrique!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0618, "text": "\x08Bari\x01\x05\x44Touche-la et tu recevras une\x01décharge électrique!\x09\x02", "box_type": 2},
    {"id": 0x0619, "text": "\x08Manta\x01\x05\x44Détruis-la avant qu'elle ne \x01t'attaque!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061A, "text": "\x08Ganon Spectral\x01\x05\x44C'est un esprit maléfique du \x01Temple de la forêt! Il surgit\x01de l'un des tableaux.\x04\x05\x44Réponds à son attaque magique \x01avec l'une des tiennes!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061B, "text": "\x08Stalfos\x01\x05\x44Attire-le et observe bien ses \x01mouvements! Attaque quand il\x01baisse sa garde!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061C, "text": "\x08Tetdoss Bleue\x01\x05\x44Protège-toi de sa flamme bleue \x01avec ton \x05\x40bouclier\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061D, "text": "\x08Tetdoss Blanche\x01\x05\x44Vise-la une fois à l'arrêt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061E, "text": "\x08Tetdoss Verte\x01\x05\x44Vise-la lorsque sa flamme verte \x01disparaît!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061F, "text": "\x08Skullwalltula\x01\x05\x44Ne la touche surtout pas!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0620, "text": "\x08Skulltula d'or\x01\x05\x44Cette Araignée de la Malédiction,\x01une fois vaincue, fera apparaître \x01un \x05\x40symbole\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0621, "text": "\x08Volcania\x01\x05\x44Il est le gardien du Temple du\x01feu, réveillé par le Roi Sombre.\x01Quel peut être son point faible?\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0622, "text": "\x08Danse-Flamme\x01\x05\x44Souffle d'abord son \x05\x40habit de \x01flammes\x05\x44...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0623, "text": "\x08Feu Visqueux\x01\x05\x44Il fuira une fois sa flamme éteinte.\x01Détruis-le avant sa régénération!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0624, "text": "\x08Tetdoss Rouge\x01\x05\x44Protège-toi de son attaque \x01avec ton \x05\x40bouclier\x05\x44!\x09\x02", "box_type": 2},
    {"id": 0x0625, "text": "\x08Morpha\x01\x05\x44Gardien du Temple de l'eau, il\x01contrôle les fluides. Son point \x01faible semble être le \x05\x40noyau\x05\x44...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0626, "text": "\x08Ombre de \x0F\x01\x05\x44Terrasse ton Frère Noir!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0627, "text": "\x08Coquillos\x01\x05\x44Son \x05\x40organe interne \x05\x44est son point\x01faible!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0628, "text": "\x08Spike\x01\x05\x44Vise-le quand il rétracte ses \x01pointes!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0629, "text": "\x08Bongo Bongo\x01\x05\x44Seigneur du Temple de l'Ombre, \x01échappé du puits de Cocorico.\x01Utilise le \x05\x40Monocle de Vérité\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062A, "text": "\x08Effroi\x01\x05\x44Son regard te paralysera. S'il te \x01mord, appuie sur les \x05\x40boutons \x05\x44pour\x01te dégager!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062B, "text": "\x1A\x08Ganon Spectral\x01\x05\x44Attaque-le \x05\x40lorsqu'il sort des \x01tableaux\x05\x44! Fais attention aux \x01illusions!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062C, "text": "062c\x02", "box_type": 2},
    {"id": 0x062D, "text": "\x08Gibdo\x01\x05\x44Son regard te paralysera. S'il te \x01mord, appuie sur les \x05\x40boutons\x05\x44 pour\x01te dégager!\x09\x02", "box_type": 2},
    {"id": 0x062E, "text": "\x08Poigneur\x01\x05\x44S'il t'empoigne, appuie sur les\x01\x05\x40boutons \x05\x44pour te dégager!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062F, "text": "\x08Poignant\x01\x05\x44Prends garde aux mains infinies! \x01Vise la tête...ça l'arrêtera net!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0630, "text": "\x08Clapoir\x01\x05\x44Fais bien attention à son \x05\x40ombre\x05\x44 \x01sur le sol. Détruis-la avant qu'elle\x01ne retourne au plafond!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0631, "text": "\x08Grossbaffe\x01\x05\x44Lorsqu'elle se divise, viens à bout\x01de toutes les mains avant qu'elles\x01ne fusionnent!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0632, "text": "\x08Koume\x01\x05\x44Mère spirituelle de Ganondorf.\x01Maîtresse des flammes infinies. \x01Elle est vulnérable au \x05\x40froid\x05\x44.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0633, "text": "\x08Kotake\x01\x05\x44Mère spirituelle de Ganondorf.\x01Maîtresse des glaces éternelles.\x01Elle est vulnérable au \x05\x40feu\x05\x44.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0634, "text": "\x08Hache-Viande\x01\x05\x44C'est étrange...\x01Cet ennemi n'est pas comme les \x01autres!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0635, "text": "\x08Hache-Viande\x01\x05\x44Sa hache est meurtrière! \x01Frappe-le quand il baisse sa garde!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0636, "text": "\x08Skull Kid\x01\x05\x44Voilà ce qu'il advient des enfants\x01perdus dans la forêt... On dirait \x01qu'il n'aime pas les adultes.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0637, "text": "\x08Pudding\x01\x05\x44Ce monstre avale \x05\x40tuniques\x05\x44 et \x01\x05\x40boucliers\x05\x44. Détruis-le vite pour\x01récupérer ton équipement!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0638, "text": "0638\x02", "box_type": 2},
    {"id": 0x0639, "text": "\x08Sentinelle\x01\x05\x44Evite son regard meurtrier!\x01A mon avis, son oeil craint la \x01fumée!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063A, "text": "\x08Anubis\x01\x05\x44Il est vulnérable au \x05\x41feu\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063B, "text": "\x08Mr. Freezzard\x01\x05\x44Attention à son souffle glacé! \x01Détruis-le entièrement avant qu'il\x01ne régénère.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063C, "text": "063c\x02", "box_type": 2},
    {"id": 0x063D, "text": "\x08Ganondorf, Seigneur du Malin\x01\x05\x44Son point faible? \x01Comment veux-tu qu'je le sache!!!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063E, "text": "\x08Ganon\x01\x05\x44Quel est son point faible?\x01Mais j'en sais rien moi!!!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063F, "text": "\x08Skull Kid\x01\x05\x44Voici ce qu'il advient des enfants\x01perdus dans la forêt. \x01Comment devenir son ami?\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0640, "text": "\x08Skull Kid\x01\x05\x44Voilà ce qu'il advient des enfants\x01perdus dans la forêt? Il a l'air\x01triste de ne plus avoir de visage.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0641, "text": "\x08Skull Kid\x01\x05\x44Voilà ce qu'il advient des enfants\x01perdus dans la forêt? Il a l'air\x01content avec sa tête de mort.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0642, "text": "\x08Octorok\x01\x05\x44Fais rebondir ses rochers!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0643, "text": "\x08Esprit du cimetière?\x01\x05\x44Fixe-le avec la \x05\x40Visée ¤ \x05\x44et il\x01disparaîtra...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0644, "text": "\x08Esprit\x01\x05\x44Fixe-le avec la \x05\x40Visée ¤ \x05\x44et il\x01disparaîtra...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0645, "text": "\x08Araknon Rouge\x01\x05\x44Fixe-le avec la \x05\x40Visée ¤ \x05\x44pendant\x01ses sauts...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0646, "text": "\x08Araknon Bleu\x01\x05\x44Attire-le de préférence vers le sol\x01pour le détruire!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0647, "text": "\x08Leever\x01\x05\x44Observe bien ses mouvements!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0648, "text": "\x08Peahat\x01\x05\x44Ses \x05\x40racines \x05\x44sont sensibles!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0649, "text": "\x08Larve Peahat\x01\x05\x44Protège-toi avec ton \x05\x40bouclier\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064A, "text": "064a\x02", "box_type": 2},
    {"id": 0x064B, "text": "064b\x02", "box_type": 2},
    {"id": 0x064C, "text": "\x08Lobo\x01\x05\x44Attire-le vers toi et observe ses\x01mouvements! Frappe quand il\x01baisse sa garde!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064D, "text": "\x08Peste Dingo\x01\x05\x44Approche-t'en et il se cachera\x01dans l'herbe...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064E, "text": "\x08Peste Marchande\x01\x05\x44Approche-t'en et il se cachera\x01dans l'herbe...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064F, "text": "\x08Spectre d'Igor\x01\x05\x44C'est le fantôme du fossoyeur!\x01Suis-le et il te remettra son \x01\x05\x40trésor\x05\x44...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0650, "text": "\x08Meg de la Confrérie des Esprits\x01\x05\x44Ne te laisse pas avoir par ses\x01répliques illusoires! Cherche \x01\x05\x40la bonne\x05\x44 et vise bien!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0651, "text": "\x08Joelle de la Confrérie des Esprits\x01\x05\x44Vise-la quand elle apparaît!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0652, "text": "\x08Beth de la Confrérie des Esprits\x01\x05\x44Vise-la quand elle apparaît!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0653, "text": "\x08Amy de la Confrérie des Esprits\x01\x05\x44Vise-la quand elle apparaît!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0654, "text": "\x08Voleuse Gerudo\x01\x05\x44Quand elle baisse sa garde, cogne-\x01la comme une brute! Fais vite ou \x01tu seras capturé.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0655, "text": "\x08Sakdoss\x01\x05\x44N'aie pas peur du Sakdoss!\x01Cogne comme un sourd en criant:\x01YAAAAAAAAAAH!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0656, "text": "\x08Saigneur givré\x01\x05\x44Détruis-le avant qu'il ne t'attaque!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0657, "text": "\x08Lobo blanc\x01\x05\x44Attire-le vers toi et observe ses\x01mouvements! Frappe quand il\x01baisse sa garde!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0658, "text": "\x08Toukor\x01\x05\x44Détruis-le avant qu'il ne t'attaque!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0659, "text": "\x08Bigocto\x01\x05\x44Attaque-le par derrière!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x065A, "text": "\x08Ame\x01\x05\x44Ce type d'Esprit, plus courageux, \x01ne fuira pas ton regard. \x01Attention: elle se déplace vite!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x065B, "text": "\x08Fusion maléfique\x01\x05\x44Le feu et la glace réunis en un\x01corps parfait. Sers-toi de leur\x01\x05\x40propre attaque magique\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x065C, "text": "\x08Esprit\x01\x05\x44Cet Esprit ne disparaît pas si tu\x01le fixes. Rien ne lui fait peur,\x01apparemment...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x086D, "text": "\x08\x06\x2DJouez avec \x05\x43\x05\x40 et \x05\x46¡\x05\x40.\x05\x46\x01\x05\x40\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x086E, "text": "\x08\x05\x43\x05\x40 et \x05\x46¡ \x05\x40- Jouer \x05\x42     \x05\x40- Annuler\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x086F, "text": "\x01\x01\x10\x02", "box_type": 3},
    {"id": 0x0870, "text": "\x08\x06\x19Jouez le \x05\x42Menuet des bois\x05\x40.\x05\x42\x01\x01\x01\x05\x40\x09\x10\x02", "box_type": 3},
    {"id": 0x0871, "text": "\x08\x06\x20Jouez le \x05\x41Boléro du feu\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0872, "text": "\x08\x06\x15Jouez la \x05\x43Sérénade de l'eau\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0873, "text": "\x08\x06\x0FJouez le \x05\x46Requiem des esprits\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0874, "text": "\x08\x06\x0FJouez le \x05\x45Nocturne de l'ombre\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0875, "text": "\x08\x06\x0CJouez le \x05\x44Prélude de la lumière\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0876, "text": "\x08\x06\x1AJouez le \x05\x42Chant de Saria\x05\x40!\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0877, "text": "\x08\x06\x21OK? Voici la\x05\x41 mélodie\x05\x40...\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0878, "text": "\x08\x06\x21Retiens cette \x05\x43mélodie\x05\x40...\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0879, "text": "\x08Retiens à jamais le \x05\x46Chant du Soleil\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x087A, "text": "\x08\x05\x44Ce chant\x05\x40 ouvre la Porte du Temps.\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x087B, "text": "\x08Je n'oublierai jamais cette \x05\x45mélodie\x05\x40!\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x087C, "text": "\x08\x05\x43\x05\x40 et \x05\x46¡ \x05\x40- Jouer \x05\x42     \x05\x40- Annuler\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x088B, "text": "\x15\x00\x20\x00\x0A\x02", "box_type": 3},
    {"id": 0x088C, "text": "\x08\x06\x0A\x05\x41Impossible de se téléporter ici!\x05\x40\x09\x0E\x28\x02", "box_type": 0},
    {"id": 0x088D, "text": "\x08\x05\x42Se téléporter aux Bois Perdus!\x05\x40\x09\x01\x01\x1B\x05\x42OK!\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x088E, "text": "\x08\x05\x41Se téléporter au Cratère du Péril!\x05\x40\x09\x01\x01\x1B\x05\x42OK!\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x088F, "text": "\x08\x05\x43Se téléporter au Lac Hylia!\x05\x40\x09\x01\x01\x1B\x05\x42OK!\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x0890, "text": "\x08\x05\x46Se téléporter au Colosse du \x01Désert!\x05\x40\x09\x01\x1B\x05\x42OK!\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x0891, "text": "\x08\x05\x45Se téléporter au Cimetière!\x05\x40\x09\x01\x01\x1B\x05\x42OK!\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x0892, "text": "\x08\x05\x44Se téléporter au Temple du Temps!\x05\x40\x09\x01\x01\x1B\x05\x42OK!\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x0893, "text": "\x08\x06\x06Vous jouez le \x05\x42Menuet des bois\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0894, "text": "\x08\x06\x10Vous jouez le \x05\x41Boléro du feu\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0895, "text": "\x08\x06\x05Vous jouez la \x05\x43Sérénade de l'eau\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0896, "text": "\x08Vous jouez le \x05\x46Requiem des esprits\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0897, "text": "\x08Vous jouez le \x05\x45Nocturne de l'ombre\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0898, "text": "\x08Vous jouez le \x05\x44Prélude de la lumière\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0899, "text": "\x08\x06\x0CVous jouez le \x05\x42Chant de Saria\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089A, "text": "\x08\x06\x0FVous jouez le \x05\x41Chant d'Epona\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089B, "text": "\x08\x06\x03Vous jouez la \x05\x43Berceuse de Zelda\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089C, "text": "\x08\x06\x0BVous jouez le \x05\x46Chant du Soleil\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089D, "text": "\x08\x06\x09Vous jouez le \x05\x44Chant du Temps\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089E, "text": "\x08Vous jouez le \x05\x45Chant des Tempêtes\x05\x40!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089F, "text": "\x08Vous jouez le \x05\x46Chant de l'Epouvantail\x05\x40\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x1000, "text": "\x1A\x05\x44Haa... Enfin debout!\x01Moi c'est \x05\x41Navi\x05\x44 la fée!\x05\x40\x04\x1A\x05\x44Le très vénérable Arbre Mojo m'a\x01désignée pour être ta \x05\x41partenaire \x05\x44!\x01J'en suis très honorée!\x05\x40\x02", "box_type": 0},
    {"id": 0x1001, "text": "\x1A\x06\x14Hé! Salut, \x0F!\x02", "box_type": 0},
    {"id": 0x1002, "text": "\x1AWhoaaa! Une fée!!\x04\x1AEnfin tu as reçu une fée,\x01\x0F!\x07\x10\x0F\x02", "box_type": 0},
    {"id": 0x1003, "text": "Je vais t'attendre ici!\x01Va voir le vénérable Arbre Mojo!\x02", "box_type": 0},
    {"id": 0x1004, "text": "\x05\x43 \x05\x40devant une pierre, et han! \x01Je la soulève.\x01\x05\x43 \x05\x40devant une pierre, et yaa!\x01Je la soulève.\x04Pfouuh, cette peste de \x05\x41Mido\x05\x40...Il \x01m'a obligé à ramasser toutes les \x01pierres devant chez lui.\x02", "box_type": 0},
    {"id": 0x1005, "text": "\x1AOh, tu as une \x05\x44fée\x05\x40 maintenant?!\x01C'est cool, \x0F!\x04\x1AComment?\x04\x1ATu as été convoqué par le \x01\x05\x41vénérable Arbre Mojo\x05\x40?\x01Quel honneur!\x04\x1AIl va peut-être te donner un joli \x01cadeau, hi hi!\x04\x1AIl est notre père à tous, tu sais!\x01Il protège la forêt de sa toute\x01puissance! Il a donné vie à tous\x01les Kokiris!\x02", "box_type": 0},
    {"id": 0x1006, "text": "Je me demande bien si le \x01\x05\x41vénérable Arbre Mojo \x05\x40a créé\x01tous les êtres de la forêt.\x02", "box_type": 0},
    {"id": 0x1007, "text": "Bon, répétons quelques \x01mouvements!\x04Cible quelque chose avec la \x01\x05\x44Visée ¤\x05\x40 et appuie sur \x05\x43\x05\x40 \x01en allant à droite ou à gauche \x01pour \x05\x41bondir sur les côtés\x05\x40.\x04Cible avec la \x05\x44Visée ¤\x05\x40, appuie\x01sur \x05\x43 \x05\x40tout en pointant vers\x01l'arrière pour faire un \x05\x41saut \x01périlleux arrière\x05\x40.\x04Pour faire une \x05\x41roulade\x05\x40, cible\x01avec la \x05\x44Visée ¤\x05\x40 et appuie \x01sur \x05\x43\x05\x40.\x04Dégaine ton épée et utilise la \x01\x05\x44Visée ¤\x05\x40 pour effectuer une \x01\x05\x41Attaque sautée\x05\x40 avec \x05\x43\x05\x40!\x01Elle fait deux fois plus mal!\x04Entraîne-toi à la \x05\x44Visée ¤\x05\x40 sur\x01ces pierres, et essaie tous ces \x01nouveaux mouvements!\x02", "box_type": 0},
    {"id": 0x1008, "text": "\x1ATu n'es pas autorisé à quitter la \x01forêt, petit Kokiri!\x07\x10\x09\x02", "box_type": 0},
    {"id": 0x1009, "text": "Le très vénérable Arbre Mojo dit\x01qu'un Kokiri hors de la forêt est\x01un Kokiri mort!\x02", "box_type": 0},
    {"id": 0x100A, "text": "\x1ACette peste de \x05\x41Mido\x05\x40 m'a obligé à\x01tondre la pelouse devant la maison\x01de Saria.\x04\x1AMido drague Saria en lui rendant \x01service! Mais au bout du compte \x01c'est moi qui me tape le sale \x01boulot à sa place!\x07\x10\x0B\x02", "box_type": 0},
    {"id": 0x100B, "text": "Toi et \x05\x41Saria\x05\x40, vous êtes plutôt \x01copains, non? Alors pourquoi tu \x01m'aiderais pas un peu à couper \x01cette herbe!\x04Tu n'as qu'à garder tout ce que tu \x01y trouveras.\x02", "box_type": 0},
    {"id": 0x100C, "text": "\x1ABravo! \x01Voilà comment s'utilise une \x05\x44fée\x05\x40!\x04\x1AC'est vraiment chouette d'en avoir\x01une, hein?\x04\x1AJe vais t'apprendre à parler aux \x01gens avec ta fée!\x07\x10\x0D\x02", "box_type": 0},
    {"id": 0x100D, "text": "Quand une fée vole autour de\x01quelqu'un, utilise \x05\x44¤\x05\x40 pour \x05\x41regarder\x05\x40 \x01dans sa direction.\x04Utilise la \x05\x44Visée ¤\x05\x40 pour parler \x01aux gens de loin, un peu comme\x01nous sommes en train de faire.\x04Et si tu n'as rien à cibler, appuie \x01sur \x05\x44¤\x05\x40 pour \x05\x41regarder\x05\x40 devant toi.\x02", "box_type": 0},
    {"id": 0x100E, "text": "\x1AAh! Enfin tu as eu ta \x05\x44fée\x05\x40!\x04\x1AMais tu as encore beaucoup à \x01apprendre!\x07\x10\x19\x02", "box_type": 0},
    {"id": 0x100F, "text": "\x1A\x12\x68\x63Yipii! \x08Quelle bonne nouvelle!\x09\x01Je suis si heureuse!\x04\x1ATu es maintenant un vrai Kokiri,\x01\x0F!\x07\x10\x10\x02", "box_type": 0},
    {"id": 0x1010, "text": "\x1AAlors, c'est vrai? \x01Le très vénérable Arbre Mojo t'a \x01convoqué?\x04\x1AC'est un véritable honneur d'être\x01convoqué par le vénérable Arbre\x01Mojo, tu sais!\x07\x10\x03\x02", "box_type": 0},
    {"id": 0x1011, "text": "\x1A\x06\x1COh...alors tu pars...déjà...\x02", "box_type": 0},
    {"id": 0x1012, "text": "\x1ACe n'est pas grave...\x01Nous serons amis pour toujours...\x01N'est-ce pas?\x02", "box_type": 0},
    {"id": 0x1013, "text": "\x1AJe veux que tu gardes cet \x01ocarina...\x01Prends-en grand soin!\x02", "box_type": 0},
    {"id": 0x1014, "text": "Pense à moi en jouant de l'ocarina.\x01Et un jour peut-être...\x01Tu reviendras me voir...\x02", "box_type": 0},
    {"id": 0x1015, "text": "\x1AOh... Navi...\x01Enfin te voici...\x04\x1A\x0F...\x01Sois le bienvenu...\x04\x1AEcoute, écoute bien, jeune enfant...\x01Moi, \x05\x41l'Arbre Mojo\x05\x40, de par mes \x01sages paroles, vais te révéler la\x01sombre réalité!\x04\x1ATon sommeil, depuis plusieurs\x01lunes, est tourmenté par\x01d'épuisants songes et de terribles \x01cauchemars...\x04\x1AAlors que les forces obscures\x01grandissent, une aura maléfique\x01s'étend sur le monde, pervertissant\x01nos rêves de sombres présages!\x04\x1AEt toi aussi, jeune enfant, tu as \x01ressenti cette infâmie...\x04\x1A\x0F... \x01Le temps est venu pour toi de \x01mettre ton courage à l'épreuve...\x07\x10\x16\x02", "box_type": 0},
    {"id": 0x1016, "text": "Je suis sous l'emprise d'une\x01odieuse \x05\x41malédiction\x05\x40...\x01Pour me libérer, j'ai besoin de \x01ta vaillance et de ta sagesse.\x04Auras-tu le courage d'entreprendre\x01cette noble quête?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x1017, "text": "\x1AAlors entre, brave \x0F,\x01et toi aussi Navi...\x04\x1ANavi la fée, tu aideras   \x01\x0F de ton mieux...\x04\x1AEt toi \x0F, quand \x05\x44Navi \x01\x05\x40désirera te parler, utilise \x05\x46¥ \x05\x40pour\x01écouter ses conseils avisés...\x02", "box_type": 0},
    {"id": 0x1018, "text": "Soit... Il est sans doute encore \x01trop tôt pour toi...\x01Alors retourne dans la forêt pour \x01terminer ton apprentissage...\x04Une fois prêt, reviens te présenter\x01devant moi... Parle en appuyant \x01sur \x05\x44¤\x05\x40...\x02", "box_type": 0},
    {"id": 0x1019, "text": "L'\x05\x42aire d'entraînement sylvestre \x05\x40 \x01t'enseignera de nouvelles \x01techniques. Dirige-toi vers \x01cette colline...\x02", "box_type": 0},
    {"id": 0x101A, "text": "\x1A\x12\x38\x82\x08Aïe-ouille-aïe!\x09 \x08Pardon, seigneur!\x09\x01Je te donne un indice et tu me \x01laisses partir, OK?\x04\x1A\x12\x38\x80Tu peux sauter d'une falaise\x01sans te faire mal. Maintiens \x05\x44ª\x05\x40 \x01vers l'avant pour faire une roulade\x01et ainsi amortir ta chute.\x04\x1A\x12\x38\x80Bon d'accord, ça ne marche pas\x01à tous les coups... Surtout si la \x01falaise est super haute...\x01Gnark, gnark...\x04\x1A\x12\x38\x80Essaie quand même!\x01\x08Warf.. arf.. arf!!!\x09\x0B\x02", "box_type": 0},
    {"id": 0x101B, "text": "Tiens tiens!...\x01On dirait bien le p'tit Kokiri\x01derrière ce masque!\x02", "box_type": 0},
    {"id": 0x101C, "text": "Pas mal ton masque. Il me plaît!\x01Avec ça sur ma face, j'aurai l'air\x01d'un dur, un vrai!\x04Donne! Donne! Donne!\x01\x01\x1B\x05\x42OK\x01Jamais\x05\x40\x02", "box_type": 0},
    {"id": 0x101D, "text": "Beuh! T'es nul...\x02", "box_type": 0},
    {"id": 0x101E, "text": "Ouais!!! Je vais le porter toute\x01la journée!\x02", "box_type": 0},
    {"id": 0x101F, "text": "\x1A\x12\x48\x07Il n'a donné que \x05\x4110 Rubis\x05\x40! Et ce \x01masque en vaut 20! Tu t'es fait \x01avoir, mec!\x04\x1ARetournons à la Foire aux Masques\x01payer les \x05\x4120 Rubis\x05\x40. La différence, \x01c'est pour ta pomme!!!\x02", "box_type": 2},
    {"id": 0x1020, "text": "Tous mes copains veulent le même \x01masque, j'ai la super cote!!!\x01Nananèreuh...\x02", "box_type": 0},
    {"id": 0x1021, "text": "Tout va bien? \x01Tu n'as pas quitté la forêt?\x02", "box_type": 0},
    {"id": 0x1022, "text": "Sais-tu qu'en maintenant \x05\x44© \x05\x40vers\x05\x44\x01\x05\x40l'avant pendant un saut tu peux \x01faire une roulade pour amortir ta \x01chute?\x04Bien sûr, tomber de trop haut te\x01fera quand même bobo...\x02", "box_type": 0},
    {"id": 0x1023, "text": "Saria t'attend à l'endroit habituel.\x02", "box_type": 0},
    {"id": 0x1024, "text": "\x1AFélicitations, \x0F...\x02", "box_type": 0},
    {"id": 0x1025, "text": "Whoa! Il est cool ton lance-pierre!\x04Tu peux viser en maintenant \x05\x46¡\x05\x40 \x01et tirer en relâchant le bouton!\x01Pratique, non?\x04Garde ton lance-pierre en main, \x01cible avec la \x05\x44Visée ¤ \x05\x40et\x05\x44 \x05\x41tire en \x01te déplaçant!\x01\x05\x40Tu le savais pas ça, hein?\x02", "box_type": 0},
    {"id": 0x1026, "text": "Hélas non, \x0F...\x01Sache que mon temps est compté...\x02", "box_type": 0},
    {"id": 0x1027, "text": "\x1AMaintenant...écoute-moi bien... \x01Un\x05\x41 vil cavalier du désert \x05\x40m'a \x01infligé cette terrible et odieuse \x01malédiction...\x02", "box_type": 0},
    {"id": 0x1028, "text": "Tu cherches Saria? \x01Elle est dans les \x05\x42Bois Perdus\x05\x40.\x01Comme d'habitude...\x04Ne dis pas que tu ne sais plus \x01comment y aller! L'entrée est sur \x01la falaise au-dessus du village!\x04Je parie que tu vas te perdre...\x01Minable!\x04\x06\x51\x08Pfeuhh!\x09\x02", "box_type": 0},
    {"id": 0x1029, "text": "\x1ATu ne dois surtout pas laisser \x01l'homme du désert en armure noire \x01s'approcher de la sainte Triforce...\x04\x1AEt tu ne permettras jamais que \x01cet homme au coeur si mauvais \x01puisse s'immiscer dans le très \x01Saint Royaume des Légendes...\x04\x1ACe vil chacal m'a jeté cette \x01malédiction infecte et mortelle \x01pour saper mon pouvoir.\x04\x1ACe sort si néfaste me promet un \x01trépas imminent...\x04\x1AMême si tes vaillants efforts\x01ont eu raison de ce maléfice, mon\x01destin est scellé depuis le début...\x04\x1AHélas, je ne peux m'y soustraire:\x01le moment fatal est proche...\x04\x1AMais ne te lamente pas sur \x01mon sort...\x04\x1AJe t'ai transmis mon savoir...\x01Tu connais la vérité maintenant...\x01Mon rôle s'achève ici...\x04\x1ATu es le dernier espoir d'Hyrule!\x02", "box_type": 0},
    {"id": 0x102A, "text": "\x1ALa destinée du monde dépend de \x01tes actes...\x01\x0F...\x01Tu es courageux et vaillant...\x04\x1ANavi, belle petite fée...\x01Aide \x0F dans sa \x01quête...\x04\x1A\x14\x02Je t'en prie... Navi...\x14\x00\x01\x14\x03...Adieuuuu...\x14\x00\x02", "box_type": 0},
    {"id": 0x102B, "text": "\x1A\x05\x44Allons au Château d'Hyrule,\x01\x0F!!\x05\x40\x02", "box_type": 0},
    {"id": 0x102C, "text": "\x1A\x14\x01\x05\x44Adieu...\x05\x40\x14\x00\x05\x44Vénérable Arbre Mojo...\x05\x40\x02", "box_type": 0},
    {"id": 0x102D, "text": "Dommage...Hein? Hein?\x02", "box_type": 0},
    {"id": 0x102E, "text": "Tu veux encore tenter ta chance?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x102F, "text": "\x1AHé, toi là! \x01\"\x05\x44Monsieur J'ai-pas-d'fée\x05\x40!\"\x01Tu lui veux quoi au vénérable \x01Arbre Mojo?\x04\x1ASans fée t'es même pas un vrai \x01Kokiri, d'abord!\x07\x10\xD0\x02", "box_type": 0},
    {"id": 0x1030, "text": "Si tu veux passer, \x05\x43équipe-toi\x05\x40 \x01d'abord d'une \x05\x42épée\x05\x40 et d'un \x05\x44bouclier\x05\x43,\x05\x40\x01minus!\x04\x06\x51\x08Pfeuh!\x09\x02", "box_type": 0},
    {"id": 0x1031, "text": "\x06\x4D\x08Quoi?!\x09\x01\x1A\x05\x41Mido \x05\x40ne veut pas te laisser voir\x01le vénérable Arbre Mojo?\x07\x10\xC8\x02", "box_type": 0},
    {"id": 0x1032, "text": "Va t'acheter un \x05\x44bouclier \x05\x40à la \x01boutique Kokiri. Mais pour l'\x05\x42épée\x05\x40... \x01Cherche bien dans un coin du \x01village!\x02", "box_type": 0},
    {"id": 0x1033, "text": "\x1ASi tu veux voir le Vénérable Arbre\x01Mojo, Il te faut d'abord une \x05\x42épée\x05\x40 \x01et un \x05\x44bouclier\x05\x40!\x07\x10\xD2\x02", "box_type": 0},
    {"id": 0x1034, "text": "Moââ, le grand Mido, je ne \x01t'accepterai jamais comme l'un\x01des nôtres!\x04Et puis d'abord, comment t'as fait \x01pour être le chouchou de Saria et\x01du vénérable Arbre Mojo?!  \x01.......Pfeuuh!.......\x02", "box_type": 0},
    {"id": 0x1035, "text": "Je peux te renseigner sur les \x01\x05\x41icônes \x05\x40en haut de l'écran. \x01\x1B\x05\x42Les icônes jaunes\x01Les icônes bleues\x05\x40\x02", "box_type": 0},
    {"id": 0x1036, "text": "Les trois icônes jaunes dans le \x01coin en haut à droite s'appellent:\x01\x05\x46Icônes\x05\x40 \x05\x46¡\x05\x40.\x04Elles montrent ce que tu peux \x01utiliser avec les boutons \x05\x46§\x05\x40,\x05\x46 ¦ \x01\x05\x40et \x05\x46¨\x05\x40.\x04Quand tu obtiens un nouvel \x05\x46objet\x05\x40, \x01tu peux l'assigner à l'un des trois\x01boutons \x05\x46¡\x05\x40 en activant le menu \x01de l'\x05\x46inventaire\x05\x40.\x02", "box_type": 0},
    {"id": 0x1037, "text": "L'icône bleue en haut de l'écran \x01est l'\x05\x43Icône d'Action\x05\x40.\x04Cette icône t'indique les actions\x01réalisables en appuyant sur \x05\x43\x05\x40.\x04Selon l'endroit et le moment, ce \x01bouton te permettra de faire\x01différentes actions.\x01Observe bien l'icône d'action!\x02", "box_type": 0},
    {"id": 0x1038, "text": "Je suis incollable sur la \x05\x41carte\x05\x40 et \x01les \x05\x41objets\x05\x40... Pose-moi n'importe\x01quelle question mais prépare-toi à  \x01de longues explications!\x04Bon alors, tu veux savoir quoi?\x01\x1C\x05\x42Ben...C'est quoi la carte?\x01Heu..Les objets... \x01Houlà! Me parle pas, toi!\x05\x40\x02", "box_type": 0},
    {"id": 0x1039, "text": "Il y a une \x05\x41carte\x05\x40 affichée dans le \x01coin en bas à droite.\x04La \x05\x46flèche jaune\x05\x40 montre ta position \x01et ton orientation actuelles. La \x01\x05\x41marque rouge\x05\x40 indique l'endroit par \x01lequel tu es entré sur cette carte.\x04Tu peux supprimer l'affichage de la \x01carte avec  \x05\x44¢\x05\x40.\x04Pour connaître le nom des divers\x01emplacements de la carte, appuie \x01sur \x05\x41START\x05\x40.\x04Tu feras alors apparaître le\x01\x05\x41Sous-Menu de la Carte\x05\x40.\x04Seront alors affichés la carte\x01générale d'Hyrule ainsi qu'une\x01multitude de renseignements!\x01Tu as bien tout compris?\x02", "box_type": 0},
    {"id": 0x103A, "text": "Les objets appartiennent à trois\x01catégories différentes:\x01l'\x05\x43Equipement\x05\x40, l'\x05\x46Inventaire\x05\x40 et \x01le \x05\x44Statut\x05\x40.\x04Les objets de\x05\x43 \x05\x40l'\x05\x43Equipement\x05\x40 sont  \x01les épées, les boucliers les \x01tuniques, etc... Equipe-les pour \x01les rendre actifs!\x04Ceux de l'\x05\x46Inventaire\x05\x40 peuvent être \x01assignés aux boutons \x05\x46§\x05\x40, \x05\x46¦\x05\x40 et \x01\x05\x46¨\x05\x40. Pour les utiliser, appuie sur \x01le bouton correspondant!\x04Ceux du \x05\x44Statut\x05\x40 sont des objets  \x01amassés au gré de l'aventure.\x01Tu ne peux que les porter!\x04Si tu veux organiser ton\x01équipement ou juste vérifier ton \x01inventaire, appuie sur \x05\x41START\x05\x40. Des \x01sous-menus apparaîtront!\x04Passe d'un sous-menu à l'autre \x01avec \x05\x44¤\x05\x40 ou \x05\x44£\x05\x40. Familiarise-toi \x01avec ce système!\x04Utilise \x05\x43\x05\x40 pour activer un \x01\x05\x43Equipement\x05\x40, et  \x05\x46§\x05\x40,\x05\x46 ¦ \x05\x40ou\x05\x46 ¨\x05\x40 \x01pour l'\x05\x46Inventaire\x05\x40.\x04Bwouff...C'était long!!!\x01J'espère que tu as bien tout \x01compris?\x02", "box_type": 0},
    {"id": 0x103B, "text": "Souviens-toi bien: pour \x01\x05\x42sauvegarder\x05\x40, appuie sur \x05\x41START\x05\x40 \x01pour accéder aux sous-menus puis \x01sur \x05\x42 \x05\x40!\x02", "box_type": 0},
    {"id": 0x103C, "text": "Ma soeur est partie faire des \x01emplettes à la Boutique au toit \x01rouge. Hi hi!\x04Au fait, un \x05\x41Rubis\x05\x40 \x05\x42vert\x05\x40 ne vaut \x01qu'un rubis, mais un \x05\x43bleu\x05\x40 en vaut\x01cinq et un \x05\x41rouge\x05\x40 en vaut vingt!\x01Hii hii hihi!\x02", "box_type": 0},
    {"id": 0x103D, "text": "Ce que propose cette boutique\x01se trouve dans la forêt!\x01Tii hii!\x04Tu sais comment ça s'utilise un \x01\x05\x41Bouclier Mojo\x05\x40, hein, tu l'sais??\x04Une fois acheté, appuie sur \x05\x41START\x01\x05\x40pour accéder aux sous-menus. \x01Sélectionne le \x05\x43sous-menu \x01Equipement \x05\x40avec \x05\x44¤\x05\x40 ou \x05\x44£\x05\x40.\x04Dans le \x05\x43Sous-Menu Equipement\x05\x40, \x01choisis l'objet qui t'intéresse et \x01active-le avec \x05\x43\x05\x40.\x04Une fois ton bouclier prêt,\x01brandis-le avec \x05\x44£\x05\x40 et change ton \x01angle de défense avec \x05\x44ª\x05\x40.\x01Tii hii!\x02", "box_type": 0},
    {"id": 0x103E, "text": "Veux-tu savoir comment utiliser\x01le \x05\x46bouton\x05\x40 \x05\x46¥\x05\x40?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x103F, "text": "Appuie sur \x05\x46¥ \x05\x40pour changer de \x01vue.\x04Dans un endroit comme celui-ci, \x01tu activeras une vue du dessus. \x01Mais à l'extérieur tu activeras une\x01vue subjective.\x04Quand \"\x05\x46Navi\x05\x40\" apparaît en haut de \x01l'écran, ta fée a quelque chose à\x01dire! Appuie alors sur \x05\x46¥ \x05\x40pour \x01l'écouter!\x02", "box_type": 0},
    {"id": 0x1040, "text": "C'est sûr, tu pourrais le découvrir\x01tout seul!\x02", "box_type": 0},
    {"id": 0x1041, "text": "Mouais...C'est pas exactement \x01comme ça, la chanson de Saria...\x02", "box_type": 0},
    {"id": 0x1042, "text": "Mido est vraiment furieux!\x01Que lui est-il arrivé?\x02", "box_type": 0},
    {"id": 0x1043, "text": "Quoi? Où tu vas?!\x04Au château?\x01C'est quoi un château?\x02", "box_type": 0},
    {"id": 0x1044, "text": "Un Kokiri ne peut quitter la forêt!\x01On dit souvent: \x01\"Qui n'en sort, n'en meurt!\"\x04...Comment ça?\x01Tu vas quitter la forêt?\x01Et notre proverbe?\x01T'en fais quoi?!\x02", "box_type": 0},
    {"id": 0x1045, "text": "\x1AHé, \x0F!\x01Qu'as-tu encore fait?!\x04\x1ALe très vénérable Arbre Mojo...\x01Il est...mort...?\x04\x1AComment as-tu pu faire une chose \x01pareille?! Tout est de ta faute!!\x01Nous allons tous mourir à cause \x01de toi!!!\x0B\x02", "box_type": 0},
    {"id": 0x1046, "text": "\x08Hé!!\x09\x01Qu'est-ce que tu trafiques \x01chez moi?!\x02", "box_type": 0},
    {"id": 0x1047, "text": "\x1A\x0F, tu vas bien?\x07\x10\x48\x02", "box_type": 0},
    {"id": 0x1048, "text": "Saria et \x0F seront \x01amis pour toujours.\x02", "box_type": 0},
    {"id": 0x1049, "text": "Il est arrivé quelque chose au \x01très vénérable Arbre Mojo?\x02", "box_type": 0},
    {"id": 0x104A, "text": "La forêt a changé... \x02", "box_type": 0},
    {"id": 0x104B, "text": "\x0F, \x01vas-tu nous quitter?\x02", "box_type": 0},
    {"id": 0x104C, "text": "Si jamais tu perds ton bouclier, \x01reviens nous voir!\x02", "box_type": 0},
    {"id": 0x104D, "text": "\x12\x38\x80Mes frères sont tous d'accord...\x01Tu es le sosie de notre totem!\x04\x12\x38\x80Accepte l'offrande de notre \x01communauté. Prends ces quelques \x01\x05\x41Bâtons\x05\x40 \x05\x41Mojo\x05\x40. Tu pourras \x01aussi en transporter plus!\x04Abracadabra!\x04\x12\x38\x80Alakazaaaam!\x0B\x02", "box_type": 0},
    {"id": 0x104E, "text": "Depuis la mort du très vénérable \x01Arbre Mojo de nombreux monstres\x01sont apparus dans la forêt...\x01J'ai très peur!\x02", "box_type": 0},
    {"id": 0x104F, "text": "\x1AUn vent diabolique nous vient du \x01Temple de la forêt.\x04\x1A\x05\x41Saria\x05\x40, avant de partir, nous a dit:\x01\"Je dois aller voir ce qu'il se \x01passe là-bas!\"\x07\x10\x50\x02", "box_type": 0},
    {"id": 0x1050, "text": "Le \x05\x42Temple de la Forêt se trouve\x01\x05\x40près du Bosquet Sacré au fond \x01des Bois Perdus.\x02", "box_type": 0},
    {"id": 0x1051, "text": "Saria est partie dans le temple, \x01mais elle n'en est jamais revenue...\x02", "box_type": 0},
    {"id": 0x1052, "text": "Hé, m'sieur! Vous pouvez pas \x01utiliser un Bouclier Mojo!\x01C'est pour les gamins!\x02", "box_type": 0},
    {"id": 0x1053, "text": "Hein? Où est Saria? \x01Vous la connaissez, Saria?\x01Heu...t'es un menteur, monsieur?\x07\x10\x54\x02", "box_type": 0},
    {"id": 0x1054, "text": "Mais où est donc \x05\x41Mido\x05\x40... \x01On a besoin de lui par ces temps \x01difficiles!\x02", "box_type": 0},
    {"id": 0x1055, "text": "Vous êtes entré dans la forêt \x01sans problème?\x04Les monstres ne vous ont pas \x01attaqué? Du temps du Vénérable \x01Arbre Mojo, vous n'auriez pas vu \x01de pareilles nuisances dans le coin.\x07\x10\x56\x02", "box_type": 0},
    {"id": 0x1056, "text": "C'est super dangereux dehors!\x01Alors je reste cloîtré chez moi!\x01....j'm'ennuie...\x02", "box_type": 0},
    {"id": 0x1057, "text": "Les \x05\x41flèches\x05\x40 ne sont que pour les\x01archers... Vous avez un \x05\x41arc\x05\x40, vous?\x02", "box_type": 0},
    {"id": 0x1058, "text": "\x1AAvez-vous beaucoup voyagé, \x01monsieur?\x01Avez-vous déja rencontré un \x01garçon nommé \x0F?\x04\x1AMido à raconté à tout le monde \x01que \x0F a tué le\x01vénérable Arbre Mojo...\x04\x1AIl n'y avait que Saria pour dire le \x01contraire!\x01Enfin...quand Saria était encore\x01parmi nous.\x07\x10\x59\x02", "box_type": 0},
    {"id": 0x1059, "text": "Qui peut savoir la vérité?\x02", "box_type": 0},
    {"id": 0x105A, "text": "On s'connaît, monsieur?\x02", "box_type": 0},
    {"id": 0x105B, "text": "\x1AMonsieur, connaissez-vous un \x01garçon du nom de \x0F?\x04\x1AIl a quitté la forêt et n'est jamais\x01revenu...\x07\x10\x5C\x02", "box_type": 0},
    {"id": 0x105C, "text": "Je me demande si \x0F  \x01reviendra un jour...\x02", "box_type": 0},
    {"id": 0x105D, "text": "\x1AEtre grand, c'est trop cool!\x01Je veux être une grosse brute \x01comme vous, m'sieur!\x04\x1AI Je voudrais être très grand et \x01très fort pour me battre contre \x01les Pestes Mojo, mais...je ne suis\x01que petit et faible...\x07\x10\x5E\x02", "box_type": 0},
    {"id": 0x105E, "text": "Nous les Kokiris ne seront jamais \x01grands...\x01C'est vraiment pas drôle!\x02", "box_type": 0},
    {"id": 0x105F, "text": "Pourquoi une fée vous suit \x01partout? Vous n'êtes pourtant pas \x01un Kokiri!\x02", "box_type": 0},
    {"id": 0x1060, "text": "\x1AMais qui êtes-vous? \x01Votre habit Kokiri ne marche pas!\x01Je ne suis pas né de la dernière\x01giboulée!\x07\x10\x61\x02", "box_type": 0},
    {"id": 0x1061, "text": "J'ai promis à Saria de ne laisser \x01passer personne.\x02", "box_type": 0},
    {"id": 0x1062, "text": "\x1ABonzour tout le monde! Ze suis le \x01\x05\x41Bourzeon de l'Arbre Mozo\x05\x40!\x04\x1AComme tu as brizé la malédiction\x01du Temple de la Forêt, ze peux \x01croître et fleurir!\x04\x1AMerzi beaucoup!\x02", "box_type": 0},
    {"id": 0x1063, "text": "\x1ATu as vu tes zanciens zamis?\x01Ze ne pense pas qu'ils te \x01reconnaissent avec ta grande \x01taille...\x04\x1AC'est parze que les \x05\x42Kokiris\x05\x40 ne \x01grandissent zamais! Même après \x01sept ans, ils restent des zenfants!\x02", "box_type": 0},
    {"id": 0x1064, "text": "\x1ATu dois te demander alors \x01pourquoi tu as grandi!\x04\x1ABon, comme tu as dézà dû le \x01deviner, tu n'es pas vraiment un \x01Kokiri! Tu es zen fait \x05\x44Hylien\x05\x40!\x04\x1AZe suis si content de te révéler\x01ce secret!\x02", "box_type": 0},
    {"id": 0x1065, "text": "Il y a très longtemps, il y eut \x01une guerre terrible, avant même \x01que le roi Hyrule n'unifie ce pays.\x0C\x5AUn zour, pour échapper à ce \x01conflit, une \x05\x41Maman Hylienne\x05\x40 et son \x01\x05\x41Petit Bébé\x05\x40 entrèrent dans cette \x01forêt interdite.\x0C\x5ACette pauvre maman était \x01gravement blessée. Son seul espoir\x01était de confier son bébé à l'Arbre\x01Mozo, l'esprit gardien de la forêt.\x0C\x5AL'Arbre Mozo pouvait dézà sentir \x01le pouvoir de cet enfant dont la \x01destinée allait affecter le monde \x01entier. Ainsi fut-il adopté...\x0C\x5AAprès la mort de sa pauvre \x01maman, il fut élevé comme un \x01\x05\x42Kokiri\x05\x40. Et désormais sa destinée\x01doit s'accomplir!\x0E\x5A\x02", "box_type": 2},
    {"id": 0x1066, "text": "\x1ATu es zun \x05\x44Hylien\x05\x40, depuis \x01touzours ze savais que tu \x01devais quitter la forêt.\x04\x1ATu connais ta propre destinée...\x01Tu sais ce qu'il te reste à \x01faire...\x04\x1ATu dois sauver Hyrule!\x04\x1AVa, \x0F... Dissipe la \x01malédiction zetée sur les temples\x01et rétablis paix et amour sur \x01Hyrule!!\x02", "box_type": 0},
    {"id": 0x1067, "text": "\x1A\x06\x34Cette melodie?!\x04\x1ASaria la jouait tout le temps!\x01Vous...connaissez Saria?\x04\x1ACette chanson...\x04\x1ASaria ne l'a enseignée qu'à ses\x01amis...\x07\x10\x6F\x02", "box_type": 0},
    {"id": 0x1068, "text": "Je ne sais pas pourquoi, mais... \x01Vous me rappelez...l'autre...\x02", "box_type": 0},
    {"id": 0x1069, "text": "\x1ACapturé dans l'enfer de ma \x01malédiction, assis sur le seuil de\x01la réalité et du rêve, il ne restera\x01de toi qu'un corps décharné!\x02", "box_type": 2},
    {"id": 0x106A, "text": "\x1AMerci, merci beaucoup...\x01Grâce à toi, je m'éveille à la \x01conscience de Sage...\x04\x1AJe suis \x05\x42Saria\x05\x40.\x01Sage du Temple de la Forêt...\x02", "box_type": 0},
    {"id": 0x106B, "text": "\x1A\x06\x26Saria sera toujours...\x01\x06\x44Ton amie...\x0E\x50\x02", "box_type": 5},
    {"id": 0x106C, "text": "\x1ALa course du temps est cruelle...\x01Sa vitesse est perçue différemment\x01par chacun, mais personne ne peut\x01la modifier...\x04\x1ASeule la mémoire des jours \x01anciens n'est pas altérée...\x04\x1APour revenir ici, joue le \x01\x05\x42Menuet des bois\x05\x40.\x02", "box_type": 0},
    {"id": 0x106D, "text": "\x1A\x0F...\x01A très bientôt...\x02", "box_type": 0},
    {"id": 0x106E, "text": "Saria n'est pas encore revenue...\x01Mais je sais qu'elle reviendra \x01bientôt...\x02", "box_type": 0},
    {"id": 0x106F, "text": "\x1AOK...\x01Je te fais confiance.\x07\x10\x68\x02", "box_type": 0},
    {"id": 0x1070, "text": "\x1AOh...Je vois...\x04\x1ASaria ne reviendra jamais...\x04\x1AMais...je...j'avais fait une promesse \x01à Saria...\x04\x1ASi \x0F revient un jour, \x01je voudrais lui dire que Saria \x01l'attend...\x04\x1AParce que \x14\x03Saria...aimait...\x14\x00\x07\x10\x71\x02", "box_type": 0},
    {"id": 0x1071, "text": "\x06\x46Mais toi...\x04Fais-lui le message...\x01S'il te plaît...\x07\x10\xD6\x02", "box_type": 0},
    {"id": 0x1072, "text": "Apprends-moi à me battre comme\x01toi! Tout ce que je sais faire \x01c'est appuyer sur \x05\x42 !\x01\x05\x40Haaa! Si j'avais lu les pancartes!\x02", "box_type": 0},
    {"id": 0x1073, "text": "Vous ressemblez à quelqu'un que \x01je connais, monsieur.\x02", "box_type": 0},
    {"id": 0x1074, "text": "Vous êtes tellement fort! Un jour, \x01je serai comme vous! Même si je \x01reste un nabot toute ma vie.\x02", "box_type": 0},
    {"id": 0x1075, "text": "\x0F... \x01Je me demande s'il reviendra\x01un jour...\x02", "box_type": 0},
    {"id": 0x1076, "text": "J'ai l'impression de vous connaître \x01depuis longtemps, monsieur!\x02", "box_type": 0},
    {"id": 0x1077, "text": "Le \x05\x41Bourgeon de l'Arbre Mojo \x01\x05\x40grandit paisiblement et la forêt\x01est de nouveau joyeuse!\x02", "box_type": 0},
    {"id": 0x1078, "text": "Nous assurerons tous ensemble la \x01protection de la forêt!\x02", "box_type": 0},
    {"id": 0x1079, "text": "Un vent paisible commence à \x01souffler sur la forêt.\x02", "box_type": 0},
    {"id": 0x107A, "text": "Ce vent paisible fera sûrement\x01revenir \x0F !\x02", "box_type": 0},
    {"id": 0x107B, "text": "Je me demande si Saria va revenir.\x02", "box_type": 0},
    {"id": 0x107C, "text": "\x0F reviendra un jour!\x01C'est certain!\x02", "box_type": 0},
    {"id": 0x107D, "text": "\x1A\x06\x1F\x05\x44Vénérable Arbre Mojo...\x01\x05\x40\x06\x2D\x05\x44Je suis de retour!\x05\x40\x02", "box_type": 0},
    {"id": 0x107E, "text": "\x1AL'homme maléfique ne cesse de \x01faire appel à ses sombres et vils \x01pouvoirs pour trouver le Saint \x01Royaume relié à Hyrule...\x04\x1ACar dans le Saint Royaume \x01sommeille la divine relique, la \x01\x05\x44Triforce\x05\x40, renfermant des pouvoirs\x01comparables à ceux des dieux...\x02", "box_type": 2},
    {"id": 0x107F, "text": "\x08\x06\x1AAvant le début du temps,\x01\x06\x2Aavant que vie et \x01\x06\x2Fesprit n'existent...\x09\x0E\x50\x02", "box_type": 4},
    {"id": 0x1080, "text": "\x08\x06\x07Trois déesses d'or et de lumière\x01\x06\x05descendirent sur l'amas chaotique\x01\x06\x1Equ'allait devenir Hyrule...\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x1081, "text": "\x08\x06\x1ADin, déesse de la Force...\x09\x0E\x3C\x02", "box_type": 4},
    {"id": 0x1082, "text": "\x08\x06\x12Nayru, déesse de la Sagesse...\x09\x0E\x3C\x02", "box_type": 4},
    {"id": 0x1083, "text": "\x08\x06\x13Farore, déesse du Courage...\x09\x0E\x3C\x02", "box_type": 4},
    {"id": 0x1084, "text": "\x08\x06\x53Din...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1085, "text": "\x08\x06\x1FDe ses bras enflammés,\x01\x06\x28elle sculpta le sol et\x01\x06\x29créa la terre rouge.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x1086, "text": "\x08\x06\x4CNayru...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1087, "text": "\x08\x06\x12Elle inonda de sa sagesse la\x01\x06\x10terre et apporta ordre et loi\x01\x06\x3Asur ce monde.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x1088, "text": "\x08\x06\x4BFarore...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1089, "text": "\x08\x06\x0DDe son âme infinie, elle donna\x01\x06\x0Evie aux êtres issus de l'ordre\x01\x06\x40et de la loi.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x108A, "text": "\x08\x06\x2BLes trois déesses, \x01\x06\x24leur oeuvre accomplie,\x01\x06\x06s'en retournèrent vers les cieux.\x09\x0E\x5A\x02", "box_type": 4},
    {"id": 0x108B, "text": "\x08\x06\x09Leur départ fit alors apparaître\x01\x06\x2Dtrois triangles d'or,\x01\x06\x0Cseuls vestiges de leur pouvoir.\x09\x0E\x5A\x02", "box_type": 4},
    {"id": 0x108C, "text": "\x08\x06\x12Depuis, les triangles sacrés\x01\x06\x1Bsymbolisent l'essence de \x01\x06\x38notre création.\x09\x0E\x5A\x02", "box_type": 4},
    {"id": 0x108D, "text": "\x08\x06\x2FEt depuis ce jour,\x01\x06\x06Le Saint Royaume est le berceau\x01\x06\x1Edes triangles de justice.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x108E, "text": "Alors moucheron... Tu as appris à\x01combattre! Tu revendiques le sang\x01des guerriers...\x0C\x3CTu n'as vaincu que mon faible\x01spectre... Quand l'heure de \x01l'affrontement sonnera, l'ombre du\x01trépas sera sur toi.\x0C\x3CCe fantôme était une création \x01pitoyable, je vais le bannir par-delà\x01les seuils dimensionnels!!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x108F, "text": "\x1AJ'ai toujours su que tu reviendrais.\x01Je le savais, je te connais bien...\x04\x1ANon...\x0C\x1E\x1ATu n'as pas besoin de te justifier\x01devant moi...\x04\x1ALe destin n'a pas voulu que nous\x01vivions dans le même monde.\x02", "box_type": 0},
    {"id": 0x1090, "text": "\x1AEn temps que Sage de la forêt, \x01ma place est ici...\x04\x1ATiens... Prends ce \x05\x42Médaillon\x05\x40...\x02", "box_type": 0},
    {"id": 0x1091, "text": "\x1ATu as fait preuve de courage\x01et de sagesse...\x04\x1ATu te révèles digne de mon estime\x01et de ma confiance...\x02", "box_type": 0},
    {"id": 0x1092, "text": "J'ai encore bien des choses à te\x01dire veux-tu bien les écouter?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x1093, "text": "\x1A\x0F...\x01Va au Château d'Hyrule...\x04\x1ATu y rencontreras la \x01\x05\x41Princesse de la Destinée\x05\x40...\x04\x1APrends cette \x05\x41Pierre\x05\x40...\x01Elle est la cause de la malédiction\x01jetée sur moi par l'homme sombre.\x02", "box_type": 0},
    {"id": 0x1094, "text": "\x1AJ'ai toujours su qu'un jour...\x01Tu quitterais la forêt,\x01\x0F...\x04\x1ACar tu es différent de nous...\x02", "box_type": 0},
    {"id": 0x1095, "text": "\x1A\x12\x68\x44\x05\x44Hé, \x08\x0F\x09!\x01Debout! Maintenant!\x05\x40\x04\x1A\x05\x44Le très \x05\x41vénérable Arbre Mojo \x01\x05\x44veut te parler!\x01Réveille-toi, \x0F!\x05\x40\x02", "box_type": 0},
    {"id": 0x1096, "text": "\x1A\x12\x68\x5F\x05\x44\x08Ho!\x09 Tu vas te lever, oui?\x05\x40\x04\x1A\x05\x44La destinée d'Hyrule repose-t-elle \x01sur un garçon aussi paresseux?\x05\x40\x02", "box_type": 0},
    {"id": 0x1097, "text": "Sauter, c'est plus à la mode. \x01Moi j'fais des \x05\x41sauts périlleux\x05\x40!\x01Tu sais en faire un, toi?\x02", "box_type": 0},
    {"id": 0x1098, "text": "\x1A\x05\x44Le très \x05\x41vénérable Arbre Mojo \x05\x44\x01veut te parler!\x01Allons-y tout de suite!\x05\x40\x02", "box_type": 0},
    {"id": 0x1099, "text": "\x1A\x06\x4BNavi...\x01\x06\x37Navi, où es-tu?\x01\x06\x3CViens à moi...\x02", "box_type": 5},
    {"id": 0x109A, "text": "\x1A\x05\x44Navi la fée\x05\x40...\x01Ecoute mes paroles, les paroles du\x01très vénérable\x05\x41 Arbre Mojo\x05\x40...\x04\x1ASens-tu le danger qui rôde?\x01Cette aura ténébreuse qui s'abat \x01sur le royaume...\x04\x1ADes forces maléfiques s'activent\x01dans l'ombre et préparent l'invasion\x01d'Hyrule...\x04\x1ADepuis toujours la \x05\x41Forêt Kokiri\x05\x40\x01s'élève comme un rempart contre \x01les forces chaotiques, assurant le\x01maintien de l'ordre et de la loi...\x04\x1AMais face à ce pouvoir terrifiant\x01et infernal, mes forces ne sont\x01que misère...\x04\x1ALe temps est venu pour ce \x05\x41garçon \x01sans fée \x05\x40de commencer son \x01périple...\x04\x1ACet enfant dont la destinée est\x01de conduire Hyrule sur la voie de \x01la justice et de la vérité...\x04\x1AVa... \x05\x44Navi\x05\x40! Trouve notre jeune ami \x01et présente-le devant moi...\x04\x1AIl ne me reste que peu de temps.\x04\x1AVole, Navi, vole! Le destin de la \x01forêt, que dis-je, du monde dépend\x01de toi!!!\x02", "box_type": 0},
    {"id": 0x109B, "text": "\x1A\x12\x38\x82Pitié, Seigneur! Je ne le ferai \x01plus jamais! Epargne-moi et je te \x01donne un indice.\x04\x1A\x12\x38\x80Tu ne pourras jamais battre mes \x01frères si tu ne respectes pas un\x01ordre précis!\x04\x1A\x12\x38\x80Le bon ordre est...\x14\x05\x05\x442 - 3 - 1!\x05\x40\x14\x00\x01\x08\x05\x44Vingt-trois est numéro un! Ha ha!\x05\x40\x09\x04\x1A\x12\x38\x80Tu crois que j'suis un traître?\x0B\x02", "box_type": 0},
    {"id": 0x109C, "text": "\x1A\x12\x38\x82Qui t'a donné notre secret?!\x01Hmmm... \x08ça me rend dingue!\x09\x04\x1A\x12\x38\x80J'suis tellement en pétard que je \x01vais te dire le point faible de \x01\x05\x41Gohma notre Reine\x05\x40!\x04\x1A\x12\x38\x80Pour lui administrer le coup de \x01grâce, frappe son oeil avec ton \x01épée après l'avoir \x05\x41étourdie\x05\x40.\x04\x1AOh ma Reine, ma p'tite Reine...\x04\x12\x38\x80\x08\x06\x1BJe ne suis qu'un traître!\x09\x0B\x02", "box_type": 0},
    {"id": 0x109D, "text": "Dans l'immense forêt d'Hyrule...\x0C\x28\x06\x0BLes siècles m'ont choisi comme\x01\x06\x0Fle gardien spirituel des bois...\x01\x06\x1FJe suis... l'Arbre Mojo...\x0E\x46\x02", "box_type": 4},
    {"id": 0x109E, "text": "\x06\x0FLes Kokiris sont mes enfants.\x01\x06\x0FIls sont le peuple de la forêt.\x0C\x3C\x06\x0ADès la naissance, chaque Kokiri\x01\x06\x3Creçoit sa fée.\x0E\x3C\x02", "box_type": 4},
    {"id": 0x109F, "text": "\x06\x19Mais seul un jeune garçon\x01\x06\x2An'avait pas de fée...\x0E\x3C\x02", "box_type": 4},
    {"id": 0x10A0, "text": "\x12\x38\x82Je me rends, c'est bon! En \x01échange je veux bien te vendre \x01des Noix Mojo!\x01\x05\x415 unités   20 Rubis\x05\x40, c'est le prix!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10A1, "text": "\x12\x38\x82T'es le plus fort! Je vais\x01te vendre des Bâtons Mojo, tiens!\x01\x05\x411 unité   15 Rubis, \x05\x40t'en veux?\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10A2, "text": "\x12\x38\x82J'abandonne! Tu veux bien \x01m'acheter des coeurs?\x01\x05\x411 unité   10 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10A3, "text": "\x12\x38\x80\x08Alors...ça marche?\x01\x01\x1B\x05\x42OK\x01Non, jamais!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x10A4, "text": "\x12\x38\x82\x08GLOPS!!\x09\x01J'me rentre, si c'est comme ça!\x02", "box_type": 0},
    {"id": 0x10A5, "text": "\x12\x38\x82Pas assez de rubis!\x01Reviens plus tard!\x02", "box_type": 0},
    {"id": 0x10A6, "text": "\x12\x38\x82T'en as plein tes poches!\x01reviens plus tard!\x02", "box_type": 0},
    {"id": 0x10A7, "text": "\x12\x38\x80\x08\x06\x41Merci bien!\x09\x0B\x02", "box_type": 0},
    {"id": 0x10A8, "text": "\x1AJe t'attendais,\x01\x0F!\x04\x1ANous sommes ici dans le \x05\x41Bosquet \x01Sacré\x05\x40. C'est mon jardin secret!\x01J'ai le sentiment que...\x04\x1ACet endroit sera très important \x01pour nous deux. J'en suis sûre!\x04\x1AJoue de l'ocarina ici et tu pourras\x01parler avec les esprits de la forêt.\x07\x10\xA9\x02", "box_type": 0},
    {"id": 0x10A9, "text": "Veux-tu jouer de l'ocarina \x01avec moi?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x10AA, "text": "\x1AEssaie de suivre cette mélodie.\x01Tu es prêt?\x02", "box_type": 0},
    {"id": 0x10AB, "text": "\x1AHeu?!\x01T'es pas drôle!\x01Allez! Jouons ensemble!\x02", "box_type": 0},
    {"id": 0x10AC, "text": "\x1A\x12\x68\x63\x06\x3ABravo! Bravo!\x04\x1AN'oublie jamais cette mélodie!\x01Tu me le promets?\x07\x10\xAD\x02", "box_type": 0},
    {"id": 0x10AD, "text": "Entonne le \x05\x42Chant de Saria \x05\x40si tu \x01as besoin de me parler...\x02", "box_type": 0},
    {"id": 0x10AE, "text": "Prends-tu bien soin de mon \x01ocarina?\x02", "box_type": 0},
    {"id": 0x10AF, "text": "\x1A\x12\x38\x80Whoaa!\x01Tu es très fort!\x01Trois fois dans le mille!\x04\x1A\x12\x38\x80Je me sens obligé de t'offrir\x01un cadeau! Prends donc ceci!\x0B\x02", "box_type": 0},
    {"id": 0x10B0, "text": "S'il y a quelqu'un pour savoir ce\x01que fait Saria, c'est bien Mido!\x04Il est sûrement dans le coin.\x02", "box_type": 0},
    {"id": 0x10B1, "text": "\x06\x5A\x05\x44??\x01\x05\x40\x06\x15\x05\x44Pas de réponse. Il doit dormir.\x05\x40\x02", "box_type": 0},
    {"id": 0x10B2, "text": "\x1AUn P'tit Poulet?  Comment ça?\x01Seul un chic type comme moi peut\x01s'en occuper...\x04\x1ACe qui veut dire que...\x04\x1A\x14\x01Toi... \x14\x00Toi aussi, tu es un chic type!\x01\x08Incroyable!\x09\x01\x08Un chic type! Un vrai!\x09\x01Oh, je t'en supplie...\x04\x1AApporte ceci à l'\x05\x41Apothicaire\x05\x40 du\x01village Cocorico!\x0B\x02", "box_type": 0},
    {"id": 0x10B3, "text": "Dépêche-toi sinon ceci va pourrir!\x01\x01\x1B\x05\x42OK\x01J'peux pas!\x05\x40\x02", "box_type": 0},
    {"id": 0x10B4, "text": "Ha bon. \x08Tu l'prends comme ça?\x09\x01T'es pas si chic que ça, alors!!\x01\x08Dégage!\x09\x02", "box_type": 0},
    {"id": 0x10B5, "text": "Saria te cherchait...\x01L'as-tu vue?\x02", "box_type": 0},
    {"id": 0x10B6, "text": "Grouille-toi, mon nouveau copain!\x01Apporte-le à la vieille peau, avant \x01qu'il ne soit trop tard...\x02", "box_type": 0},
    {"id": 0x10B7, "text": "\x1ALe garçon n'est plus ici.\x04\x1AUn Hylien perdu dans la forêt est\x01un Hylien de moins! (proverbe)\x04\x1AUn Hylien perdu dans la forêt \x01devient un monstre......\x01Il ne reste que sa scie. Hii hii.\x07\x10\xB8\x02", "box_type": 0},
    {"id": 0x10B8, "text": "La mixture est à base de champi-\x01gnons. Voulez-vous la rendre?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x10B9, "text": "Hi hi hi hi!\x01Vas-tu te transformer en monstre,\x01toi aussi?\x02", "box_type": 0},
    {"id": 0x10BA, "text": "Nous vendons des boucliers, mais\x01pas d'épées!\x0B\x02", "box_type": 0},
    {"id": 0x10BB, "text": "\x1ATu connais le \x05\x42Chant de Saria\x05\x40! \x01Alors soyons amis! \x01Tiens, prends donc ceci!\x02", "box_type": 0},
    {"id": 0x10BC, "text": "Salut! Ne trouves-tu pas que mon\x01visage n'a rien d'extraordinaire?\x01J'aimerais avoir du style...\x02", "box_type": 0},
    {"id": 0x10BD, "text": "Reviens jouer quand tu veux!\x02", "box_type": 0},
    {"id": 0x10BE, "text": "\x1AAccompagne-nous avec ton ocarina. \x01Nous allons te donner le rythme.\x02", "box_type": 0},
    {"id": 0x10BF, "text": "\x1AQuelle belle prestation!\x01En gage de notre amitié, \x01accepte donc ceci.\x02", "box_type": 0},
    {"id": 0x10C0, "text": "\x1AHé ho! Par ici!\x01Hou hou!\x0C\x28\x1A\x0F... \x01Quel plaisir de te voir! \x01Ecoute donc mes sages paroles!\x01Hou hou....\x07\x10\xC1\x02", "box_type": 0},
    {"id": 0x10C1, "text": "Après avoir traversé les Bois \x01Perdus tu arriveras au \x05\x42Bosquet\x01Sacré\x05\x40.\x04Ce saint domaine ne fut exploré\x01que par très peu d'aventuriers.\x04Chuuut... Ecoute...\x01J'entends un chant mystérieux...\x04Tu devrais tendre l'oreille à\x01ton tour! Hou hou hou!\x0B\x02", "box_type": 0},
    {"id": 0x10C2, "text": "Veux-tu que je répète tout ça?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x10C3, "text": "\x1ASois courageux et la forêt ne\x01te posera pas de problèmes...\x04\x1AFais confiance à tes oreilles,\x01dirige-toi grâce aux sons de \x01la forêt! Hou hou!\x02", "box_type": 0},
    {"id": 0x10C4, "text": "\x1AHou hou!\x0C\x28\x1ASaria t'a-t-elle appris une chanson?\x04\x1ACette mélodie semble avoir de \x01mystérieux pouvoirs.\x04\x1ATu apprendras sûrement d'autres \x01chants au gré de ton périple...\x07\x10\xC5\x02", "box_type": 0},
    {"id": 0x10C5, "text": "Utilise ton ocarina avec les \x01boutons \x05\x46¡\x05\x40 au bon endroit et une \x01\x05\x41portée \x05\x40apparaîtra.\x04Je te conseille alors de jouer un \x01chant que tu connais.\x04Je te conseille aussi de jouer\x01même si la portée n'apparaît pas.\x01Comme ça:\x01Hou hou hou hout hout hout!\x0B\x02", "box_type": 0},
    {"id": 0x10C6, "text": "Veux-tu que je répète tout ça?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x10C7, "text": "\x1ALes mélodies que tu apprendras\x01seront enregistrées dans le \x01\x05\x44Sous-Menu du Statut\x05\x40.\x02", "box_type": 0},
    {"id": 0x10C8, "text": "\x1AOhh...Le vilain! Je ne sais \x01pas pourquoi il est si méchant\x01avec tout le monde!\x04\x1AMême s'il a raison cette fois-ci!\x07\x10\xC9\x02", "box_type": 0},
    {"id": 0x10C9, "text": "\x1AIl se passe des choses étranges \x01dans la forêt...\x04\x1ASois prêt à tout!\x01Tu ferais mieux de te trouver une \x01arme!\x07\x10\x32\x02", "box_type": 0},
    {"id": 0x10CA, "text": "\x12\x38\x82Paix! Gentil! T'as gagné! \x01Veux-tu des \x05\x41Graines Mojo\x05\x40?\x01\x05\x4130 unités   40 Rubis, \x05\x40pas cher!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CB, "text": "\x12\x38\x82J'me rends! Laisse-moi partir et \x01je te vends un Bouclier Mojo pour\x01\x05\x4150 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CC, "text": "\x12\x38\x82J'abandonne! Veux-tu des \x05\x41bombes\x05\x40?\x01\x05\x415 unités   40 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CD, "text": "\x12\x38\x82C'est bon! Laisse-moi tranquille\x01et je te vends des \x05\x41flèches\x05\x40!\x01\x05\x4130 unités   70 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CE, "text": "\x12\x38\x82T'as gagné! Epargne-moi et je te\x01vends une \x05\x41potion rouge\x05\x40 pour \x01\x05\x4140 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CF, "text": "\x12\x38\x82T'as gagné! Epargne-moi et je te \x01vends une \x05\x42potion verte\x05\x40 pour \x01\x05\x4140 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10D0, "text": "\x1AQuoi?!? Tu as une fée?!\x01Comment? Le Vénérable Arbre \x01Mojo t'a convoqué?\x07\x10\xD1\x02", "box_type": 0},
    {"id": 0x10D1, "text": "\x1A\x06\x33Heiiiiinnnnnnnn?!\x04\x1AEt pourquoi j'suis pas \x01convoqué, moi le grand \x05\x41Mido\x05\x40? \x04\x1AC'est pas juste...\x04\x1AJ'te crois pas!\x01Tu n'es même pas équipé!\x04\x1AComment pourrais-tu aider le \x01Vénérable Arbre Mojo sans \x05\x42épée\x05\x40 \x01ni \x05\x44bouclier\x05\x40, hein!?\x04Quoi? \x01Ok, mon équipement non plus n'est\x01pas prêt mais...\x01Et puis de quoi j'me mêle?\x07\x10\x30\x02", "box_type": 0},
    {"id": 0x10D2, "text": "\x1A\x06\x24Heu... C'est quoi ça?!\x04\x1AOh! Tu as un \x05\x44Bouclier\x05\x40 \x05\x44Mojo\x05\x40...\x04\x1AEt pis ça c'est quoi?!\x04\x1AMais... C'est l'\x05\x42Epée\x05\x40 \x05\x42Kokiri\x05\x40!?\x04\x1A\x06\x30BEN CA ALORS!!\x07\x10\xD3\x02", "box_type": 0},
    {"id": 0x10D3, "text": "\x1AEnfin... Même avec tout ça,\x01une mauviette est toujours une \x01mauviette, hein?\x07\x10\x34\x02", "box_type": 0},
    {"id": 0x10D4, "text": "\x12\x38\x82Houlà! Doucement! J'ai perdu mais\x01je peux te vendre des \x01\x05\x41Bâtons\x05\x40 \x05\x41Mojo \x05\x40pour \x05\x4115 Rubis\x05\x40.\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10D5, "text": "\x12\x38\x82Perdu! Dommage pour moi! \x01Veux-tu des \x05\x41Noix\x05\x40 \x05\x41Mojo\x05\x40?\x01\x05\x415 unités   20 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10D6, "text": "Et aussi...\x04\x08\x06\x3ADis-lui aussi...\x09\x04\x06\x32Que je m'excuse.\x02", "box_type": 0},
    {"id": 0x10D7, "text": "Hii hii hii!\x01Tu es arrivé jusqu'ici tout seul? \x01Comme un grand?\x01T'es un homme, un vrai de vrai!\x07\x10\xD8\x02", "box_type": 0},
    {"id": 0x10D8, "text": "Regarde! Belle vue, non?\x01Tu peux changer ton angle de vue \x01avec \x05\x46¥\x05\x40 et ainsi admirer la forêt \x01avec \x05\x44ª\x05\x40.\x02", "box_type": 0},
    {"id": 0x10D9, "text": "Qu'as-tu fait au très vénérable \x01Arbre Mojo?\x02", "box_type": 0},
    {"id": 0x10DA, "text": "Avant d'aller dans les Bois Perdus, \x01il te faudra d'abord te trouver le \x01bon équipement!\x01Hii hii!\x02", "box_type": 0},
    {"id": 0x10DB, "text": "\x12\x38\x82Tous mes frères sont d'accord: \x01Ta face est trop moche...\x04\x12\x38\x82Mais ne pleure pas! \x01On va te donner des \x05\x41Noix Mojo\x05\x40.\x04\x12\x38\x82Nous allons aussi te donner le \x01pouvoir d'en porter plus!\x04Abracadabra...\x04\x12\x38\x80Alakazaaaam!!\x0B\x02", "box_type": 0},
    {"id": 0x10DC, "text": "\x12\x38\x82J'me rends!\x04\x12\x38\x80Pour faciliter ta quête, je peux\x01te donner le pouvoir de porter \x01plus de \x05\x41Bâtons Mojo\x05\x40!\x01Cela te coûtera \x05\x4140 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10DD, "text": "\x12\x38\x82J'me rends!\x04\x12\x38\x80Pour faciliter ta quête, je peux\x01te donner le pouvoir de porter \x01plus de \x05\x41Noix\x05\x40 \x05\x41Mojo\x05\x40!\x01Cela te coûtera \x05\x4140 Rubis\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10DE, "text": "\x12\x38\x82Yaaaa! Dommage! \x01Pas d'argent, pas d'amis!\x02", "box_type": 0},
    {"id": 0x10DF, "text": "Le garçon n'est plus ici.\x04Un Hylien dans la forêt est un\x01Hylien de moins. (proverbe)\x04Il est devenu un monstre.\x01Comme tous les autres.\x02", "box_type": 0},
    {"id": 0x2000, "text": "\x1AMerci encore pour l'autre jour...\x01Au fait...\x01Je ne connais même pas ton nom!\x04\x1A\x14\x02........\x14\x00\x04\x1AVraiment?\x01\x0F!\x04\x1A\x08J'en étais sûre!\x09\x01Tu es le garçon de la forêt! \x01Cela fait si longtemps!\x01Tu te souviens de moi?\x04\x1AOui? J'étais certaine de t'avoir\x01déjà rencontré quand Epona est \x01venue vers toi!\x04\x1AOh, au fait... Je dois te parler de\x01\x05\x41Monsieur Ingo\x05\x40...\x04\x1AIl craignait que le Roi Sombre\x01n'apprenne qu'Epona a disparu...\x01Il était si préoccupé!\x04\x1AMais un beau jour, sans crier gare,\x01il redevint un \x05\x41homme gentil\x05\x40!\x04\x1AMon père est maintenant de \x01retour au Ranch...\x01C'est incroyable, la paix est \x01revenue!\x04\x1AEt tout ça grâce à toi!\x01Je te suis si reconnaissante!\x04\x1AMerci infiniment,\x01\x0F!\x02", "box_type": 0},
    {"id": 0x2001, "text": "Comment se porte \x05\x41Epona\x05\x40?\x04Si tu joues le \x05\x41Chant d'Epona\x05\x40 avec \x01ton ocarina, elle viendra vers toi.\x04Reviens vite au Ranch si tu veux\x01\x05\x41entraîner \x05\x40Epona!\x02", "box_type": 0},
    {"id": 0x2002, "text": "\x1AEpona\x05\x41 \x05\x40est en pleine forme!\x01On dirait que tu as réussi à la \x01dompter, toi aussi!\x07\x20\x03\x02", "box_type": 0},
    {"id": 0x2003, "text": "Pourquoi ne pas mettre tes talents\x01de cavalier à l'épreuve avec une\x01petite \x05\x41course d'obstacle\x05\x40?\x04Je relèverai ton temps pour \x01\x05\x41deux tours\x05\x40. Tu perdras si tu ne \x01sautes pas toutes les barrières\x01dans le bon ordre.\x04Qu'en dis-tu?\x01Tu veux tenter ta chance? \x01\x1B\x05\x42C'est parti!\x01Pas question\x05\x40\x02", "box_type": 0},
    {"id": 0x2004, "text": "Ton temps est de \x05\x41\x17\x05\x40.\x01Il te faut plus d'entraînement!\x04Souviens-toi bien: tu n'as besoin\x01d'accélérer que pour sauter de\x01grandes barrières!\x02", "box_type": 0},
    {"id": 0x2005, "text": "\x1A\x06\x09\x0F... M'entends-tu?\x01\x06\x30C'est moi...Zelda...\x0E\x3C\x02", "box_type": 5},
    {"id": 0x2006, "text": "\x12\x28\xDFMeuuuuuuu!\x04Quel chant mélooooodieux...\x01Il me rappelle les verts pâturages\x01de ma jeuuuuunesse...\x04Je me sens si repooooosée!\x0B\x02", "box_type": 0},
    {"id": 0x2007, "text": "Prends donc un peu de mooooon \x01déliceuuuuux lait!\x0B\x02", "box_type": 0},
    {"id": 0x2008, "text": "\x0F, quand tu trouveras\x01cet ocarina...\x0C\x3CJe serai déjà si loin...\x0C\x3CMalgré mes efforts, je n'ai pu \x01retarder ma fuite...\x0C\x3CJe ne peux t'offrir que cet\x01ocarina ainsi que \x05\x44cette melodie\x05\x40...\x0E\x3C\x02", "box_type": 2},
    {"id": 0x2009, "text": "\x1AVa, \x0F.\x01Entonne ce chant devant l'autel du\x01Temple du Temps.\x01Tu dois protéger la Triforce!\x02", "box_type": 5},
    {"id": 0x200A, "text": "\x1AWha-ha-ha-hah! Alors comme ça \x01on s'déguise, p'tite tête?\x04\x1A\x06\x57Oh?\x04\x1AN'est-ce pas un Masque du... \x01Comment déjà...putois? Non...\x01Du Renard?\x04\x1AMon gamin en est marteau!\x01Tu veux bien me le vendre alors \x01ce \"Masque du...truc...bidule...\"?\x01Allez, sois chic.\x07\x20\x0B\x02", "box_type": 0},
    {"id": 0x200B, "text": "Marché conclu?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x200C, "text": "Je ne lâcherai pas le morceau!\x01J'ai de la patience, tu sais!\x01Il en faut pour faire un boulot \x01comme le mien!  Hah hah hah!\x0B\x02", "box_type": 0},
    {"id": 0x200D, "text": "\x1AMmmm...(baille)...quoi?...\x01Hein? Ouais, ouais. J'suis réveillé!\x04\x1AComment?\x04\x1AHé, c'est toi? Bien le bonjour!\x04\x1AQuelle histoire!\x01Malon n'a pas arrêté de me crier\x01dessus!\x04\x1ATu nous as bien aidés...\x01Je suis fier de t'offrir ce \x05\x41lait\x05\x40!\x01Tu peux garder la bouteille.\x02", "box_type": 0},
    {"id": 0x200E, "text": "Au-delà de cette limite, la \x05\x41route \x01est fermée\x05\x40!\x01N'as-tu pas lu la pancarte,\x01là-bas?\x04Ah, je vois. Tu n'es qu'un gamin et\x01tu ne sais pas encore lire, hein?\x01Tu t'paies ma tête?\x02", "box_type": 0},
    {"id": 0x200F, "text": "J'en veux pas d'ce machin!\x02", "box_type": 0},
    {"id": 0x2010, "text": "\x1AOh, n'est-ce pas...\x01Mais si! C'est l'écriture de la\x01Princesse Zelda! Voyons voir...\x04\x1A\x06\x06\"\x05\x45Ce preux chevalier se nomme\x01\x05\x40\x06\x06\x05\x45\x0F...\x01\x05\x40\x06\x06\x05\x45Sa noble quête est de sauver \x01\x05\x40\x06\x06\x05\x45Hyrule.\x05\x40\"\x04\x1AWah ha ha ha ha!\x01C'est quoi cette histoire?\x01Encore un jeu de la Princesse!\x04\x1AOK, OK, très bien. Je te laisse\x01passer... Sois quand même prudent,\x01Preux Chevalier! Wah hah ha ha!\x0B\x02", "box_type": 0},
    {"id": 0x2011, "text": "Oh, le Preux Chevalier!\x01Merci de sauver Hyrule!\x01\x14\x01Wah ha ha hah\x14\x00!!\x02", "box_type": 0},
    {"id": 0x2012, "text": "Woah! Génial!\x01Ton temps est de \x05\x41\x17\x05\x40!\x01Toi et Epona êtes faits l'un pour\x01l'autre!\x02", "box_type": 0},
    {"id": 0x2013, "text": "Ooooooh, quel doooommage.\x01Si tu avais une bouteille, j'aurais \x01pu t'offrir un peu de lait...\x0B\x02", "box_type": 0},
    {"id": 0x2014, "text": "Mon nom est \x05\x41Ingo\x05\x40--Monsieur Ingo.\x01Je prends soin des chevaux.\x01J'ai du boulot... Dégage!\x02", "box_type": 0},
    {"id": 0x2015, "text": "\x1AAu fait, Preux Chevalier...\x04\x1ASi tu comptes t'attaquer au\x01Sommet du Péril, équipe-toi du bon\x01\x05\x44bouclier\x05\x40! \x01Ce volcan est en activité!\x04\x1ASi tu retournes au marché,\x01va au Bazar. Ils auront un bouclier\x01pour toi!\x04\x1ADis bien que tu viens de ma part,\x01ils te feront un prix!\x04\x1AEn échange, j'aimerais que tu me\x01rendes un p'tit service...\x01Tu n'es pas obligé, mais...\x01On ne sait jamais!\x04\x1AEs-tu déjà allé à la \x05\x41Foire aux \x01Masques\x05\x40 sur la place du marché?\x01Tout le monde en parle!\x04\x1AMon gamin veut absolument un\x01masque à la mode mais je n'ai pas\x01le temps de m'y rendre...\x04\x1APourrais-tu y aller pour moi?\x01Encore une fois, rien ne t'oblige\x01à me rendre ce service...\x04\x1AMon boulot est vraiment nul.\x04\x1A\x06\x4B...pfff...\x0B\x02", "box_type": 0},
    {"id": 0x2016, "text": "J'aimerais tant pouvoir me rendre \x01à la \x05\x41Foire aux Masques \x05\x40...\x04\x06\x4B...pfff...\x02", "box_type": 0},
    {"id": 0x2017, "text": "Il est bel et bien mort...\x02", "box_type": 2},
    {"id": 0x2018, "text": "\x0F!?\x02", "box_type": 0},
    {"id": 0x2019, "text": "\x1A\x08\x06\x10Tssss...!\x09 Elle s'est échappée!\x02", "box_type": 0},
    {"id": 0x201A, "text": "\x1A\x06\x41Toi, là-bas!\x01\x06\x41\x08Moucheron!\x09\x02", "box_type": 0},
    {"id": 0x201B, "text": "\x1A\x06\x43\x14\x0A\x08Ha\x09 \x08ha\x09 \x08ha\x09...\x14\x00\x01\x06\x1ATu cherches le contact?!\x01\x06\x3CBonne blague!\x01\x06\x1CTu es brave, mais sot!\x02", "box_type": 0},
    {"id": 0x201C, "text": "\x1A\x08\x06\x34Insecte ridicule!\x09\x01\x06\x19Sais-tu bien qui je suis?!\x02", "box_type": 0},
    {"id": 0x201D, "text": "\x1A\x06\x2DJe suis \x05\x41Ganondorf\x05\x40!\x01\x08\x06\x04Et sous peu, le monde sera mien!\x09\x02", "box_type": 0},
    {"id": 0x201E, "text": "\x1A\x06\x03Un destrier blanc vient de passer\x01\x06\x2Eil y a un instant...\x01\x06\x26Par où s'est-il enfui?\x01\x06\x46\x08Réponds!!\x09\x02", "box_type": 0},
    {"id": 0x201F, "text": "Tsss... Bientôt je te ficherai\x01tout ça dehors.\x02", "box_type": 0},
    {"id": 0x2020, "text": "Mon gamin sera fou de joie!\x01Tu es vraiment un Preux Chevalier!\x01Wha ha ha ha!\x0B\x02", "box_type": 0},
    {"id": 0x2021, "text": "\x1A\x12\x48\x07Vous vendez le masque pour\x01\x05\x4115 Rubis\x05\x40. Vous gardez les\x01bénéfices.\x04\x1ARetournons à la Foire aux Masques\x01pour rendre les \x05\x4110 Rubis\x05\x40.\x0B\x02", "box_type": 2},
    {"id": 0x2022, "text": "\"\x05\x41l'Excursion du fossoyeur\x05\x40\" est \x01interdite aux enfants.\x04Alors je me balade dans le\x01cimetière en imitant Igor le\x01fossoyeur.\x04Mais avec mon visage d'ange,\x01je ne suis pas aussi terrifiant que\x01ça, hein?\x02", "box_type": 0},
    {"id": 0x2023, "text": "\x08Gyaah!\x09 C'est Igor le fossoyeur!\x04\x06\x57???\x04Oh, c'est juste un masque. \x01Il m'a fait une de ces frousses...\x01Mais je l'adore!\x04Peux-tu me le donner?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2024, "text": "J'ai de l'argent tu sais...\x02", "box_type": 0},
    {"id": 0x2025, "text": "Hop là! C'est fini, mon ami!\x01Tu n'as payé que 10 Rubis!\x01Tu t'es suffisamment amusé!\x0B\x02", "box_type": 0},
    {"id": 0x2026, "text": "Je vais être une terreur avec ce \x01masque! Comme Igor, mon idole! \x01Voilà mes sous!\x02", "box_type": 0},
    {"id": 0x2027, "text": "\x1A\x12\x48\x07Vous vendez le masque à l'enfant\x01au prix fort! Quel arnaqueur vous \x01faites!\x04\x1ARetournons à la Foire aux Masques\x01rendre les \x05\x4130 Rubis\x05\x40. \x01Vous y trouverez aussi un nouveau\x01modèle!\x02", "box_type": 2},
    {"id": 0x2028, "text": "Je vais creuser et creuser!\x01Tout comme Igor!!\x02", "box_type": 0},
    {"id": 0x2029, "text": "Du temps jadis, force lapins \x01gambadaient de-ci de-là sur la\x01noble Plaine d'Hyrule. \x01Enfin, avant qu'on les bouffe tous!\x04Je veux être un lapin.\x01Un gentil lapinou.\x01Qui court, qui saute et tout ça...\x04Je donnerais n'importe quoi pour \x01me mettre des oreilles de lapinou\x01sur la tête.\x04Un lapin tout mimi...\x01C'est le lapinou gentil!\x02", "box_type": 0},
    {"id": 0x202A, "text": "Oh.... Quelle jolies oreilles de...\x01\x08LAPIN???\x09\x01Sont-ce de véritables oreilles de\x01lapinou tout mimi et tout poilu?\x07\x20\x2B\x02", "box_type": 0},
    {"id": 0x202B, "text": "Ton prix sera le mien!!!\x01Je les veux. MAINTENANT!!\x01\x1B\x05\x42OK\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x202C, "text": "Mauvaise réponse.\x01Je les veux. Je les veux.\x01Je les veux. Je les veux.\x01Je les veux. Je les veux.\x02", "box_type": 0},
    {"id": 0x202D, "text": "Enfin... Mon rêve se réalise.\x01Je suis un petit lapin.\x01Tout mimi. Tout gentil.\x01Je cours et je saute. Youki!\x0B\x02", "box_type": 0},
    {"id": 0x202E, "text": "\x1A\x12\x48\x07Ce masque à 50 rubis a été\x01vendu à un prix incroyable!\x04\x1ARetournez à la Foire aux Masques\x01rendre les \x05\x4150 Rubis\x05\x40.\x02", "box_type": 2},
    {"id": 0x202F, "text": "\x1A\x06\x10Tu crois que ton silence les \x01\x06\x12protègera? Jeune impudent...\x02", "box_type": 0},
    {"id": 0x2030, "text": "\x1AOn dit à Cocorico que j'ai fichu\x01Talon à la porte du Ranch...\x04\x1A\x08\x06\x1EC'est du n'importe quoi!\x09\x04\x1ACe vieux crétin était inutile!\x01Moi, \x05\x41Ingo \x05\x40le travailleur, me suis \x01dévoué entièrement à ce Ranch!\x04\x1AAlors fais gaffe à tes paroles!\x01Je n'aime pas trop les rigolos \x01dans ton genre qui racontent \x01n'importe quoi sur moi!\x04\x1ALe \x05\x41grand Ganondorf \x05\x40a reconnu mes\x01talents et m'a fait don de ce \x01Ranch! Ca te la coupe, hein?\x04\x1AJe vais dresser un cheval \x01d'exception et le grand Ganondorf\x01sera ravi de mes services!\x04\x1AAu fait, mon ami, que dirais-tu de\x01monter l'un de mes chevaux?\x07\x20\x31\x02", "box_type": 0},
    {"id": 0x2031, "text": "Donne-moi \x05\x4110 Rubis \x05\x40et tu pourras\x01monter un de mes chevaux.\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2032, "text": "Alors... Hors de ma vue, microbe!\x02", "box_type": 0},
    {"id": 0x2033, "text": "Tu n'as pas assez d'argent!\x01Va bosser un peu et reviens me\x01voir!\x02", "box_type": 0},
    {"id": 0x2034, "text": "Veux-tu savoir comment monter?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2035, "text": "Place-toi près du flanc du cheval \x01et appuie sur \x05\x43\x05\x40 pour le monter.\x04Utilise le \x05\x44ª \x05\x40pour le faire galoper.\x01Pendant sa course, appuie sur\x01\x05\x43\x05\x40 pour le cravacher. \x01Il ira beaucoup plus vite!\x04Pour sauter par-dessus un \x01obstacle, fais galoper ta monture\x01le plus vite possible!\x04Attention: un cheval est parfois\x01capricieux! Il ne sautera pas si\x01l'angle de saut ne lui plaît pas.\x04Fais arrêter le cheval puis appuie\x01sur \x05\x43\x05\x40 pour mettre pied à terre.\x01Et maintenant va t'amuser!\x0B\x02", "box_type": 0},
    {"id": 0x2036, "text": "Utilise la \x05\x44Visée ¤ \x05\x40pour parler \x01tout en montant ton cheval.\x04Veux-tu t'arrêter maintenant?\x01\x01\x1B\x05\x42Non, je veux encore monter\x01Oui, j'en ai marre\x05\x40\x02", "box_type": 0},
    {"id": 0x2037, "text": "Pour mettre pied à terre, \x01arrête-toi puis appuie sur \x05\x43\x05\x40.\x04Dis-moi jeune homme, on ne se\x01connaîtrait pas, par hasard?\x01J'ai l'impression de t'avoir déjà\x01vu quelque part...\x07\x20\x36\x02", "box_type": 0},
    {"id": 0x2038, "text": "Tu t'améliores!\x01Ca te dit une petite course\x01contre moi? Le premier à faire le\x01tour de l'enclos a gagné.\x04Paie-moi \x05\x4150 Rubis \x05\x40et c'est parti!\x01Tu es d'accord?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2039, "text": "Hé hé...\x01Tu n'as même pas 50 Rubis?!\x01Je ne fais pas la course contre \x01un clochard!\x02", "box_type": 0},
    {"id": 0x203A, "text": "\x1A\x06\x3CNooooooooon!\x04\x1ASi le grand Ganondorf apprend\x01cette infâmie...\x01Hé, toi!!  On refait la course!\x01Et si tu gagnes cette fois encore...\x04\x1ATu pourras garder...le cheval!!\x0B\x02", "box_type": 0},
    {"id": 0x203B, "text": "\x1AYaaaah!!! Quelle est cette jument?\x01Est-ce \x05\x41Epona\x05\x40?\x04\x1AComment as-tu pu dresser cet \x01animal sauvage???\x04\x1ACette jument était destinée au \x01grand Ganondorf... Mais je l'ai \x01pariée et perdue! Noooooooon!\x0B\x02", "box_type": 0},
    {"id": 0x203C, "text": "\x1A\x06\x36Hah ha hah!\x04\x1AComme promis, \x01tu peux garder le cheval.\x04\x1A\x06\x3CCependant...\x04\x1ATu ne sortiras jamais de ce Ranch!\x0B\x02", "box_type": 0},
    {"id": 0x203D, "text": "Hé hé hé hé... Dommage, petit!\x01Je garde tes 50 Rubis.\x0B\x02", "box_type": 0},
    {"id": 0x203E, "text": "Wah ha hah!\x01Tu n'es qu'un débutant, après tout!\x01Reviens quand tu veux pour te \x01faire ridiculiser...\x02", "box_type": 0},
    {"id": 0x203F, "text": "\x1AHuh? Que fais-tu là? \x01Sale môme, va!\x04\x1AMon nom est \x05\x41Ingo \x05\x40et je m'occupe\x01du ranch.\x04\x1AJe travaille pour ce crétin de\x01Talon depuis très longtemps. \x01Trop longtemps.\x01Il ne fait rien de toute la journée!\x04\x1AAujourd'hui, par exemple, il est \x01parti faire une livraison et...\x01Il n'est toujours pas rentré!\x04\x1AAlors je me tape tout le boulot.\x01Cool, non?\x07\x20\x40\x02", "box_type": 0},
    {"id": 0x2040, "text": "Pfff...ça craint d'bosser!\x02", "box_type": 0},
    {"id": 0x2041, "text": "\x1AHé! Tes vêtements! Ils sont...\x01Différents...\x01Tu n'es pas du coin, toi?\x04\x1A\x14\x02.........\x14\x00........\x04\x1AOhh... \x01Tu es un garçon de la forêt!\x01Mon nom est \x05\x41Malon\x05\x40! Mon père \x01tient le Ranch Lon Lon.\x07\x20\x42\x02", "box_type": 0},
    {"id": 0x2042, "text": "Papa est parti livrer du lait au\x01Château mais il n'est toujours\x01pas revenu...\x02", "box_type": 0},
    {"id": 0x2043, "text": "\x1AVas-tu au Château, garçon de la \x01forêt? Peux-tu trouver mon \x05\x41père\x05\x40?\x04\x1A\x12\x68\x6DIl a dû s'endormir quelque part\x01autour du Château. \x01Il est si paresseux! Hi hi hi!\x04\x1APrends ceci... Tu en auras\x01probablement besoin.\x04\x1AJ'en prends soin depuis longtemps...\x01Hi hi hi!\x0B\x02", "box_type": 0},
    {"id": 0x2044, "text": "Assigne l'oeuf à \x05\x46¡\x05\x40 pour le \x01couver. Hi hi!\x04Mon père est...spécial, hein?\x01Hi hi hi!\x02", "box_type": 0},
    {"id": 0x2045, "text": "\x1AEt dire que moi, le grand \x05\x41Ingo\x05\x40, \x01travaille dans un ranch aussi nul!\x01C'est de la folie!\x04\x1ALe propriétaire est si paresseux!\x01Alors je me tape toutes les \x01corvées! J'en ai ras la moustache!\x07\x20\x46\x02", "box_type": 0},
    {"id": 0x2046, "text": "Moi, le grand \x05\x41Ingo\x05\x40, devrait être le\x01patron de ce ranch. Pas l'autre\x01crétin de Talon!\x02", "box_type": 0},
    {"id": 0x2047, "text": "\x1AOh, revoilà le garçon de la forêt!\x01Alors, tu as trouvé mon papa?\x01As-tu visité le Château? As-tu \x01rencontré la Princesse? Hi hi!\x04\x1A\x12\x68\x6DPapa est revenu à la maison\x01en courant comme un lapin après \x01votre rencontre. Hi hi hi!\x04\x1AAu fait... Je ne t'ai pas encore\x01présenté mon amie!\x04\x1ACette petite jument s'appelle\x01\x05\x41Epona\x05\x40. N'est-elle pas adorable?\x02", "box_type": 0},
    {"id": 0x2048, "text": "On dirait qu'Epona a peur de toi,\x01M. le garçon de la forêt...\x02", "box_type": 0},
    {"id": 0x2049, "text": "Ma mère me chantait cette \x01chanson. Elle est belle, non?\x01Chantons-la tous les deux.\x02", "box_type": 0},
    {"id": 0x204A, "text": "Oh, Epona! Elle semble vous\x01apprécier, M. le garçon de la forêt.\x02", "box_type": 0},
    {"id": 0x204B, "text": "\x14\x02Z Z Z Z Z Z Z Z Z Z Z Z Z Z Z\x14\x00...\x02", "box_type": 0},
    {"id": 0x204C, "text": "Oh...de la visite!\x01Les visiteurs se font rares\x01en ce moment...\x01D'où viens-tu?\x04Depuis la venue de Ganondorf, \x01les gens ont fui les villes, le pays\x01est en ruines, et des monstres \x01sont apparus un peu partout.\x04M. Ingo ne dirige le Ranch que \x01pour plaire à Ganondorf...\x04Tout le monde semble devenir\x01méchant...\x04Et puis il y a mon père...\x01M. Ingo l'a jeté dehors...\x04Si jamais j'ose désobéir à M. Ingo,\x01il fera du mal aux chevaux...\x04Alors...\x01On ne peut pas dire que ce soit \x01la fête dans le coin...\x02", "box_type": 0},
    {"id": 0x204D, "text": "Personne n'est aussi rapide que \x01moi! Alors, résultat: j'm'ennuie.\x02", "box_type": 0},
    {"id": 0x204E, "text": "\x14\x02Z Z Z Z Z Z Z Z Z Z Z Z Z\x14\x00...\x01Arrête de chanter...\x01Mmmm....Idiote...\x02", "box_type": 0},
    {"id": 0x204F, "text": "\x1ARegarde bien cette montagne.\x01C'est le \x05\x41Mont du Péril\x05\x40, la demeure\x01des Gorons. Ils détiennent la\x01Pierre Ancestrale du feu.\x02", "box_type": 0},
    {"id": 0x2050, "text": "Ne dis surtout pas à M. Ingo que\x01je chante cette chanson...\x02", "box_type": 0},
    {"id": 0x2051, "text": "\x1ATu...\x01Tu connais la \x05\x41chanson de ma mère\x05\x40?\x04\x1ATout le monde adorait cette\x01chanson...\x01Mon père... Même M. Ingo...\x04\x1AMais...depuis la venue de\x01Ganondorf, M. Ingo a changé.\x04\x1ACette chanson me rappelle\x01les beaux jours...\x07\x20\x52\x02", "box_type": 0},
    {"id": 0x2052, "text": "\x05\x41Epona\x05\x40 était folle de cette chanson...\x01J'étais la seule à pouvoir la \x01monter... Même M. Ingo a des \x01problèmes avec elle...\x04Hi hi hi!\x02", "box_type": 0},
    {"id": 0x2053, "text": "L'oeil de cette statue perce les\x01mystères de votre esprit...\x02", "box_type": 2},
    {"id": 0x2054, "text": "Grâce à votre masque, cette \x01étrange statue vous parle...\x04Voici ses paroles...\x02", "box_type": 2},
    {"id": 0x2055, "text": "J'ai pris de bonnes résolutions:\x01Désormais je vais me mettre à \x01bosser comme un méga-dingue.\x02", "box_type": 0},
    {"id": 0x2056, "text": "M. Ingo... De sombres pouvoirs\x01ont dû l'ensorceler...\x01Il n'a jamais été un mauvais\x01homme...\x02", "box_type": 0},
    {"id": 0x2057, "text": "Z Z Z Z Z Z Z Z...\x01Mmmm... J'en ai marre de bosser...\x02", "box_type": 0},
    {"id": 0x2058, "text": "Bon alors...\x01Tu veux faire la course?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2059, "text": "Si tu changes d'avis,\x01reviens me voir!\x02", "box_type": 0},
    {"id": 0x205A, "text": "Alors... Hors de ma vue, microbe!\x0B\x02", "box_type": 0},
    {"id": 0x205B, "text": "Hé hé... Tu m'en veux d'avoir \x01gagné, hein? Dans ce cas je peux\x01t'accorder une revanche!\x01On refait la course?\x04Aboule \x05\x4150 Rubis \x05\x40et c'est parti!\x01\x01\x1B\x05\x42OK\x01Pas question\x05\x40\x02", "box_type": 0},
    {"id": 0x205C, "text": "Merci beaucoup, Hé hé!\x0B\x02", "box_type": 0},
    {"id": 0x205D, "text": "Ingo va me hurler dessus si je te\x01donne ceci pour rien.\x01Alors je vais te faire un prix.\x02", "box_type": 0},
    {"id": 0x205E, "text": "Veux-tu du lait pour \x05\x4130 Rubis\x05\x40?\x01\x01\x1B\x05\x42Acheter\x01Ne pas acheter\x05\x40\x02", "box_type": 0},
    {"id": 0x205F, "text": "Bien le bonjour mon bon monsieur!\x01Mon nom est Ingo. Travailler ici\x01est un honneur.\x02", "box_type": 0},
    {"id": 0x2060, "text": "\x1APetit...tu es courageux!\x01Nous devons protéger cette belle\x01terre d'Hyrule!\x02", "box_type": 0},
    {"id": 0x2061, "text": "\x1AOh, le bel ocarina!\x01Vas-tu jouer ma chanson avec ton\x01instrument?\x02", "box_type": 0},
    {"id": 0x2062, "text": "\x1AAu pied du Mont du Péril tu \x01trouveras mon village natal, \x01\x05\x41Cocorico\x05\x40.\x04\x1AInterroge les villageois avant\x01de t'aventurer dans la montagne.\x02", "box_type": 0},
    {"id": 0x2063, "text": "\x1ALa mélodie que je t'ai enseignée\x01possède d'étranges pouvoirs. Elle \x01est le patrimoine de la Famille\x01Royale...\x04\x1AElle t'aidera à prouver ton alliance\x01avec la Famille Royale.\x04\x1AMaintenant va, jeune guerrier...\x01Tu dois rapporter les Pierres au \x01Château. Nous comptons tous sur \x01toi!\x02", "box_type": 0},
    {"id": 0x2064, "text": "\x1A\x08Hou houuu!\x09\x01\x0F...\x01Regarde un peu par là!\x0C\x28\x1APrépare-toi car ta noble quête \x01débute enfin!\x04\x1ATon destin est tourmenté.\x01Obstacles et épreuves t'attendent. \x01Mais jamais le courage ne doit te\x01faire défaut!\x07\x20\x65\x02", "box_type": 0},
    {"id": 0x2065, "text": "Va tout droit pour aller au\x01\x05\x41Château d'Hyrule\x05\x40.\x04Une \x05\x41Princesse \x05\x40t'y attend...\x04Si par malheur tu perds ton \x01chemin, n'hésite pas à consulter\x01la \x05\x41Carte\x05\x40.\x04Les contrées déjà explorées seront\x01affichées à l'écran. Appuie sur\x01\x05\x41START \x05\x40puis sur \x05\x44¤\x05\x40 ou \x05\x44£\x05\x40 pour \x01trouver la carte.\x04Sur l'\x05\x41écran de la carte\x05\x40 apparaîtra\x01un \x05\x41point clignotant\x05\x40 t'indiquant la \x01position de ta prochaine épreuve.\x07\x20\x66\x02", "box_type": 0},
    {"id": 0x2066, "text": "M'as-tu bien compris?\x01\x01\x1B\x05\x42Non\x01Oui\x05\x40\x02", "box_type": 0},
    {"id": 0x2067, "text": "\x1ABonne chance brave petit!\x01Et à la prochaine!\x01Hou hou houuu!\x02", "box_type": 0},
    {"id": 0x2068, "text": "\x1AHé, \x0F! Par ici!\x0C\x28\x1ALa Princesse est dans le Château.\x01Ne te fais surtout pas repérer \x01par les gardes!\x01Hou hou hou houuuu!\x0B\x02", "box_type": 0},
    {"id": 0x2069, "text": "Par ici, le temps s'écoule\x01normalement.\x04Mais le temps reste comme figé\x01lorsque tu visites le Ranch \x01Lon Lon ou une ville.\x04Dans ces conditions, tu devras \x01quitter la ville pour faire avancer\x01le temps normalement.\x04Dis-moi... Par où vas-tu aller\x01maintenant?\x01Hou hou houuu!\x0B\x02", "box_type": 0},
    {"id": 0x206A, "text": "Veux-tu que je répète tout ça?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x206B, "text": "\x1AHouuu. T'es un malin, toi!\x01Bonne chance mon garçon...\x01Hou hou hou.\x02", "box_type": 0},
    {"id": 0x206C, "text": "Hé, \x0F! \x01Attends une minute, l'ami!\x04Par là tu trouveras le\x05\x41 village de \x01Cocorico\x05\x40. As-tu déjà rencontré la\x01Princesse d'Hyrule? Si la réponse \x01est non, dirige-toi vers le Château.\x0B\x02", "box_type": 0},
    {"id": 0x206D, "text": "Hé, \x0F! \x01Par ici, mon tout petit!\x0C\x28\x1APar là tu trouveras le \x05\x41village de \x01Cocorico\x05\x40. Prends garde à toi!\x01Houu houuu!\x0B\x02", "box_type": 0},
    {"id": 0x206E, "text": "\x1A\x0F, sur tes minces \x01épaules repose la destinée du\x01Royaume! Sois à la hauteur! \x01Houu houuu!\x02", "box_type": 0},
    {"id": 0x206F, "text": "\x0F!\x01Ecoute donc mes sages paroles!\x01Hou houuuu!\x0C\x28Au sud s'étend le \x05\x41Lac Hylia\x05\x40.\x04A l'ouest tu trouveras la \x05\x41Vallée\x01Gerudo\x05\x40. Un repaire de voleuses\x01occupe l'autre versant de la\x01vallée.\x04Tu es libre d'aller n'importe où!\x01Hou hou hou...houuu!\x0B\x02", "box_type": 0},
    {"id": 0x2070, "text": "\x1AReste courageux devant l'adversité.\x01Hou Hou Houuu!\x02", "box_type": 0},
    {"id": 0x2071, "text": "Dans cette direction s'étend les\x01eaux riches et pures du Lac Hylia.\x0C\x28Les \x05\x43Zoras\x05\x40, un peuple vivant en \x01amont du fleuve, sont les gardiens \x01du Temple sous-marin et de la \x01Fontaine Zora.\x04Pour confirmer sa position sur la \x01carte, appuie sur \x05\x41START \x05\x40puis sur \x01\x05\x44¤ \x05\x40ou \x05\x44£\x05\x40 pour trouver la carte.\x04Toutes les contrées visitées sont\x01indiquées sur la carte.\x01Houuu houuu heu...hou!\x0B\x02", "box_type": 0},
    {"id": 0x2072, "text": "\x1AMène à bien ta quête, \x01petit homme!\x02", "box_type": 0},
    {"id": 0x2073, "text": "\x1AQuel est ton nom?\x0B\x02", "box_type": 0},
    {"id": 0x2074, "text": "\x1A\x14\x01.....\x14\x00\x04\x1A\x05\x42\x0F\x05\x40...\x04\x1AC'est étrange...j'ai l'impression... \x01de te connaître.\x0B\x02", "box_type": 0},
    {"id": 0x2075, "text": "\x1AEcoute-moi bien, \x0F...\x04\x1AJe vais te révéler la légende du\x01Saint Royaume, gardée depuis bien\x01des lunes par la noble Famille\x01d'Hyrule.\x0B\x02", "box_type": 0},
    {"id": 0x2076, "text": "\x06\x28L'Ocarina du Temps!\x0B\x02", "box_type": 0},
    {"id": 0x2077, "text": "As-tu bien compris toute l'histoire?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2078, "text": "\x1AJe regardais par cette fenêtre...\x04\x1ALes \x05\x43nuages noirs \x05\x40de mon rêve...\x01Je crois qu'ils symbolisent...\x01Cet homme!\x04Veux-tu jeter un coup d'oeil?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x2079, "text": "\x1A\x14\x01........\x14\x00Bien sûr!\x04\x1AJ'ai parlé de mon rêve à Père...\x04\x1AMais il n'a rien voulu savoir...\x04\x1AQuoi qu'il en soit...\x01Je suis certaine que cet homme \x01nourrit de noirs desseins!\x0B\x02", "box_type": 0},
    {"id": 0x207A, "text": "\x1AGanondorf est à la recherche de\x01la \x05\x41Triforce \x05\x40du Saint Royaume.\x01J'en suis sûre!\x04\x1ASa venue jusqu'à Hyrule en est la\x01preuve!\x04\x1ACependant...\x01Ses plans de conquête ne se \x01bornent pas à Hyrule...\x01Mais au monde entier!\x0B\x02", "box_type": 0},
    {"id": 0x207B, "text": "\x1A\x0F...\x01Nous sommes les seuls en mesure\x01de protéger le Royaume d'Hyrule!\x0B\x02", "box_type": 0},
    {"id": 0x207C, "text": "\x1ALe vil Ganondorf ne doit JAMAIS\x01mettre la main sur la Triforce!\x04\x1AJe vais garder précieusement\x01l'\x05\x44Ocarina du Temps\x05\x40. \x01Jamais il ne le trouvera!\x04\x1ADe ton côté, va récupérer les \x01deux autres \x05\x41Pierres Ancestrales\x05\x40!\x04\x1AIl est de notre devoir de trouver\x01la Triforce avant Ganondorf et de\x01contrecarrer ses plans de \x01conquête!\x0B\x02", "box_type": 0},
    {"id": 0x207D, "text": "\x1AEncore une chose...\x01Prends cette \x05\x41lettre\x05\x40...\x01Elle te sera d'une grande aide.\x0B\x02", "box_type": 0},
    {"id": 0x207E, "text": "\x1AMmm...zzz..mmm...hein?\x01OK, j'suis réveillé maintenant!\x04\x1AQuoi?\x04\x1ASacré nom d'un pétard mouillé!\x01C'est le p'tit gars d'la forêt!\x01Au fait, merci de m'avoir réveillé\x01l'aut'jour!\x04\x1ATu as dû comprendre que mon truc\x01à moi, c'est d'pioncer.\x04\x1AAlors quels sont tes projets pour\x01la journée? Ca te dirait de jouer\x01avec ton pote Talon?\x01(Heu... Talon, c'est moi.)\x04\x1ALes trois cocottes que j'ai ici \x01sont des \x05\x41Super Cocottes\x05\x40!\x04\x1AJe vais lancer ces trois Cocottes \x01au milieu de toutes les autres.\x04\x1ASi tu peux les retrouver avant\x01la fin du chrono, j'te donnerai\x01\x05\x41un truc cool\x05\x40.\x04Dans le cas contraire, c'est moi\x01le vainqueur. On parie 10 Rubis...\x01\x1B\x05\x42OK\x01Jamais!\x05\x40\x02", "box_type": 0},
    {"id": 0x207F, "text": "Mmm...mmmm...quoi?\x01OK, OK, j'suis réveillé!\x04Qu'y a-t-il?\x04Salut, p'tit gars d'la forêt!\x01Tu as du temps devant toi?\x01Alors on va jouer!\x04Je vais lancer ces trois \x01\x05\x41Super Cocottes \x05\x40au milieu de \x01toutes les autres.\x04Si tu peux les retrouver avant\x01la fin du chrono, j'te donnerai\x01\x05\x41un truc cool\x05\x40.\x04Dans le cas contraire, c'est moi\x01le vainqueur. On parie 10 Rubis... \x01\x1B\x05\x42OK\x01Jamais!\x05\x40\x02", "box_type": 0},
    {"id": 0x2080, "text": "Tu as 30 secondes!\x01Prépare-toi...car voici...les...\x01Super Cocottes!\x04\x06\x37C'EST PARTI!!!\x0B\x02", "box_type": 0},
    {"id": 0x2081, "text": "Hop là! C'est fini!\x01Dommaaaaage mon poussin!!\x04Il est cool mon jeu, hein?\x01Mes Cocottes si mignonnes!\x04Super Cocottes... Au pied!\x0B\x02", "box_type": 0},
    {"id": 0x2082, "text": "En voilà une!\x01Bien joué mon poussin!\x01Encore \x05\x41deux\x05\x40 à trouver!\x0B\x02", "box_type": 0},
    {"id": 0x2083, "text": "En voilà une autre!\x01Le moment de vérité! \x01Plus qu'\x05\x41une\x05\x40 à trouver!\x0B\x02", "box_type": 0},
    {"id": 0x2084, "text": "Sacré nom d'une pipe en bois!\x01J'en reste baba!\x04C'était la dernière!\x01Tu les as toutes trouvées!\x01Approche un peu mon poussin!\x0B\x02", "box_type": 0},
    {"id": 0x2085, "text": "Veux-tu jouer encore une fois?\x04Un p'tit gars comme toi a de\x01l'énergie à revendre!\x01Trouve mes Super Cocottes en\x0130 secondes.\x04On parie 5 Rubis?\x01\x01\x1B\x05\x42Oui\x01Jamais!\x05\x40\x02", "box_type": 0},
    {"id": 0x2086, "text": "Mon p'tit gars...\x01Tu as l'étoffe d'un éleveur de\x01Cocottes!\x04Ca te dirait d'épouser Malon?\x01\x01\x1B\x05\x42Oh oui! Oh oui!\x01Jamaiiiis!!!\x05\x40\x02", "box_type": 0},
    {"id": 0x2087, "text": "\x1AHa ha! Je blaguais! \x01T'es peut-être un peu jeune pour \x01ça, p'tite tête!\x01Ha ha ha!\x04\x1AVoici un échantillon de notre\x01célèbre \x05\x41Lait de Lon Lon\x05\x40. \x01Il restaurera ton énergie en une\x01seconde!\x04\x1AAprès l'avoir bu, rapporte la \x01\x05\x41bouteille\x05\x40 pour faire le plein!\x0B\x02", "box_type": 0},
    {"id": 0x2088, "text": "Hé l'ami... tu m'as l'air honnête et \x01travailleur!\x04Une fois plus grand tu pourras\x01travailler au Ranch!\x01L'offre tiendra toujours dans\x01quelques années.\x0B\x02", "box_type": 0},
    {"id": 0x2089, "text": "Voilà pour toi! Un bon litre de\x01\x05\x41Lait de Lon Lon \x05\x40bien frais!\x0B\x02", "box_type": 0},
    {"id": 0x208A, "text": "Voilà pour toi! \x01Du lait bien frais...hein?...\x04Dommaaaaaaaaage!!\x01Tu n'as pas de bouteille vide!\x02", "box_type": 0},
    {"id": 0x208B, "text": "Mmm...mmm...\x01OK, OK, j'suis réveillé!\x04Quoi?\x04Salut, \x0F!\x01Si tu cherches Malon, elle est \x01dehors. Tu es peut-être venu pour\x01jouer?\x04Alors que dirais-tu d'une partie de\x01\x05\x41Cherche-la-Super-Cocotte\x05\x40?\x01Ou veux-tu plutôt du \x01\x05\x41lait de Lon Lon\x05\x40?\x04Dis-moi tout!\x01\x1C\x05\x42Lait de Lon Lon - 30 Rubis\x01Jeu de la Cocotte - 10 Rubis\x01Quitter\x05\x40\x02", "box_type": 0},
    {"id": 0x208C, "text": "\x08\x05\x41Perdu!\x05\x40\x01Tu dois sauter par-dessus tous les\x01obstacles!\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x208D, "text": "\x08\x05\x41Encore un tour!\x05\x40\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x208E, "text": "Es-tu sûr de t'y prendre\x01correctement? Galope tout droit\x01vers les barrières ou ton cheval\x01ne sautera pas!\x04Grimpe sur Epona pour retenter\x01ta chance!\x02", "box_type": 0},
    {"id": 0x208F, "text": "\x1AFantastique!\x01\x05\x41\x17\x05\x40 est le nouveau record!\x04\x1AJe dois te donner un petit\x01quelque chose pour te féliciter!\x04\x1AJe viendrai te livrer mon cadeau\x01chez toi...... Tu dois te demander\x01ce que c'est, hein? Hi hi hi!\x02", "box_type": 0},
    {"id": 0x2090, "text": "Le record est de \x05\x4150 secondes\x05\x40.\x01Ton meilleur temps est de \x05\x41\x1E\x03\x05\x40.\x04Si tu bats le record, je t'offrirai \x01un petit cadeau.\x01Alors fais de ton mieux, OK?\x04Et c'est parti!\x0B\x02", "box_type": 0},
    {"id": 0x2091, "text": "Ton meilleur temps est de \x05\x41\x1E\x03\x05\x40!\x01Peux-tu faire mieux que ça?\x01Allez, c'est parti!\x0B\x02", "box_type": 0},
    {"id": 0x2092, "text": "Le record actuel est \x05\x4150 secondes\x05\x40.\x01Tente d'abord de battre ce temps!\x04Si tu bats le record, je t'offrirai\x01un petit cadeau!\x01Alors fais de ton mieux, OK?\x04Et c'est parti!\x0B\x02", "box_type": 0},
    {"id": 0x2093, "text": "2093\x02", "box_type": 0},
    {"id": 0x2094, "text": "2094\x02", "box_type": 0},
    {"id": 0x2095, "text": "2095\x02", "box_type": 0},
    {"id": 0x2096, "text": "2096\x02", "box_type": 0},
    {"id": 0x2097, "text": "2097\x02", "box_type": 0},
    {"id": 0x2098, "text": "2098\x02", "box_type": 0},
    {"id": 0x2099, "text": "2099\x02", "box_type": 0},
    {"id": 0x209A, "text": "209A\x02", "box_type": 0},
    {"id": 0x209B, "text": "209B\x02", "box_type": 0},
    {"id": 0x209C, "text": "209C\x02", "box_type": 0},
    {"id": 0x209D, "text": "209D\x02", "box_type": 0},
    {"id": 0x209E, "text": "209E\x02", "box_type": 0},
    {"id": 0x209F, "text": "209F\x02", "box_type": 0},
    {"id": 0x3000, "text": "\x1AVous ne savez pas ce que\x01\"frères de sang\" veut dire mais \x01vous avez désormais deux Pierres\x01Ancestrales! Plus qu'une à trouver!\x02", "box_type": 2},
    {"id": 0x3001, "text": "\x1AVous ne savez pas ce que\x01\"frères de sang\" veut dire mais\x01vous avez les trois Pierres \x01Ancestrales! Allez vite voir Zelda!\x02", "box_type": 2},
    {"id": 0x3002, "text": "J'ai faaaiiiis çççççaaaaaa...\x01Je veux le \x05\x41certiffficaaat\x05\x40...\x02", "box_type": 0},
    {"id": 0x3003, "text": "J'ai fait ceeeeeeciiiiii...\x01Commmmmmme sssouvvvenirrrr...\x02", "box_type": 0},
    {"id": 0x3004, "text": "\x1A\x06\x2DPetit, j't'aime bien!\x04\x1APourquoi qu'on deviendrait pas \x01des frères de sang?!\x04\x1APas besoin de cérémonie! \x01Accepte ce cadeau en témoignage \x01de notre amitié!\x02", "box_type": 0},
    {"id": 0x3005, "text": "\x06\x25Viens faire un bisou!\x0E\x1E\x02", "box_type": 0},
    {"id": 0x3006, "text": "\x06\x14Tu veux un gros cââlinouu?\x0E\x1E\x02", "box_type": 0},
    {"id": 0x3007, "text": "\x06\x50Hé!!!\x0C\x1E\x06\x4BOh-oh!\x0C\x28\x06\x26\x08Plus fort la musique!\x09\x0C\x1E\x06\x11Allez donne-toi...\x08ça balance\x09!!\x0C\x28\x06\x37\x08C'est CHAUD!!\x09\x0C\x1E\x06\x28Quel rythme!\x0C\x28\x06\x32WHOOOOAH!\x0C\x28\x06\x3C\x08YHAAAAA!\x09\x0C\x28\x06\x3C\x08YAHBADAA!!\x09\x02", "box_type": 0},
    {"id": 0x3008, "text": "\x1ANous les \x05\x41Gorons\x05\x40 mangeons les\x01pierres du Mont du Péril.\x04\x1ARegarde cet énorme rocher!\x04\x1AIl bloque l'entrée de la \x05\x41Caverne\x05\x40\x01\x05\x41Dodongo\x05\x40.\x05\x41 \x05\x40C'est un endroit très \x01important pour les Gorons!\x04\x1AMais un jour, de nombreux \x01Dodongos infestèrent la caverne\x01et y aller devint très dangereux!\x04\x1AEt en plus, comme si ça suffisait \x01pas, un vilain \x05\x41Gerudo en armure \x01noire \x05\x40a jeté un sort pour bloquer\x01l'entrée avec ce rocher!\x07\x30\x2A\x02", "box_type": 0},
    {"id": 0x3009, "text": "Mon boulot c'est de dévaler le \x01long de la montagne avec un \x01\x05\x41Chou-Péteur\x05\x40 dans les dents. \x01Je dois foncer dans l'rocher et...\x04\x08\x06\x3C\x05\x41BOOOUUUM!\x05\x40\x09\x04Mais...j'suis un peu lent...\x01Mon Chou-Péteur explose trop tôt \x01et mes dents...bah...comment dire...\x01Elles sont nazes, quoi!\x02", "box_type": 0},
    {"id": 0x300A, "text": "Je reste ici pour faire de l'ombre\x01aux \x05\x41Choux-Péteurs\x05\x40. \x01Ouais...c'est mon boulot à moi!\x04Tu veux m'poser une question?\x01\x01\x1B\x05\x42Chou-Péteur?\x01Caverne Dodongo?\x05\x40\x02", "box_type": 0},
    {"id": 0x300B, "text": "Les plantes du coin sont des \x01\x05\x41Choux-Péteurs\x05\x40. Elles peuvent \x01exploser et ne poussent que sur \x01cette montagne.\x04Leur fruit est l'essence même\x01des célèbres bombes.\x04Mais un non-Goron ne peut se\x01servir d'un tel engin!\x04Ces plantes ne poussent que dans \x01les endroits sombres... Mais \x01celle-ci est une des rares\x01exceptions.\x02", "box_type": 0},
    {"id": 0x300C, "text": "Les plantes du coin sont des \x01\x05\x41Choux-Péteurs\x05\x40.  Elles peuvent \x01exploser et ne poussent que sur \x01cette montagne.\x04Ces plantes ne poussent que dans\x01les endroits sombres, comme\x01les cavernes, mais celle-ci est une \x01des rares exceptions.\x04Grâce au célèbre Bracelet Goron,\x01même un petit gars comme toi \x01pourrait les soulever avec \x05\x43\x05\x40.\x02", "box_type": 0},
    {"id": 0x300D, "text": "As-tu vu l'entrée d'une caverne\x01sur ton chemin? Hé ben, c'etait la\x01\x05\x41Caverne Dodongo\x05\x40.\x04Comme il n'y a que très peu de \x01lumière là-dedans, les \x05\x41Choux-\x01Péteurs \x05\x40poussent comme du \x01chiendent!\x02", "box_type": 0},
    {"id": 0x300E, "text": "\x1A\x06\x55Oh?\x04\x1ALes visiteurs se font rares! \x01D'où viens-tu?\x04\x1ALa forêt?\x04\x1AC'est quoi une \"forêt\"?\x04\x1AHein?\x04\x1AOn y trouve des \"arbres\" et\x01des \"plantes\"?\x04\x1AHeu... Tu me parles de quoi, là?\x01Ici il y a bien des \x05\x41Choux-Péteurs\x05\x40...\x04\x1AMais les Bâtons Mojo c'est \x01super rare dans l'coin!\x07\x30\x22\x02", "box_type": 0},
    {"id": 0x300F, "text": "J'ai pas grand chose à vendre \x01alors j'ai fermé l'entrée. \x01Mais je vois que tu es un client \x01acharné...\x0B\x02", "box_type": 0},
    {"id": 0x3010, "text": "Je suis désolé...\x01Cette bombe est en exposition.\x01J'ai \x05\x41vendu\x05\x40 tout mon stock.\x0B\x02", "box_type": 0},
    {"id": 0x3011, "text": "Ben...pourquoi tu m'as arrêté?\x01Pas ici! Non pas ici!\x04Tu peux pas faire ça!\x04Les roulés-boulés sont ma seule \x01raison de vivre: ça me calme les\x01nerfs!\x04Respecte mes roulés-boulés! \x01Ecarte-toi que j'roule un peu!!\x02", "box_type": 0},
    {"id": 0x3012, "text": "\x1ABon... Prends ceci en récompense\x01de ton courage!\x0B\x02", "box_type": 0},
    {"id": 0x3013, "text": "Merci, merci! Laisse-moi te \x01remercier en exécutant un de \x01mes plus beaux roulés-boulés!\x02", "box_type": 0},
    {"id": 0x3014, "text": "\x1A\x06\x31Oh...J'ai si faim...\x04\x1ATout le monde crève la dalle ici. \x01Nous sommes devenus une race en \x01voie d'extinction... \x01Faut nous protéger!\x04\x1AOn ne peut plus entrer dans les \x01carrières de la \x05\x41Caverne Dodongo\x05\x40, \x01notre garde-manger!\x04\x1AOn doit alors se contenter de \x01graviers, et ça c'est dur...\x04\x1ALes meilleurs rochers, à la fois\x01nutritifs et délicieux, sont dans la\x01Caverne Dodongo! Mais c'est de \x01l'histoire ancienne...\x04\x1ANous sommes tous devenus \x01de vrais gourmets! Il est alors\x01impossible d'avaler autre chose \x01que de la pierre Dodongo!\x07\x30\x15\x02", "box_type": 0},
    {"id": 0x3015, "text": "Beuhh... Je me taperais bien\x01un gigot de caillasse de la\x01\x05\x41Caverne Dodongo\x05\x40!\x02", "box_type": 0},
    {"id": 0x3016, "text": "\x1AHé!\x04\x1AC'est dangereux par ici! \x01Un petit gars comme toi pourrait \x01tomber n'importe où!\x04\x1AAttends! Tu ne serais pas\x01venu pour manger notre \x01\x05\x41pierre rouge\x05\x40, par hasard?\x01Dommage! Elle n'est plus là!\x04\x1AQuoi? Tu n'es pas ici pour ça?\x04\x1ATu cherches la Pierre Ancestrale? \x01Il doit s'agir de la pierre rouge\x05\x41 \x05\x40si \x01appétissante qui était là!\x04\x1AJ'avais si faim alors je me suis\x01dit: \"une p'tite bouchée de cette \x01belle pierre, personne ne le saura!\"\x01Mais elle avait déjà disparu!\x04\x1AJe crois que le Chef l'a cachée.\x04\x1AIl dit toujours que ça rend les \x01frères complètement dingues de \x01regarder cette pierre rouge par \x01ces temps de famine.\x07\x30\x17\x02", "box_type": 0},
    {"id": 0x3017, "text": "Le Chef s'est cloîtré dans son \x01antre après avoir dit:\x01\"\x05\x41J'attends le messager de la \x01Famille Royale!\x05\x40\"\x02", "box_type": 0},
    {"id": 0x3018, "text": "\x1AJ'ai si faim que je ne pense qu'à\x01manger!\x04\x1AAdresse-toi au Chef pour les \x01histoires compliquées.\x04\x1AS'il est de mauvaise humeur, il \x01risque de se fâcher pour un rien.\x01Et là...tu seras mal.\x04\x1AJe connais son SECRET.\x04\x1AIl n'en a peut-être pas l'air,\x01mais il adore danser!\x01S'il entend une belle mélodie,\x01qui sait ce qu'il se passera!\x07\x30\x19\x02", "box_type": 0},
    {"id": 0x3019, "text": "Je crois que le Chef adore\x01la \x05\x42musique de la forêt\x05\x40...\x04Ha! C'était le bon vieux temps...\x01Cette musique me rend nostalgique.\x07\x30\x2C\x02", "box_type": 0},
    {"id": 0x301A, "text": "\x1AMmm? Quoi? Qui es-tu?!\x04\x1AC'est toi qui a joué le \x05\x43chant de la \x01Famille Royale\x05\x40? Mais tu n'es pas \x01un messager! Tu n'es qu'un nabot \x01avec un chapeau vert!\x04\x1A\x05\x41Darunia\x05\x40, le Chef des Gorons,\x01mérite plus de considération de la \x01part de son frère de clan, le Roi \x01d'Hyrule!\x04\x1AAlors là je suis furax!\x01Hors d'ici, le gnome!\x04\x1ATu me demandes pourquoi je suis\x01si furieux? Whoa! T'es mignon toi!\x01Ecoute...\x04\x1A\x08Des monstres infestent notre \x01Caverne Dodongo!\x09\x04\x1A\x08Notre récolte de Choux-Péteurs\x01est minable!\x09\x04\x1A\x08On crève tous de faim par ici!\x01Y'a plus un rocher mangeable!!\x09\x04\x1A\x06\x48Mais...\x07\x30\x1B\x02", "box_type": 0},
    {"id": 0x301B, "text": "\x08\x06\x23C'est notre problème...\x09\x04\x08\x06\x05Cela ne regarde que les Gorons!\x09\x02", "box_type": 0},
    {"id": 0x301C, "text": "\x1A\x08\x06\x11Hé! Ca c'est de la chanson!\x09\x04\x1AMa déprime vient de s'envoler!\x01J'ai eu tout d'un coup envie de \x01danser! Comme un méga-dingue!\x04\x1A\x06\x32Mon nom est \x05\x41Darunia\x05\x40!\x04\x1AJe suis le Chef des Gorons!\x01Je peux faire quelque chose pour\x01toi?\x04\x1A\x06\x4BPardon?\x04\x1ATu veux la \x05\x41Pierre Ancestrale du \x01Feu\x05\x40? Ben voyons!\x04\x1ALa Pierre Ancestrale du Feu est \x01notre trésor secret! Nous \x01l'appelons le Rubis Goron...\x04\x1AMais si tu la veux vraiment,\x01tu pourrais peut-être nous rendre\x01un service...\x04\x1APeux-tu détruire les monstres de\x01la Caverne Dodongo?\x04\x1AAinsi nous aurions de quoi manger!\x01Je suis prêt à donner n'importe \x01quoi à notre sauveur...\x01Même la Pierre Ancestrale!\x04\x1ATiens, prends déjà cet objet!\x01Il te sera certainement utile!\x04\x1AEn l'utilisant, même un petit\x01gars comme toi pourra déraciner \x01des \x05\x41Choux-Péteurs\x05\x40 avec \x05\x43\x05\x40.\x02", "box_type": 0},
    {"id": 0x301D, "text": "Allez, nettoie-moi la \x05\x41Caverne\x01Dodongo\x05\x40! Nous reparlerons de \x01cette pierre plus tard!\x02", "box_type": 0},
    {"id": 0x301E, "text": "Hé! Mon Frère! Rejoue-moi cette \x01chanson quand tu veux!\x02", "box_type": 0},
    {"id": 0x301F, "text": "Je ne me lasserai jamais de cette \x01chanson! Elle est si funky!\x02", "box_type": 0},
    {"id": 0x3020, "text": "Hmmm... Ce n'est pas vraiment mon\x01style de musique...\x04Mais plutôt un truc...rigolo...\x01...champêtre...genre nature, quoi!\x04Mon style à moi c'est le rock\x01des arbres et tout ça...\x02", "box_type": 0},
    {"id": 0x3021, "text": "Alors on peut entrer dans la \x01caverne maintenant? \x01T'es un génie! Je me demande bien\x01comment tu as fait!\x02", "box_type": 0},
    {"id": 0x3022, "text": "Je connais un truc pour conserver \x01un bâton: quand il brûle, range-le\x01avec \x05\x43\x05\x40 avant qu'il ne soit trop\x01tard!\x04Au fait, j'ai planqué un bâton \x01quelque part...\x01Hé hé hé...\x02", "box_type": 0},
    {"id": 0x3023, "text": "\x1AC'est moi! \x05\x41Darunia\x05\x40!\x01Bien joué! Chapeau, petit!\x04\x1AGrâce à toi, nous pouvons manger \x01les délicieuses pierres de la \x01Caverne Dodongo jusqu'à explosion \x01ventrale!\x02", "box_type": 0},
    {"id": 0x3024, "text": "\x1AJ'ai si faim! Je ne pense qu'à\x01manger!\x04\x1A\"Pierre Ancestrale?\"\x01Cette \x05\x41pierre rouge\x05\x40 qui éclairait\x01notre village?\x04\x1ALe chef \x05\x41Darunia\x05\x40 a dû la cacher\x01avant de s'enfermer dans son \x01antre.\x04\x1ADepuis j'ai l'impression que toutes\x01les lumières du village sont ternes!\x01Tout le monde déprime à mort...\x07\x30\x25\x02", "box_type": 0},
    {"id": 0x3025, "text": "J'aimerais que tu apportes le \x05\x41feu\x01\x05\x40de l'antre du chef jusqu'ici!\x02", "box_type": 0},
    {"id": 0x3026, "text": "Je comprends maintenant!\x01Il fallait lancer la bombe du haut\x01de la falaise...D'accooooord! \x01On aurait dû y penser plus tôt!\x02", "box_type": 0},
    {"id": 0x3027, "text": "C'est dingue! \x01T'as détruit les Dodongos? \x01Je peux t'appeller Grand Frère?\x02", "box_type": 0},
    {"id": 0x3028, "text": "Merci! Nous sommes sauvés!!!\x01Tu peux acheter des bombes \x01maintenant!\x0B\x02", "box_type": 0},
    {"id": 0x3029, "text": "Je te remercie à mort! Tu es mon \x01héros! Mon fils portera ton nom!\x02", "box_type": 0},
    {"id": 0x302A, "text": "Si tu veux en savoir plus sur les\x01Gorons, va dans notre village!\x04Le\x05\x41 Village Goron \x05\x40est au bout du\x01chemin. C'est à deux pas!\x02", "box_type": 0},
    {"id": 0x302B, "text": "Ramasse un Chou-Péteur avec \x05\x43\x05\x40. \x01Appuie sur \x05\x43 \x05\x40pour\x05\x43 \x05\x40le poser\x01ou le lancer.\x02", "box_type": 0},
    {"id": 0x302C, "text": "Si toutes les \x05\x41torches\x05\x40 étaient \x01allumées, le Village Goron serait \x01un peu plus vivant!\x02", "box_type": 0},
    {"id": 0x302D, "text": "Alors tu veux nous débarrasser \x01des Dodongos? C'est le problème \x01des Gorons, tu sais!\x04Mais ton aide est quand même la\x01bienvenue! Sauve-nous et nous \x01pourrons récupérer toutes les \x01bombes dont nous avons besoin...\x04Laisse-moi te prévenir...\x01Les Dodongos, c'est pas de la \x01rigolade! Ils mangeraient\x01n'importe quoi!!!\x04Alors fais gaffe à ne pas te faire \x01croquer!\x0B\x02", "box_type": 0},
    {"id": 0x302E, "text": "Je t'ai déjà dit!\x01J'ai plus de BOMBES!!!\x01Hooo...j'ai tellement faim!\x0A\x02", "box_type": 0},
    {"id": 0x302F, "text": "Comment va le chef?\x01......\x01Je vois...\x04Au fait, connais-tu la musique\x01qui vient de ce tunnel?\x01Nous l'adorons tous!\x02", "box_type": 0},
    {"id": 0x3030, "text": "Tu ne m'auras jamais!\x01Tu es au service de Ganondorf!\x02", "box_type": 0},
    {"id": 0x3031, "text": "\x1AComment peux-tu me faire ça?\x01Tu es aux ordres de Ganondorf!\x04\x1AEntends mon nom et tremble car \x01je suis...\x04\x1A\x05\x41\x0F\x05\x40! \x01Héros des Gorons!\x02", "box_type": 0},
    {"id": 0x3032, "text": "\x1AQuoi?\x04\x1ATon nom c'est aussi \x01\x0F?\x04\x1AAlors tu dois être le légendaire\x01tueur de Dodongos, \x01\x0F!\x04\x1AMon pôpa c'est \x05\x41Darunia\x05\x40...\x01Tu te souviens de lui?\x04\x1APôpa m'a appellé \x0F\x01en souvenir de ton courage!\x04\x1AC'est un super nom!\x01Je l'aime trop!\x04\x1A\x0F, \x01tu es le héros des Gorons! \x01Je suis très fier de te \x01rencontrer!\x04\x1ATu peux me signer un autographe?\x01Ecris juste...\x01\x06\x0C\"Pour mon ami...\x01\x06\x0C\x0F, le Goron\"\x04\x1AHo...\x04\x1APardon...c'est peut-être pas le\x01moment de te demander ça...\x04\x1AMon pôpa est parti dans le \x01\x05\x41Temple du Feu\x05\x40. \x01Il y a un dragon là-bas!\x04\x1ASi personne ne va l'aider,\x01il va se faire croquer!!\x07\x30\x33\x02", "box_type": 0},
    {"id": 0x3033, "text": "B-b-b-bouuu hoouuuu!\x0B\x02", "box_type": 0},
    {"id": 0x3034, "text": "Il a besoin d'être calmé...\x01Peut-être faut-il lui parler?\x04Sur quoi allez-vous le questionner?\x01\x01\x1B\x05\x42Le dragon\x01Les Gorons\x05\x40\x02", "box_type": 2},
    {"id": 0x3035, "text": "\x1AIl y a très longtemps de ça,\x01un gros dragon nommé \x05\x41Volcania\x05\x40 \x01vivait dans cette montagne.\x04\x1ACe dragon était très méchant!\x01Il mangeait les Gorons!\x04\x1AMais avec un marteau gigantesque,\x01le héros des Gorons...\x01Vlan! Paf! Boum!\x04\x1AIl en a fait de la purée...\x01C'est peut-être une légende mais\x01c'est vrai!\x04\x1AJ'le sais parce que mon pôpa à moi\x01c'est un descendant de ce héros!\x07\x30\x33\x02", "box_type": 0},
    {"id": 0x3036, "text": "\x1AIls ont tous été emmenés dans le\x01\x05\x41Temple du Feu\x05\x40...\x04\x1APendant que pôpa était dehors...\x01Les soldats de Ganondorf sont \x01arrivés et ils ont enlevé tout le\x01monde!\x04\x1AIls vont tous se faire manger par\x01\x05\x41Volcania\x05\x40!\x04\x1APôpa dit que c'est Ganondorf qui a\x01réveillé le dragon...\x04\x1APour faire peur aux autres races,\x01Ganondorf va donner les Gorons \x01en pâture à Volcania!!!\x04\x1APôpa est allé au Temple du Feu\x01pour les sauver...\x04\x1AAide-nous, \x0F!\x01En échange, je te donne cette \x01\x05\x41tunique résistante au feu\x05\x40!\x02", "box_type": 0},
    {"id": 0x3037, "text": "\x1APôpa m'a dit de ne laisser \x01personne le suivre, mais...\x04\x1ATu es le seul, \x0F, à \x01pouvoir sauver tout le monde!\x04\x1AJe suis sûr que le patron de la\x01boutique sera prêt à t'aider. \x01Il se cache quelque part!\x04\x1AMaintenant je vais te dire où se \x01trouve le passage secret menant \x01au Temple du Feu!\x07\x30\x38\x02", "box_type": 0},
    {"id": 0x3038, "text": "Essaie de bouger la \x05\x41statue\x05\x40 dans \x01l'antre de mon Pôpa!\x02", "box_type": 0},
    {"id": 0x3039, "text": "\x1AQui est là? Est-ce toi,\x01\x0F...?\x04\x1AC'est vraiment toi?!?\x04\x1ATu es devenu si grand depuis la\x01dernière fois!\x04\x1ABon... Faut qu'on parle...\x01D'homme à homme... \x01Mais y'a pas le temps!\x04\x1AGanondorf sème la pagaille sur le \x01Mont du Péril encore une fois!\x01Il a réveillé l'ancien dragon \x01démoniaque Volcania!\x04\x1AEt en plus il va donner tout mon\x01peuple en amuse-gueule à ce sale \x01dragon! Tout ça pour faire peur \x01aux autres races du royaume...\x04\x1ASi ce cracheur de feu s'échappe \x01de la montagne, il y a des chances\x01pour qu'Hyrule devienne un vrai \x01feu de joie!!!\x04\x1AJe vais aller voir s'il y a un\x01moyen d'enfermer ce gros reptile...\x04\x1AJe n'ai pas la masse légendaire, \x01mais le temps presse!\x04\x1A\x0F...\x01Rends-moi un service, en tant que \x01Frère de sang...\x04\x1AVa sauver mon peuple pendant que \x01je m'occupe du dragon!\x04\x1ALes cellules sont de l'autre côté.\x01Je compte sur toi, \x0F!\x02", "box_type": 0},
    {"id": 0x303A, "text": "Je suis libre!\x01Merci! Merci! Merci!\x01Voilà pour toi!\x02", "box_type": 0},
    {"id": 0x303B, "text": "\x1A\x0F...Vite...\x01Je ne peux plus tenir...\x04\x1ASors vite d'ici!!\x02", "box_type": 0},
    {"id": 0x303C, "text": "\x1AMerci mon Frère. \x05\x41\x01\x05\x40Tu as fait du bon boulot.\x01Je te remercie au nom du peuple \x01Goron tout entier!\x04\x1ATu es un vrai brave.\x01Je l'ai toujours su!\x02", "box_type": 0},
    {"id": 0x303D, "text": "\x06\x39N'oublie jamais...\x01\x06\x0DNous sommes Frères de sang!\x0E\x50\x02", "box_type": 5},
    {"id": 0x303E, "text": "\x1AIl est un fait que le temps ne \x01peut altérer...Une amitié partagée...\x01Un sentiment profond du coeur qui\x01devient plus fort au fil des jours...\x04\x1ALa confiance réciproque cèdera \x01bientôt sa place au pouvoir de \x01justice, te révélant le sentier de \x01la victoire et de la paix...\x04\x1ACette chanson est dédiée au\x01pouvoir de l'amitié...\x01Ecoute bien le \x05\x41Boléro du Feu\x05\x40...\x02", "box_type": 0},
    {"id": 0x303F, "text": "\x1A\x0F...à bientôt...\x02", "box_type": 0},
    {"id": 0x3040, "text": "\x08\x05\x44\x0F, \x01il fait beaucoup trop chaud! \x01Nous ne tiendrons pas longtemps!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3041, "text": "\x1AFrère \x0F!\x01Pôpa est revenu!\x01Tout le monde est revenu!\x04\x1APôpa et toi avez vaincu le\x01dragon! Tous les deux!\x07\x30\x42\x02", "box_type": 0},
    {"id": 0x3042, "text": "Quand j'serai grand, je s'rai fort\x01comme toi, \x0F!\x02", "box_type": 0},
    {"id": 0x3043, "text": "Merci, \x0F!!\x02", "box_type": 0},
    {"id": 0x3044, "text": "Merci de nous avoir sauvés!\x0A\x02", "box_type": 0},
    {"id": 0x3045, "text": "\x1AMoi, Darunia l'indomptable,\x01m'éveille à la conscience de \x01\x05\x41Sage du Feu\x05\x40...\x04\x1AMoi! Un Sage! \x01C'est marrant, non? Enfin...\x01C'est ce qu'on appelle le destin.\x04\x1ASi ma présence ici peut faire\x01reculer les forces du mal...\x01Tu peux compter sur moi!\x02", "box_type": 0},
    {"id": 0x3046, "text": "\x1ATiens mon Frère! Prends ceci!\x01Ce \x05\x41médaillon\x05\x40 renferme le pouvoir \x01du feu...et mon amitié.\x02", "box_type": 0},
    {"id": 0x3047, "text": "Alors là, gros problème!\x01Tout le monde est parti!\x01Mais ma boutique est toujours\x01ouverte!\x0A\x02", "box_type": 0},
    {"id": 0x3048, "text": "\x1ABen dis donc! Quelle histoire!\x04\x1AEt dire que l'on croyait les \x01Dodongos disparus depuis bien des \x01lunes! Toute cette affaire est \x01étrange...\x04\x1AEt puis ce rocher à l'entrée de la \x01caverne...\x04\x1AA mon avis \x05\x41Ganondorf\x05\x40 est le \x01responsable de tout ce tintouin!\x04\x1A\"\x05\x44Donne-moi la Pierre Ancestrale et\x05\x40 \x01\x05\x44j'ouvrirai la caverne\x05\x40\", qu'il a dit...\x04\x1AQuel sale type...\x01Par contre toi, tu n'as pas hésité \x01à risquer ta vie pour nous... Merci.\x02", "box_type": 0},
    {"id": 0x3049, "text": "\x06\x3DUn peu serré...\x02", "box_type": 0},
    {"id": 0x304A, "text": "Je travaille sur un truc vraiment\x01costaud! Mais ça va me prendre \x01du temps...\x07\x30\x4B\x02", "box_type": 0},
    {"id": 0x304B, "text": "Reviens disons dans...\x01Cinq ou six ans, OK?\x02", "box_type": 0},
    {"id": 0x304C, "text": "Je viens de finir ce cure-dent. \x01Qu'en dis-tu?\x07\x30\x4F\x02", "box_type": 0},
    {"id": 0x304D, "text": "Alors qu'en penses-tu?\x02", "box_type": 0},
    {"id": 0x304E, "text": "Je n'ai pas encore résolu son \x01problème de résistance...\x01Mais enfin...\x07\x30\x4F\x02", "box_type": 0},
    {"id": 0x304F, "text": "Me le prends-tu pour 200 Rubis?\x01\x01\x1B\x05\x42J'achète!\x01Trop cher\x05\x40\x02", "box_type": 0},
    {"id": 0x3050, "text": "Ok, reviens quand tu veux.\x02", "box_type": 0},
    {"id": 0x3051, "text": "Ne me mange pas! \x01Ne me mange pas!\x01Ne me mange pas!\x01Ne me mange pas!\x04J'ai un goût atroce!\x02", "box_type": 0},
    {"id": 0x3052, "text": "Le Chef Darunia t'a demandé de \x01me sauver? Je te dois une fière\x01chandelle!\x04Va vite aider Grand Frère!\x02", "box_type": 0},
    {"id": 0x3053, "text": "Mon frèèèère...\x01A ouveeeert un nouveau maaagasin...\x01C'est la boutique de laaaaames de\x01Medigoooooron...\x04Mais mooooiiiiiii... \x01Je fooooorge les meilleures \x01épées du mooooonde!\x04Les ouvriers Hyliens admiiiirent\x01mes taaaaalents...\x01J'te jure!\x02", "box_type": 0},
    {"id": 0x3054, "text": "\x1ACette lame est briiiiisée...\x01J'aimeraiiiis te la répaaaarer mais...\x04\x1AL'éruuuuuption d'hier a irriiité\x01mes yeux...\x04\x1ALe \x05\x41Roi Zoooora \x05\x40a\x05\x41 \x05\x40des gouttes \x01pour mes yeeeuuuuuux...\x07\x30\x55\x02", "box_type": 0},
    {"id": 0x3055, "text": "Peuuuuux-tu aller les chercher?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x3056, "text": "Nooooon... \x01Mes yeuuuuux....\x01Ouuiiillle...Booooboooo!\x02", "box_type": 0},
    {"id": 0x3057, "text": "Tout le monde est parti!\x01Je suis le seul survivant!\x0B\x02", "box_type": 0},
    {"id": 0x3058, "text": "Je t'ai attendu les yeux pleeiiins\x01de laaarrrrmmmmmes...\x02", "box_type": 0},
    {"id": 0x3059, "text": "\x1AOooooh? Tu as rapportééé les\x01gouuutttes?! Je vais les utiliiiser\x01tout de suuiiitte!\x0B\x02", "box_type": 0},
    {"id": 0x305A, "text": "\x1A\x05\x41Wowwwwwwwwwwwwww!!\x05\x40\x04\x1ACaaaaa faaaiiiittt duuuu bieeennn!\x01J'y voooiiiis pluus claiiir!\x04\x1AJe vais pouvoir me remettre au\x01boulot! Tiens prends çaaaa, pour\x01te faaaiiire patienter.\x07\x30\x5C\x02", "box_type": 0},
    {"id": 0x305B, "text": "Tout le monde est revenu!\x01Je fais des affaires monstres!\x0B\x02", "box_type": 0},
    {"id": 0x305C, "text": "Revieeeens...\x01Daaanns quelques jours...\x01Paaatience...\x02", "box_type": 0},
    {"id": 0x305D, "text": "Paaaaas encoooore...\x01Tu vas patienter, ouais?\x02", "box_type": 0},
    {"id": 0x305E, "text": "Voilàààààà c'est finiiiii!\x02", "box_type": 0},
    {"id": 0x305F, "text": "\x08\x05\x44Votre \x05\x40bouclier\x05\x44 a disparu!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3060, "text": "\x08\x05\x44Votre \x05\x40tunique \x05\x44a disparu!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3061, "text": "\x08\x05\x44Votre \x05\x40bouclier\x05\x44 et votre \x05\x40tunique\x05\x44 \x01ont disparu!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3062, "text": "\x1ABravo! \x01Tu es parvenu jusqu'ici sans\x01trop de problèmes, \x0F. \x01Te voici au Sommet du Péril!\x04\x1AOn raconte que les nuages autour\x01du pic reflètent la santé de la\x01Montagne. S'ils sont blancs, le\x01Mont est en paix...\x04\x1AEscalader cette montagne est bien\x01la preuve de ton courage! Mais \x01sauras-tu faire une sage décision?\x04\x1ALa \x05\x41Grande Fée\x05\x40 demeure au sommet.\x01Va donc la voir et elle te remettra\x01un nouveau pouvoir! Hou Hou Hou!\x04\x1AJe vais attendre ton retour. \x01N'hésite à me demander de te\x01faire descendre de la montagne.\x01A plus tard! Hou hou hou!!!\x02", "box_type": 0},
    {"id": 0x3063, "text": "Hoouu hou!\x01Le nouveau pouvoir de la Grande \x01Fée a augmenté tes capacités...\x04Mais long est le chemin qui te \x01mènera jusqu'au salut d'Hyrule!\x04Accroche-toi à mes griffes pour \x01\x05\x41descendre la montagne\x05\x40! \x01Je peux au moins te rendre ce\x01service!\x02", "box_type": 0},
    {"id": 0x3064, "text": "On dit qu'il y a une très \x05\x41belle\x05\x40 \x01\x05\x41fée\x05\x40 au Sommet du Péril!\x01Tu y crois, toi?\x02", "box_type": 0},
    {"id": 0x3065, "text": "Il paraît qu'une \x05\x41fée\x05\x40 vit en haut de \x01la montagne.\x04Il te faut le bon \x05\x44bouclier \x05\x40pour \x01arriver jusqu'au sommet en un seul \x01morceau...\x02", "box_type": 0},
    {"id": 0x3066, "text": "\x08\x05\x44Un \x05\x40poulet\x05\x44 est sorti de ton \x05\x40oeuf\x05\x44! \x01C'est-y pas mimi la nature? Hein?\x05\x40\x09\x0E\x63\x02", "box_type": 2},
    {"id": 0x3067, "text": "Alors? Tu l'as ta pierre rouge?\x01Fais-moi goûter! Fais-moi goûter!\x04Non? Beeeuuuuhhhh!\x02", "box_type": 0},
    {"id": 0x3068, "text": "\x1AFrère! Tu vas vite devenir une\x01montagne de muscles si tu \x01continues comme ça!\x04\x1AJe te conseille d'aller voir\x01la \x05\x41Grande Fée\x05\x40 au sommet du \x01Mont du Péril! Elle a un cadeau \x01pour toi!\x04\x1AHé les gars! Venez tous faire un\x01gros câlinou à notre Frère!\x02", "box_type": 0},
    {"id": 0x3069, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1ADans ce temple tu trouveras des \x01\x05\x41portes\x05\x40...agressives. \x01Evite de te faire écraser!\x04\x1ATu pourras les détruire avec la\x01\"spécialité locale\" des Gorons.\x02", "box_type": 0},
    {"id": 0x306A, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1ASi ta tunique se met à brûler, \x01agite ton épée dans tous les sens\x01ou fait une roulade pour l'éteindre...\x01Tu le savais déjà? Ah bon.\x02", "box_type": 0},
    {"id": 0x306B, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1ACertaines créatures vont bientôt\x01t'attaquer en dansant... \x01Elles sont insensibles aux flèches!\x04\x1AJe crois que tu auras besoin\x01d'une bonne moisson de notre \x01\"spécialité locale\".\x02", "box_type": 0},
    {"id": 0x306C, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1ATu devras trancher certains \x01interrupteurs pour les activer. \x01Mais notre \"spécialité locale\" est\x01aussi très efficace!\x02", "box_type": 0},
    {"id": 0x306D, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1ALa carte t'indiquera certains \x01endroits inaccessibles. \x01Utilise ton ocarina!\x02", "box_type": 0},
    {"id": 0x306E, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1APour accéder à la pièce de \x01Darunia, tu devras faire quelque\x01chose avec le pilier coincé au\x01plafond.\x04\x1ATrouve un moyen d'aller au-dessus\x01du plafond!\x02", "box_type": 0},
    {"id": 0x306F, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1AUne porte est cachée dans la \x01statue à l'entrée du temple.\x04\x1AMais la \"specialité locale\" ne sera\x01pas suffisante...Trouve quelque \x01chose de plus costaud!\x02", "box_type": 0},
    {"id": 0x3070, "text": "\x1APour te remercier, voici un petit\x01conseil...\x04\x1ALes parois sensibles à notre\x01\"spécialité locale\" sonnent \x01différemment lorsqu'elles sont \x01frappées avec une épée.\x02", "box_type": 0},
    {"id": 0x3071, "text": "Oh? Tu es venu me sauver?\x01Je peux partir?\x0B\x02", "box_type": 0},
    {"id": 0x3072, "text": "3072\x02", "box_type": 0},
    {"id": 0x3073, "text": "3073\x02", "box_type": 0},
    {"id": 0x4000, "text": "\x1ACes yeux sont délicieux!\x01Je vais m'en faire un bon ragoût!\x01Nyaha ha ha ha!\x04\x1ADis bien merci au Roi Zora!\x01Hein? Quoi?\x0B\x02", "box_type": 0},
    {"id": 0x4001, "text": "\x1AJe dois en faire des \x05\x41Gouttes pour\x01Biggoron\x05\x40? Oh! Quel dommage!\x01Tu m'as donné faim!\x0B\x02", "box_type": 0},
    {"id": 0x4002, "text": "\x1A\x0F!\x01Par ici!  Hou hou!\x0C\x28\x1AJe me demande ce que devient \x01\x05\x41Saria\x05\x40! Pourquoi ne pas aller dans \x01la forêt de temps en temps?\x02", "box_type": 0},
    {"id": 0x4003, "text": "\x1AQue fais-tu là? Tu as parcouru\x01un bien long chemin pour arriver\x01jusqu'ici...\x0C\x28\x1AN'hésite pas à consulter le \x01\x05\x41Sous-menu de la Carte\x05\x40.\x04\x1A\x0F... \x01Regarde autour de toi...\x01Ce lac est d'une pureté cristalline.\x04\x1AAu fond des eaux se trouve le \x01\x05\x43Temple de l'Eau \x05\x40dédié aux \x05\x43Esprits \x01de l'Eau\x05\x40. Les Zoras en sont\x01les gardiens. Hou, hou!\x04\x1ALes Zoras sont originaires du \x01Domaine Zora au Nord Est d'Hyrule.\x01Cette race aquatique est fidèle à\x01la Famille Royale.\x04\x1ASeuls les membres de la Famille \x01Royale peuvent entrer dans le \x01Domaine Zora...\x01Hou hou!\x04\x1ABon, je retourne au \x05\x41château\x05\x40.\x01Pour venir avec moi, accroche-toi \x01à mes serres!\x02", "box_type": 0},
    {"id": 0x4004, "text": "Bon, je retourne au \x05\x41château\x05\x40.\x01Pour venir avec moi, accroche-toi \x01à mes serres!\x02", "box_type": 0},
    {"id": 0x4005, "text": "\x1A...Hein?\x04\x1AIl y a quelque chose dans\x01cette bouteille. C'est une \x05\x41lettre\x05\x40:\x04\x1A\x08\x06\x0C\"\x05\x45A l'aide!\x01\x05\x40\x06\x0C\x05\x45Je suis enfermée dans le\x01\x05\x40\x06\x0C\x05\x45ventre du\x05\x40 \x05\x46Grand Jabu-Jabu!\x05\x45\x01\x05\x40\x06\x18-\x05\x46Ruto\x05\x40\x09\x04\x1A\x08\x06\x0C\x05\x45PS: N'en parlez pas à Père.\x05\x40\"\x09\x02", "box_type": 2},
    {"id": 0x4006, "text": "\x1AQui es-tu?\x04\x1ANous sommes les \x05\x43Zoras\x05\x40, fier \x01peuple aquatique!\x04\x1ATu dis avoir quelques liens avec\x01la Famille Royale d'Hyrule...\x01Que pouvons nous faire pour toi?\x02", "box_type": 0},
    {"id": 0x4007, "text": "Nous sommes d'excellents \x01plongeurs! Et toi?\x04Pour devenir un bon plongeur, \x01essaie le \x05\x41jeu du plongeon \x05\x40en haut \x01de la cascade! Va piquer une tête!\x02", "box_type": 0},
    {"id": 0x4008, "text": "\x1ALa Fontaine Zora est la source\x01du fleuve.\x01\x05\x41Le Grand Jabu-Jabu \x05\x40vit dans cette\x05\x41 \x01\x05\x40fontaine.\x07\x40\x09\x02", "box_type": 0},
    {"id": 0x4009, "text": "Le Grand Jabu-Jabu est notre dieu.\x01La \x05\x41Princesse Ruto\x05\x40  a pour mission \x01de lui préparer ses repas matin et\x01soir.\x02", "box_type": 0},
    {"id": 0x400A, "text": "Nous sommes tous les sujets du\x01grand \x05\x41Roi Zora\x05\x40!\x02", "box_type": 0},
    {"id": 0x400B, "text": "Le grand Roi Zora est dans la\x01\x05\x41salle du trône\x05\x40.\x02", "box_type": 0},
    {"id": 0x400C, "text": "As-tu vu le Grand Jabu-Jabu?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x400D, "text": "Selon la \"Légende Zora\", faire\x01présent d'un poisson au Grand\x01Jabu-Jabu te rendra heureux pour\x01la journée.\x02", "box_type": 0},
    {"id": 0x400E, "text": "Non? Quel dommage!\x04Tous les nouveaux visiteurs se \x01doivent de présenter leurs \x01respects au \x05\x41Grand Jabu-Jabu\x05\x40!\x04La Fontaine Zora est juste \x01derrière la salle du trône du Roi \x01Zora. Le Grand Jabu-Jabu y prend\x01son bain. Mais...\x04Sans la permission du Roi Zora\x01tu ne pourras y accéder.\x02", "box_type": 0},
    {"id": 0x400F, "text": "\x1ALa \x05\x41Princesse Ruto \x05\x40est introuvable.\x01Nous l'avons cherchée partout, \x01même dans le \x05\x43Lac Hylia\x05\x40....\x02", "box_type": 0},
    {"id": 0x4010, "text": "Si tu trouves des indices sur la\x01disparition de la \x05\x41Princesse Ruto\x05\x40, \x01va vite en informer notre Roi!\x02", "box_type": 0},
    {"id": 0x4011, "text": "Toute l'eau d'Hyrule provient de la\x01\x05\x43Fontaine Zora\x05\x40.\x04Cette eau parcourt le Fleuve Zora\x01et aboutit dans le \x05\x43Lac Hylia \x05\x40\x01au sud.\x02", "box_type": 0},
    {"id": 0x4012, "text": "\x1AOh--Nous revenons à la vie!\x04\x1AEst-ce toi qui Nous a sauvé?\x01Ne sois pas timide devant Nous!\x04\x1AIl Nous semble que tu ne puisses \x01respirer sous l'eau comme les \x01nobles Zoras...\x04\x1AEn reconnaissance de tes services,\x01Nous t'offrons cette \x05\x41tunique\x05\x40. \x01Elle te permettra de respirer sous\x01l'eau. Comme Nous, quoi.\x02", "box_type": 0},
    {"id": 0x4013, "text": "La Princesse Ruto est partie au \x01Lac Hylia et n'est jamais revenue.\x01Nous sommes inquiet...\x02", "box_type": 0},
    {"id": 0x4014, "text": "\x1AHoo...\x01Il veut donc....hmmm...\x01Hmmm... \x05\x41Des Gouttes\x05\x40...?\x04\x1APeut-être en avons-Nous,\x01peut-être n'en avons-Nous pas...\x01Nous en avons les \x05\x41ingrédients\x05\x40.\x04\x1AApporte les ingrédients au docteur\x01du \x05\x41laboratoire\x05\x40, il en fera des\x01Gouttes!\x04\x1AMais garde-les au frais...\x07\x40\x15\x02", "box_type": 0},
    {"id": 0x4015, "text": "Peux-tu t'en occuper avant qu'\x05\x41ils \x01ne se dessèchent\x05\x40?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4016, "text": "Alors ne penses-tu pas être aussi\x01rapide que Nous?\x01Ce n'est qu'à une minute à cheval!\x02", "box_type": 0},
    {"id": 0x4017, "text": "\x1AHou hou!\x0C\x28\x1A\x0F, \x01Ton aventure te plait-elle?\x04\x1ALa Princesse Zelda t'attend.\x04\x1ATu as déjà le \x05\x41Rubis Goron\x05\x40,\x01n'est-ce pas?\x02", "box_type": 0},
    {"id": 0x4018, "text": "Salut à toi, mon garçon! \x01En mélangeant l'eau du Lac Hylia à\x01des trucs baveux je fais des \x01potions dégueulasses!!!\x04As-tu déjà rencontré la p'tite \x01vieille de l'apothicaire?\x04Elle est comme mon élève et \x01teste toutes mes potions...\x01Nyarf nyarf nyarf!\x02", "box_type": 0},
    {"id": 0x4019, "text": "\x08Oh! Woah!\x09\x04\x1ASuperbe \x05\x41Crapaud-qui-louche\x05\x40.\x01Un spécimen comme celui-ci se\x01fait rare depuis un bon moment!\x0B\x02", "box_type": 0},
    {"id": 0x401A, "text": "Notre chère et douce Princesse\x01Ruto... Mais où est-elle?\x01Nous sommes si inquiet...\x02", "box_type": 0},
    {"id": 0x401B, "text": "\x1AHo! Cette lettre! \x01Elle est de la \x05\x41Princesse Ruto\x05\x40!!\x04\x1AHmmm...voyons voir...\x01Elle est dans le ventre du Grand\x01Jabu-Jabu?\x01C'est incroyable!\x04\x1ANotre dieu protecteur, le \x05\x41Grand\x05\x40\x01\x05\x41Jabu-Jabu\x05\x40, ne ferait jamais une\x01chose pareille à la Princesse Ruto!\x04\x1AMais depuis la venue de cet \x01étranger, \x05\x41Ganondorf\x05\x40, le Grand \x01Jabu-Jabu est un peu pâlot...\x04\x1ALes faits sont clairs...\x01Tu dois délivrer Notre Ruto!\x01Passe derrière Nous et dirige-toi \x01vers l'autel du Grand Jabu-Jabu.\x04\x1ANous gardons cette lettre.\x01Tu peux conserver cette \x05\x41bouteille\x05\x40!\x07\x40\x1C\x02", "box_type": 0},
    {"id": 0x401C, "text": "Nous t'en prions...\x01Sauve la \x05\x41Princesse Ruto\x05\x40...\x02", "box_type": 0},
    {"id": 0x401D, "text": "\x08\x05\x44Vous ne pouvez respirer sous l'eau!\x01Retirez ves \x05\x40bottes \x05\x44avant qu'il ne\x01soit trop tard!\x05\x40\x09\x0E\x3C\x02", "box_type": 2},
    {"id": 0x401E, "text": "\x08\x06\x36Hoooo! Noooooonnnn!\x09\x02", "box_type": 0},
    {"id": 0x401F, "text": "\x1AOh--Nous revenons à la vie!\x04\x1ANous as-tu sauvé?\x01Ne sois pas timide et parle-Nous!\x04\x1ANous allons te donner cette \x01tunique Zora en gage de Notre \x01immense gratitude!\x01Tu pourras...Quoi?!\x04\x1ATu en as déjà une? \x01Tu es à la mode, toi!\x04\x1ABon alors...\x01Que dirais-tu d'un de Nos bisous?\x01Quoi? Tu n'en veux pas?\x01Ha! Bon...\x04\x1ASi tu ne veux pas de Nos cadeaux,\x01écoute au moins Nos petits\x01malheurs...\x07\x40\x13\x02", "box_type": 0},
    {"id": 0x4020, "text": "Je suis un \x05\x43Zora\x05\x40. As-tu vu une\x01jolie fille zora dans le coin?\x02", "box_type": 0},
    {"id": 0x4021, "text": "Je suis un \x05\x43Zora\x05\x40. As-tu vu quelque\x01chose d'étrange dans le Lac? \x01Le fleuve véhicule souvent bien\x01des curiosités!\x02", "box_type": 0},
    {"id": 0x4022, "text": "\x1AToi...\x08t'es en retard!\x09\x01\x08Je t'attends depuis une heure!\x09\x01Tu es \x08NUL!\x09\x04\x1AJe me sentais seule, c'est tout...\x01Juste un peu!!\x02", "box_type": 0},
    {"id": 0x4023, "text": "\x1A\x08J'avais peur...\x09\x08un peu!\x09 \x01Enfin juste un peu!!\x02", "box_type": 0},
    {"id": 0x4024, "text": "\x1A\x0F!\x01\x0F!\x02", "box_type": 5},
    {"id": 0x4025, "text": "\x1A\x08Toi!\x09\x01T'es cool... Plus cool que je ne le\x01pensais... \x08Enfin juste un peu!\x09\x04\x1ATu m'as sauvée... Je dois donc te \x01récompenser!\x04\x1AQue veux-tu de moi? Je t'écoute...\x01\x01\x1B\x05\x42La Pierre Ancestrale\x01Rien du tout\x05\x40\x02", "box_type": 0},
    {"id": 0x4026, "text": "\x1ATu veux le \x05\x43Saphir Zora\x05\x40?\x07\x40\x27\x02", "box_type": 0},
    {"id": 0x4027, "text": "\x1AMa mère me l'a transmis et je ne\x01le donnerai qu'à mon futur mari.\x01C'est une bague de fiançailles \x01Zora!\x04\x1A\x06\x4E\x08Bon OK!\x09\x04\x1AJe te donne mon bien le plus\x01précieux:\x01Le Saphir Zora!\x02", "box_type": 0},
    {"id": 0x4028, "text": "Ne le dis pas à Père...\x02", "box_type": 0},
    {"id": 0x4029, "text": "\x1AHihihihi... Ne sois pas timide.\x04\x1AJe sais à quoi tu penses...\x07\x40\x27\x02", "box_type": 0},
    {"id": 0x402A, "text": "Je veux acheter un poisson mais \x01je n'ai pas assez d'argent...\x04Il ne me reste qu'à en pêcher un.\x01Il y en a dans ce coin...\x02", "box_type": 0},
    {"id": 0x402B, "text": "Oh, \x0F!\x01Alors tu as sauvé la Princesse?\x01Nous en sommes ravi!\x02", "box_type": 0},
    {"id": 0x402C, "text": "Prends-tu soin de mon bien le plus \x01précieux?\x01Hihihihihihi!\x02", "box_type": 0},
    {"id": 0x402D, "text": "Oh! Salut \x0F!\x01La Princesse Ruto ne parle que de\x01toi!\x02", "box_type": 0},
    {"id": 0x402E, "text": "Oh! C'est toi, \x0F!\x01Merci pour tout! Le Grand \x01Jabu-Jabu est en pleine forme!\x02", "box_type": 0},
    {"id": 0x402F, "text": "\x1ATous les Zoras respectent le Roi\x01Zora! Il a la dignité et la noblesse\x01d'un grand souverain! \x01Il a une classe...dingue!\x04\x1ALe grand Roi Zora a une fille \x01unique: la Princesse \x05\x41Ruto\x05\x40. \x04\x1AC'est un vrai garçon manqué!\x01Notre Roi en est très inquiet.\x07\x40\x0B\x02", "box_type": 0},
    {"id": 0x4030, "text": "\x1AVoilà!\x04\x1AGaranties sans colorants ni \x01conservateurs! Mais elles risquent\x01de tourner dans \x05\x41peu de temps\x05\x40.\x04\x1AVa vite à la montagne Goron! \x01Tu es jeune et rapide, non?\x01Tu peux y arriver!\x02", "box_type": 0},
    {"id": 0x4031, "text": "\x1AHou hou! \x01Tu es devenu très fort, \x01\x0F!\x04\x1APlus loin se trouve le \x05\x43Domaine\x01Zora\x05\x40. Les Zoras protègent cette \x01source d'eau et servent la Famille \x01Royale d'Hyrule.\x04\x1ALeur porte ne s'ouvrira que pour\x01un ami de la Famille Royale.\x04\x1AChante haut et fort la \x05\x41Mélodie de \x01la Famille Royale\x05\x40!\x01Houu hou hoouu!\x02", "box_type": 0},
    {"id": 0x4032, "text": "Apporte-moi un p'tit cadeau la\x01prochaine fois!\x02", "box_type": 0},
    {"id": 0x4033, "text": "\x1AVous avez trouvé la Princesse \x01Ruto! Le Roi Zora vous donnera \x01sûrement la \x05\x43Pierre Ancestrale de \x01l'Eau\x05\x40! Enfin...peut-être.\x04\x1AHummm?\x02", "box_type": 2},
    {"id": 0x4034, "text": "\x1ASon \"bien le plus précieux\"?\x01Vous ne savez pas de quoi elle\x01parlait mais vous avez deux\x01Pierres! Plus qu'une à trouver!\x02", "box_type": 2},
    {"id": 0x4035, "text": "\x1ASon \"bien le plus précieux\"?\x01Vous ne savez pas de quoi elle\x01parlait mais vous avez les trois\x01Pierres Ancestrales!!\x04\x1AAllez voir Zelda!\x02", "box_type": 2},
    {"id": 0x4036, "text": "\x1AA nouveau nos routes se croisent,\x01\x0F...\x02", "box_type": 0},
    {"id": 0x4037, "text": "\x1ACette glace est le fruit d'une \x01malédiction... Le monstre du \x05\x43Temple \x01de l'Eau\x05\x40 en est la source.\x04\x1AVivant, la glace ne pourra jamais\x01fondre....\x04\x1ATon courage puisse-t-il sauver tous\x01les Zoras. Je vais t'enseigner la\x01mélodie du Temple de l'Eau.\x02", "box_type": 0},
    {"id": 0x4038, "text": "\x1ALe temps file et emporte les\x01hommes...\x01Ainsi coule le fleuve et jamais ne\x01s'arrête...\x04\x1AUn jeune esprit renferme un coeur\x01ambitieux... Des amours légères \x01cèdent à une passion profonde...  \x01Un miroir d'eau pure reflète la vie.\x04\x1AEcoute la \x05\x43Sérénade de l'Eau \x05\x40et \x01contemple ton reflet...\x02", "box_type": 0},
    {"id": 0x4039, "text": "\x1ATu arrives trop tard, les Zoras \x01ne sont pas ici...\x01Voici ce qu'il en reste...\x04\x1ALes Zoras sont prisonniers de\x01cette vague de glace! \x01Tous...sauf une......\x04\x1AJ'ai pu sauver la Princesse du gel\x01éternel, mais elle s'est rendue \x01au \x05\x43Temple de l'Eau\x05\x40...\x02", "box_type": 0},
    {"id": 0x403A, "text": "Il te faut un récipient pour \x01acheter un poisson.\x0B\x02", "box_type": 0},
    {"id": 0x403B, "text": "Tu veux acheter une \x05\x43tunique Zora\x05\x40?\x01Cet habit est cousu d'un tissu\x01précieux. Il est honteusement cher!\x04\x05\x41Les familles fortunées\x05\x40 de Cocorico \x01sont les seules à pouvoir se \x01l'offrir!\x0B\x02", "box_type": 0},
    {"id": 0x403C, "text": "403C\x02", "box_type": 0},
    {"id": 0x403D, "text": "403D\x02", "box_type": 0},
    {"id": 0x403E, "text": "\x1AHo!...Toi?...Tu es?...\x01\x0F?!\x04\x1A\x0F, c'est bien toi?\x04\x1AC'est moi, \x05\x43Ruto\x05\x40!\x05\x43 \x05\x40Ta fiancée!\x01Princesse des Zoras!\x04\x1AJe n'ai pas oublié notre promesse!\x04\x1ATu ne manques pas d'air!\x01Me faire attendre pendant sept \x01longues années...\x04\x1AMais l'heure n'est pas vraiment \x01aux histoires de coeur...\x04\x1AAs-tu vu le Domaine Zora?\x01Tout est gelé!\x04\x1AUn jeune homme nommé \x05\x41Sheik\x05\x40 m'a \x01sauvée des glaces...\x04\x1AMais mon père et les autres Zoras\x01sont\x14\x02...encore...\x14\x00\x04\x1AJe veux tous les sauver!\x01Je veux sauver le Domaine Zora!\x04\x1ATu dois m'aider!\x01C'est une faveur que je te \x01demande, moi...ta future femme!\x04\x1A\x0F, \x01tu dois m'aider à détruire l'infect\x01monstre du temple, d'accord?!\x04\x1ATu trouveras \x05\x41trois endroits\x05\x40 te \x01permettant de changer le niveau \x01de l'eau.\x04\x1AJe passe devant...\x01Suis-moi! Vite!!!\x02", "box_type": 0},
    {"id": 0x403F, "text": "\x1A\x0F! Attention!\x01Cette eau n'est pas normale!\x02", "box_type": 0},
    {"id": 0x4040, "text": "4040\x02", "box_type": 0},
    {"id": 0x4041, "text": "\x1A\x0F...\x04\x1ATu es bien digne d'être mon futur\x01époux.\x04\x1ALe Domaine Zora et son peuple \x01vont enfin se libérer des glaces.\x02", "box_type": 0},
    {"id": 0x4042, "text": "\x1ADis bien merci à Sheik de ma part.\x0E\x5A\x02", "box_type": 5},
    {"id": 0x4043, "text": "\x1ARuto veut me remercier?\x04\x1AJe vois....\x04\x1AC'est aussi pour elle que nous \x01devons ramener paix et joie \x01en Hyrule.\x02", "box_type": 0},
    {"id": 0x4044, "text": "4044\x02", "box_type": 0},
    {"id": 0x4045, "text": "Nous voyons...\x01La Princesse Ruto est dans le \x01Temple de l'Eau...\x02", "box_type": 0},
    {"id": 0x4046, "text": "\x1AComme récompense...\x01Je t'offre mon amour éternel.\x04\x1AMême si pour l'instant je ne peux\x01t'en offrir davantage.\x02", "box_type": 0},
    {"id": 0x4047, "text": "\x1ALa Princesse Zelda...Elle est en vie.\x01Je le sens. Ne te décourage pas.\x02", "box_type": 0},
    {"id": 0x4048, "text": "\x08\x06\x42Beuâââârk!\x01\x06\x17C'est quoi? Une pieuvre?!\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x4049, "text": "\x1AEn tant que \x05\x43Sage de l'Eau\x05\x40,\x05\x43 \x01\x05\x40mon devoir est d'assurer la garde \x01du Temple de l'Eau...\x04\x1ALe tien est de chercher la \x01Princesse...comment...?\x01\x05\x41Zelda\x05\x40?\x04\x1AHa!\x01Tu ne peux rien me cacher!\x02", "box_type": 0},
    {"id": 0x404A, "text": "\x1ATa quête de justice et de paix \x01sera victorieuse...j'en suis sûre.\x01Prends ce \x05\x43Médaillon \x05\x40et garde-le\x01précieusement!\x02", "box_type": 0},
    {"id": 0x404B, "text": "\x1AToi! Qui es-tu?!\x04\x1AJe suis \x05\x41Ruto\x05\x40, Princesse des Zoras.\x04\x1A\x08Quoi?!\x09\x01Mon père t'a demandé de me \x01sauver?\x04\x1AJe n'ai \x08rien\x09 demandé à personne!\x04\x1A\"Un message dans une bouteille?\" \x01Je ne \x08vois pas\x09 de quoi tu parles!\x04\x1AMon père est très inquiet?\x04\x1AJ'm'en \x08fiche!\x09\x04\x1ADe toute façon, je ne peux pas \x01partir maintenant.\x01Quant à toi...\x08Va-t'en d'ici!\x09\x01\x08Compris?!\x09\x02", "box_type": 0},
    {"id": 0x404C, "text": "\x1ATu es encore là, toi?\x01Je t'ai dit de partir!\x04\x1AJe vais dans le ventre de \x01Jabu-Jabu depuis que je suis toute \x01petite! Alors j't'ai pas attendu!\x04\x1ALe Grand Jabu-Jabu n'est pas \x01dans son assiette aujourd'hui...\x04\x1AIl y a d'étranges méduses \x01électriques et des trous partout...\x04\x1AEt en plus, ma chère pierre a été...\x01\x08Mais c'est pas tes oignons!\x09\x04\x1AToi! \x08Tu rentres chez toi!\x09\x01\x08Compris?!\x09\x0B\x02", "box_type": 0},
    {"id": 0x404D, "text": "\x1ATu t'inquiètes tant que ça pour \x01moi?\x04\x1AAlors je t'accorde l'honneur de me\x01porter!\x04\x1A\x08Toutefois\x09...Je ne partirai pas \x01sans avoir trouvé ce que je \x01cherche. Tu peux en être sûr!\x0B\x02", "box_type": 0},
    {"id": 0x404E, "text": "\x08Ho! Vilain!\x09\x01Tu m'as abandonnée?!\x01Comment oses-tu faire une chose\x01pareille à une Princesse?\x0B\x02", "box_type": 0},
    {"id": 0x404F, "text": "\x1A\x08Voilà!\x09\x01C'est ça que je cherche!\x01Lance-moi sur cette plate-forme!\x02", "box_type": 0},
    {"id": 0x4050, "text": "\x1A\x08La Princesse Ruto trouve la \x01\x05\x43Pierre Ancestrale\x05\x40!\x09\x01\x14\x02Mais\x14\x00 pourquoi la Princesse Ruto?\x02", "box_type": 2},
    {"id": 0x4051, "text": "\x1AEnfin!\x01J'ai trouvé... \x01La Pierre de ma maman...\x04\x1AJ'étais tellement triste quand le\x01Grand Jabu-Jabu l'a avalée...\x04\x1ATout ça s'est passé pendant son\x01repas... Il s'est agité et m'a avalée\x01d'un seul coup!\x04\x1ABon...on peut partir maintenant!\x02", "box_type": 0},
    {"id": 0x4052, "text": "Ramène-moi à la maison!\x01Tout de suite!\x02", "box_type": 0},
    {"id": 0x4053, "text": "Jeu du plongeon: 20 Rubis.\x01Tu veux essayer?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4054, "text": "\x08\x06\x47PARFAIT!\x09\x04Ramasse tous les rubis avant la \x01fin du chrono!\x04Passe cette épreuve et reviens me \x01voir pour gagner un prix!\x0B\x02", "box_type": 0},
    {"id": 0x4055, "text": "\x1A\x08Hé! Félicitations!\x09\x01J'ai un beau cadeau pour toi! \x01Viens vite le chercher!\x0B\x02", "box_type": 0},
    {"id": 0x4056, "text": "\x1AQuel magnifique plongeon!\x01Prends donc ceci!\x04\x1ACette \"\x05\x41écaille\x05\x40\" de Zora te\x01permettra de plonger plus \x01profondément.\x0B\x02", "box_type": 0},
    {"id": 0x4057, "text": "\x1ALes flots s'élèvent... \x01Et le mal se dissout...\x01Tu as triomphé \x0F!\x02", "box_type": 0},
    {"id": 0x4058, "text": "\x1AJe te crois capable de sauver ce \x01monde...\x02", "box_type": 0},
    {"id": 0x4059, "text": "\x1ARegarde, \x0F...\x04\x1ALa bête maléfique a péri. \x01Toi et la Princesse Ruto avez\x01accompli cet acte héroïque!\x04\x1ALes eaux pures et claires \x01emplissent à nouveau ce paisible \x01lac...\x02", "box_type": 0},
    {"id": 0x405A, "text": "\x08\x06\x38\x05\x41Et c'est parti!\x05\x40\x09\x0B\x02", "box_type": 0},
    {"id": 0x405B, "text": "Passe les cascades pour un \x01raccourci!\x0B\x02", "box_type": 0},
    {"id": 0x405C, "text": "Attrape un maximum pour 20 Rubis.\x01Ca te tente?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x405D, "text": "\x08Hé! Bravo!!\x09\x0B\x02", "box_type": 0},
    {"id": 0x405E, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Les ventes sont faibles...\x04Je t'en propose...\x01\x05\x4110 Rubis\x05\x40 pièce?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x405F, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Leur succès est médiocre.\x04Je t'en propose...\x01\x05\x4120 Rubis\x05\x40 pièce?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4060, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Ils sont assez populaires...\x04\x05\x4130 Rubis\x05\x40 pièce.\x01T'en veux?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4061, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Ils sont à la mode!\x04\x05\x4140 Rubis\x05\x40 pièce.\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4062, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Il ne m'en reste que très peu!\x04\x05\x4150 Rubis\x05\x40 pièce.\x01(Offre spéciale)\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4063, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Ils sont siiiii bons!\x04Super promo!\x01\x05\x4160 Rubis \x05\x40pièce!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4064, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Ca marche du tonnerre!\x04Promo de la mort!\x01\x05\x4170 Rubis\x05\x40 pièce!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4065, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Ils sont introuvables!\x04Offre de folie!\x01\x05\x4180 Rubis\x05\x40 pièce!\x01\x1B\x05\x42Oui \x01No\x05\x40\x02", "box_type": 0},
    {"id": 0x4066, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01C'est cher mais...c'est cool!\x04Je ne peux les lâcher à moins de\x01\x05\x4190 Rubis\x05\x40 pièce!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4067, "text": "\x1AMiam miam miam...\x01Veux-tu des \x05\x41haricots magiques\x05\x40?\x01Combien??? Devine!!!! \x01Hé hé hé...\x04\x05\x41100 Rubis pièce\x05\x40!\x01Wouahahahahaha!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4068, "text": "Ha! Bon...\x01Miam miam...\x02", "box_type": 0},
    {"id": 0x4069, "text": "Pas assez d'argent! \x01J'vais pas te les donner pour \x01rien! Miam miam...\x02", "box_type": 0},
    {"id": 0x406A, "text": "Assigne un haricot à \x05\x46¡ \x05\x40et \x01plante-le dans la terre à côté.\x02", "box_type": 0},
    {"id": 0x406B, "text": "Dommage! Je suis en rupture de\x01de stock! Miam miam...Comment?\x01Non! Ces haricots ne sont pas à \x01vendre! C'est mon goûter...\x02", "box_type": 0},
    {"id": 0x406C, "text": "Tu trouveras de nombreux trous\x01pour planter tes haricots...\x01Cherche bien!!!\x01Miam miam miam.\x02", "box_type": 0},
    {"id": 0x406D, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x41un mètre\x05\x40. \x01C'est pas terrible.\x02", "box_type": 0},
    {"id": 0x406E, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x412 mètres\x05\x40. \x01C'est pas terrible.\x02", "box_type": 0},
    {"id": 0x406F, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x413 mètres\x05\x40. \x01C'est pas terrible.\x02", "box_type": 0},
    {"id": 0x4070, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x414 mètres\x05\x40. \x01Ce n'est pas assez.\x02", "box_type": 0},
    {"id": 0x4071, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x415 mètres\x05\x40. \x01Ce n'est pas assez.\x02", "box_type": 0},
    {"id": 0x4072, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x416 mètres\x05\x40. \x01Tu peux faire mieux.\x02", "box_type": 0},
    {"id": 0x4073, "text": "Sans que tu le saches, je \x01t'observais... \x01Tu viens de plonger à \x05\x417 mètres\x05\x40. \x01Tu peux faire mieux.\x02", "box_type": 0},
    {"id": 0x4074, "text": "\x1ASans que tu le saches, je\x01t'observais...\x01Tu as \x05\x41touché le fond\x05\x40. Tu es fort!\x01Prends ceci en récompense!\x02", "box_type": 0},
    {"id": 0x4075, "text": "Tu es le meilleur plongeur du \x01monde... Peut-être devrais-tu \x01plonger dans le Lac Hylia?\x02", "box_type": 0},
    {"id": 0x4076, "text": "Mon nom est \x05\x41Pierre\x05\x40 l'épouvantail! \x01J'adore les rythmes entraînants! \x01Mais je suis planté ici...\x02", "box_type": 0},
    {"id": 0x4077, "text": "Superbe mélodie! \x01Elle fait bouger mon p'tit corps!\x0B\x02", "box_type": 0},
    {"id": 0x4078, "text": "N'hésite pas à revenir me chanter\x01quelque chose!\x0B\x02", "box_type": 0},
    {"id": 0x4079, "text": "Cette mélodie est gravée au fond\x01de mon coeur...\x01Joue-la encore une fois!\x0B\x02", "box_type": 0},
    {"id": 0x407A, "text": "Je garde cette mélodie au fond \x01de mon coeur!\x0B\x02", "box_type": 0},
    {"id": 0x407B, "text": "La partie de pêche te coûtera...\x01\x05\x4120 Rubis\x05\x40!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x407C, "text": "Ha! Tu n'as pas de \x05\x41Kit Vibration\x05\x40! \x01Tu ne pourras malheureusement \x01pas sentir les poissons taquiner \x01ton hameçon.\x04Pas de vibrations pour toi!\x0B\x02", "box_type": 0},
    {"id": 0x407D, "text": "Whoa! Tu as un \x05\x41Kit Vibration\x05\x40!\x01Tu pourras sentir les poissons\x01taquiner ton hameçon!\x0B\x02", "box_type": 0},
    {"id": 0x407E, "text": "Dommage! Tu n'as pas assez\x01d'argent!\x02", "box_type": 0},
    {"id": 0x407F, "text": "Bon! Je t'explique!\x04Approche-toi du bord de l'eau et \x01appuie sur \x05\x44¤\x05\x40 pour repérer un\x01poisson.\x04Envoie ta ligne vers ce poisson \x01avec \x05\x42 \x05\x40  puis appuie sur \x05\x43 \x05\x40pour\x01arrêter le déroulement de la ligne.\x04Remue l'appât avec \x05\x44ª\x05\x40 ou utilise\x01\x05\x42  \x05\x40si tu es un débutant!\x04Remonte ta ligne avec \x05\x43 \x05\x40et \x01appuie sur \x05\x44£ \x05\x40pour l'enrouler \x01plus vite.\x04Si tu sens une touche, accroche-la\x01avec \x05\x43\x05\x42 \x05\x40et \x05\x44ª \x05\x40vers le bas. \x01Remonte ensuite la ligne avec \x05\x43\x05\x40.\x04Tu as bien tout compris?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4080, "text": "Je suis très généreux aujourd'hui!\x01Tu peux pêcher aussi longtemps \x01que tu le désires... Mais tu ne \x01pourras conserver qu'un poisson.\x04Le poisson le plus gros jamais \x01attrapé pèse \x05\x41\x1D livres\x05\x40.\x04Au fait! Change ton angle de vue\x01avec \x05\x44¤ \x05\x40après avoir jeté ta ligne.\x04\x06\x20Allez hop! A la pêche!\x0B\x02", "box_type": 0},
    {"id": 0x4081, "text": "Wah ha ha ha ha!\x01As-tu accroché ce poisson en \x01appuyant sur \x05\x43\x05\x40 et \x05\x44ª \x05\x40en bas?\x02", "box_type": 0},
    {"id": 0x4082, "text": "Que s'est-il passé?\x01Tu as perdu ta prise!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x4083, "text": "Mouais... Il pèse \x05\x41\x1D livres.\x05\x40\x01Veux-tu le garder?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4084, "text": "Que veux-tu?\x01\x1C\x05\x42Peser mon bô poisson!\x01Discuter un peu\x01Partir\x05\x40\x02", "box_type": 0},
    {"id": 0x4085, "text": "La passion seule ne fait pas le \x01bon pêcheur!\x02", "box_type": 0},
    {"id": 0x4086, "text": "\x06\x4BWHOAAAA!\x04Ce poisson est é-norme! C'est un \x01nouveau record! Il pèse au bas\x01mot \x05\x41\x1D livres\x05\x40! Vraiment! \x01Tiens voilà ton prix!\x0B\x02", "box_type": 0},
    {"id": 0x4087, "text": "Héééé! \x01J'suis pas un poisson moi!!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x4088, "text": "Hé! P'tite tête! T'as pas un truc\x01plus important à faire?\x04Quoi? Tu trouves que c'est plus\x01drôle de jouer ici?\x04Y'en a beaucoup qui sont morts\x01en faisant ça! C'est mauvais pour\x01la santé! Sérieux!\x01Enfin bon...\x02", "box_type": 0},
    {"id": 0x4089, "text": "\x08Plus gros poisson jamais pêché.\x01Poids:  \x1D livres.\x01Pêcheur: \x0F\x09\x02", "box_type": 2},
    {"id": 0x408A, "text": "Veux-tu continuer à pêcher?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x408B, "text": "Il ne pèse que:  \x05\x41\x1D livres\x05\x40...\x01Y'a plus gros, c'est sûr!\x0B\x02", "box_type": 0},
    {"id": 0x408C, "text": "Ben alors! C'est pas la forme?\x0B\x02", "box_type": 0},
    {"id": 0x408D, "text": "Tu veux essayer un autre appât?\x01N'as-tu pas confiance en moi?\x01N'aimes-tu pas mon matériel?\x04On dit souvent:\x01\"Le bon pêcheur ne décide jamais\x01de ses appâts!\"\x02", "box_type": 0},
    {"id": 0x408E, "text": "Quoi? Tu veux connaître ma \x01technique secrète de pêche?\x01Ben justement, ma technique...\x01Elle est secrète...\x02", "box_type": 0},
    {"id": 0x408F, "text": "Quoi? Tu veux savoir si je suis \x01un bon pêcheur!\x04T'étais pas né que le grand \x01Jabu-Jabu se balançait au bout de\x01ma ligne! \x01J'suis un pro! Une pointure!\x02", "box_type": 0},
    {"id": 0x4090, "text": "\x08Règlement:\x09\x01\x081. Ne pas utiliser d'appâts coulants.\x012. Ne pas cracher dans l'étang.\x013. Rester calme.\x09\x04\x084. Ne pas jeter sa ligne sur \x01le patron.\x015. Ne pas utiliser de bombes.\x09\x02", "box_type": 1},
    {"id": 0x4091, "text": "Wooaa! Quel gros morceau!\x01Voyons voir... Il pèse...\x01\x05\x41\x1D livres\x05\x40!\x04Veux-tu le garder?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4092, "text": "Reviens une fois plus grand!\x01Les poissons auront grandi aussi!\x01Wha ha ha ha...hmm...hmm.\x02", "box_type": 0},
    {"id": 0x4093, "text": "\x1AHé, jeune homme! Je me souviens \x01de toi! Cela fait un bail!\x04\x1ACombien d'années? Sept?! \x01Alors...quelles nouvelles?!\x04\x1AMoi? Bof....\x01Tu es mon seul client. \x01Je n'ai plus de boulot.\x01Les temps sont durs!\x04\x1AEn plus mes cheveux...\x04\x1AEnfin...\x01C'est un charme dont j'me passe.\x04\x1ABon...tu veux pêcher?\x01\x05\x4120 Rubis\x05\x40!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x4094, "text": "Quoi?\x04Tu veux pêcher ailleurs? \x01T'es fou!?\x04Qu'est-ce que je vais devenir?\x02", "box_type": 0},
    {"id": 0x4095, "text": "Quoi?\x04Pourquoi j'me gratte tout l'temps?\x01Mais...j'me gratte pas!\x01T'es un p'tit marrant, toi!\x02", "box_type": 0},
    {"id": 0x4096, "text": "Quoi?\x04L'eau est trop sombre?\x01Les poissons ne mordent pas?\x04Mais.... N'importe quoi!\x01C'est le meilleur moment pour\x01pêcher!\x04Un énorme poisson peut mordre à\x01n'importe quel moment!\x01C'est ça la grande aventure de la\x01pêche, mon p'tit bonhomme!\x02", "box_type": 0},
    {"id": 0x4097, "text": "Hé! Ho non! C'est interdit, ça!\x01Rends-moi mon chapeau ou \x01j't'accroche à mon hameçon!\x04Tu m'cherches ou quoi?\x01Rends-le moi!\x01\x1B\x05\x42OK\x01Jamais!\x05\x40\x02", "box_type": 0},
    {"id": 0x4098, "text": "Quoi? Humm? Oh?\x01Je crois que ce poisson est plus\x01petit que ta précédente prise...\x04Tu veux vraiment le garder?\x01\x01\x1B\x05\x42Non\x01Oui\x05\x40\x02", "box_type": 0},
    {"id": 0x4099, "text": "Peuchère! Il est bizarre ce \x01poisson! En plus il pèse\x01\x05\x41\x1D livres\x05\x40!\x04Veux-tu le garder?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x409A, "text": "\x06\x14Mmmm? C'est quoi ce truc?\x04C'est pas un...? Incroyable!\x01Vous trouvez un \x05\x41appât coulant\x05\x40!\x04Voulez-vous l'utiliser maintenant?\x01\x01\x1B\x05\x42Oui\x01Jamais!\x05\x40\x02", "box_type": 0},
    {"id": 0x409B, "text": "Voyons, voyons...\x04WOW! C'est pas commun!\x01C'est un \x05\x41brochet Hylien\x05\x40!\x04Ce poisson est si rare, son poids \x01n'est pas important... \x01Voilà ton prix!\x0B\x02", "box_type": 0},
    {"id": 0x409C, "text": "Ce type de poisson se fait rare.\x01Je vais le relâcher.\x0B\x02", "box_type": 0},
    {"id": 0x409D, "text": "\x08Règlement:\x011. Ne pas utiliser d'appâts coulants.\x012. Ne pas utiliser de bombes.\x013. Rester calme.\x09\x02", "box_type": 1},
    {"id": 0x409E, "text": "Holà! Holà!\x01Les cannes ne sortent pas d'ici!\x04Ta journée de pêche finie, \x01rapporte ta canne au patron!\x02", "box_type": 0},
    {"id": 0x409F, "text": "Ohhhh mon Dieuuuuu!!!\x01Ce poisson est énooooorme!!\x04Il ne tient même pas à l'écran! \x01J'peux pas l'peser... Il va faire \x01imploser ma balance!!! \x01Il doit faire \x05\x41\x1D livres\x05\x40!\x04Tu veux garder ce monstre, hein?\x01\x01\x1B\x05\x42Le garder\x05\x40\x01\x05\x42Ne pas le garder\x05\x40\x02", "box_type": 0},
    {"id": 0x40A0, "text": "Hé! P'tit mec!\x01Moi c'est \x05\x41Bonooru\x05\x40, l'épouvantail!\x01j'ai une mémoire fabuleuse!\x04N'hésite pas à me jouer une\x01super mélodie!\x04Voilà la mélodie que tu m'as jouée\x01la dernière fois, mec!\x04Chauffe, petit!\x0B\x02", "box_type": 0},
    {"id": 0x40A1, "text": "Je suis \x05\x41Bonooru\x05\x40 l'épouvan-tail \x01musi-cal et gé-nial!\x01Moi...J'n'oublie jamais une mélodie!\x02", "box_type": 0},
    {"id": 0x40A2, "text": "Entonne ta mélodie pour appeler \x01mon copain Pierre! \x01Il apparaîtra s'il se trouve dans \x01l'coin, mec!\x02", "box_type": 0},
    {"id": 0x40A3, "text": "Hé! N'es-tu pas le p'tit mec à la\x01fée d'il y a sept ans?\x01Wow! T'as bien grandi!\x04Tiens voilà ta mélodie...\x04Quoi?\x04Non, moi j'oublie rien!\x01Alors joue ta mélodie pour voir...\x01Tu l'as peut-être oubliée, qui sait?\x01Joue, mec! Joue!!!\x02", "box_type": 0},
    {"id": 0x40A4, "text": "Whaouuu! Tu as un ocarina!\x01Pourquoi ne pas en pousser une \x01petite?\x0B\x02", "box_type": 0},
    {"id": 0x40A5, "text": "Mmmmm.... Pas mal!\x01Je vais l'enregistrer pour toi!\x04A la différence de Pierre, je peux\x01mémoriser n'importe quelle chanson,\x01même très longue! Mais ne \x01retenons que cette partie, OK?\x0B\x02", "box_type": 0},
    {"id": 0x40A6, "text": "C'est mal! \x01Jouer de cette façon ne fera \x01jamais bouger mon p'tit corps!!!\x0B\x02", "box_type": 0},
    {"id": 0x40A7, "text": "HO YEAHHH!!\x01C'est ça! C'est la mélodie!!\x01Ca balance!! Je suis soufflé!\x04Je n'ai pas oublié cette mélodie...\x01Je n'oublie jamais rien! \x01Je vais te récompenser, mec!\x04........\x01J'ai une idée!\x04Mon pote Pierre se balade dans le\x01coin! Joue cette mélodie et il\x01apparaîtra...peut-être!\x04Je vais lui dire de t'aider au \x01son de ton ocarina!\x0B\x02", "box_type": 0},
    {"id": 0x40A8, "text": "Hé! C'est un ocarina!\x01Joue ta chanson, mec!\x0B\x02", "box_type": 0},
    {"id": 0x40A9, "text": "\x12\x28\xE4Quel chant délicieux!\x01Cette mélodie est très belle...\x01Crooâââââ! Nous allons l'apprendre\x01par coeur...Croooââââ !\x04Prends donc ces Rubis!\x01N'hésite pas à revenir nous\x01chanter quelque chose...\x01Croooâââ croooâââ!\x0B\x02", "box_type": 0},
    {"id": 0x40AA, "text": "\x12\x28\xE3Crooooââââââ!\x01Cette mélodie est divine! \x01Croooâââââ!\x04Je chaaaaannnte sous la pluie!\x01Croooââââ!!\x04La communauté grenouille te dit:\x01Merci!!! A bientôt!!\x01Crooooâââââ!\x0B\x02", "box_type": 0},
    {"id": 0x40AB, "text": "\x12\x28\xE4Nous sommes les célèbres ténors \x01grenouillesques!!! Les stars de \x01l'étang! Croooââââ!!\x04Fais-nous sauter pour avaler les\x01insectes! Croooââââ!!!\x04D'accord? \x01Trois, deux, un, PARTEZ!\x0B\x02", "box_type": 0},
    {"id": 0x40AC, "text": "\x12\x28\xE3Fantastique! Délicieux!\x01Un repas bien équilibré!\x01Crooooââââââ!\x04Gros crapauds et belles grenouilles\x01te disent: Merci! Burp.\x0B\x02", "box_type": 0},
    {"id": 0x40AD, "text": "Je ne me souviens pas de cette \x01chanson, mec! \x01Pourquoi? J'sais pas moi!\x02", "box_type": 0},
    {"id": 0x40AE, "text": "\x08Le plus gros poisson pêché dans \x01cet étang pèse: \x1D livres.\x01Pêcheur: le patron \x09\x02", "box_type": 2},
    {"id": 0x40AF, "text": "Quoi? Tu veux pêcher avec un \x01autre appât?\x01...Hé! C'est quoi ça?\x04Quoi? Tu l'as trouvé? Mon oeil!\x01Tu n'as pas le droit d'utiliser ça! \x01C'est le règlement!\x01Enfin...je passe l'éponge...\x02", "box_type": 0},
    {"id": 0x40B0, "text": "WHOOOOOAAAAAAOOOO!\x01Il est E-N-O-R-M-E!!! \x01Tu as pulvérisé le record!!! \x01Il pèse \x05\x41\x1D livres\x05\x40!!\x04Maaaaaaais...tu n'as pas utilisé un\x01appât réglementaire!\x01Donc...pas de prix pour toi!\x01Hé hé hé hé!!! P'tit tricheur!\x0B\x02", "box_type": 0},
    {"id": 0x40B1, "text": "\x08Le plus gros poisson pêché dans\x01cet étang pèse: \x1D livres.\x01Pêcheur: \x0F\x01(NOTE: appât non-réglementaire!)\x09\x02", "box_type": 2},
    {"id": 0x40B2, "text": "T'es un bon p'tit gars!\x01Mais ne dis pas à tout le monde \x01que j'ai plus un poil sur l'caillou!\x0B\x02", "box_type": 0},
    {"id": 0x40B3, "text": "QUOIIIIII?!?\x04Pourquoi tant de haine?\x01T'es un punk, toi?\x04Mais j'vais pas m'laisser faire!\x01Paie-moi \x05\x4150 Rubis\x05\x40!\x01Non mais des fois!\x0B\x02", "box_type": 0},
    {"id": 0x5000, "text": "\x08GYAAAH!\x09\x01\x14\x02\x08Tu\x09 \x08m'as\x09 \x08tué!!\x09\x14\x00\x01Hein? Oh! C'est toi.\x04As-tu déjà utilisé le\x01\x05\x46Chant du soleil\x05\x40?\x04Comme je te l'ai déjà dit, ce chant\x01te permet de passer de la nuit au \x01jour et inversement. Et ceci à\x01n'importe quel moment.\x04Même plongé dans les ténèbres, ce \x01chant te viendra en aide.\x01N'hésite pas à souvent l'utiliser!\x02", "box_type": 0},
    {"id": 0x5001, "text": "\x08En creusant un trou, j'ai trouvé un\x01truc qui fait BOING! BOING!\x01On dirait un ressort...\x01Je ne le donnerai à personne!\x09\x02", "box_type": 2},
    {"id": 0x5002, "text": "Vous trouvez le \x05\x41journal du \x01fossoyeur\x05\x40.\x04Désirez-vous le lire?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 2},
    {"id": 0x5003, "text": "\x08Toi le petit curieux qui lit ce\x01journal, viens dans ma tombe.\x01Et peut-être auras-tu droit à mon\x01précieux \x05\x41trésor\x05\x40.\x09\x04\x08Je t'attends...\x01--Igor\x09\x02", "box_type": 2},
    {"id": 0x5004, "text": "\x08Etre curieux, c'est pas bien...\x09\x02", "box_type": 2},
    {"id": 0x5005, "text": "Vous avez vaincu un Esprit!\x04Voulez-vous le garder dans une\x01bouteille?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 2},
    {"id": 0x5006, "text": "Vous n'avez malheureusement pas \x01de bouteille vide.\x02", "box_type": 2},
    {"id": 0x5007, "text": "L'Esprit peut alors s'enfuir.\x02", "box_type": 2},
    {"id": 0x5008, "text": "Vous obtenez un Esprit!\x02", "box_type": 2},
    {"id": 0x5009, "text": "\x1A\x08\x06\x14La course du soleil s'achève\x01\x06\x3Ble soir venu...\x01\x06\x18Les nouvelles vies un jour\x01\x06\x3Dse meurent...\x09\x04\x1A\x08\x06\x2DUn soleil, une lune.\x01\x06\x30Un jour, une nuit.\x09\x04\x1A\x08\x06\x05Respecte les morts jadis vivants.\x09\x04\x1APurée... Que c'est beau!\x02", "box_type": 2},
    {"id": 0x500A, "text": "\x08\x06\x0CEntonne le \x05\x46Chant du Soleil\x05\x40 et \x01\x06\x11apaise le long tourment des \x01\x06\x3Aâmes damnées\x09\x02", "box_type": 2},
    {"id": 0x500B, "text": "\x1AIl y a quelque chose d'écrit\x01sur cette pierre tombale...\x04\x1AC'est la \x05\x46mélodie secrète\x05\x40 des \x01Frères Musiciens!\x02", "box_type": 2},
    {"id": 0x500C, "text": "Potion ultime! Que dis-tu de\x01\x05\x41100 Rubis\x05\x40?\x01\x1B\x05\x42Acheter\x01Ne pas acheter\x05\x40\x02", "box_type": 0},
    {"id": 0x500D, "text": "Reviens me voir si tu changes\x01d'avis... Hé hé hé hé!\x02", "box_type": 0},
    {"id": 0x500E, "text": "Tu n'as pas assez d'argent!\x01Hé hé hé hé!\x02", "box_type": 0},
    {"id": 0x500F, "text": "\x1AGYAAAAH!\x01\x14\x02\x08Tu\x09 \x08m'as\x09 \x08tué...\x09\x14\x00\x08INCROYABLE!\x09\x04\x1AOh! Hein?\x01Tu n'es pas un soldat de \x01Ganondorf! Qui es-tu?\x04\x1ADésolé de m'être comporté de la \x01sorte, mais... Je ne suis qu'un\x01fantôme, après tout!\x04\x1ASais-tu qui je suis? Non?\x01Ah bon... Alors écoute-moi bien.\x01Hum hum...\x07\x50\x10\x02", "box_type": 0},
    {"id": 0x5010, "text": "Je suis un fantôme de l'un des \x01frères musiciens du Village \x01Cocorico.\x04Tous les habitants de ce village \x01sont les loyaux sujets de la Famille\x01Royale d'Hyrule.\x04Mon frère et moi-même avions\x01pour mission d'étudier les pouvoirs\x01mystiques héréditaires de la Famille\x01Royale.\x04Tout en ignorant à quoi pouvait \x01bien servir la célèbre Triforce,\x04nous fûmes sur le point d'achever\x01nos expériences sur le \x05\x41contrôle du\x05\x40\x01\x05\x41temps\x05\x40 grâce aux ocarinas.\x04Plus précisément...\x04Nous avons percé le mystère du \x01temps!\x04La gloire nous tendait les bras\x01mais cet odieux Ganondorf tenta \x01de dérober le résultat d'années \x01d'études!\x04Et c'est donc au prix de nos vies\x01que nous pûmes protéger le secret.\x07\x50\x11\x02", "box_type": 0},
    {"id": 0x5011, "text": "Veux-tu que je répète tout ça?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x5012, "text": "\x1A\x08GYAAAAH!\x09\x01\x14\x02\x08JE SUIS\x09 \x08MORT!\x09 \x08Heu...\x09\x08ENCORE?\x09\x14\x00\x01Gueuh?? C'est toi?\x04\x1ATu me fais vraiment penser à la\x01Princesse Zelda.\x04\x1ATu es en si bons termes avec la\x01Famille Royale que je vais de ce \x01pas te conter la suite de notre\x01tragique histoire.\x04\x1AEn raison de nos nombreuses\x01symphonies, les sujets d'Hyrule \x01nous élevèrent au rang de Grands\x01Compositeurs.\x04\x1AMais notre rôle sur cette terre ne \x01se bornait pas à la composition.\x04\x1ANotre mission était d'analyser les\x01mystérieux pouvoirs de la Famille\x01Royale d'Hyrule.\x04\x1AMais les évènements ont voulu\x01que le résultat de nos recherches \x01ne soit jamais révélé...\x01Pourtant la gloire nous souriait!\x04\x1ANos études furent gardées \x01secrètes jusqu'à terme....\x07\x50\x14\x02", "box_type": 0},
    {"id": 0x5013, "text": "\x1A\x08GYAAAAH!\x09\x01\x14\x02\x08JE SUIS\x09 \x08MORT!\x09 \x08Heu?\x09\x08ENCORE?\x09\x14\x00\x01Quoi?? Encore toi?\x04\x1ATu me fais vraiment penser à la\x01Princesse Zelda.\x04\x1ATu es en si bons termes avec la\x01Famille Royale que je vais de ce \x01pas te conter la suite de notre\x01tragique histoire.\x07\x50\x14\x02", "box_type": 0},
    {"id": 0x5014, "text": "Pour être franc, chaque frère \x01étudiait un chant différent.\x01L'un pour \x05\x41invoquer le soleil \x05\x40et \x01l'autre pour \x05\x41invoquer la lune\x05\x40.\x04Si un membre de la Famille Royale\x01t'a envoyé jusqu'ici, je pense \x01pouvoir te faire confiance et te\x01faire partager notre secret.\x04Va donc examiner les inscriptions\x01sur la \x05\x41pierre tombale royale\x05\x40.\x04Toi, jeune messager de la Famille\x01Royale, chante haut et fort ta\x01loyauté sur la Sainte Triforce.\x07\x50\x11\x02", "box_type": 0},
    {"id": 0x5015, "text": "Z Z Z...\x04Malon...tout va bien...\x01Mmm...(ronfle)...Mmm...\x01Tout va bien...\x02", "box_type": 0},
    {"id": 0x5016, "text": "Ingo s'occupe du Ranch Lon Lon à\x01présent. On l'appelle le \x05\x41Ranch Ingo\x05\x40.\x04On m'a fichu dehors et...\x01Regarde dans quel état j'suis!\x01Ma fille Malon y travaille toujours.\x04Je me fais tant de souci...\x02", "box_type": 0},
    {"id": 0x5017, "text": "Malon est de nouveau heureuse?\x01Je vais retourner au Ranch!\x02", "box_type": 0},
    {"id": 0x5018, "text": "\x1A\x08Hé! Petit!\x09\x01Laisse les tombes à leur place!\x04\x1AMoi c'est \x05\x41Igor le fossoyeur\x05\x40!\x01Ma face fait peur aux mouches \x01mais je suis un chic type...\x04\x1AConnais-tu l'attraction du\x01cimetière?\x01Elle s'appelle...\x04\x1A\x06\x1A\x05\x41L'excursion du fossoyeur\x05\x40!\x04\x1AJe creuse, je creuse...\x01J'trouve un truc ou que dalle...\x01Fais-moi creuser et...\x01Garde tout pour ta pomme!\x07\x50\x19\x02", "box_type": 0},
    {"id": 0x5019, "text": "Tu veux que j'creuse ici?\x01C'est \x05\x4110 Rubis\x05\x40 le trou.\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x501A, "text": "\x05\x41Y'a rien ici!\x05\x40\x02", "box_type": 0},
    {"id": 0x501B, "text": "\x1AArrière, \x0F!\x02", "box_type": 0},
    {"id": 0x501C, "text": "\x1A\x0F....\x01Un grand malheur vient de se \x01produire! Le \x05\x41monstre de l'ombre\x05\x40 \x01s'est échappé!\x04\x1A\x05\x41Impa\x05\x40, chef du Village Cocorico, \x01a jadis combattu puis enfermé le \x01Monstre de l'Ombre au fond du \x01puits....\x04\x1AMais depuis longtemps cette bête,\x01grâce à l'influence de Ganondorf, \x01rassemble ses forces pour enfin\x01recouvrer sa liberté!!!\x02", "box_type": 0},
    {"id": 0x501D, "text": "\x1AJe vais m'occuper du village!\x01Je compte sur toi \x0F.\x02", "box_type": 0},
    {"id": 0x501E, "text": "\x08\x06\x28Frère Musicien Royal\x01\x06\x3CBémol l'aîné\x01\x06\x37Repose En Paix\x09\x0B\x02", "box_type": 2},
    {"id": 0x501F, "text": "\x08\x06\x28Frère Musicien Royal\x01\x06\x38Dièse le cadet\x01\x06\x37Repose En Paix\x09\x0B\x02", "box_type": 2},
    {"id": 0x5020, "text": "\x08\x06\x37Tombe Royale\x09\x02", "box_type": 2},
    {"id": 0x5021, "text": "\x1A\x08Cette ode est dédiée à la mémoire\x01\x06\x03des disparus de la Famille Royale.\x09\x0B\x02", "box_type": 0},
    {"id": 0x5022, "text": "\x1AJeune garçon à l'ocarina...\x01Enfin tu es venu.\x04\x1AMon nom est \x05\x41Impa\x05\x40 des Sheikahs.\x01Je suis la nourrice de la Princesse\x01et le Sage du Temple de l'Ombre.\x02", "box_type": 0},
    {"id": 0x5023, "text": "\x1APrends bien soin de la Princesse!\x0E\x32\x02", "box_type": 5},
    {"id": 0x5024, "text": "\x1A\x0F, le héros!\x04\x1AEnfin les \x05\x41six Sages \x05\x40sont éveillés!\x01L'heure est venue pour toi de \x01défier le Seigneur du Malin!\x04\x1AMais avant de croiser le fer avec\x01le vil Ganondorf, il te reste une \x01personne à rencontrer...\x04\x1ACette personne t'attend au\x01\x05\x44Temple du Temps\x05\x40....\x02", "box_type": 0},
    {"id": 0x5025, "text": "\x1ADepuis des siècles, les Sheikahs \x01furent les serviteurs secrets de \x01la Famille Royale d'Hyrule.\x01Toutefois...\x04\x1AIl y a sept ans, Ganondorf lança\x01son attaque et le Château d'Hyrule \x01dut se rendre après une très \x01courte bataille.\x04\x1AGanondorf était à la recherche\x01de l'une des clés du Saint \x01Royaume...le trésor secret de la \x01Famille Royale...l'Ocarina du Temps!\x04\x1AMon devoir était de mettre\x01la Princesse Zelda à l'abri.\x04\x1AJe me souviens t'avoir vu lors\x01de notre fuite...\x04\x1ATu es devenu un valeureux\x01guerrier...\x02", "box_type": 0},
    {"id": 0x5026, "text": "\x1AMon devoir est de rester ici... \x01Trouve la Princesse Zelda et \x01protège-la à ma place.\x04\x1AJe vais maintenant te transmettre\x01mon pouvoir grâce à ce \x05\x43Médaillon\x05\x40!\x02", "box_type": 0},
    {"id": 0x5027, "text": "Comment se porte ta Cocotte?\x01Veux-tu me la remettre?\x02", "box_type": 0},
    {"id": 0x5028, "text": "\x1A\x12\x68\x55Je suis le \x05\x41chef des ouvriers \x01\x05\x40engagé par Impa pour transformer\x01le village en grande ville!\x04\x1AMais les jeunes gens d'aujourd'hui\x01n'ont aucune ambition...\x04\x1AMes ouvriers se baladent toute\x01la sainte journée! Alors le travail \x01prend du retard et ça me rend \x01dingue...\x04\x1AMême mon propre fils ne travaille\x01pas. Il fiche sa vie en l'air!\x07\x50\x29\x02", "box_type": 0},
    {"id": 0x5029, "text": "\x1AInutiles et paresseux! TOUS!\x02", "box_type": 0},
    {"id": 0x502A, "text": "Regarde-moi cette pauvre fille.\x01Elle s'occupe des cocottes même \x01en étant allergique aux plumes!\x01Quel courage...je l'aime...\x04J'aimerais bien l'aider mais...\x01Les cocottes, moi ça m'énerve!\x01Pas toi?\x02", "box_type": 0},
    {"id": 0x502B, "text": "\x1ALa Princesse est à l'abri \x01maintenant...\x02", "box_type": 0},
    {"id": 0x502C, "text": "\x1ATrès bientôt, Zelda viendra tout \x01t'expliquer...\x04\x1AUne fois les six Sages réunis et\x01le Roi Sombre détruit, la vérité te \x01sera révélée.\x02", "box_type": 0},
    {"id": 0x502D, "text": "\x1AHéhéhé, mon p'tit bouchon...\x01Alors t'es un rapide, hein?\x04\x1AEn récompense je te donne mon\x01trésor... un \x05\x41Grappin\x05\x40!\x04\x1ACette chaîne montée sur ressort\x01te hissera là où sa pointe s'est\x01plantée. Pratique, hein?\x04\x1AReviens me voir et tu gagneras \x01peut-être un autre p'tit cadeau. \x01Alors à bientôt!\x04\x1AAu fait... Bonne chance pour sortir \x01d'ici! Yark yark yark!\x02", "box_type": 0},
    {"id": 0x502E, "text": "Te revoilà, mon bouchon...\x01As-tu toujours sur toi mon\x01p'tit cadeau?\x02", "box_type": 0},
    {"id": 0x502F, "text": "\x06\x05Le temps de cette course est de\x01\x06\x4B\x17!!\x0B\x02", "box_type": 0},
    {"id": 0x5030, "text": "\x1ABien... Tu reviens à toi...\x02", "box_type": 0},
    {"id": 0x5031, "text": "\x1AImpa est partie sceller le\x01\x05\x45Temple de l'Ombre\x05\x40,\x05\x43 \x05\x40mais...\x01Elle sera en danger si personne ne \x01vient lui prêter main-forte!\x04\x1A\x0F!\x01Impa est l'une des six Sages.\x01Va détruire le Monstre de l'Ombre\x01et sauve Impa!\x04\x1AL'entrée du Temple se trouve sous \x01le cimetière de ce village.\x04\x1ALa seule chose en mon pouvoir est\x01de t'apprendre la mélodie t'ouvrant \x01le passage vers le Temple de \x01l'Ombre...\x04\x1ACet air te plongera dans les \x01ténèbres abyssales... \x01Hors du temps et de l'espace...\x01Entends le \x05\x45Nocturne de l'Ombre\x05\x40!!\x02", "box_type": 0},
    {"id": 0x5032, "text": "Tourne et tourne! \x01Encore et encore!\x01Quelle fête!!!\x04Je suis un joyeux musicien\x01qui tourne et tourne et tourne!\x01Danse et tourne avec moi!!!\x04J'aimerais que ma chanson du \x01moulin fasse le tour du monde!\x01Tourne et tourne et tourne!!!\x02", "box_type": 0},
    {"id": 0x5033, "text": "Tourne et tourne et...hein?\x01Holà! Ca tourne trop vite!\x01Stooooooooooooooop!!!\x02", "box_type": 0},
    {"id": 0x5034, "text": "Grrrrrrrrr!\x04Si jamais je retrouve ce môme...\x01Je lui écrase la tête!\x01Grrrrrrrrr!\x04Il y a sept ans, il a tout détraqué \x01mon beau moulin avec son ocarina!\x01Si jamais je le retrouve...\x01Ping! Vlan! Dans les dents!\x02", "box_type": 0},
    {"id": 0x5035, "text": "\x1AQuoi?! Tu as un ocarina!!\x01Nom d'un chou-péteur!\x01Comme ce môme, il y a sept ans...\x04\x1AIl est arrivé ici comme une fleur\x01et il a joué une \x05\x45curieuse mélodie\x05\x40. \x01Mon moulin est ensuite devenu \x01complètement dingue!\x02", "box_type": 0},
    {"id": 0x5036, "text": "Que dois-je faire!?\x01Mes \x05\x41Cocottes\x05\x40 sont perdues!\x04Aide-moi, mon petit!\x01Dépose toutes les cocottes dans\x01cet enclos!\x02", "box_type": 0},
    {"id": 0x5037, "text": "Mes Cocottes sont perdues!\x01Dépose encore quatre cocottes \x01dans l'enclos!\x02", "box_type": 0},
    {"id": 0x5038, "text": "Mes Cocottes sont perdues!\x01Dépose encore trois cocottes \x01dans l'enclos!\x02", "box_type": 0},
    {"id": 0x5039, "text": "Mes Cocottes sont perdues!\x01Dépose encore deux cocottes \x01dans l'enclos!\x02", "box_type": 0},
    {"id": 0x503A, "text": "Mes Cocottes sont perdues!\x01Dépose encore une cocotte dans \x01l'enclos!\x02", "box_type": 0},
    {"id": 0x503B, "text": "\x1AMerci d'avoir retrouvé mes\x01cocottes. Mon allergie aux plumes\x01est vraiment pénible!\x04\x1AVoici un petit quelque chose\x01pour te remercier...\x0B\x02", "box_type": 0},
    {"id": 0x503C, "text": "Mais que fais-tu?!\x01Rassemble-les dans l'enclos ou \x01paie le prix fort!\x0B\x02", "box_type": 0},
    {"id": 0x503D, "text": "Sois gentil avec les cocottes!\x02", "box_type": 0},
    {"id": 0x503E, "text": "\x1AJ'élève une nouvelle espèce de\x01Cocotte: les \x05\x41Cocottes de Poche\x05\x40! \x01Je n'y suis plus allergique!\x04\x1ALes \x05\x41Cocottes \x05\x40font d'excellents \x01réveils! Fais donc l'essai avec\x01quelqu'un de paresseux!\x04\x1ALeur chant est si mélodieux...\x01\x08\x06\x2D\x05\x41COCOOOOOOTTE\x05\x40!\x09\x01Surtout lorsqu'un gros dormeur\x01se trouve à proximité! Hi hi hi!\x04\x1AToutefois... Mes cocottes ne sont\x01pas toutes heureuses...\x04\x1ADis-moi... \x01Tu m'as l'air d'aimer les cocottes!\x01Je me trompe?\x04\x1ATiens, prends cet oeuf.\x01Après l'apparition d'une cocotte,\x01reviens me voir et nous \x01examinerons son humeur.\x07\x50\x3F\x02", "box_type": 0},
    {"id": 0x503F, "text": "Qu'en penses-tu? \x01L'idée t'intéresse?\x01\x1B\x05\x42Mouais\x01Bof\x05\x40\x02", "box_type": 0},
    {"id": 0x5040, "text": "Dommage... \x01Les cocottes te font-elles peur?\x0B\x02", "box_type": 0},
    {"id": 0x5041, "text": "Hé hé hé! Mon p'tit bouchon...\x01Tu t'crois rapide?\x04J'ai peut-être la trogne de\x01travers mais... Je fonce comme \x01une flèche! On fait la course?\x02", "box_type": 0},
    {"id": 0x5042, "text": "Sois gentil avec ma cocotte!\x01D'accord?\x02", "box_type": 0},
    {"id": 0x5043, "text": "\x1AOh! Ta cocotte est en pleine \x01forme! Tu as sûrement réveillé\x01quelqu'un de très paresseux!\x04\x1ATu aimes les cocottes à la folie!\x01Je vais te donner une cocotte \x01très rare...\x04\x1ASon nom est \x05\x41P'tit Poulet\x05\x40!\x01Mon frère s'en occupait...\x01Ses plumes bleues sont si douces!\x04\x1ADepuis le départ de mon frère,\x01P'tit Poulet n'a pas chanté une \x01seule fois....\x07\x50\x44\x02", "box_type": 0},
    {"id": 0x5044, "text": "Veux-tu garder \x05\x41P'tit Poulet\x05\x40?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x5045, "text": "Tu es amoureux de ta cocotte!\x01C'est génial! Garde-la encore un \x01peu et reviens me voir quand le\x01P'tit Poulet t'intéresse...\x0B\x02", "box_type": 0},
    {"id": 0x5046, "text": "Une vieille bique a ouvert une\x01boutique derrière celle-ci.\x01Va à gauche du comptoir pour y\x01accéder.\x0B\x02", "box_type": 0},
    {"id": 0x5047, "text": "Mon frère devait se sentir bien\x01seul...\x02", "box_type": 0},
    {"id": 0x5048, "text": "L'on dit souvent que de par les\x01\x05\x42Bois Perdus\x05\x40, d'étranges senteurs \x01vous titillent les naseaux...\x01Gniii gniii gniii...\x04Il me plairait tant de cueillir \x01maintes et diverses choses en un \x01tel lieu... Gniii gniii gniiii!\x04Mes yeux ne sont plus que l'ombre\x01d'eux-mêmes mais mes saintes \x01narines sont si fines...C'est fou! \x01Gniii gniii gniii!\x02", "box_type": 0},
    {"id": 0x5049, "text": "Sniff sniff sniff...\x04Dieu! Quelle étrange senteur...\x04Qu'as-tu dans ta besace?\x02", "box_type": 0},
    {"id": 0x504A, "text": "Jeune fou! Perdu dans la forêt...\x01\x14\x01.....\x14\x00Je vois.\x07\x50\x4B\x02", "box_type": 0},
    {"id": 0x504B, "text": "Remets-le moi prestement!\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x504C, "text": "Dommage...Gniiii...\x02", "box_type": 0},
    {"id": 0x504D, "text": "\x1AVa donc tendre à ce jeune insensé\x01cette mixture. Gniii niiii!\x01Elle est puissante! C'est dingue!\x04\x1AAllez...dehors maintenant! Gnii!\x0B\x02", "box_type": 0},
    {"id": 0x504E, "text": "Jeune homme! Il te faut un \x01récipient pour transporter une\x01potion!\x0B\x02", "box_type": 0},
    {"id": 0x504F, "text": "L'on dit de par les villes qu'un\x01jeune sot dans les bois se perd,\x01sa vie n'est plus que poussière.\x01C'est complètement fou!\x02", "box_type": 0},
    {"id": 0x5050, "text": "J'suis coincé ici...ça craint.\x01Alors je regarde le \x05\x41Mont du Péril\x05\x40.\x01Et alors ça...ça craint à mort.\x02", "box_type": 0},
    {"id": 0x5051, "text": "J'suis coincé ici...ça craint.\x01Alors je regarde les étoiles.\x01Et alors ça...ça craint à mort.\x02", "box_type": 0},
    {"id": 0x5052, "text": "T'as vu? Là-haut! \x01Il se passe quelque chose sur le\x01\x05\x41Mont du Péril\x05\x40!\x02", "box_type": 0},
    {"id": 0x5053, "text": "Tu as remarqué?\x01Le \x05\x41Mont du Péril \x05\x40est devenu normal!\x02", "box_type": 0},
    {"id": 0x5054, "text": "Je n'ai plus envie de descendre!\x01Je ne me lasserai jamais d'admirer\x01le Mont du Péril.\x02", "box_type": 0},
    {"id": 0x5055, "text": "\x1AHé! Comment vas-tu?\x01C'est mon jour de bonté...\x01Prends donc ceci!\x02", "box_type": 0},
    {"id": 0x5056, "text": "Admire les environs avec \x05\x46¥\x05\x40 et \x01utilise ensuite le \x05\x44ª\x05\x40.\x02", "box_type": 0},
    {"id": 0x5057, "text": "\x1ADis donc petit! Cela t'arrive \x01souvent d'entrer chez les gens \x01comme ça? Tu te crois où?\x01Chez ta p'tite soeur?\x04\x1A\x06\x1EEnfin...je passe l'éponge.\x04\x1AAs-tu rencontré une gentille\x01fille derrière cette maison?\x01Elle a de gros ennuis.\x04\x1A\x06\x2DTu m'écoutes, oui?\x07\x50\x58\x02", "box_type": 0},
    {"id": 0x5058, "text": "Si cette fille te parle de ses\x01cocottes, écoute-la attentivement.\x02", "box_type": 0},
    {"id": 0x5059, "text": "\x1ANon mais tu rentres chez les gens\x01comme ça, toi? Et en pleine nuit?\x01Tu serais pas un p'tit peu malade?\x01Tu t'crois où? Au zoo?\x04\x1A\x06\x1EEnfin...je passe l'éponge.\x07\x50\x5A\x02", "box_type": 0},
    {"id": 0x505A, "text": "La fille derrière chez moi s'occupe\x01de cocottes mais elle est allergique\x01aux plumes...\x01Pfff... J'te jure...\x04\x06\x0DEnfin...après tout...j'm'en fiche.\x02", "box_type": 0},
    {"id": 0x505B, "text": "\x1ADites donc jeune homme! \x01Cela vous prend souvent d'entrer\x01chez les autres comme ça?\x01Vous vous croyez dans une gare?\x04\x1A\x06\x1EEnfin...je passe l'éponge.\x04\x1ACe n'est même pas chez moi ici.\x01C'est la maison de la \x05\x41noble Impa\x05\x40!\x04\x1AImpa est allée au \x05\x41cimetière\x05\x40 pour y\x01enfermer une sale bête.\x04\x1ADepuis la venue de Ganondorf, de\x01nombreux monstres sont apparus \x01dans les environs.\x04\x1ASeule la grande Impa a su \x01préserver la paix dans notre \x01village. Ne l'oubliez jamais!\x04\x1A\x06\x2DEnfin...après tout...\x04\x1AAu fait! Impa n'est toujours pas\x01revenue du cimetière! Lui est-il\x01arrivé malheur?\x07\x50\x5C\x02", "box_type": 0},
    {"id": 0x505C, "text": "Il paraît que le \x05\x41spectre du \x01fossoyeur \x05\x40se balade souvent dans\x01le cimetière, la nuit tombée...\x04\x06\x1FEnfin...moi j'y crois pas.\x02", "box_type": 0},
    {"id": 0x505D, "text": "\x1AHé! Petit! C'est la première fois\x01que tu visites ce village?\x04\x1AUne noble dame, \x05\x41Impa\x05\x40, a créé ce\x01village pour nous, pauvres paysans.\x07\x50\x5E\x02", "box_type": 0},
    {"id": 0x505E, "text": "Fais comme chez toi...\x02", "box_type": 0},
    {"id": 0x505F, "text": "La noble Impa n'est pas ici. \x01Lui est-il arrivé quelque chose?\x02", "box_type": 0},
    {"id": 0x5060, "text": "\x1ALes habitants ont tous de \x01douloureux souvenirs...\x01Enfouis dans leur mémoire.\x07\x50\x61\x02", "box_type": 0},
    {"id": 0x5061, "text": "Regarde ce gros moustachu...\x01Même lui a souffert par le passé...\x02", "box_type": 0},
    {"id": 0x5062, "text": "Le gros moustachu est parti au \x01Ranch. Il était si joyeux!\x02", "box_type": 0},
    {"id": 0x5063, "text": "\x1ADing dong, ding dong!\x01Je suis le soldat-pendule!\x01Au quatrième top il sera: \x1F.\x04\x1ABonjour mon ami!\x01La nourrice de Zelda, \x05\x41Impa\x05\x40, a  \x01fondé ce village.\x04\x1ANous ne sommes que très peu\x01d'habitants pour l'instant mais\x01un jour ce village sera aussi\x01important que le bourg d'Hyrule!\x04\x1ALes \x05\x41escaliers au nord\x05\x40 du village\x01mènent au Mont du Péril.\x04\x1AMais ce chemin n'est ouvert que \x01sur présentation d'un écrit royal.\x02", "box_type": 0},
    {"id": 0x5064, "text": "Ding dong, ding dong!\x01Au quatrième top il sera: \x1F.\x02", "box_type": 0},
    {"id": 0x5065, "text": "Ding dong, ding dong!\x01Au quatrième top il sera: \x1F.\x01Au fait... \x01Que s'est-il passé au château?\x02", "box_type": 0},
    {"id": 0x5066, "text": "\x1AHé! L'ami... Que fais-tu dehors\x01à une heure pareille?\x04\x1AOh! Je vois! Tu mets ton courage\x01à l'épreuve, hein? Alors pourquoi \x01ne pas aller au...cimetière?\x04\x1AAllez, circule!\x01J'ai du travail!\x07\x50\x67\x02", "box_type": 0},
    {"id": 0x5067, "text": "Ding dong, ding dong!\x01Au quatrième top il sera: \x1F.\x04A l'Est du village tu trouveras le\x01\x05\x41cimetière\x05\x40. On dit souvent qu'une\x01\x05\x43mélodie de la Famille Royale \x05\x40a le\x01pouvoir d'apaiser les âmes...\x02", "box_type": 0},
    {"id": 0x5068, "text": "Un type louche vit dans le moulin.\x01Il chante toute la sainte journée \x01et sa voix me tape sur les nerfs...\x02", "box_type": 0},
    {"id": 0x5069, "text": "Les gens me dégoûtent.\x01Mes parents me dégoûtent.\x01Ta p'tite tête me dégoûte.\x02", "box_type": 0},
    {"id": 0x506A, "text": "Toute la journée, nous travaillons\x01sur les chantiers... Cela va \x01prendre du temps avant que tout \x01soit terminé.\x04Notre chef nous fait travailler \x01dur!\x02", "box_type": 0},
    {"id": 0x506B, "text": "J'ai faim! On passe à table tout \x01de suite? Et après ça une bonne \x01sieste et...hop! Au lit!\x02", "box_type": 0},
    {"id": 0x506C, "text": "Vous n'êtes tous que de gros\x01flemmards! Le travail n'avance pas\x01et vous ne pensez qu'à bouffer!\x01JE VOUS HAIS!\x02", "box_type": 0},
    {"id": 0x506D, "text": "\x08\x05\x41Esprit   30 Rubis\x01\x05\x40Spectre en bouteille. \x01A vendre à un passionné.\x09\x0A\x02", "box_type": 0},
    {"id": 0x506E, "text": "\x08Esprit  30 Rubis\x09\x01\x01\x1B\x05\x42Acheter\x01Ne pas acheter\x05\x40\x02", "box_type": 0},
    {"id": 0x506F, "text": "506f\x02", "box_type": 0},
    {"id": 0x5070, "text": "Mes cocottes sont perdues!\x01Dépose six cocottes dans l'enclos!\x02", "box_type": 0},
    {"id": 0x5071, "text": "\x08\x05\x44\x0F!\x01Ce navire sombre!\x01Vite! Mets-toi à l'abri!!!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x5072, "text": "Il me manque encore des cocottes!\x01Dépose encore 5 cocottes!\x02", "box_type": 0},
    {"id": 0x5073, "text": "\x08Sois sage ou j'le dirai à Igor!\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x5074, "text": "Regarde-moi ça! Je me suis cassé\x01un ongle en travaillant.\x01C'est super moche!\x01Pffff....\x02", "box_type": 0},
    {"id": 0x5075, "text": "Travailler...moi j'aime pas.\x01Je veux devenir un voleur. \x01Un grand voleur! Avec des bottes\x01rouges et une cape! Cool, non?\x02", "box_type": 0},
    {"id": 0x5076, "text": "Il paraît que la maison du chef \x01est derrière celle-ci...\x01Et si on la brûlait? Hein?\x02", "box_type": 0},
    {"id": 0x5077, "text": "As-tu déjà rencontré \x05\x41Igor\x05\x40?\x01Il vit dans le cimetière du village.\x04Il est \x1F... Il doit dormir dans \x01sa cabane à cette heure-ci.\x04Pourquoi ne pas te balader sur\x01la Plaine d'Hyrule en attendant?\x02", "box_type": 0},
    {"id": 0x5078, "text": "J'ai faiiiim !!  !\x01On va manger?\x01Il est déjà \x1F!\x02", "box_type": 0},
    {"id": 0x5079, "text": "\x1AIci vivait autrefois la \x05\x41noble Impa\x05\x40.\x04\x1ACette maison est ouverte à tous \x01les villageois. \x01L'entrée est gratuite.\x07\x50\x7A\x02", "box_type": 0},
    {"id": 0x507A, "text": "Ce village fut jadis un repaire\x01\x05\x43Sheikah \x05\x40mais la noble Impa en fit\x01une terre d'accueil.\x02", "box_type": 0},
    {"id": 0x507B, "text": "Mais j'en suis sûr! J'l'ai vu!\x04J'ai vu le fantôme d'Igor entrer \x01dans sa tombe! Il portait même un\x01\x05\x41trésor\x05\x40... J'te l'jure!\x02", "box_type": 0},
    {"id": 0x507C, "text": "C'est lui! C'est lui!\x01Il est tombé du ciel entouré d'une\x01lumière bleue! J'ai tout vu!\x04Tu me crois, hein?\x02", "box_type": 0},
    {"id": 0x507D, "text": "Depuis bientôt sept ans, personne \x01ne veut croire à mes histoires.\x01C'est agaçant à la fin!\x02", "box_type": 0},
    {"id": 0x507E, "text": "Le village fut ravagé mais nous \x01avons pu maîtriser le feu!\x01Beau boulot, hein?\x02", "box_type": 0},
    {"id": 0x507F, "text": "Wah hah hah hah hah hah!\x04Mate-moi ce type! Depuis son \x01évasion du Bourg d'Hyrule, il est\x01devenu un méga-froussard!\x02", "box_type": 0},
    {"id": 0x5080, "text": "Wah hah hah hah hah hah!\x04Ce type a des visions!\x01Wah hah hah hah hah hah!\x02", "box_type": 0},
    {"id": 0x5081, "text": "Wah hah hah hah hah hah!\x01Elles sont chouettes tes fringues!\x02", "box_type": 0},
    {"id": 0x5082, "text": "Wah hah hah hah hah hah!\x01Mon truc à moi c'est rigoler!\x01Wah hah hah hah hah hah!\x02", "box_type": 0},
    {"id": 0x5083, "text": "Ya-ha-ha! Je suis le roi du monde!\x01J'adore regarder les gens d'ici!\x01Ils sont si petits!\x02", "box_type": 0},
    {"id": 0x5084, "text": "J'ai peur de m'endormir...\x01Je risquerais de tomber!\x02", "box_type": 0},
    {"id": 0x5085, "text": "Le moulin draine l'eau du puits...\x04Mais le puits est à sec depuis un \x01bon moment...\x02", "box_type": 0},
    {"id": 0x5086, "text": "La fille du coin est vraiment\x01gentille... Elle s'est même occupée\x01des ouvriers.\x02", "box_type": 0},
    {"id": 0x5087, "text": "Il y a bien longtemps...\x01Le regard perçant d'un habitant de \x01ce village permettait à celui-ci de \x01voir la vérité!\x04La vérité est une notion plus \x01philosophique que visuelle.\x01La percevoir est le fruit d'un long\x01travail intellectuel...\x04Mais cet homme avait une autre \x01façon de procéder...\x04Le puits fut construit là où\x01se trouvait sa maison...\x02", "box_type": 0},
    {"id": 0x5088, "text": "On raconte dans le coin qu'une\x01\x05\x41riche famille\x05\x40 possédait une maison\x01dans ce village...\x04Mais les membres de cette famille\x01étaient avares... Ainsi ils furent \x01maudits.\x04Bien heureux le pauvre... \x01Crois-moi!\x02", "box_type": 0},
    {"id": 0x5089, "text": "Oh....\x04Quel malotru...\x01Nous déranger en plein câlin!\x01Où en étions-nous, amour?\x02", "box_type": 0},
    {"id": 0x508A, "text": "Hi hi...\x04Nous déranger en plein câlinou!\x01Le crois-tu jaloux, mon gnougnou?\x02", "box_type": 0},
    {"id": 0x508B, "text": "\x1ARegarde celui-là...\x01Le gros moustachu...\x01On l'a mis à la porte du Ranch.\x07\x50\x8C\x02", "box_type": 0},
    {"id": 0x508C, "text": "Il ne fait rien de la journée. \x01Et la crise actuelle...\x01Il s'en contre-fiche!\x02", "box_type": 0},
    {"id": 0x508D, "text": "Ce gros flemmard me rappelle kiki.\x04Comment? Tu n'as jamais entendu \x01parler de mon cher petit kiki\x01d'amour et d'amitié trop mignon?\x01C'est mon chien!\x02", "box_type": 0},
    {"id": 0x508E, "text": "Oh NoOoOoOoOoOoN!!!!\x01Encore un orage? \x01\x08C'est de ta faute ! ! !\x09\x01Grrrrrrrrrrrrrrr!!\x02", "box_type": 0},
    {"id": 0x508F, "text": "Vous attrapez une Ame!\x01Allez la vendre chez le\x01\x05\x41Marchand d'Ames \x05\x40au prix fort!\x02", "box_type": 2},
    {"id": 0x6000, "text": "\x08\x06\x19Halte! On ne bouge plus!\x09\x02", "box_type": 0},
    {"id": 0x6001, "text": "Salut le nouveau!\x02", "box_type": 0},
    {"id": 0x6002, "text": "Une minute, le nouveau...\x01Je vais t'ouvrir la porte.\x02", "box_type": 0},
    {"id": 0x6003, "text": "\x08\x06\x0FNe jamais défier une Gerudo!\x09\x02", "box_type": 0},
    {"id": 0x6004, "text": "\x1AJ'ai vu comment tu as évité les\x01gardes. Tu es fort et rapide.\x04\x1AJ'ai toujours pensé que les mâles\x01n'étaient que des larves! Tous \x01sauf le Grand Ganondorf, bien sûr!\x01Mais tu m'as prouvé le contraire...\x04\x1A\x05\x41Nabooru l'exaltée\x05\x40, notre chef, \x01m'a confié la garde de cette \x01forteresse.\x04\x1ANabooru est le bras droit du \x01grand Ganondorf, Roi des Voleurs\x01Gerudo.\x04\x1ASon quartier général se trouve \x01dans le \x05\x46Temple de l'Esprit\x05\x40, au-delà \x01du désert...\x04\x1AA mon avis...tu aimerais devenir un\x01Gerudo! J'me trompe?\x01Alors c'est chose faite!\x04\x1APrends donc ceci. C'est une carte \x01de membre Gerudo. Toutes les \x01pièces de la forteresse te seront\x01désormais accessibles!\x0B\x02", "box_type": 0},
    {"id": 0x6005, "text": "Tu es désormais libre d'emprunter\x01la porte du désert.\x04Tu trouveras dans le désert le \x01\x05\x46Temple de l'Esprit\x05\x40. \x01Nabooru l'exaltée y a élu domicile.\x02", "box_type": 0},
    {"id": 0x6006, "text": "\x08Pauvre idiot!\x09\x01Entre là-dedans et reste \x01tranquille!\x02", "box_type": 0},
    {"id": 0x6007, "text": "\x1ATu as évité tous les gardes?\x01Je ne sais pas d'où tu viens, mais\x01tu dois être très fort!\x04\x1ATous les autres ouvriers sont\x01enfermés dans la forteresse.\x04\x1AFais-nous tous sortir de ce\x01traquenard et nous te rendrons un\x01grand service!\x04\x1ASois prudent! Des gardes \x05\x41Gerudos\x05\x40 \x01rôdent dans les couloirs...\x04\x1A\x08Woah!\x09 \x08Attention!\x09\x02", "box_type": 0},
    {"id": 0x6008, "text": "\x08\x06\x11Le Seuil ouvert sur le Passé\x09\x02", "box_type": 1},
    {"id": 0x6009, "text": "\x08\x06\x0CLe Seuil ouvert sur le Présent\x09\x02", "box_type": 1},
    {"id": 0x600A, "text": "\x08\x06\x11Le Seuil ouvert sur le Futur\x09\x02", "box_type": 1},
    {"id": 0x600B, "text": "\x12\x38\xECLe sentier laisse-moi te révéler\x01ou du désert tu seras prisonnier.\x01Poursuis bien mon halo spectral\x01qui te mènera jusqu'au lieu du mal!\x0E\x5A\x02", "box_type": 0},
    {"id": 0x600C, "text": "\x1APassé, présent, futur...\x04\x1AL'épée de Légende est un esquif\x01voguant sur les flots tumultueux \x01du temps...\x04\x1ASon voyage fait halte dans le\x01Temple du Temps...\x04\x1APour entrer dans ce \x05\x46Temple\x05\x40, \x01remonte le cours des âges...\x04\x1AEntends le \x05\x46Requiem des Esprits\x05\x40...\x01Cette mélodie conduira un enfant\x01aux portes du désert.\x02", "box_type": 0},
    {"id": 0x600D, "text": "Je suis la meilleure archère \x01montée des Gerudos! Je suis \x01aussi la meilleure cavalière!\x04L'archerie montée te tente?\x01Alors paie \x05\x4120 Rubis\x05\x40!\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x600E, "text": "Tu as du cran...j'aime ça.\x01Suis-moi!!!\x02", "box_type": 0},
    {"id": 0x600F, "text": "Mais t'es un crétin!\x01L'archerie montée se fait à cheval!\x01Si t'en a pas...t'en fais pas!\x01C'est logique!!!\x02", "box_type": 0},
    {"id": 0x6010, "text": "\x08Lâche! Fuis mon regard! \x01Tu n'es que l'ombre d'un rat!\x09\x02", "box_type": 0},
    {"id": 0x6011, "text": "Tu es faible... \x01Comme tous les hommes!\x01Peut-être la prochaine fois.\x02", "box_type": 0},
    {"id": 0x6012, "text": "Tu es fort. J'en conviens.\x04Aujourd'hui je perds, demain à moi\x01la victoire!!!\x02", "box_type": 0},
    {"id": 0x6013, "text": "Voici l'entrée du \x05\x41Gymnase Gerudo\x05\x40.\x04Ne sont autorisés que les \x01membres actifs.\x02", "box_type": 0},
    {"id": 0x6014, "text": "Voici l'entrée du \x05\x41Gymnase Gerudo\x05\x40.\x04Carte de membre acceptée.\x04Une session pour 10 Rubis!\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x6015, "text": "C'est parti...\x01Bonne chance, le nouveau!\x01Ha ha ha ha ha!\x0B\x02", "box_type": 0},
    {"id": 0x6016, "text": "Tu n'as pas assez d'argent!\x01\x08Reviens les poches pleines.\x09\x02", "box_type": 0},
    {"id": 0x6017, "text": "\x1AHé! Le nouveau!\x04\x1AVas-tu dans le désert?\x01Je t'ouvre la porte, mais...\x04\x1APrends garde: tu ne pourras \x01traverser le désert sans passer \x01les \x05\x41deux épreuves\x05\x40.\x07\x60\x18\x02", "box_type": 0},
    {"id": 0x6018, "text": "La première épreuve est le \x05\x41Fleuve\x01de Sable\x05\x40! Franchis-le et suis le\x01chemin bordé de drapeaux.\x04La deuxième épreuve est... \x01\x05\x41Le Guide Spectral\x05\x40!\x04Ceux qui ne peuvent\x05\x41 distinguer la \x01vérité de leurs yeux \x05\x40s'en \x01reviendront ici.\x04Enfin...si ton choix est fait, je ne\x01peux te retarder davantage...\x01Fonce, beau gosse!!!\x0B\x02", "box_type": 0},
    {"id": 0x6019, "text": "\x1AQue fais-tu là? Quoi?\x01Tu allais me poser la même \x01question?\x07\x60\x1A\x02", "box_type": 0},
    {"id": 0x601A, "text": "Te voilà bien avancé!\x01Comment vas-tu remonter à \x01présent?\x02", "box_type": 0},
    {"id": 0x601B, "text": "Merci mon garçon!\x01Désolé, je n'ai pas grand chose à \x01te donner, mais...\x01Prends ceci...pour le geste!\x02", "box_type": 0},
    {"id": 0x601C, "text": "601C\x02", "box_type": 0},
    {"id": 0x601D, "text": "\x1ATu es nouveau dans le coin, \x01gamin...\x04Que veux-tu?\x01\x1C\x05\x42Voir le Temple\x01Je cherche les Sages\x01Heu...j'me balade\x05\x40\x02", "box_type": 0},
    {"id": 0x601E, "text": "Tu n'es qu'un gamin! \x01Et les temples... C'est pas pour \x01les gamins!\x02", "box_type": 0},
    {"id": 0x601F, "text": "Quoi? Les Sages? \x01C'est quoi donc?\x01Ici il n'y a que des voleurs!\x02", "box_type": 0},
    {"id": 0x6020, "text": "\x1ATu te balades? Tu n'as donc rien \x01à faire? Ca tombe très bien! \x01J'ai un petit service à te \x01demander...\x04\x1AAu fait...juste une question...\x01Tu ne serais pas un des sbires \x01de...\x04Ganondorf...par hasard?\x01\x01\x1B\x05\x42Peut-être...j'hésite encore.\x01Ganondorf? Je le HAIS!\x05\x40\x02", "box_type": 0},
    {"id": 0x6021, "text": "\x1AWha-ha-ha-ha!\x01Tu veux jouer au dur! \x01C'est trooooop mignon!\x04\x1ACrois-tu que Ganondorf recruterait\x01un gamin comme toi?\x04\x1ABon...allons droit au but...\x07\x60\x23\x02", "box_type": 0},
    {"id": 0x6022, "text": "\x1AHo-hoh!\x04\x1ATu n'as pas froid au yeux!\x01Hmm...J'aime ça.\x07\x60\x23\x02", "box_type": 0},
    {"id": 0x6023, "text": "\x1AJe me présente: mon nom est \x01\x05\x41Nabooru \x05\x40la Gerudo! Je suis une \x01voleuse solitaire.\x04\x1AMais...attention!\x04\x1AGanondorf et moi-même sommes\x01des voleurs, soit! Mais je suis \x01très différente de ce chacal!\x04\x1AGanondorf et ses infâmes\x01serviteurs volent les femmes et\x01les enfants. Ils commettent parfois \x01des meurtres!!!\x04\x1ASais-tu que la race des Gerudos\x01ne comporte que des femmes? \x01Un homme Gerudo n'apparaît qu'une\x01fois tous les cent ans.\x04\x1ANos lois sont claires: cet homme\x01est né pour être roi des Gerudos.\x01Mais je refuse de jurer allégeance\x01à un homme aussi vil!\x04\x1AJe parle, je parle et...au fait...\x01Quel est ton nom?\x04\x1A\x0F?!\x04\x1AWhoa! Tes parents ont le sens de\x01l'humour! Quel drôle de nom!\x01Enfin...peu importe...\x07\x60\x24\x02", "box_type": 0},
    {"id": 0x6024, "text": "\x1ARends-moi service, veux-tu?\x04\x1ADe l'autre côté de ce passage se\x01trouve un trésor. Peux-tu me le \x01rapporter?\x04\x1ACe trésor renferme les \x05\x43Gantelets \x01d'argent\x05\x40. En les portant, n'importe\x01qui peut déplacer d'immenses \x01objets!\x04\x1ANon, non, non, gamin! \x01Ne pense même pas à les garder \x01pour ta pomme!\x04\x1ALes Gantelets d'argent sont trop\x01grands pour tes petites mains!\x01Sois un gentil petit et rapporte\x01à tata Nabooru!\x04\x1AGanondorf et ses sbires ont élu \x01domicile dans ce temple.\x04\x1AGrâce aux Gantelets d'argent, je\x01pourrai m'y glisser discrètement...\x04\x1AUne fois sur place, je déroberai \x01leurs trésors et saccagerai leurs \x01plans de conquête!\x04Alors? Veux-tu m'aider?\x01\x01\x1B\x05\x42Oui\x01Nan, j'veux pas!\x05\x40\x02", "box_type": 0},
    {"id": 0x6025, "text": "\x1AMerci bien, gamin!\x04\x1ANous allons mettre une de ces\x01pagailles dans les affaires de \x01Ganondorf! On va bien rire!\x07\x60\x26\x02", "box_type": 0},
    {"id": 0x6026, "text": "En échange, si tu me rapportes \x01les \x05\x43Gantelets d'argent\x05\x40...\x04Je te donnerai un petit bisou!\x02", "box_type": 0},
    {"id": 0x6027, "text": "Pfff... Après tout, tu n'es qu'un\x01gamin! Allez, ouste! Du balai!\x02", "box_type": 0},
    {"id": 0x6028, "text": "\x1AHé! Lâchez-moi! Nooon!\x02", "box_type": 0},
    {"id": 0x6029, "text": "\x1AGni...gni...gniii!\x01Tiens, tiens, tiens!!!\x01Voici de la visite, Koume!\x02", "box_type": 0},
    {"id": 0x602A, "text": "\x1AGnan...gnan...gnan!\x01De la visite en effet, Kotake!\x02", "box_type": 0},
    {"id": 0x602B, "text": "\x1AQui es-tu, jeune impudent, pour\x01t'introduire dans notre temple?\x01Gni...gni...gni!\x02", "box_type": 0},
    {"id": 0x602C, "text": "\x1AUne bonne correction!\x01Oh oui! Une bonne correction!\x01Gnan...gnan...gnan!\x02", "box_type": 0},
    {"id": 0x602D, "text": "\x1AEsclave! Entends-moi...\x02", "box_type": 0},
    {"id": 0x602E, "text": "\x1AMon verbe est ton ordre...\x01Tue ce jeune sot! Tue!!!\x02", "box_type": 0},
    {"id": 0x602F, "text": "\x1AGrand Ganondorf... Intrus...\x01Mise à mort...\x02", "box_type": 0},
    {"id": 0x6030, "text": "\x1AHein? Quoi?...\x01Où suis-je...?\x02", "box_type": 0},
    {"id": 0x6031, "text": "\x1ATiens, tiens...\x01Le charme est brisé...\x01Koume...\x02", "box_type": 0},
    {"id": 0x6032, "text": "\x1ACe n'est qu'une jeune fille\x01mais grande est son influence au \x01sein des Gerudos, Kotake...\x02", "box_type": 0},
    {"id": 0x6033, "text": "\x1AElle se doit de servir la noble \x01cause du Seigneur Ganondorf!\x01Gni...gni...gni!\x02", "box_type": 0},
    {"id": 0x6034, "text": "\x1AUtilisons le charme une fois\x01encore....\x01Gnan...gnan...gnan!\x02", "box_type": 0},
    {"id": 0x6035, "text": "\x1AMerci, gamin...du fond du coeur.\x01\x1ARegardez-moi ça! \x01Le gamin est devenu un grand\x01guerrier!\x02", "box_type": 0},
    {"id": 0x6036, "text": "Tu es devenu beau et fort...\x0C\x50J'aurais dû tenir ma promesse...\x0E\x50\x02", "box_type": 5},
    {"id": 0x6037, "text": "\x1ATiens! Je te donne \x05\x41ceci\x05\x40...\x01J'y tiens beaucoup. \x01Mais tu as mérité ma confiance!\x02", "box_type": 0},
    {"id": 0x6038, "text": "\x1A\x0F...A bientôt!\x02", "box_type": 0},
    {"id": 0x6039, "text": "\x1AAu fait...\x04\x1AExcuse-moi de t'avoir attaqué.\x04\x1AJ'étais sous le contrôle des\x01sorcières et sous les ordres de\x01Ganondorf... Pouah!\x04\x1AToute cette histoire est \x01incroyable, non? \x01Moi! Le \x05\x46Sage de l'Esprit\x05\x40! \x01C'est à mourir de rire!\x04\x1AMais en tant que Sage, mon devoir \x01est désormais de combattre!\x01Hé hé hé...\x04\x1AMa vengeance sera terrible!\x01Yaaaaaaaaah!!! \x02", "box_type": 0},
    {"id": 0x603A, "text": "\x1AGamin...heu...\x04\x1ANon...\x01\x0F, Héros du Temps!\x04\x1AJe te remets ce \x05\x46Médaillon\x05\x40!\x01Le p'tit bisou sera pour plus tard.\x04\x1APrends-en soin!\x02", "box_type": 0},
    {"id": 0x603B, "text": "\x1A\x08\x06\x0BYaaaaaah!\x09 Laissez-moi partir!!\x02", "box_type": 0},
    {"id": 0x603C, "text": "\x1A\x06\x1F\x08Créatures démoniaques!\x09\x01\x06\x23Larbins de Ganondorf!\x02", "box_type": 0},
    {"id": 0x603D, "text": "\x1A\x08\x06\x1E\x0F!\x09\x01\x06\x25Fuis cet enfer! Vite!\x02", "box_type": 0},
    {"id": 0x603E, "text": "\x1A\x06\x10Ces sorcières! Elles utilisent\x01\x06\x19leur magie noire sur moi!\x02", "box_type": 0},
    {"id": 0x603F, "text": "Hé, l'nouveau! Voici notre \x05\x41terrain\x01d'archerie montée\x05\x40.\x04Tout en faisant galoper nos \x01chevaux, nos flèches se plantent\x01dans le mille à tous les coups!\x04Apprends à monter à cheval et\x01reviens nous voir pour tester tes\x01capacités... On va bien rire!\x02", "box_type": 0},
    {"id": 0x6040, "text": "Hé, l'nouveau!\x01Ton cheval a fière allure!\x04Je ne sais où tu l'as volé, mais...\x04Pourquoi ne pas participer au\x01concours d'archers montés?\x04Fais galoper ton destrier et\x01décoche tes flèches vers les \x01cibles. \x04Tu as 20 flèches. Voyons un peu \x01quel sera ton score après un\x01aller-retour.\x04Totalise plus de \x05\x411,000 points\x05\x40,\x01et tu gagneras un prix!\x0B\x02", "box_type": 0},
    {"id": 0x6041, "text": "Veux-tu tenter ta chance pour \x01\x05\x4120 Rubis\x05\x40?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x6042, "text": "Hé, l'nouveau!\x01T'es plutôt doué!\x01Augmentons un peu la difficulté...\x04Totalise \x05\x411,500 points \x05\x40ou plus \x01pour voir!\x0B\x02", "box_type": 0},
    {"id": 0x6043, "text": "Quoi? Tu veux recommencer?\x01Tu as un certain potentiel!\x0B\x02", "box_type": 0},
    {"id": 0x6044, "text": "Fabuleux! Un vrai maître!\x04Prends cet objet, il conviendra\x01mieux à un expert comme toi.\x04Ce carquois m'est très cher.\x01Mais je tiens à te le donner.\x01Prends-en soin, OK?\x02", "box_type": 0},
    {"id": 0x6045, "text": "\x18 points?!?\x01Wha-ha-ha! La gloire n'est pas \x01pour tout de suite!\x0B\x02", "box_type": 0},
    {"id": 0x6046, "text": "Fantastique! De toute beauté!\x01Tu es un archer d'exception!\x04Ceci te sera d'une grande aide...\x02", "box_type": 0},
    {"id": 0x6047, "text": "\x18 points...\x01Pas mal...enfin...bof.\x0B\x02", "box_type": 0},
    {"id": 0x6048, "text": "Quel jeune insensé!\x01Venir de son propre chef s'offrir \x01en sacrifice au Grand Ganondorf...\x0E\x5A\x02", "box_type": 0},
    {"id": 0x6049, "text": "\x06\x14Le souffle de mes flammes \x01\x06\x28consumera son âme!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604A, "text": "\x06\x1BLa morsure de ma glace \x01\x06\x2Fpétrifiera ses os!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604B, "text": "\x06\x28Quelle petite peste!\x01\x06\x12Cette fois, c'est du serieux,\x01\x06\x26n'est-ce pas Kotake?\x0E\x5A\x02", "box_type": 0},
    {"id": 0x604C, "text": "\x06\x51Hein?\x0C\x14\x06\x17Hé! Koume! Tu as un truc\x01\x06\x24au-dessus de la tête!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604D, "text": "\x06\x19Heu? Regarde! Toi aussi!\x01\x06\x15C'est quoi ce machin rond?\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604E, "text": "\x06\x18Mais je n'ai que 400 ans!\x0E\x28\x02", "box_type": 0},
    {"id": 0x604F, "text": "\x06\x14Et moi je n'ai que 380 ans!\x0E\x28\x02", "box_type": 0},
    {"id": 0x6050, "text": "\x08\x06\x08Nous sommes jumelles! Tu ne \x01\x06\x19peux pas avoir 380 ans! \x01\x06\x34Arrête de mentir!\x09\x0E\x28\x02", "box_type": 0},
    {"id": 0x6051, "text": "\x08\x06\x2ET'es devenue sénile!\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x6052, "text": "\x08\x06\x12Quoi? C'est moi la sénile?\x01\x06\x01Cause meilleur à ta grande soeur!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x6053, "text": "\x08\x06\x05ON...EST...JUMELLES! JU-MELLES!\x01\x06\x05Tu ne peux pas être plus vieille \x01\x06\x43que moi!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x6054, "text": "\x08\x06\x35Gnyyaaaarghh!!\x09\x01\x08\x06\x0DC'que tu peux être sournoise!\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x6055, "text": "\x08\x06\x10Comment fais-tu pour être  \x01\x06\x34aussi mesquine?\x09\x0E\x0A\x02", "box_type": 0},
    {"id": 0x6056, "text": "\x08\x06\x39T'es sournoise!!\x09\x0E\x04\x02", "box_type": 0},
    {"id": 0x6057, "text": "\x08\x06\x37T'es mesquine...\x09\x0E\x04\x02", "box_type": 0},
    {"id": 0x6058, "text": "\x08\x06\x10En tout cas...moi j'suis sexy!\x09\x0E\x28\x02", "box_type": 5},
    {"id": 0x6059, "text": "\x08Bon... Cette fois y'en a marre!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x605A, "text": "\x06\x32\x08En avant, Koume!\x09\x0C\x14\x06\x2D\x08Kotake\x09 et \x08Koume\x09...\x01\x06\x1C\x08Double\x09 Fusion \x08Maléfique!\x09\x0E\x28\x02", "box_type": 0},
    {"id": 0x605B, "text": "\x1ATu es venu pour me sauver?\x01Alors ça, c'est trop chou! \x01Je suis \x05\x41Hiro l'ouvrier\x05\x40.\x04\x1ANous voulions tous joindre leur\x01club de filles mais elles nous ont\x01enfermés! Tout ça parce que nous\x01sommes des...mâles!\x04\x1AAu diable ces jolies filles Gerudos!\x01Elles sont trop dures!\x04\x1A\x05\x41Trois de mes compagnons\x05\x40 sont \x01aussi enfermés. Peux-tu les sauver?\x02", "box_type": 0},
    {"id": 0x605C, "text": "\x1AGentil petit bouchon! \x01Je suis \x05\x41Julio l'ouvrier\x05\x40.\x04\x1ACes femmes me font peur! \x01Je préfère travailler que d'en \x01épouser une!\x04\x1AJ'ai hâte de quitter cet endroit!\x01Mais encore \x05\x41deux petits camarades\x01\x05\x40sont enfermés! Peux-tu les sauver?\x02", "box_type": 0},
    {"id": 0x605D, "text": "\x1AMerci p'tite tête, t'es un amour! \x01Je suis \x05\x41Jibo l'ouvrier\x05\x40.\x04\x1AT'as pas vu notre chef? Y doit\x01se faire du mouron! Je dois le \x01voir maintenant! Je suis déjà à la\x01\x08bourre!\x09\x04\x1AMais un \x05\x41autre ouvrier \x05\x40est \x01encore enfermé... Sauve-le!\x01Je l'aime tant!\x02", "box_type": 0},
    {"id": 0x605E, "text": "\x1AYouki! Je suis Liiiiibre!\x01Mon nom est \x05\x41Nico l'ouvrier\x05\x40.\x04\x1APour te remercier, voici ce que\x01mes petites oreilles d'amour ont \x01entendu il n'y a pas si longtemps...\x04\x1A\"Seul l'oeil de vérité peut faire\x01traverser le désert... La déesse \x01est au-delà des sables...\"\x04\x1ABon...je retourne dans ma\x01\x05\x41tente près de la Vallée Gerudo\x05\x40!\x01Viens donc y faire un tour!\x01Saluuuut!\x02", "box_type": 0},
    {"id": 0x605F, "text": "Le chef du clan des voleurs est \x01\x05\x41Nabooru\x05\x40. Elle efface la mémoire \x01des voyageurs près des ruines\x01dans le désert.\x02", "box_type": 0},
    {"id": 0x6060, "text": "Ganondorf, le seigneur du malin, \x01est derrière toute cette histoire\x01de voleuses...\x02", "box_type": 0},
    {"id": 0x6061, "text": "\x1AQuand \x05\x41Nabooru\x05\x40 n'était qu'une \x01voleuse solitaire, elle ne dérobait\x01jamais les faibles, mais...\x07\x60\x62\x02", "box_type": 0},
    {"id": 0x6062, "text": "Aujourd'hui le clan de Nabooru est \x01violent et cruel! Elle se prétend \x01noble et chevaleresque...\x01Ben voyons!\x02", "box_type": 0},
    {"id": 0x6063, "text": "Comme je l'ai toujours dit, \x01Nabooru était manipulée par les \x01sbires de Ganondorf...\x02", "box_type": 0},
    {"id": 0x6064, "text": "\x1AChez les Gerudos, un bon archer\x01et un fier cavalier est toujours \x01respecté.\x07\x60\x65\x02", "box_type": 0},
    {"id": 0x6065, "text": "Tu devrais te risquer au concours \x01d'archerie montée près de la \x01forteresse Gerudo!\x04Si tu as un cheval, une Gerudo\x01te lancera un défi.\x02", "box_type": 0},
    {"id": 0x6066, "text": "Tu as été brillant, jeune homme!\x02", "box_type": 0},
    {"id": 0x6067, "text": "Construire un pont est une simple \x01tâche si nous travaillons en équipe.\x02", "box_type": 0},
    {"id": 0x6068, "text": "Sans ces sales vieilles sorcières, \x01le clan des voleuses est moins\x01terrifiant!\x02", "box_type": 0},
    {"id": 0x6069, "text": "La \x05\x41forteresse Gerudo\x05\x40 est de \x01l'autre côté...mais un gamin comme \x01toi n'a rien à y faire.\x02", "box_type": 0},
    {"id": 0x606A, "text": "\x1A\x12\x68\x55Je suis le \x05\x41chef des ouvriers\x05\x40. \x01Les voleuses Gerudos ont cassé \x01mon joli pont.\x04\x1AJ'aimerais le réparer mais mes \x01hommes ont disparu!\x01Alors...je suis coincé ici.\x04\x1ALeur condition d'ouvrier ne leur \x01plaisait pas...des mauviettes, oui! \x01Alors ils sont tous partis à \x01la \x05\x41forteresse Gerudo\x05\x40...\x07\x60\x6B\x02", "box_type": 0},
    {"id": 0x606B, "text": "Hé! Toi! Tu vas à la forteresse?\x01Pourrais-tu voir ce que fabriquent\x01mes ouvriers?\x02", "box_type": 0},
    {"id": 0x606C, "text": "Hé! C'est toi qui as sauvé mes \x01hommes! Pour te remercier on t'a \x01construit ce pont! Pas mal, hein!\x01C'est pas du boulot d'Goron!!!\x04Il est droit, il est soigné...\x01Mon pont à moi c'est le plus beau\x01de tous les ponts du mooooonde!\x04Mes ouvriers sont, soit, un peu\x01paresseux...mais en travaillant en\x01équipe, ils font du bon travail!\x02", "box_type": 0},
    {"id": 0x606D, "text": "\x1A\x12\x68\x55Hé! Mais c'est ma scie!\x04\x1AJe l'avais égarée chez ma vieille \x01femme...C'est fou!\x07\x60\x6E\x02", "box_type": 0},
    {"id": 0x606E, "text": "Mon outil Biggoron est brisé. \x01Je m'apprêtais à le faire réparer \x01au village Goron.\x04Ta venue est providentielle.\x01Peux-tu me rendre la scie?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x606F, "text": "\x06\x4D\x08Quoi?!\x01\x06\x30Sale petit voleur!\x01\x06\x38JE TE HAIS!!!\x09\x02", "box_type": 0},
    {"id": 0x6070, "text": "Voici l'entrée du \x05\x41Gymnase \x05\x40Gerudo.\x01Les personnes non autorisées sont\x01interdites d'accès!\x02", "box_type": 0},
    {"id": 0x6071, "text": "Voici l'entrée du \x05\x41Gymnase \x05\x40Gerudo.\x01Carte de membre valide...\x01Entre et donne-toi à fond!\x0B\x02", "box_type": 0},
    {"id": 0x6072, "text": "Voici l'entrée du \x05\x41Gymnase \x05\x40Gerudo. \x01Même si ta carte est valide, ne \x01garde pas tous les trésors pour\x01ta pomme!\x02", "box_type": 0},
    {"id": 0x6073, "text": "6073\x02", "box_type": 0},
    {"id": 0x6074, "text": "Oh! Comme c'i dommage\x04Li marque qui ti mènera au Temple\x01di Isprits c'i li \x05\x41drapeau à gauche \x01\x05\x40en sortant d'ici.\x04N'hisite pas à rivinir mi voir!\x02", "box_type": 0},
    {"id": 0x6075, "text": "Oh! Ti as pas assez di Rubis!\x01Ji fi pas cridit ici!!!\x02", "box_type": 0},
    {"id": 0x6076, "text": "Hé! Hé!\x01Tu m'as l'air préoccupé.\x04Pour me défier, il faut avoir\x01l'esprit clair... Une course est\x01un travail mental et physique!\x02", "box_type": 0},
    {"id": 0x6077, "text": "Bienvinue chez Sabib al Mamoud!\x04Ji vends di choses...mirvilleuses.\x01Li curiositi, li objits magiques...\x01Ti trove tout chi Sabib al Mamoud!\x01Aujourd'hui, ji ti propose...\x04Une arme qu'elle est tirrible!\x01Mais montre à Sabib tes Rubis...\x04Donne \x05\x41200 Rubis \x05\x40et ji ti li donne.\x01\x01\x1B\x05\x42Acheter\x01Ne pas acheter\x05\x40\x02", "box_type": 0},
    {"id": 0x6078, "text": "Merci di li beaucoup!\x01Ti es beau! Que ti es beau!\x04Ci qui ji li vends c'est di...\x01\x14\x02\x05\x41Missiles Teigneux\x05\x40!\x14\x00\x04Si ti veux aller au Temple di \x01l'Isprit va vers li \x05\x41drapeau à\x01gauche \x05\x40en sortant d'ici!\x02", "box_type": 0},
    {"id": 0x6079, "text": "\x1ABonjour \x0F!\x01Content de me voir?\x04\x1ALe temps n'a aucune prise sur toi! \x01Comme c'est étrange!\x04\x1AJ'ai toujours cru qu'un voyageur \x01du temps n'était qu'une légende...\x04\x1A\x0F, \x01tu es devenu un adulte!\x07\x60\x7A\x02", "box_type": 0},
    {"id": 0x607A, "text": "Le destin d'Hyrule est désormais\x01entre tes mains.\x04Le moment est mal choisi mais \x01voici un dernier conseil...\x04Deux puissantes sorcières habitent\x01dans ce temple. Pour les vaincre, \x01il te faudra \x05\x41utiliser contre elles \x01leur propre magie\x05\x40. Hou hou!\x07\x60\x7B\x02", "box_type": 0},
    {"id": 0x607B, "text": "Veux-tu que je répète tout ça?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x607C, "text": "\x1AJe garde un oeil sur toi...\x01Hou hou hou hou!\x02", "box_type": 0},
    {"id": 0x607D, "text": "\x1AJe suis le marathonien errant!\x01J'ai parcouru ce monde à la \x01recherche du véritable esprit\x01de compétition.\x04\x1AJ'ai triomphé de tous mes \x01adversaires...\x01Car je suis...(tadaaaaa!).....\x01\x08Le marathonien errant\x09!\x04\x1ATu m'as l'air costaud. \x01L'instinct du furieux guerrier \x01sanguinaire brille dans ton regard.\x04\x1ALe pont de la vallée Gerudo est \x01à nouveau en état. Je cherche des\x01adversaires de valeur.\x07\x60\x7E\x02", "box_type": 0},
    {"id": 0x607E, "text": "Le meilleur temps d'ici jusqu'au \x01\x05\x42pont des bois perdus\x05\x40 est \x05\x41\x1E\x04\x05\x40.  \x01C'est mon record perso...\x04Relèves-tu le défi?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x607F, "text": "Parfait!\x01Alors...\x04Tu pars le premier.\x01Tu prendras la tête de la course.\x01Enfin...au début!\x04Prêt? \x14\x02Partez!\x14\x00\x02", "box_type": 0},
    {"id": 0x6080, "text": "Pfffff.....\x01Tu ne découvriras jamais ton \x01instinct de furieux guerrier \x01sanguinaire de cette façon!!!\x02", "box_type": 0},
    {"id": 0x6081, "text": "Pas mal. Pas super-super, mais tu \x01t'es bien défendu! \x01Enfin...ne rêve pas trop!\x01Tu ne pourras JAMAIS me battre.\x04Ton temps est de \x05\x41\x1E\x04\x05\x40, non?\x01Malheureusement pour ta pomme,\x01je suis arrivé une seconde avant \x01toi! C'est bête, hein?\x0B\x02", "box_type": 0},
    {"id": 0x6082, "text": "Hé hé hé hé hé...\x01Ne sois pas timide! \x14\x02Passe devant!\x14\x00\x02", "box_type": 0},
    {"id": 0x6083, "text": "C'est mal! \x01Tu as abandonné la course! \x01Tu ne seras donc jamais un \x01furieux guerrier sanguinaire!!!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x6084, "text": "Hé hé hé hé...\x01Ton instinct de furieux guerrier \x01sanguinaire est faible.\x04Entraîne-toi encore et encore!\x01A la prochaine... \x08Limace!\x09\x0B\x02", "box_type": 0},
    {"id": 0x6085, "text": "\x14\x01\x08Heuff...\x09\x08peuff...\x09\x08heuff...\x09\x14\x00\x04Woah! Tu as fait très fort!\x04Maaaaaiiiis...je suis le vainqueur! \x01Ton temps est de \x05\x41\x16\x05\x40.\x01Je t'ai battu d'une seconde!\x04Heuff...heuff... \x01N'hésite pas à me défier une \x01nouvelle fois! Quand tu veux!\x04Heuff...heuff...\x01A la prochaine, \x08limace!\x09\x0B\x02", "box_type": 0},
    {"id": 0x6086, "text": "Je suis le marathonien errant!\x01Je cherche un adversaire à\x01l'instinct du furieux guerrier\x01sanguinaire!\x04J'aimerais rejoindre la plaine\x01d'Hyrule, mais le pont est...\x01Enfin ça se voit d'ici! \x01Alors je suis coincé ici.\x04Je suis désolé mais je ne peux\x01te défier aujourd'hui. Hé hé hé!\x02", "box_type": 0},
    {"id": 0x6087, "text": "6087\x02", "box_type": 0},
    {"id": 0x6088, "text": "6088\x02", "box_type": 0},
    {"id": 0x6089, "text": "6089\x02", "box_type": 0},
    {"id": 0x608A, "text": "608A\x02", "box_type": 0},
    {"id": 0x608B, "text": "608B\x02", "box_type": 0},
    {"id": 0x608C, "text": "608C\x02", "box_type": 0},
    {"id": 0x608D, "text": "608D\x02", "box_type": 0},
    {"id": 0x608E, "text": "608E\x02", "box_type": 0},
    {"id": 0x608F, "text": "608F\x02", "box_type": 0},
    {"id": 0x7000, "text": "Je n'arrive pas à attraper cette \x01cocotte!\x02", "box_type": 0},
    {"id": 0x7001, "text": "Huff huff! \x01Je suis en retard!\x01J'ai un rencard!\x02", "box_type": 0},
    {"id": 0x7002, "text": "Gloire et longue vie à la noble\x01Famille Royale d'Hyrule!\x02", "box_type": 0},
    {"id": 0x7003, "text": "Les gamins ne se promènent pas \x01près du château la nuit! \x01Reste dans la ville en attendant \x01le lever du soleil!\x02", "box_type": 0},
    {"id": 0x7004, "text": "Bwooarff! Je m'ennuie...\x01Ha! S'il y avait un peu plus \x01d'action, je pourrais m'amuser...\x04Mais tu gardes ça pour toi, OK?\x04Enfin...on peut toujours faire un \x01peu de bruit en brisant ces jarres.\x04Appuie sur \x05\x43\x05\x40 pour en soulever\x01une. Utilise ensuite \x05\x43\x05\x40 pour\x01la lancer!\x02", "box_type": 0},
    {"id": 0x7005, "text": "\x1AC'est fantastique!\x04\x1AHa! J'ai oublié de te dire...\x0B\x02", "box_type": 0},
    {"id": 0x7006, "text": "\x08Le château est en alerte! Je ne \x01laisserai même pas une souris\x01entrer!\x09\x02", "box_type": 0},
    {"id": 0x7007, "text": "\x1AArrrrgh...es-tu le garçon de la\x01forêt...?\x04\x1AEnfin te voici...\x01E-éc-écoute...\x04\x1A\x05\x41Ganondorf\x05\x40, le prince des voleurs,\x01a trahi notre Roi...\x04\x1A\x05\x41Impa\x05\x40 la nourrice a senti le danger\x01et s'est enfuie du château avec la\x01Princesse Zelda...\x04\x1AJ'ai essayé d'arrêter les hommes \x01de Ganondorf...mais...\x04\x1ALa Princesse attendait...un garçon\x01de la forêt...toi... Elle voulait\x01te donner \x05\x41quelque chose\x05\x40...\x04\x1ASi la Princesse te l'a remis, \x01\x14\x03\x08Vite\x09...\x08va au\x09 \x08\x05\x44Tem\x09\x08ple\x09 \x08du\x09 Temps\x05\x40....\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x7008, "text": "Il ne bouge plus....\x02", "box_type": 2},
    {"id": 0x7009, "text": "\x1ATu vois cet homme aux yeux \x01noirs de haine?\x04\x1AC'est \x05\x41Ganondorf\x05\x40, il est le chef \x01des Gerudos, une tribu du désert.\x04\x1AMême s'il jure fidélité à Père, \x01je suis sûre qu'il est un traître.\x04\x1AMes rêves me font voir de \x01sombres nuages sur Hyrule...\x01Ils doivent représenter cet homme!\x02", "box_type": 0},
    {"id": 0x700A, "text": "\x06\x05Ha hah hah! Félicitations, gamin!\x0C\x3C\x06\x02Comme je le pensais, tu avais en \x01\x06\x06ta possession la clé des portes \x01\x06\x44du temps!\x0C\x5A\x06\x0BTu m'as ouvert la voie jusqu'au\x01\x06\x34Saint Royaume...\x0C\x50\x06\x0FJe te dois ma victoire, petit!\x0E\x32\x02", "box_type": 0},
    {"id": 0x700B, "text": "\x1AVite! Il va s'en aller!\x0B\x02", "box_type": 0},
    {"id": 0x700C, "text": "Pitié...avec \x05\x46¡\x05\x40...\x01Pitié vends-moi le \x05\x41contenu\x05\x40 d'une\x01bouteille...\x01Pitié...avec \x05\x46¡\x05\x40...\x02", "box_type": 0},
    {"id": 0x700D, "text": "Quelle étrange boutique!\x01Quand va-t-elle ouvrir?\x01J'ai lu le panneau mais... \x01J'y comprends rien!\x02", "box_type": 0},
    {"id": 0x700E, "text": "L'aube se fait attendre...\x04La vue du château sous le soleil \x01du matin est superbe!\x02", "box_type": 0},
    {"id": 0x700F, "text": "Pour sauver la fille de la forêt il\x01te faudra un \x05\x41nouveau pouvoir\x05\x40... \x01Va au village Cocorico!\x02", "box_type": 0},
    {"id": 0x7010, "text": "Tu as le pouvoir qu'il te faut...\x01La \x05\x42fille de la forêt \x05\x40t'attend...\x02", "box_type": 0},
    {"id": 0x7011, "text": "Il te faut une bouteille vide\x01pour transporter une potion!\x0A\x02", "box_type": 0},
    {"id": 0x7012, "text": "Désolé...ce n'est qu'une maquette. \x01La crise du village Goron nous\x01a mis en rupture de stock.\x0A\x02", "box_type": 2},
    {"id": 0x7013, "text": "Avant d'aller sur le Mont du Péril, \x01procure-toi un \x05\x44bouclier Hylien\x05\x40. \x01Les chutes de pierres sont \x01terribles, tu verras!\x04Mais il risque d'être un peu grand \x01pour toi...\x0A\x02", "box_type": 0},
    {"id": 0x7014, "text": "T'es fou! Je ne danse pas...\x01J'ai le dos qui me gratte...\x01Haaaa! Hooooo! Rhaaaaa!\x02", "box_type": 0},
    {"id": 0x7015, "text": "On dit que les grandes oreilles \x01des \x05\x44Hyliens\x05\x40 servent à entendre la \x01voix des dieux...faut croire que les \x01miennes sont en panne.\x02", "box_type": 0},
    {"id": 0x7016, "text": "\x1AEs-tu déjà allé au \x05\x46Ranch Lon Lon\x05\x40,\x01Gamin?\x04\x1ALeur lait est délicieux!\x01Ils ont beaucoup de chevaux et la\x01fille du patron est très mignonne!\x07\x70\x17\x02", "box_type": 0},
    {"id": 0x7017, "text": "Pour te rendre au \x05\x46Ranch\x05\x40, c'est \x01simple: traverse la plaine vers \x01le Sud en sortant du château!\x01Tu m'en diras des nouvelles!\x02", "box_type": 0},
    {"id": 0x7018, "text": "\x1AJe voulais voir la \x05\x41Princesse Zelda\x05\x40!\x04\x1AJ'ai évité tous les gardes...\x04\x1AJ'ai nagé dans les douves...\x04\x1AJ'y étais presque mais...ils m'ont\x01attrapé!\x07\x70\x19\x02", "box_type": 0},
    {"id": 0x7019, "text": "J'ai trouvé un petit \x05\x41trou\x01d'évacuation\x05\x40 sur la droite du \x01château. J'ai voulu m'y glisser \x01mais je suis resté coincé!\x02", "box_type": 0},
    {"id": 0x701A, "text": "\x06\x37Ahem! \x08Hrrrm!\x09\x04\x06\x15Cette barbe est ma fierté!\x01\x06\x17Elle est belle, hein? Hein?\x02", "box_type": 0},
    {"id": 0x701B, "text": "\x1A\x06\x37Ahem! \x08Hrrrm!\x09\x04\x1A\x06\x16Cette barbe est ma fierté.\x01\x06\x0EElle est belle et bien fournie!\x04\x1A\x08\x06\x4DQuoi?!\x09\x04\x1ATu cherches le gars du Ranch \x01Lon Lon?\x04\x1AHmm, Peut-être...\x07\x70\x1C\x02", "box_type": 0},
    {"id": 0x701C, "text": "J'ai vu un \x05\x41type avec une horrible\x01moustache noire \x05\x40apporter du lait\x01au château.\x02", "box_type": 0},
    {"id": 0x701D, "text": "\x1ASais-tu que le \x05\x44Temple du Temps\x05\x40\x01se trouve au Nord Est du Bourg?\x07\x70\x1E\x02", "box_type": 0},
    {"id": 0x701E, "text": "Les légendes racontent que le \x01Temple du Temps est l'entrée du\x01Saint Royaume...\x04C'est trop terrible ça!\x02", "box_type": 0},
    {"id": 0x701F, "text": "\x1AWha-ha-ha! Il est dingue ce type!\x04\x1AIl a essayé d'entrer dans le \x01château pour voir la \x05\x41Princesse \x01Zelda\x05\x40! Il est dingue, lui!\x07\x70\x20\x02", "box_type": 0},
    {"id": 0x7020, "text": "A cause de ce crétin ils ont \x01doublé la garde! C'est malin!\x01Wha-ha-hah!\x02", "box_type": 0},
    {"id": 0x7021, "text": "\x1AJ'ai gagné beaucoup d'argent!\x04\x1AMoi j'aime vendre des trucs \x01et des machins!\x07\x70\x22\x02", "box_type": 0},
    {"id": 0x7022, "text": "Je vais me faire des sous près du\x01\x05\x43Lac Hylia\x05\x40! On trouve plein d'objets\x01au fond de l'eau! Hah hah!\x02", "box_type": 0},
    {"id": 0x7023, "text": "\x1AHé! P'tit gars de la forêt! \x01Voici le \x05\x44Bourg d'Hyrule\x05\x40! \x01Prends ton temps et admire!\x07\x70\x24\x02", "box_type": 0},
    {"id": 0x7024, "text": "Pour aller au \x05\x44Château d'Hyrule\x05\x40,\x01prends la rue à droite.\x04Pour examiner la \x05\x43ruelle\x05\x40, emprunte\x01la rue de gauche.\x02", "box_type": 0},
    {"id": 0x7025, "text": "Amour...\x04Tu es si...beau...\x04Comme le Roi d'Hyrule...\x04Amour...\x02", "box_type": 0},
    {"id": 0x7026, "text": "Comme tu es belle...\x04Tu es...\x04Encore plus belle que...\x04La Princesse Zelda...\x04Mon p'tit chat... Je t'aime tant!\x02", "box_type": 0},
    {"id": 0x7027, "text": "\x1AConnais-tu le \"peuple de l'ombre\"?\x04\x1ALes \x05\x43Sheikahs \x05\x40sont l'ombre des \x01Hyliens.\x04\x1AOn dit qu'ils ont juré fidélité au\x01Roi d'Hyrule! Leur tâche est de \x01protéger la Famille Royale.\x04\x1AMais ils se font très rares par \x01ces temps de paix ...\x04\x1AEnfin...\x07\x70\x28\x02", "box_type": 0},
    {"id": 0x7028, "text": "J'ai entendu dire qu'un \x05\x43Sheikah \x01\x05\x40vivait au château...\x02", "box_type": 0},
    {"id": 0x7029, "text": "Quoi? Tu veux voir la \x05\x41Princesse\x01Zelda\x05\x40?\x01Haaaa... Encore un!\x04Bon! Ce que tu veux, on s'en \x01contre-fiche!\x01Alors...\x04\x08Du balai!\x09 \x08Ouste!!\x09\x01Jamais la Princesse n'accordera\x01une audience à un bouseux comme \x01toi! Hah ah ah ha ha!\x02", "box_type": 0},
    {"id": 0x702A, "text": "Z Z Z Z Z....\x04Ronnnff...Zzzzzz...Hmmmpfff! \x04Bienvenue...au Ranch...\x04Il est beau mon Ranch...\x01Roooooonnnfle....\x02", "box_type": 0},
    {"id": 0x702B, "text": "\x1A\x08\x06\x32Nom d'un pétard!\x09\x04\x1AOn peut pas piquer un p'tit\x01roupillon en paix ici?\x02", "box_type": 0},
    {"id": 0x702C, "text": "\x1ABonjour mon ami! Qui es-tu?\x04\x1AOuaip! Moi c'est \x05\x41Talon\x05\x40, patron du\x01Ranch Lon Lon.\x04\x1AJe suis venu au château livrer du\x01lait et...j'ai dû m'endormir...\x04\x1A\x06\x4C\x12\x68\x52Quoi?!\x01\x06\x2DMalon me cherche?\x01Houlà je vais m'faire crier dessus!\x04\x1AMalon n'aime pas mes p'tites\x01pauses!\x04\x1AJe ne vais pas y couper!\x0B\x02", "box_type": 0},
    {"id": 0x702D, "text": "\x08\x06\x0FHé! Le mioche! Viens par là!\x09\x0B\x02", "box_type": 0},
    {"id": 0x702E, "text": "\x1A\x06\x5F!\x0C\x0A\x1A\x06\x4E\x08Qui?!\x09\x0B\x02", "box_type": 0},
    {"id": 0x702F, "text": "\x1A\x06\x42Qui es-tu?\x04\x1AComment as-tu évité les gardes?\x0B\x02", "box_type": 0},
    {"id": 0x7030, "text": "Alors...tu as la Pierre?\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x7031, "text": "Etrange...\x01Tu ressembles pourtant au garçon \x01de mon rêve...\x01Vraiment? Tu ne l'as pas?\x04Allez... Dis-moi la vérité...\x0B\x02", "box_type": 0},
    {"id": 0x7032, "text": "\x1A\x06\x34J'en étais sûre!\x0B\x02", "box_type": 0},
    {"id": 0x7033, "text": "Bon...ne répète ça à personne...\x01\x01\x1B\x05\x42OK\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x7034, "text": "Tu vas cafarder? \x01Sois gentil...\x0B\x02", "box_type": 0},
    {"id": 0x7035, "text": "\x1AVoici ce que dit la légende...\x0B\x02", "box_type": 0},
    {"id": 0x7036, "text": "\x1A\x06\x0ALes trois déesses dissimulèrent\x01la \x05\x41Triforce\x05\x40 renfermant la puissance\x01\x06\x04des dieux quelque part en Hyrule.\x0C\x50\x1A\x06\x1FCette puissance permet\x01\x06\x0Ad'exaucer un voeu au détenteur\x01\x06\x39de la Triforce.\x0C\x50\x1A\x06\x11Si ce voeu est prononcé par\x01\x06\x08un homme au coeur pur, Hyrule \x01\x06\x26connaîtra l'âge d'or....\x0C\x3C\x1A\x06\x08Mais si le voeu est formulé par\x01\x06\x04un homme mauvais, le monde sera\x01\x06\x15englouti dans les flammes...\x0C\x50\x1A\x06\x08Les Sages anciens ont construit\x01\x06\x05le \x05\x44Temple du Temps \x05\x40pour tenir la\x01\x06\x22Triforce à l'écart des \x01\x06\x33forces obscures.\x0E\x5A\x02", "box_type": 2},
    {"id": 0x7037, "text": "En effet... Le Temple du Temps est\x01la porte vers le Saint Royaume \x01légendaire.\x04Mais la \x05\x44Porte du Temps\x05\x40 en interdit\x01l'accès...\x04Pour ouvrir cette porte les trois\x01\x05\x41Pierres Ancestrales\x05\x40 sont\x01indispensables.\x04Ainsi que le trésor de la Famille\x01Royale......\x0B\x02", "box_type": 0},
    {"id": 0x7038, "text": "Excuse-moi...\x01Je ne suis pas douée pour conter \x01les légendes...\x0B\x02", "box_type": 0},
    {"id": 0x7039, "text": "\x1A\x08Que s'est-il passé?\x09 Il t'a vu?\x04\x1ACe n'est pas grave...\x04\x1AIl ignore nos plans... \x01Enfin pour l'instant!\x0B\x02", "box_type": 0},
    {"id": 0x703A, "text": "\x1AJe t'en prie!\x01\x01\x1B\x05\x42OK\x01Je ne te crois pas\x05\x40\x02", "box_type": 0},
    {"id": 0x703B, "text": "\x1A\x06\x4EMerci!\x0B\x02", "box_type": 0},
    {"id": 0x703C, "text": "Ma nourrice te guidera hors du\x01château. N'aie pas peur et va lui \x01parler.\x02", "box_type": 0},
    {"id": 0x703D, "text": "La Pierre Ancestrale...\x01Tu l'as enfin trouvée!\x04Il est dit que les races possédant \x01une Pierre Ancestrale ouvrent leur \x01esprit au son de la \x05\x43Mélodie de la \x01Famille Royale\x05\x40.\x04Mais tu connais déjà cette \x01mélodie, n'est-ce pas?\x02", "box_type": 0},
    {"id": 0x703E, "text": "Hé! Sais-tu que la Princesse \x01Zelda fait souvent des rêves \x01prémonitoires?\x02", "box_type": 0},
    {"id": 0x703F, "text": "Gné? Quoué? Comment? \x01Va-t'en, petit...\x02", "box_type": 0},
    {"id": 0x7040, "text": "Il y a trois socles et une \x01inscription....\x04\x08Toi qui portes les trois Pierres\x01Ancestrales, entonne le \x05\x44chant du \x01temps \x05\x40avec l'\x05\x44Ocarina du Temps\x05\x40.\x09\x0B\x02", "box_type": 2},
    {"id": 0x7041, "text": "Allez, fais-moi un prix! \x01Une réduc' quoi! \x01C'est trop cher!\x02", "box_type": 0},
    {"id": 0x7042, "text": "Hé! Va-t'en! C'est à môa!\x01Je l'ai vu la première!\x02", "box_type": 0},
    {"id": 0x7043, "text": "Hé! Qui c'est qui m'a poussée? \x01QUI?!\x02", "box_type": 0},
    {"id": 0x7044, "text": "Etrange...Un groupe de Gerudos \x01dans la ville...Il se passe quelque\x01chose de pas très correct dans \x01le coin! Ouais, ça c'est sûr!\x02", "box_type": 0},
    {"id": 0x7045, "text": "C'était pas la Princesse Zelda sur\x01ce cheval blanc?!\x02", "box_type": 0},
    {"id": 0x7046, "text": "j'ai failli me faire écraser par \x01cet énorme cheval noir!\x01L'est fou l'aut' grand type!\x02", "box_type": 0},
    {"id": 0x7047, "text": "L'homme sur le cheval noir \x01s'appelle Ganondorf. Il est connu \x01comme étant le Roi des Voleurs \x01Gerudo.\x02", "box_type": 0},
    {"id": 0x7048, "text": "Hein?! Que s'est-il passé?!\x02", "box_type": 0},
    {"id": 0x7049, "text": "Regarde ce type! Il est mort de\x01trouille! Quelle mauviette!\x01Ha ha hah!\x02", "box_type": 0},
    {"id": 0x704A, "text": "Hmmmm...ça craint dans l'coin...\x01Je vais prendre des vacances!\x02", "box_type": 0},
    {"id": 0x704B, "text": "Un drame est arrivé au château!\x01Sois prudent, gamin!\x02", "box_type": 0},
    {"id": 0x704C, "text": "Cette \x05\x41clé\x05\x40 te permet d'ouvrir la\x01salle suivante!\x02", "box_type": 0},
    {"id": 0x704D, "text": "Sur le cheval blanc...\x01C'était pas cette...Sheikah?\x02", "box_type": 0},
    {"id": 0x704E, "text": "\x1A\x06\x2D\x0F...\x04\x1A\x06\x37Reviens à toi...\x01\x06\x4B...L'élu...\x02", "box_type": 5},
    {"id": 0x704F, "text": "\x1AJe suis \x05\x41Rauru\x05\x40...\x01L'un des anciens Sages.\x04\x1AJadis, les Sages bâtirent le Temple \x01du Temps pour protéger l'entrée \x01du Saint Royaume Légendaire...\x04\x1AVoici le \x05\x41Sanctuaire des Sages\x05\x40 au\x01sein même du Temple de la \x01Lumière!\x04\x1ALe Temple de la Lumière se trouve\x01au centre du Saint Royaume. Il est\x01le dernier rempart contre \x01l'influence maléfique de Ganondorf.\x04\x1AL'\x05\x41Epée de Légende\x05\x40, la lame \x01purificatrice jadis prisonnière \x01du piédestal du Temps, est la\x01clé ultime du Saint Royaume.\x04\x1A\x0F...\x01N'aie pas peur...\x01Regarde-toi...!\x02", "box_type": 0},
    {"id": 0x7050, "text": "\x1A\x06\x1B\x05\x44Regarde \x0F!\x05\x40\x04\x1A\x06\x38\x05\x44Tu as grandi!!\x01\x05\x40\x06\x32\x05\x44Tu es un adulte!\x05\x40\x02", "box_type": 0},
    {"id": 0x7051, "text": "\x1AL'Epée de Légende est une lame \x01sacrée interdite aux forces \x01obscures....\x04\x1ASeul le \"\x05\x41Héros du Temps\x05\x40\" peut la \x01retirer de son socle de granit....\x04\x1AMais tu étais trop jeune pour être\x01ce Héros du Temps....\x04\x1ATon esprit fut scellé en ce lieu\x01pendant sept ans.\x04\x1AMais il est enfin temps de \x01t'éveiller et de laisser la \x01destinée du Héros du Temps \x01s'accomplir par tes actes!\x04As-tu conscience de la tâche à \x01accomplir?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x7052, "text": "Oui, je comprends, ton esprit est \x01encore embrumé par les voiles d'un\x01repos de sept ans...Je vais tout\x01te répéter.\x07\x70\x51\x02", "box_type": 0},
    {"id": 0x7053, "text": "\x1AMais souviens-toi...\x04\x1AMême si tu as ouvert les Portes \x01du Temps au nom de la paix et \x01de la justice...\x04\x1A\x05\x41Ganondorf\x05\x40, le Roi des voleurs\x01Gerudo, en a profité pour violer\x01le Saint Royaume interdit!\x04\x1AIl a dérobé la Triforce dans le \x01Temple de la Lumière, et grâce à\x01ses nouveaux pouvoirs il s'est \x01sacré \x05\x41Seigneur du Malin\x05\x40...\x04\x1ASon pouvoir maléfique a perverti\x01les Temples d'Hyrule et a transfor-\x01mé en sept ans notre monde en \x01un chaos innommable.\x04\x1AMon pouvoir est bien faible, mon\x01influence mineure, dans le \x01Saint Royaume...et...\x04\x1A...dans ce Sanctuaire des Sages.\x04\x1AMais il reste un espoir.\x04\x1ALa puissance des Sages.\x04\x1AQuand la puissance des \x05\x41sept\x01Sages \x05\x40se manifestera......\x04\x1A...les influences maléfiques seront \x01endiguées par le \x05\x41Sceau des Sages\x05\x40.\x04\x1AMoi, Rauru, je suis l'un des Sages.\x01Et...\x04\x1A...ta puissance combinée à celle\x01des Sages te proclame...\x01\x05\x41Héros du Temps\x05\x40!\x04\x1AElu par l'Epée de Légende,\x01ta destinée sera de guider Hyrule\x01vers la lumière.\x04\x1AGarde mon esprit avec toi...\x01Trouve les autres Sages et reviens\x01ici consacré de leurs pouvoirs!\x02", "box_type": 0},
    {"id": 0x7054, "text": "\x1A\x05\x44Nous sommes de retour dans le \x01\x05\x40Temple du Temps\x05\x44...\x01\x05\x40Sept ans\x05\x44 se sont-ils vraiment\x01écoulés?\x05\x40\x04\x1A\x05\x44Je pense que tu ne pourras plus\x01utiliser ton équipement d'enfant \x01ainsi que certaines \x05\x40armes\x05\x44...\x04\x05\x40\x1A\x05\x44Bon...partons d'ici!\x05\x40\x02", "box_type": 0},
    {"id": 0x7055, "text": "Hééé! Quoi...? \x01Qu'y a-t-il de mal à ne rien\x01faire de la journée?\x04Hein? hein? hein?\x02", "box_type": 0},
    {"id": 0x7056, "text": "\x1AJe t'attendais,\x01Héros du Temps...\x02", "box_type": 0},
    {"id": 0x7057, "text": "\x1AQuand le mal est sur le monde, \x01ceux sensibles à l'appel du Saint\x01Royaume Légendaire se réfugient \x01dans les \x05\x41cinq Temples\x05\x40.\x04\x1ADans une \x05\x42profonde forêt\x05\x40...\x04\x1ASur une \x05\x41haute montagne\x05\x40...\x04\x1ADans un \x05\x43vaste lac\x05\x40...\x04\x1ADans la \x05\x45maison des morts\x05\x40...\x04\x1ADans la \x05\x46déesse de sable\x05\x40...\x04\x1AGrâce au Héros du Temps les \x01éveillés chasseront les forces \x01maléfiques du monde et apporteront \x01paix et justice en Hyrule!\x04\x1ATelle est la légende des temples,\x01transmise de génération en \x01génération par mon peuple, les\x01\x05\x43Sheikahs\x05\x40.\x02", "box_type": 0},
    {"id": 0x7058, "text": "Oh! Je suis désolée.\x01Nous ne sommes pas ouverts pour \x01l'instant. Revenez plus tard!\x0B\x02", "box_type": 0},
    {"id": 0x7059, "text": "\x1AFrappe-le avec \x05\x41l'Epée de Légende\x05\x40!\x01Seule la sainte lame peut terrasser\x01Ganon!\x02", "box_type": 0},
    {"id": 0x705A, "text": "\x1AJe t'attendais,\x01\x0F.\x02", "box_type": 0},
    {"id": 0x705B, "text": "\x1A\x0F, Héros du Temps...\x04\x1ATu as traversé bien des épreuves\x01pour éveiller les six Sages.\x04\x1AIl ne te reste plus que la dernière\x01épreuve, la plus terrible! La \x01confrontation finale avec \x01Ganondorf, le Seigneur du Malin...\x02", "box_type": 0},
    {"id": 0x705C, "text": "\x1A\x06\x21Toi, quêteur des saints\x01\x06\x21triangles, écoute bien...\x0C\x3C\x1A\x06\x0ELes triangles sacrés reposent\x01\x06\x29en un lieu mystique,\x01\x06\x11un miroir reflétant l'intérieur\x01\x06\x46de l'âme...\x0C\x46\x1A\x06\x14Si une âme noire y pénètre,\x01\x06\x0Cle royaume deviendra chaos et\x01\x06\x0Bflammes. Si elle est pure, il se\x01\x06\x23changera en paradis....\x0C\x5A\x1A\x06\x06La Triforce, les triangles sacrés,\x01\x06\x11est une balance qui équilibre\x01\x06\x28les trois puissances:\x01\x06\x15Force, Sagesse et Courage.\x0C\x5A\x1A\x06\x20Si l'âme du porteur des\x01\x06\x1BSaints Triangles préserve\x01\x06\x0Fcet équilibre, alors le porteur\x01\x06\x20aura l'ultime puissance!\x0C\x50\x1A\x06\x07Mais si son âme est tourmentée\x01\x06\x25la Triforce se brisera\x01\x06\x18en trois parties: la Force,\x01\x06\x19la Sagesse et le Courage.\x0C\x50\x1A\x06\x11A celui qui a brisé l'équilibre\x01\x06\x15il ne restera qu'une pièce...\x01\x06\x13Celle qui correspond le plus\x01\x06\x34à ses ambitions.\x0C\x5A\x1A\x06\x0CEt s'il cherche l'Ultime Pouvoir,\x01\x06\x19il devra acquérir les deux\x01\x06\x3Aautres pièces.\x0C\x50\x1ACes deux pièces seront transmises\x01\x06\x2Baux élus du Destin.\x01\x06\x10Ils porteront la marque de la\x01\x06\x10Triforce au dos de leur main.\x0E\x5A\x02", "box_type": 2},
    {"id": 0x705D, "text": "\x1AIl y a sept ans, Ganondorf, \x01utilisa la porte que tu as ouverte \x01dans le temple du temps pour \x01violer le Saint Royaume.\x04\x1AMais en posant la main sur la \x01Triforce la légende devint réalité.\x02", "box_type": 0},
    {"id": 0x705E, "text": "\x1ALe porteur de la \x05\x41Triforce du \x01courage\x05\x40, c'est...\x01Toi, \x0F!\x02", "box_type": 0},
    {"id": 0x705F, "text": "\x1ALe détenteur de la \x05\x41Triforce\x01de la sagesse\x05\x40...\x04\x1A...est le septième Sage, dont\x01le destin est de conduire les \x01autres éveillés...\x02", "box_type": 0},
    {"id": 0x7060, "text": "\x1AC'est moi,\x05\x41 Zelda\x05\x40, Princesse\x01d'Hyrule.\x02", "box_type": 0},
    {"id": 0x7061, "text": "\x1APardonne-moi de t'avoir caché ma\x01véritable identité, mais je devais \x01me dérober aux yeux de Ganondorf.\x02", "box_type": 0},
    {"id": 0x7062, "text": "Je t'ai vu en m'enfuyant du \x01château d'Hyrule.\x0E\x50\x02", "box_type": 2},
    {"id": 0x7063, "text": "\x1AEn te confiant l'ocarina, je pensais\x01pouvoir empêcher Ganondorf de \x01violer le Saint Royaume, mais...\x04\x1AQuelque chose d'inattendu\x01est arrivé...\x02", "box_type": 0},
    {"id": 0x7064, "text": "\x1A\x06\x19Cette secousse...c'est...!?\x02", "box_type": 0},
    {"id": 0x7065, "text": "\x1APrincesse Zelda...\x01Petite cachottière!\x04\x1AJe te félicite d'avoir échappé à\x01mes recherches pendant sept ans.\x02", "box_type": 2},
    {"id": 0x7066, "text": "\x1ASi tu veux sauver la Princesse,\x01viens la chercher au château!\x02", "box_type": 2},
    {"id": 0x7067, "text": "\x1A\x0F... C'est moi, Rauru!\x01Peux-tu m'entendre?\x04\x1ANous, les six Sages, allons \x01concentrer nos pouvoirs pour \x01créer une passerelle vers le \x01château de Ganondorf...\x04\x1ALe donjon, la Tour de Ganon, \x01est protégé par \x05\x41six barrières \x01maléfiques\x05\x40.\x04\x1AAbats ces barrières et sauve la\x01Princesse Zelda!!\x02", "box_type": 2},
    {"id": 0x7068, "text": "7068\x02", "box_type": 0},
    {"id": 0x7069, "text": "7069\x02", "box_type": 0},
    {"id": 0x706A, "text": "706a\x02", "box_type": 2},
    {"id": 0x706B, "text": "706b\x02", "box_type": 0},
    {"id": 0x706C, "text": "Anciens créateurs d'Hyrule!\x0C\x3COuvrez le sceau dimensionnel et\x01renvoyez l'incarnation du Malin\x01dans le vide infernal!!\x0E\x5A\x02", "box_type": 0},
    {"id": 0x706D, "text": "\x1A\x0F!\x01Achève-le avec la lame sacrée, \x01l'Epée de Légende!\x02", "box_type": 0},
    {"id": 0x706E, "text": "\x1AÔ, sceau dimensionnel ouvert par \x01les Sages... Referme-toi sur \x01l'Incarnation du Malin!!\x02", "box_type": 0},
    {"id": 0x706F, "text": "\x1AMerci, \x0F...\x04\x1AGrâce à toi, Ganondorf est \x01prisonnier du royaume infernal!\x04\x1ALa paix et la justice vont à \x01nouveau régner sur ce monde...\x01Et pour longtemps.\x02", "box_type": 0},
    {"id": 0x7070, "text": "\x1A\x06\x1EMerci, \x0F...\x0C\x28\x1A\x06\x4BAdieu....\x0E\x3C\x02", "box_type": 2},
    {"id": 0x7071, "text": "Tu veux vraiment passer? \x01Bon...laisse-moi réfléchir...\x01C'est d'accord, mais en échange...\x07\x70\x72\x02", "box_type": 0},
    {"id": 0x7072, "text": "Donne-moi 10 Rubis...\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x7073, "text": "Crois-moi....\x01Mes visions prophétiques sont\x01toujours exactes!\x0B\x02", "box_type": 0},
    {"id": 0x7074, "text": "\x1ATu as détruit l'odieux fantôme\x01de ce temple et éveillé le Sage...\x04\x1AMais d'autres Sages ont besoin de\x01ton aide.\x04\x1APour éveiller les autres Sages, tu \x01devras devenir encore plus \x01puissant...\x04\x1AVa par les montagnes...\x04\x1ASous les flots...\x04\x1AEt deviens voyageur du Temps...\x02", "box_type": 0},
    {"id": 0x7075, "text": "\x1AAussi longtemps que tu garderas\x01\x05\x44l'ocarina \x05\x40et \x05\x44l'Epée de Légende\x05\x40...\x04\x1A...le temps sera avec toi...\x04\x1A\x0F... A bientôt!\x02", "box_type": 0},
    {"id": 0x7076, "text": "C'est un nouveau type de bombes!\x01Disponible uniquement en quantité\x01limitée! Quand y'en a pus, ben... \x01Y'en a pus!\x0B\x02", "box_type": 0},
    {"id": 0x7077, "text": "\x1AMon nom est \x05\x41Sheik\x05\x40.\x01L'un des derniers Sheikahs...\x02", "box_type": 0},
    {"id": 0x7078, "text": "\x1AArmé de L'\x05\x41Epée de Légende\x05\x40, \x01le titre de Héros du Temps te\x01revient de droit...\x02", "box_type": 0},
    {"id": 0x7079, "text": "\x1ASi j'en crois les légendes, ta quête\x01est claire... Tu dois éveiller \x05\x41les \x01cinq Sages \x05\x40dans les cinq temples...\x02", "box_type": 0},
    {"id": 0x707A, "text": "\x1AL'un des Sages attend dans le \x01\x05\x42Temple de la forêt \x05\x40l'heure de son \x01éveil. C'est une jeune fille que tu \x01connais...\x04\x1AL'influence maléfique qui pervertit \x01les temples l'empêche de répondre \x01aux appels du Saint Royaume...\x04\x1AEquipé comme tu l'es, tu ne\x01pourras entrer dans le Temple...\x04\x1AAlors crois-moi, rends-toi au\x01\x05\x41Village Cocorico\x05\x40...\x04\x1AM'as-tu compris, \x01\x0F?\x02", "box_type": 0},
    {"id": 0x707B, "text": "Je pensais que te confier l'ocarina\x01était notre seule chance...\x0E\x50\x02", "box_type": 2},
    {"id": 0x707C, "text": "\x1AJ'ai certaines choses à te dire... \x01Ecoute-moi bien.\x04\x1AVoici une autre légende sur la\x01Triforce connue des Sheikahs, \x01le peuple de l'ombre....\x02", "box_type": 0},
    {"id": 0x707D, "text": "\x1ALa Triforce s'est brisée en \x01trois parties. Ganondorf possède \x01la \x05\x41Triforce de la Force\x05\x40.\x02", "box_type": 0},
    {"id": 0x707E, "text": "\x1AGrâce à sa Triforce il put devenir\x01le Seigneur du Malin. Mais ses \x01ambitions maléfiques n'ont pas de\x01limites.\x02", "box_type": 0},
    {"id": 0x707F, "text": "\x1APour devenir le maître du monde\x01Ganondorf cherche les \x05\x41élus du \x01destin\x05\x40 pour s'approprier les deux \x01pièces restantes de la Triforce.\x02", "box_type": 0},
    {"id": 0x7080, "text": "\x1AEn ce jour maudit, il y a sept ans,\x01Ganondorf prit d'assaut le Château \x01d'Hyrule...\x02", "box_type": 0},
    {"id": 0x7081, "text": "\x1AAprès avoir ouvert les portes du\x01Temps, l'Epée de Légende t'a \x01envoyé dans le Saint Royaume...\x02", "box_type": 0},
    {"id": 0x7082, "text": "\x1ATon esprit s'est endormi dans le \x01Saint Royaume et Ganondorf viola\x01ce lieu sacré pour se saisir de la\x01Triforce...\x04\x1AGanondorf est devenu le Roi du \x01Mal, et sous son règne de haine, \x01Hyrule s'est transformée en une \x01terre hostile.\x04\x1AJe pris l'apparence d'un Sheikah en \x01attendant l'éveil de ton esprit. \x01Pendant sept longues années...\x02", "box_type": 0},
    {"id": 0x7083, "text": "\x1ADésormais...et grâce à toi....\x01Le règne maléfique de Ganondorf \x01va prendre fin!\x02", "box_type": 0},
    {"id": 0x7084, "text": "\x1ALes six Sages ouvriront le sceau\x01pour attirer Ganondorf dans le \x01Saint Royaume.\x04\x1AJe fermerai ensuite la porte.\x01Pour toujours...\x04\x1AAinsi Ganondorf, le Seigneur du \x01Malin, disparaîtra d'Hyrule.\x04\x1A\x0F...\x01Ton devoir est de me protéger\x01pendant l'exécution de ce plan.\x04\x1AVoici une arme qui pourra \x01pénétrer les défenses du Seigneur\x01du Malin...\x01L'arme sacrée de l'élu...\x04\x1A\x06\x0FLa sainte \x05\x44flèche de lumière\x05\x40!!!\x02", "box_type": 0},
    {"id": 0x7085, "text": "\x1AMais tu as baissé ta garde...\x01Et grâce à ce gamin, encore une \x01fois, j'ai pu te retrouver!\x02", "box_type": 0},
    {"id": 0x7086, "text": "\x1AMa seule erreur fut de sous-\x01estimer sa puissance...\x02", "box_type": 0},
    {"id": 0x7087, "text": "\x1AMais sa puissance n'est que\x01misère...\x01Sa seule force est la Triforce du\x01Courage!\x04\x1AGrâce à la Triforce de la Sagesse, \x01celle de Zelda...\x01Deux parties seront en ma \x01possession!\x04\x1AEt bientôt tu me remettras ton\x01fragment... \x01Je serai alors le maître du monde!\x02", "box_type": 0},
    {"id": 0x7088, "text": "\x08Ouverte par l'Ocarina du Temps, \x01la porte laissa apparaître l'élu, \x01porteur de l'Epée de Légende.\x09\x02", "box_type": 2},
    {"id": 0x7089, "text": "Je ne sais pas pourquoi, mais les \x01chiens aiment sortir le soir.\x01C'est curieux, hein?\x02", "box_type": 0},
    {"id": 0x708A, "text": "Hé! Mon petit, écoute ceci...\x04On dit qu'il y a une \x05\x41étrange \x01fontaine\x05\x40 près du château...\x02", "box_type": 0},
    {"id": 0x708B, "text": "\x1APour voyager vers le passé, \x01pose l'Epée de Légende dans le \x01\x05\x41piédestal\x05\x40.\x04\x1AA nouveau tu seras un jeune\x01garçon....\x02", "box_type": 0},
    {"id": 0x708C, "text": "\x1AUn jour viendra où tu voudras\x01revenir ici au plus vite...\x01Ecoute-moi et ton esprit volera,\x01défiant le temps et l'espace...\x04\x1AEntends et apprends car voici...\x01\x05\x44Le Prélude de la lumière\x05\x40.\x02", "box_type": 0},
    {"id": 0x708D, "text": "\x1AMon nom est \x05\x41Impa \x05\x40des Sheikahs.\x01Je suis chargée de la protection\x01de la Princesse Zelda.\x02", "box_type": 0},
    {"id": 0x708E, "text": "Les gardes du Roi ne doivent \x01pas te trouver en ces lieux. \x01Laisse-moi te guider hors du \x01château.\x02", "box_type": 0},
    {"id": 0x708F, "text": "\x08Hé! Toi! Ne fais pas l'imbécile!\x09\x0B\x02", "box_type": 0},
    {"id": 0x7090, "text": "\x1ATu es un garçon courageux...\x01Une grande et périlleuse aventure\x01t'attend!\x04\x1AD'après les prédictions de la \x01Princesse, mon rôle est d'enseigner\x01une mélodie au garçon de la forêt.\x04\x1ACette mélodie est transmise de\x05\x43\x01\x05\x40génération en génération\x05\x43 au sein\x01de la Famille Royale\x05\x40.\x04\x1AElle fut pendant longtemps la \x01berceuse de la Princesse Zelda...\x04\x1ACes notes renferment un pouvoir\x01mystérieux.\x04\x1AEcoute bien...\x02", "box_type": 0},
    {"id": 0x7091, "text": "\x1AJe suis responsable de tous les \x01maux d'Hyrule...\x04\x1AJ'étais si jeune... \x01J'ignorais que le contrôle du Saint \x01Royaume pouvait entraîner tant de \x01troubles...\x04\x1AJe t'ai fait prendre beaucoup de\x01risques.\x04\x1AIl est temps pour moi de réparer\x01mes erreurs...\x04\x1ALaisse derrière toi l'Epée de \x01Légende et scelle les portes du \x01Temps...\x02", "box_type": 0},
    {"id": 0x7092, "text": "\x1AMais en faisant cela les chemins\x01du temps seront à jamais fermés...\x02", "box_type": 0},
    {"id": 0x7093, "text": "\x1A\x0F,\x01rends-moi l'Ocarina...\x04\x1AEn tant que Sage, je peux te\x01renvoyer dans ton temps.\x02", "box_type": 0},
    {"id": 0x7094, "text": "\x1AQuand la paix reviendra en Hyrule...\x01\x1AIl sera temps de nous dire adieu...\x02", "box_type": 0},
    {"id": 0x7095, "text": "\x1ARentre chez toi, \x0F.\x01Retourne à ton époque!\x04\x1ATa maison... \x01Là est ta place...\x01Là est ton temps...\x02", "box_type": 0},
    {"id": 0x7096, "text": "\x06\x42\x08Tss...\x09 \x08Tss...\x09\x0B\x02", "box_type": 0},
    {"id": 0x7097, "text": "Hmmm...Tu as perdu ton argent de\x01poche?\x0B\x02", "box_type": 0},
    {"id": 0x7098, "text": "Bon...j'te laisse passer!\x0B\x02", "box_type": 0},
    {"id": 0x7099, "text": "GARDE CA POUR TOI!\x01NE LE REPETE A PERSONNE!\x02", "box_type": 0},
    {"id": 0x709A, "text": "Haaa! Je suis siiiii fatigué!\x04Les tours de garde nocturnes sont\x01super-méga-lourds!\x01Y'a même pas de fantômes...\x04Hein? J'adore les fantômes!\x04C'est ma passion! En savoir \x01beaucoup sur les Esprits et les\x01Ames peut être utile, non?\x02", "box_type": 0},
    {"id": 0x709B, "text": "Mon petit Kiki est le plus beau!\x01Il est le plus beau du moooonde!\x01C'est un gentil Kiki d'amour et\x01d'amitié qui me fait des bisous!\x02", "box_type": 0},
    {"id": 0x709C, "text": "Mon p'tit Kiki, il est le Kiki le \x01plus rapide du moooonde!\x01Il court et saute et fait des \x01bisous à sa mémère.\x02", "box_type": 0},
    {"id": 0x709D, "text": "Je ne trouve plus mon petit KIKI!\x01Il est où le Kiki? Il est où?\x01Kiki! Kiki! Mon p'tit Kiki!\x02", "box_type": 0},
    {"id": 0x709E, "text": "\x06\x4C\x08Arrrgh!\x09\x01C'est pas mon chien ça!\x01Celui-là il bave et il est moche!\x02", "box_type": 0},
    {"id": 0x709F, "text": "\x06\x53\x08KIKI!\x09\x04Mon p'tit Kiki! C'est bien lui!\x01Merci! Merci!\x01Tiens! Voilà pour toi!\x02", "box_type": 0},
    {"id": 0x70A0, "text": "La nuit des chiens errants sèment \x01la terreur, j'ai peur!\x01Pas pour toi...pour mon chien.\x01Mon Kiki à moi....mon p'tit Kiki!\x02", "box_type": 0},
    {"id": 0x70A1, "text": "B'jour!\x01Bienvenue à la \x05\x41Foire aux Masques\x05\x40!\x01Notre devise:\x01Un masque, un sourire,...la joie!\x04Veux-tu devenir un coursier \x01officiel distributeur de bonheur? \x01Je te prête un masque, tu le \x01vends et tu me rapportes \x05\x41l'argent\x05\x40.\x04Pour jeter un oeil aux clauses du\x01contrat, va lire la \x05\x41pancarte\x05\x40.\x04Après avoir vendu tous les \x01masques, ta joie sera aussi grande\x01que le Mont du Péril!\x04\x06\x32Aie la foi, petit...\x0B\x02", "box_type": 0},
    {"id": 0x70A2, "text": "\x08Choisis un masque avec le \x05\x44ª\x05\x40.\x01\x01\x1B\x05\x42Parler au vendeur\x01Quitter\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70A3, "text": "Un \x05\x41masque\x05\x40 est un objet \x01d'\x05\x46inventaire ¡\x05\x40.\x01Assigne-le à \x05\x46¡\x05\x40 et active-le avec\x01\x05\x46¡\x05\x40 pour le porter.\x04Tes interlocuteurs réagiront\x01différemment en fonction de ton\x01masque.\x04Si quelqu'un s'intéresse à ton \x01masque, n'hésite pas à lui vendre.\x04Quelque part, perdu dans ce \x01monde de haine, une voix s'élève \x01par-delà les montagnes:\x01\x08\"J'VEUX UN MASQUE\"!\x09\x04C'est une image, bien sûr...\x0B\x02", "box_type": 0},
    {"id": 0x70A4, "text": "J'ai vu une jolie fille passer...\x01Elle allait vers le château?\x01J'en sais rien moi!\x02", "box_type": 0},
    {"id": 0x70A5, "text": "Haaaa, bien! Tu l'as vendu!\x01Donne-moi \x05\x4110 Rubis \x05\x40pour le Masque\x01du Renard.\x0B\x02", "box_type": 0},
    {"id": 0x70A6, "text": "Ho! Tu n'as pas vendu le masque?\x01Pas grave...ça viendra...\x01Cherche encore! Encore! Encore!\x0B\x02", "box_type": 0},
    {"id": 0x70A7, "text": "Merci mon joli!\x0B\x02", "box_type": 0},
    {"id": 0x70A8, "text": "\x08Quoi?!\x09\x01Tu n'as pas mon argent?!\x04\x08C'EST MAL!\x09\x04Donne-moi mon pognon...sinon...\x01Plus de masques!\x0B\x02", "box_type": 0},
    {"id": 0x70A9, "text": "Fantastique!\x04Tous les masques ont été vendus.\x04Tu es un excellent vendeur.\x01Je l'ai toujours su!\x0B\x02", "box_type": 0},
    {"id": 0x70AA, "text": "\x1AEn récompense...\x01Je te laisse ce masque spécial.\x04\x1AC'est le \x05\x41Masque de Vérité\x05\x40. \x01ses pouvoirs sont mystérieux...\x01Il me vient des Sheikahs.\x04\x1ACe masque te permet de lire dans\x01l'esprit des gens...\x01Pratique mais effrayant!\x04\x1APourquoi effrayant?\x04\x1AHa! Tu as encore bien des choses\x01à apprendre! Ho ho ho!\x0B\x02", "box_type": 0},
    {"id": 0x70AB, "text": "Tu peux désormais emprunter \x01n'importe quel masque.\x01Amuse-toi bien...\x0B\x02", "box_type": 0},
    {"id": 0x70AC, "text": "Bienvenue!\x01Quel masque te ferait plaisir?\x0B\x02", "box_type": 0},
    {"id": 0x70AD, "text": "\x08Choisis un masque avec le \x05\x44ª\x05\x40.\x01\x01\x1B\x05\x42Le Masque de Vérité?\x01Quitter\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70AE, "text": "Voici le \x05\x41Masque de Vérité\x05\x40. \x01Cet objet Sheikah est très \x01mystérieux.\x04Il permet de lire dans les esprits.\x01Pratique mais effrayant!\x04Pourquoi effrayant?\x04Tu comprendras quand tu seras \x01grand!\x04Ho ho ho!\x0B\x02", "box_type": 0},
    {"id": 0x70AF, "text": "\x08\x05\x41Masque de Vérité -- En exposition\x01\x05\x40Ce masque détient d'étranges \x01pouvoirs.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B0, "text": "\x08\x05\x41Masque de Mort -- 20 Rubis\x05\x40\x01Une tête de mort avec des cornes.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B1, "text": "\x08\x05\x41Masque d'Effroi -- 30 Rubis\x01\x05\x40Un masque de bois bien triste.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B2, "text": "\x08\x05\x41Masque du Renard -- 10 Rubis\x01\x05\x40Le Renard est à la mode!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B3, "text": "\x08\x05\x41Masque du Lapin -- 50 Rubis\x01\x05\x40Ses oreilles sont à croquer!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B4, "text": "\x08\x05\x41Masque  de Mort -- Gratuit\x05\x40\x01Une tête d'os avec des cornes.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B5, "text": "\x08\x05\x41Masque d'Effroi -- Gratuit\x01\x05\x40Un  masque en bois bien triste.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B6, "text": "\x08\x05\x41Masque du Renard -- Gratuit\x01\x05\x40Le Renard est à la mode!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B7, "text": "\x08\x05\x41Masque du Lapin -- Gratuit\x01\x05\x40Ses oreilles sont à croquer!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B8, "text": "\x08\x05\x41Masque de Goron -- Gratuit\x01\x05\x40Une grosse tête, c'est rigolo!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B9, "text": "\x08\x05\x41Masque de Zora -- Gratuit\x05\x40\x01A la mode pour une baignade!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70BA, "text": "\x08\x05\x41Masque de Gerudo -- Gratuit\x01\x05\x40Un parfait déguisement de femme.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70BB, "text": "\x08\x05\x41Masque de Vérité -- Gratuit\x05\x40\x01Un mystérieux masque permettant \x01de lire dans l'esprit des hommes.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70BC, "text": "\x08Veux-tu le \x05\x41Masque de Mort\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70BD, "text": "\x08Veux-tu le \x05\x41Masque d'Effroi\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70BE, "text": "\x08Veux- tu le \x05\x41Masque du Renard\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70BF, "text": "\x08Veux-tu le \x05\x41Masque du Lapin\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70C0, "text": "\x08Veux-tu le \x05\x41Masque de Goron\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70C1, "text": "\x08Veux-tu le \x05\x41Masque de Zora\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70C2, "text": "\x08Veux-tu le \x05\x41Masque de Gerudo\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70C3, "text": "\x08Veux-tu le \x05\x41Masque de Vérité\x05\x40?\x09\x01\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70C4, "text": "Bravo! Tu as vendu ton masque!\x01Donne-moi \x05\x4120 Rubis \x05\x40pour le\x01Masque de Mort.\x0B\x02", "box_type": 0},
    {"id": 0x70C5, "text": "Bravo! Tu as vendu ton masque!\x01Donne-moi \x05\x4130 Rubis \x05\x40pour le \x01Masque d'Effroi.\x0B\x02", "box_type": 0},
    {"id": 0x70C6, "text": "Bravo! Tu as vendu ton masque!\x01Donne-moi \x05\x4150 Rubis \x05\x40pour le \x01Masque du Lapin.\x0B\x02", "box_type": 0},
    {"id": 0x70C7, "text": "Oh! Tu n'as pas encore vendu le\x01masque. Continue et garde espoir.\x04Tu veux peut-être essayer avec\x01un autre masque?\x01\x1B\x05\x42Oui\x01Non\x05\x40\x02", "box_type": 0},
    {"id": 0x70C8, "text": "\x1ALes fragments de la Triforce \x01se réveillent...\x01Ils fusionnent une fois de plus...\x02", "box_type": 0},
    {"id": 0x70C9, "text": "\x1AIl y a sept ans...\x01Deux fragments ont échappé à \x01mon contrôle...\x04\x1AComment ont-ils pu arriver entre\x01vos mains?\x02", "box_type": 0},
    {"id": 0x70CA, "text": "\x1AQuoi qu'il en soit, les fragments \x01vont enfin s'unir en ce lieu!\x02", "box_type": 0},
    {"id": 0x70CB, "text": "\x1APauvres insectes....\x01Cette puissance n'est pas \x01pour vous!\x02", "box_type": 0},
    {"id": 0x70CC, "text": "\x1AJe vous ordonne de me les rendre!\x02", "box_type": 0},
    {"id": 0x70CD, "text": "\x1A\x12\x68\x5F\x05\x44\x0F!\x01Je ne peux pas t'aider!\x01L'énergie noire m'empêche \x01d'approcher!\x04\x05\x40\x1A\x05\x44Pardonne-moi, \x0F!\x05\x40\x02", "box_type": 0},
    {"id": 0x70CE, "text": "\x1AQuoi? Le Grand Ganondorf vaincu \x01par ce gamin?!\x02", "box_type": 0},
    {"id": 0x70CF, "text": "\x1A\x0F....!\x02", "box_type": 0},
    {"id": 0x70D0, "text": "\x1AMisérable Ganondorf......\x04\x1ASans un esprit sain et fort il ne\x01put maîtriser la puissance \x01des dieux...et...\x02", "box_type": 0},
    {"id": 0x70D1, "text": "\x1A\x0F, Ecoute-moi!\x01La tour va s'effondrer!\x04\x1ADe son dernier souffle de haine, \x01Ganon tente de nous écraser sous \x01les ruines de cette tour!\x01Dépêchons-nous!\x02", "box_type": 0},
    {"id": 0x70D2, "text": "\x1ASuis-moi vite!\x02", "box_type": 0},
    {"id": 0x70D3, "text": "\x1AC'est terminé...enfin...\x02", "box_type": 0},
    {"id": 0x70D4, "text": "\x1A\x05\x44\x0F... \x01Pardonne-moi...je n'ai pas pu t'aider.\x05\x40\x02", "box_type": 0},
    {"id": 0x70D5, "text": "\x1AQuel est ce bruit?\x02", "box_type": 0},
    {"id": 0x70D6, "text": "\x1A\x12\x68\x5F\x05\x44Cette fois-ci je ne fuirai pas!\x01\x05\x40\x08\x05\x44Nous combattrons ensemble!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70D7, "text": "\x1A\x0F! \x01L'Epée de Légende est ici! \x01\x08Vite!!\x09\x02", "box_type": 0},
    {"id": 0x70D8, "text": "\x1AMes pouvoirs paralysent Ganon!\x01Utilise l'Epée et porte-lui le coup\x01de grâce!\x02", "box_type": 0},
    {"id": 0x70D9, "text": "\x1A\x06\x41Six Sages...\x01\x08\x06\x3DMaintenant!!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70DA, "text": "\x1A\x14\x03TOI...\x14\x00\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70DB, "text": "\x1A\x14\x03SOIS MAUDITE...ZELDA!\x01\x14\x02PESTE SOIT DES...SAGES!!\x14\x00\x0E\x32\x02", "box_type": 0},
    {"id": 0x70DC, "text": "\x1AJE TE MAUDIS...\x08\x0F!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70DD, "text": "\x1AUn jour...\x01Ce sceau se brisera et....\x0C\x50\x1AJe tuerai de mes mains tes \x01descendants!!\x0E\x50\x02", "box_type": 0},
    {"id": 0x70DE, "text": "\x1AN'oublie pas...\x01Le fragment de la Force est \x01toujours en ma possession!....\x0E\x50\x02", "box_type": 0},
    {"id": 0x70DF, "text": "\x14\x02Toi...\x14\x00Qui es-tu?\x0E\x50\x02", "box_type": 2},
    {"id": 0x70E0, "text": "\x06\x15La \x05\x42Barrière de la Forêt \x05\x40est\x01\x06\x48dissipée!\x01\x06\x23Vite, \x0F!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E1, "text": "\x06\x21La \x05\x41Barrière du Feu \x05\x40est\x01\x06\x48dissipée!\x01\x06\x3FVite, Frère!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E2, "text": "\x06\x1FLa \x05\x43Barrière de l'Eau \x05\x40est\x01\x06\x48dissipée!\x01\x06\x3EDepèche-toi!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E3, "text": "\x06\x17La \x05\x45Barrière de l'Ombre \x05\x40est\x01\x06\x48dissipée!\x01\x06\x18Va et sauve la Princesse!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E4, "text": "\x06\x18La \x05\x46Barrière de l'Esprit \x05\x40est\x01\x06\x48dissipée!\x01\x06\x40Vite, gamin!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E5, "text": "\x06\x0FLa \x05\x44Barrière de la Lumière\x05\x40 est\x01\x06\x48dissipée!\x01\x06\x52Vite!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E6, "text": "\x05\x44\x0F, mais c'est...?!\x05\x40\x02", "box_type": 0},
    {"id": 0x70E7, "text": "\x05\x44C'est la Lame purificatrice...\x05\x40\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70E8, "text": "\x08\x06\x29\x05\x44L'Epée de Légende!!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70E9, "text": "\x1ATrouve les Sages et sauve Hyrule!\x0E\x50\x02", "box_type": 5},
    {"id": 0x70EA, "text": "Cet homme effrayant a semé une\x01sacrée pagaille ici!\x02", "box_type": 0},
    {"id": 0x70EB, "text": "Oh! J'ai si peur...\x01Je suis terrifié...\x02", "box_type": 0},
    {"id": 0x70EC, "text": "Hé! Que veux-tu?\x01Je n'ai pas le temps de parler!\x02", "box_type": 0},
    {"id": 0x70ED, "text": "Pitié avec \x05\x46¡\x05\x40...\x01Pitié vends-moi un truc...\x01Pitié avec \x05\x46¡\x05\x40...\x02", "box_type": 0},
    {"id": 0x70EE, "text": "Non...\x01C'est pas ça que je veux...\x01Je veux un truc \x05\x41dans une bouteille\x05\x40.\x01Pas ce drôle de truc...\x02", "box_type": 0},
    {"id": 0x70EF, "text": "Non...\x01Je peux pas prendre ça...\x01J'veux pas acheter ça...\x02", "box_type": 0},
    {"id": 0x70F0, "text": "Oh! C'est une \x05\x44Flamme Bleue\x05\x40!\x01Je t'en donne \x05\x41150 Rubis\x05\x40!\x01Vends-la moi! Vends-la moi!\x02", "box_type": 0},
    {"id": 0x70F1, "text": "Oh! Un p'tit \x05\x45poisson\x05\x40!\x01Je t'en donne \x05\x41100 Rubis\x05\x40!\x01Dis-moi oui...chéri.\x02", "box_type": 0},
    {"id": 0x70F2, "text": "Mais...c'est un superbe...\x05\x42insecte\x05\x40!\x01Je t'en donne \x05\x4150 Rubis\x05\x40!\x01Donne! Donne!\x02", "box_type": 0},
    {"id": 0x70F3, "text": "Quelle jolie \x05\x44fée\x05\x40!\x01Je t'en offre \x05\x4125 Rubis\x05\x40, OK?\x02", "box_type": 0},
    {"id": 0x70F4, "text": "\x1AQuel garçon plein d'entrain et \x01de vie...j'adore ça...\x04\x1AHé hé hé...ton nom est bien\x01\x0F?\x04\x1AHé hé hé...ne sois pas surpris!\x01Je lis dans les esprits comme \x01dans un livre ouvert.\x04\x1ASi j'avais autant d'énergie que toi, \x01je pourrais changer de métier!\x01Hé hé hé...\x04\x1AJe suis l'unique \x05\x41marchand d'âmes \x01\x05\x40de tout le Royaume d'Hyrule.\x04\x1ADepuis la venue de Ganondorf, les\x01affaires marchent plutôt bien...\x01Hé hé hé...\x04\x1AOh...Je ne peux qu'espérer une\x01nouvelle guerre!\x04\x1ALes fantômes du nom d'\x05\x41Esprits\x05\x40\x01sont l'essence même de la haine. \x01Ils apparaissent dans les \x01cimetières ou dans les plaines.\x04\x1AJeune homme plein de vie, si par \x01chance tu en captures un, viens \x01donc me le vendre...\x01Tu gagneras beaucoup d'argent!\x02", "box_type": 0},
    {"id": 0x70F5, "text": "Hé! Jeune homme plein de vie!\x01Quoi de neuf? \x01As-tu un Esprit ou une Ame à me \x01vendre?\x04Ta carte a \x05\x45\x1E\x01 \x05\x40points.\x01Reviens vite me voir!\x01Hé hé hé!\x02", "box_type": 0},
    {"id": 0x70F6, "text": "\x1AOh! Tu as apporté un fantôme!\x04\x1A\x14\x02........\x14\x00\x04\x1AHmmm...\x04\x1ACe n'est qu'un \x05\x41Esprit\x05\x40.\x01Je t'en donne \x05\x4110 Rubis\x05\x40. \x01C'est tout!\x04\x1AHé hé hé.\x02", "box_type": 0},
    {"id": 0x70F7, "text": "\x1AOh! Tu as apporté un fantôme!\x04\x1AHmmmm!\x04\x1AMagnifique!\x01C'est une \x05\x41Ame\x05\x40!\x04\x1AJe t'en donne \x05\x4150 Rubis\x05\x40.\x04Et en plus, j'inscris \x05\x41100 points\x01\x05\x40sur ta carte.\x04\x1AObtiens \x05\x411,000 points\x05\x40 et tu ne\x01seras pas déçu...\x01Hé hé hé.\x02", "box_type": 0},
    {"id": 0x70F8, "text": "\x1AOoooh! WHOA!\x04\x1ATu as obtenu \x05\x411,000 points\x05\x40!\x04\x1ATu es un véritable \x05\x41chasseur de\x01fantômes\x05\x40!\x04\x1AIl est content? Hein? \x01Il est content le monsieur?\x01Hé hé hé!\x04\x1AGrâce à toi, mon stock d'\x05\x41Ames\x05\x40 est\x01plein! C'est donc la dernière fois \x01que nous faisons affaire.\x04\x1AJe sais, je sais...\x01Nous avions passé un pacte...\x01Tu as eu tes 1000 points et je \x01t'en félicite... Hé hé hé!\x04\x1AAlors prends donc ceci, \x01mon bon ami!\x02", "box_type": 0},
    {"id": 0x70F9, "text": "\x1AOh? C'est quoi ça?\x04\x1A\x14\x02\x08Est-ce\x09 \x08une\x09...\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x70FA, "text": "\x06\x4B...\x08\x05\x44Fée\x05\x40\x09?!\x04\x1AAlors tu es un garçon...\x01de la forêt?\x0B\x02", "box_type": 0},
    {"id": 0x70FB, "text": "\x1AAlors...mais alors...tu dois avoir\x01la...la \x05\x42Pierre Ancestrale de la \x01forêt\x05\x40?! Hein? Cette belle pierre \x01verte et brillante...\x0B\x02", "box_type": 0},
    {"id": 0x70FC, "text": "\x1AJ'ai fait un rêve...Dans ce rêve,\x01des nuages noirs et épais \x01recouvraient la terre d'Hyrule...\x04\x1AQuand soudain, un rayon de \x01lumière surgit de la forêt, \x01dispersant les ténèbres et \x01illuminant la terre...\x04\x1ACette lumière se matérialisa sous \x01la forme d'un garçon tenant une \x01\x05\x42pierre verte \x05\x40dans la main. \x01Une \x05\x44fée \x05\x40volait à ses côtés...\x0B\x02", "box_type": 0},
    {"id": 0x70FD, "text": "\x1AJe sais qu'une prophétie annonce\x01la venue d'un enfant de la \x05\x42forêt\x05\x40...\x04\x1ACet enfant...ne peut être que toi.\x0B\x02", "box_type": 0},
    {"id": 0x70FE, "text": "\x1A\x06\x2DOh! Pardonne-moi!\x04\x1AJe parle, je parle et je ne me\x01suis toujours pas présentée...\x0B\x02", "box_type": 0},
    {"id": 0x70FF, "text": "\x1A\x06\x2AMon nom est \x05\x44Zelda\x05\x40,\x01\x06\x2EPrincesse d'Hyrule.\x0B\x02", "box_type": 0},
    {"id": 0x7100, "text": "Quoi? On se connaît?\x02", "box_type": 0},
    {"id": 0x7101, "text": "Oooh... C'est trop mignon!\x01Où l'as-tu trouvé?\x02", "box_type": 0},
    {"id": 0x7102, "text": "Wouaaaaaah!\x01Au secours!\x02", "box_type": 0},
    {"id": 0x7103, "text": "Hein?...ouais? Et alors?\x02", "box_type": 0},
    {"id": 0x7104, "text": "JE HAIS LES RENARDS!\x02", "box_type": 0},
    {"id": 0x7105, "text": "C'est agaçant ton truc!\x02", "box_type": 0},
    {"id": 0x7106, "text": "Whoa! La classe!\x02", "box_type": 0},
    {"id": 0x7107, "text": "\x08Beuark! C'est quoi ton problème?\x09\x02", "box_type": 0},
    {"id": 0x7108, "text": "Oooh...c'est un Zora?\x01Ses yeux sont fascinants...\x02", "box_type": 0},
    {"id": 0x7109, "text": "Yaaah! J'ai peur!!\x01Ne me mange pas! \x01Ne me mange pas!\x02", "box_type": 0},
    {"id": 0x710A, "text": "C'est-y pas mignon...\x01La jeunesse, les masques...\x01Tout ça est si loin à présent.\x02", "box_type": 0},
    {"id": 0x710B, "text": "C'est rigolo ton truc!\x01Hi hi hi!\x02", "box_type": 0},
    {"id": 0x710C, "text": "\x08Oh-oh!\x09 Bonjour maman!\x01...Hein? C'est toi!\x01T'es malade ou quoi?\x02", "box_type": 0},
    {"id": 0x710D, "text": "Woah! T'as une de ces têtes!\x02", "box_type": 0},
    {"id": 0x710E, "text": "Enlève-le tout d'suite!\x01J'ai peur...\x02", "box_type": 0},
    {"id": 0x710F, "text": "Y a-t-il un concours de masques \x01en ce moment?\x01\x08Je vais voter pour toi!\x09\x02", "box_type": 0},
    {"id": 0x7110, "text": "Oh! Un lapin! Un petit lapinou!\x01Tout mimi. Tout gentil.\x01Il est à qui le lapin? Hein?\x01Il est à qui? C'est mignoooon.\x02", "box_type": 0},
    {"id": 0x7111, "text": "Oooh! Quelle belle fille!\x01Un peu petite mais...jolie.\x02", "box_type": 0},
    {"id": 0x7112, "text": "Mmm? Oui? C'est pour quoi?\x01Tu veux ma photo?\x02", "box_type": 0},
    {"id": 0x7113, "text": "Oh! Un masque... Cela me rappelle\x01mon enfance. Je gambadais dans\x01la forêt avec un masque...\x01Et puis un jour...? Tu m'écoutes?\x02", "box_type": 0},
    {"id": 0x7114, "text": "Ohhhh...Je vois...\x01C'est une illusion d'optique...\x02", "box_type": 0},
    {"id": 0x7115, "text": "Hé petit! Ne deviens pas comme\x01moi...ça craint.\x02", "box_type": 0},
    {"id": 0x7116, "text": "\x08YAAAAAAAAAAAH!\x01UNE GERUDO!!!!\x09\x04Quoi? Un masque?\x01Mais pourquoi tu portes un truc\x01comme ça? T'es tapé ou quoi?!\x02", "box_type": 0},
    {"id": 0x7117, "text": "Laisse-moi tranquille...ouste!\x02", "box_type": 0},
    {"id": 0x7118, "text": "Cool! C'est le Renard!\x01Bonjour monsieur le Renard!\x02", "box_type": 0},
    {"id": 0x7119, "text": "Quelle horreur!\x01Un petit garçon à Cocorico \x01cherchait un masque comme\x01celui-ci...\x02", "box_type": 0},
    {"id": 0x711A, "text": "Mmm...super...tu n'as pas un autre\x01masque?\x02", "box_type": 0},
    {"id": 0x711B, "text": "Woah! Il est louche ton masque!\x02", "box_type": 0},
    {"id": 0x711C, "text": "Tu vois pas qu'on discute?\x01Laisse-nous tranquilles!\x02", "box_type": 0},
    {"id": 0x711D, "text": "Désolé. Je ne pourrai plus jamais\x01regarder une autre femme!\x02", "box_type": 0},
    {"id": 0x711E, "text": "Hi hi hi...\x01Ne prête pas attention à ce petit.\x01Embrasse-moi plutôt, amour.\x02", "box_type": 0},
    {"id": 0x711F, "text": "Heu....\x01Tu veux pas aller aut'part?\x02", "box_type": 0},
    {"id": 0x7120, "text": "On dit qu'un apothicaire fabrique\x01un médicament surpuissant!\x02", "box_type": 0},
    {"id": 0x7121, "text": "On raconte qu'un monstre avale\x01les \x05\x44boucliers\x05\x40. \x01En as-tu déjà vu un?\x02", "box_type": 0},
    {"id": 0x7122, "text": "Je suis venu vendre des bombes...\x01En veux-tu?\x02", "box_type": 0},
    {"id": 0x7123, "text": "\x1AJ'ai...J'ai peur...\x01J'ai le sentiment que cet homme\x01va anéantir Hyrule.\x04\x1ASes pouvoirs sont terrifiants!\x04\x1AMais ta venue est providentielle.\x0B\x02", "box_type": 0},
    {"id": 0x7124, "text": "Hein? Mais tu veux quoi?\x01Tu vas me lâcher, ouais?\x02", "box_type": 0},
    {"id": 0x7125, "text": "J'suis occupé! Dégage!\x01JE TE HAIS!\x02", "box_type": 0},
    {"id": 0x7126, "text": "Mmm... Du bois de qualité!\x02", "box_type": 0},
    {"id": 0x7127, "text": "Grrrr!\x01Tu m'oublies, oui?\x01Mauviette...\x02", "box_type": 0},
    {"id": 0x7128, "text": "YAAAAAAAAAAAAH!\x01Oups. Désolé.\x01Je ne devrais pas crier comme ça.\x02", "box_type": 0},
    {"id": 0x7129, "text": "Désolé, chef!\x01Ma pause est terminée!\x01Je vais travailler...promis!\x04Heu...chef? C'est vous?\x02", "box_type": 0},
    {"id": 0x712A, "text": "Les Gerudos sont si belles...\x01Je les aime! Toutes!\x02", "box_type": 0},
    {"id": 0x712B, "text": "Un jour j'aurai du talent.\x01Et alors je pourrai sculpter un \x01masque comme le tien!\x02", "box_type": 0},
    {"id": 0x712C, "text": "C'est ça le masque à la mode?\x01Il est méga-moche!\x02", "box_type": 0},
    {"id": 0x712D, "text": "Wa-ha-hah!\x01Tout se passe comme vous le \x01voulez, M. Le Preux Chevalier?\x01Hah hah hah!\x02", "box_type": 0},
    {"id": 0x712E, "text": "Je suis de service.\x01T'as compris?\x01DE SERVICE!\x02", "box_type": 0},
    {"id": 0x712F, "text": "Mmmm... Pas mal...enfin...\x01J'm'en fiche, quoi!\x02", "box_type": 0},
    {"id": 0x7130, "text": "Oooh! C'est trop mimi!\x01Mais mes cocottes sont encore \x01plus mignonnes!\x02", "box_type": 0},
    {"id": 0x7131, "text": "Hein? Quoi?\x01Tu es joyeux ou triste?\x01Difficile à dire...\x02", "box_type": 0},
    {"id": 0x7132, "text": "Mmm... Ce n'est pas vraiment mon \x01style...\x02", "box_type": 0},
    {"id": 0x7133, "text": "Le petit garçon du cimetière nous\x01parle toute la journée de son \x01visage...\x02", "box_type": 0},
    {"id": 0x7134, "text": "Je suis un type bien.\x01Tu ne me crois pas?\x02", "box_type": 0},
    {"id": 0x7135, "text": "YAAAA--! Hein?\x01J'ai cru que c'était encore l'autre\x01vieille bique! J'ai eu une de ces\x01frousses!\x02", "box_type": 0},
    {"id": 0x7136, "text": "Mon père me parlait souvent\x01d'un forgeron...mais tout ça ne\x01m'intéresse plus....\x02", "box_type": 0},
    {"id": 0x7137, "text": "Les monstres de la forêt ne me\x01font pas peur! Tu me prends pour\x01qui, toi?\x02", "box_type": 0},
    {"id": 0x7138, "text": "Mmm? C'est quoi ça?\x01Je ne vois rien d'ici...\x02", "box_type": 0},
    {"id": 0x7139, "text": "Bonjour! Quelles nouvelles?\x02", "box_type": 0},
    {"id": 0x713A, "text": "Belle journée, n'est-ce pas?\x02", "box_type": 0},
    {"id": 0x713B, "text": "Fatigué...dormir...\x02", "box_type": 0},
    {"id": 0x713C, "text": "Les renards m'agacent!\x02", "box_type": 0},
    {"id": 0x713D, "text": "Tu es assez agaçant toi, non?\x01Allez! Du balai!\x02", "box_type": 0},
    {"id": 0x713E, "text": "Mmmm...joli!\x02", "box_type": 0},
    {"id": 0x713F, "text": "Waaaaaaah!\x01C'est quoi ton problème, petit?\x02", "box_type": 0},
    {"id": 0x7140, "text": "Crétin! Enlève ton masque avant \x01de parler à quelqu'un!\x02", "box_type": 0},
    {"id": 0x7141, "text": "Crétin! Ne parle pas aux gens en\x01les fixant!\x02", "box_type": 0},
    {"id": 0x7142, "text": "Crétinus!\x01Regarde-moi quand j'te parle!\x02", "box_type": 0},
    {"id": 0x7143, "text": "Bouffon!\x01Je ne sais pas pourquoi mais...\x01Bouffon!\x02", "box_type": 0},
    {"id": 0x7144, "text": "Mon dieu! Ton visage!\x01Il est tout...\x01Quoi? C'est un masque?\x01\x08Sors de chez moi!\x09\x02", "box_type": 0},
    {"id": 0x7145, "text": "Laisse-moi tranquille...\x01J'suis occupé.\x02", "box_type": 0},
    {"id": 0x7146, "text": "Un masque est un instrument: \x01il reflète la personnalité... \x01J'aime ton style, petit!\x02", "box_type": 0},
    {"id": 0x7147, "text": "Quelle tête ENORME!\x01Comment as-tu pu entrer ici?!\x02", "box_type": 0},
    {"id": 0x7148, "text": "JE HAIS LES RENARDS!\x01Je les..... \x08HAIS\x09!\x02", "box_type": 0},
    {"id": 0x7149, "text": "Alors ça...c'est bien la tête la\x01plus énervante de tous les temps!\x01Félicitations, petit!\x02", "box_type": 0},
    {"id": 0x714A, "text": "Whoa! Joli visage, petit!\x02", "box_type": 0},
    {"id": 0x714B, "text": "Tu veux me parler?\x01Alors enlève ce truc!\x02", "box_type": 0},
    {"id": 0x714C, "text": "Heu...comment dire...\x01On n'a pas vraiment le temps de \x01jouer avec toi, petit!\x01SAUVE-NOUS!\x02", "box_type": 0},
    {"id": 0x714D, "text": "J'ai beau être un demi-monstre \x01mais... ton masque...comment dire...\x01YAAAAAAAAAAH!\x02", "box_type": 0},
    {"id": 0x714E, "text": "Excuse-moi si je n'explose pas de\x01rire mais...comment dire...\x01SAUVE-NOUS ! ! ! !\x02", "box_type": 0},
    {"id": 0x714F, "text": "\x12\x68\x67WOUAAAAAAA!\x01Il est monstrueux ton masque!\x01Hein? Oui, je sais...merci...\x01Moi aussi j'suis un monstre!\x02", "box_type": 0},
    {"id": 0x7150, "text": "Gheu?! Quoi?!?\x04Oh...c'est juste un gamin...\x01J'ai eu une de ces trouilles!\x01Ma face fait peur aux cafards\x01mais je suis super sensible!\x02", "box_type": 0},
    {"id": 0x7151, "text": "Nom d'un ver pourri...\x01Regardez-moi cette tête!\x01Hein? Quoi ma tête?\x02", "box_type": 0},
    {"id": 0x7152, "text": "Hé! Tu sais c'que tu portes, là?\x01Vraiment? Mais t'es tapé!\x02", "box_type": 0},
    {"id": 0x7153, "text": "Je bosse, là... \x01Si tu veux qu'je creuse,\x01laisse-moi tranquille.\x02", "box_type": 0},
    {"id": 0x7154, "text": "C'est quoi ça? C'est pas un p'tit\x01truc tout mignon qui saute un peu\x01partout? Comment ça s'appelle?\x02", "box_type": 0},
    {"id": 0x7155, "text": "Hé! C'est un masque du Renard!!\x01J'ai demandé à mon papa de m'en\x01acheter un!\x02", "box_type": 0},
    {"id": 0x7156, "text": "C'est Igor tout craché, hein?\x02", "box_type": 0},
    {"id": 0x7157, "text": "Rien à voir avec Igor, hein?\x02", "box_type": 0},
    {"id": 0x7158, "text": "\x12\x68\x63Cool comme masque mais...\x01Il est un p'tit peu trop effrayant!\x02", "box_type": 0},
    {"id": 0x7159, "text": "Ce masque me dit quelque chose...\x01Je l'ai déjà vu dans la forêt, non?\x02", "box_type": 0},
    {"id": 0x715A, "text": "\x12\x68\x63Ce masque me rend...heureuse...\x02", "box_type": 0},
    {"id": 0x715B, "text": "Oooh.....sniff...\x01Ce masque...me rend...\x01Si triiiiste! Bouhouuuuuu!\x02", "box_type": 0},
    {"id": 0x715C, "text": "Ha! Tu portes un masque, hein?\x01Tu as donc peur de moi!Ha ha!\x02", "box_type": 0},
    {"id": 0x715D, "text": "Yaaaaaaaaah! C'est quoi ça?\x01J'ai pas peur! J'ai pas peur!\x01Mais...ne t'approche pas de moi!\x01Compris?\x02", "box_type": 0},
    {"id": 0x715E, "text": "Whoa! Il est génial ton masque!\x01Tu veux bien être mon copain?\x01....Ha ha! Tu m'as cru, hein?\x01Pauv'nul, va! Ha ha ha ha ha!\x02", "box_type": 0},
    {"id": 0x715F, "text": "Wah hah ha hah!\x01C'est ton portrait tout craché!\x02", "box_type": 0},
    {"id": 0x7160, "text": "Yaaaaaah Waaaah! \x01J-Je vais le dire à Mido!\x02", "box_type": 0},
    {"id": 0x7161, "text": "Bwaaaaaaaahh!\x01J-Je vais dire à Mido de te \x01casser la figure!\x02", "box_type": 0},
    {"id": 0x7162, "text": "Whooooah!\x01Es-tu un fantôme de la forêt?\x02", "box_type": 0},
    {"id": 0x7163, "text": "Gé-nial! Super ton masque!\x01Heu...ne répète pas à Mido que j'ai \x01dit ça, OK?\x02", "box_type": 0},
    {"id": 0x7164, "text": "Hein?!\x01Tu es revenu!\x01Pas la peine de se cacher derrière\x01ce masque! Je t'ai reconnu!\x02", "box_type": 0},
    {"id": 0x7165, "text": "Je me demande quelle serait la \x01réaction de Mido en voyant ça...\x02", "box_type": 0},
    {"id": 0x7166, "text": "Je vois...\x01Tu veux faire peur à Mido avec ce\x01masque, hein?\x02", "box_type": 0},
    {"id": 0x7167, "text": "Hah hah hah!\x01C'est trop drôle!\x01Saria va adorer ce masque!\x02", "box_type": 0},
    {"id": 0x7168, "text": "Hi hi hi hi!!!\x01Un masque de bois?\x01C'est comme si tu portais un\x01bouclier sur la tête!\x02", "box_type": 0},
    {"id": 0x7169, "text": "Quelle drôle de tête!\x04Au fait... Un enfant de la forêt\x01se plaint de son visage toute la\x01journée...\x02", "box_type": 0},
    {"id": 0x716A, "text": "Quelle ENORME tête!\x02", "box_type": 0},
    {"id": 0x716B, "text": "Hi hi!\x01Où l'as-tu trouvé?\x01En dehors de la forêt?\x01Impossible! Je ne te crois pas!\x02", "box_type": 0},
    {"id": 0x716C, "text": "Ha ha!\x01C'est rigolo mais...ce n'est pas\x01vraiment mon style...\x02", "box_type": 0},
    {"id": 0x716D, "text": "Cool! \x01Porter ce masque me donne\x01l'impression d'être un vrai dur!\x01Hé hé!\x02", "box_type": 0},
    {"id": 0x716E, "text": "Hé hé! \x01Cool ton masque mais...bon.\x02", "box_type": 0},
    {"id": 0x716F, "text": "Hé hé!\x01J'ai mon masque maintenant...\x01Les autres ne m'intéressent pas...\x02", "box_type": 0},
    {"id": 0x7170, "text": "\x12\x68\x6DWoah! Tu as une ENORME tête!\x02", "box_type": 0},
    {"id": 0x7171, "text": "\x12\x68\x6BOh! Le mignon petit rat!\x01Quoi?\x01C'est pas un rat? Tu rigoles?\x02", "box_type": 0},
    {"id": 0x7172, "text": "\x12\x68\x6CC'est quoi ces trucs mous\x01au-dessus de ta p'tite tête?\x01Des oreilles? T'en as quatre?\x02", "box_type": 0},
    {"id": 0x7173, "text": "\x12\x68\x69Tu as réussi à éviter les gardes\x01avec ça sur la tête?\x02", "box_type": 0},
    {"id": 0x7174, "text": "Bonjour gentil garçon à la fée!\x01...Pardon?\x01Mais bien sûr que je t'ai reconnu!\x02", "box_type": 0},
    {"id": 0x7175, "text": "Whoa!\x01Quels énormes yeux!\x01Les Gorons sont siiiii mignons!\x02", "box_type": 0},
    {"id": 0x7176, "text": "Oh! Je te reconnais! tu es le\x01Renard! Bonjour le Renard!\x01Tu es très à la mode, tu sais!\x02", "box_type": 0},
    {"id": 0x7177, "text": "Les garçons...tous les mêmes!\x02", "box_type": 0},
    {"id": 0x7178, "text": "Attends...attends...\x01Je sais qui tu es...\x01Tu es...le Renard, non?\x01Woah! J'suis trop fort!\x02", "box_type": 0},
    {"id": 0x7179, "text": "Whoa!... Il est moche ton masque!\x01Presque aussi moche que...Ingo!\x02", "box_type": 0},
    {"id": 0x717A, "text": "Tu me rappelles ma femme...\x01Attends...finalement non.\x01Tu ne lui ressembles pas du tout!\x02", "box_type": 0},
    {"id": 0x717B, "text": "(Baille)...\x01J'suis un peu naze...\x01Tu me le montreras plus tard...\x02", "box_type": 0},
    {"id": 0x717C, "text": "Hors de ma vue!\x01Tu vois pas que j'travaille?!\x02", "box_type": 0},
    {"id": 0x717D, "text": "Très drôle... Tu verras plus tard!\x01La vie active n'est pas aussi \x01marrante que ça!\x02", "box_type": 0},
    {"id": 0x717E, "text": "YAAAAAAAH!\x01Heu? C'est juste un masque...\x01OK. Bonne blague. Super. Dégage.\x02", "box_type": 0},
    {"id": 0x717F, "text": "Hé hé hé...\x01Un petit rayon de soleil dans ma\x01journée... Merci mon garçon!\x02", "box_type": 0},
    {"id": 0x7180, "text": "Mmmm... Voyons un peu ceci...\x01Du bel ouvrage! Du bois de\x01premier choix! Gni gni....\x02", "box_type": 0},
    {"id": 0x7181, "text": "Ahhh...oui! En effet...\x01Un travail impeccable...\x01L'auteur de ce masque est un \x01véritable chef.\x02", "box_type": 0},
    {"id": 0x7182, "text": "Oh! Un joli Goron!\x01A propos...Je me demande comment \x01se porte mon vieil ami Biggoron du\x01Mont du Péril.\x02", "box_type": 0},
    {"id": 0x7183, "text": "Etrange...\x01Il ne doit pas être soluble.\x02", "box_type": 0},
    {"id": 0x7184, "text": "Miam miam miam...\x01Cool. Un masque. Youpi.\x01Tu veux m'acheter des haricots?\x02", "box_type": 0},
    {"id": 0x7185, "text": "Miam miam miam...\x01J'en veux pas de ton masque.\x02", "box_type": 0},
    {"id": 0x7186, "text": "Miam miam miam...\x01Ce n'est pas vraiment mon style...\x02", "box_type": 0},
    {"id": 0x7187, "text": "Miam miam miam...\x01Heu...non. J'en veux pas.\x02", "box_type": 0},
    {"id": 0x7188, "text": "Que veux-tu?\x02", "box_type": 0},
    {"id": 0x7189, "text": "Tu n'as pas l'air d'être un bon\x01nageur...\x02", "box_type": 0},
    {"id": 0x718A, "text": "Cheveux rouges...peau mate...\x01Cela me rappelle quelque chose...\x02", "box_type": 0},
    {"id": 0x718B, "text": "Hé hé hé!\x01Tu es trop petit pour être un\x01Zora...\x02", "box_type": 0},
    {"id": 0x718C, "text": "Ho ho ho!\x01Tu Nous fais bien rire!\x02", "box_type": 0},
    {"id": 0x718D, "text": "Ce visage...il Nous fait peur!\x02", "box_type": 0},
    {"id": 0x718E, "text": "Cela Nous rappelle notre vieil ami\x01d'enfance: le joyeux Biggoron!\x02", "box_type": 0},
    {"id": 0x718F, "text": "Te paies-tu Notre tête?\x02", "box_type": 0},
    {"id": 0x7190, "text": "T'es rigolo, toi!\x02", "box_type": 0},
    {"id": 0x7191, "text": "Ta tête... Elle est ENORME!\x02", "box_type": 0},
    {"id": 0x7192, "text": "Arrête ça tout de suite...\x01Tu me perturbes...\x02", "box_type": 0},
